fn handle_composer_input_result(&mut self, result: InputResult) -> bool {
        match result {
            InputResult::Submitted {
                text,
                text_elements,
            }
            | InputResult::Queued {
                text,
                text_elements,
                ..
            } => {
                self.apply_submission_to_draft(text, text_elements);
                self.validation_error = None;
                self.go_next_or_submit();
                true
            }
            _ => false,
        }
    }

fn apply_vim_insert_action(&mut self, action: VimAction) -> bool {
        let deletion = matches!(
            action,
            VimAction::DeleteBackward
                | VimAction::DeleteForward
                | VimAction::DeleteBackwardWord
                | VimAction::DeleteForwardWord
                | VimAction::KillLineStart
                | VimAction::KillLine
                | VimAction::KillLineEnd
        );
        if deletion && let Some(range) = self.mouse_selection_range() {
            self.vim_commands = VimCommandState::default();
            if matches!(action, VimAction::DeleteBackward | VimAction::DeleteForward) {
                self.replace_range(range, "");
            } else {
                self.kill_range(range);
            }
            return true;
        }
        self.mouse_selection = None;
        let recording = self.vim_enabled
            && matches!(self.vim_mode, VimMode::Insert | VimMode::Replace)
            && !self.vim_commands.replaying
            && !self.vim_commands.pending_change.is_empty();
        let prior_len = self.text.len();
        if !self.apply_vim_editor_action(action.clone()) {
            return false;
        }
        let changed =
            self.text.len() != prior_len || matches!(action, VimAction::RestoreReplacedCharacter);
        if recording && (changed || !deletion) {
            self.vim_commands
                .pending_change
                .push(VimEdit::Editor(VimEditorEdit(action)));
        }
        self.vim_commands.changed |= recording && changed;
        true
    }

fn agent_tool_fallbacks_preserve_status_without_duplicating_v2_activity() {
    let cwd = test_path_buf("/workspace").abs();
    let mut snapshots = Vec::new();
    for (tool, status) in [
        (
            CollabAgentTool::SpawnAgent,
            CollabAgentToolCallStatus::InProgress,
        ),
        (
            CollabAgentTool::SendInput,
            CollabAgentToolCallStatus::Failed,
        ),
        (
            CollabAgentTool::CloseAgent,
            CollabAgentToolCallStatus::Interrupted,
        ),
        (
            CollabAgentTool::ResumeAgent,
            CollabAgentToolCallStatus::Failed,
        ),
        (
            CollabAgentTool::Wait,
            CollabAgentToolCallStatus::Interrupted,
        ),
        (
            CollabAgentTool::SendMessage,
            CollabAgentToolCallStatus::InProgress,
        ),
        (
            CollabAgentTool::FollowupTask,
            CollabAgentToolCallStatus::InProgress,
        ),
        (
            CollabAgentTool::InterruptAgent,
            CollabAgentToolCallStatus::InProgress,
        ),
        (
            CollabAgentTool::ListAgents,
            CollabAgentToolCallStatus::InProgress,
        ),
    ] {
        let visible = matches!(
            tool,
            CollabAgentTool::SpawnAgent
                | CollabAgentTool::SendInput
                | CollabAgentTool::CloseAgent
                | CollabAgentTool::ResumeAgent
                | CollabAgentTool::Wait
        );
        let item = ThreadItem::CollabAgentToolCall {
            id: "pending-agent-call".to_string(),
            tool,
            status,
            sender_thread_id: "00000000-0000-0000-0000-000000000001".to_string(),
            receiver_thread_ids: vec!["00000000-0000-0000-0000-000000000002".to_string()],
            prompt: Some("Inspect the parser".to_string()),
            model: None,
            reasoning_effort: None,
            agents_states: Default::default(),
        };
        let cells = thread_items_to_transcript_cells(
            /*thread_id*/ None,
            &cwd,
            [item],
            RawReasoningVisibility::Hidden,
            /*config*/ None,
        );
        assert_eq!(cells.len(), usize::from(visible));
        for cell in cells {
            assert_eq!(cell.transcript_animation_tick(), None);
            let text = cell
                .transcript_lines(/*width*/ 80)
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join("\n");
            snapshots.push(text);
        }
    }
    insta::assert_snapshot!(snapshots.join("\n"));
}

