fn disabled_renderers_preserve_source_independently() {
    let samples = [
        "```mermaid\nflowchart LR\nA[Request] --> B[Reply]\n```\n",
        "Inline $\\alpha_1$ and \\(x^{2}\\).\n\n\\[\n\\frac{a}{b}\n\\]\n",
        "| **Name** | Value |\n|---|---|\n| `a` | path\\_1 &amp; \\* |\n",
        "- [ ] Pending\n- [x] Done\n- Ordinary\n",
    ];
    let defaults = samples.map(render_markdown_text);
    let mut snapshot = Vec::new();
    for rendering in [
        TuiRendering {
            mermaid: false,
            ..Default::default()
        },
        TuiRendering {
            math: false,
            ..Default::default()
        },
        TuiRendering {
            tables: false,
            ..Default::default()
        },
        TuiRendering {
            lists: false,
            ..Default::default()
        },
    ] {
        init(rendering);
        for (index, source) in samples.iter().enumerate() {
            let rendered = render_markdown_text(source);
            if [
                rendering.mermaid,
                rendering.math,
                rendering.tables,
                rendering.lists,
            ][index]
            {
                assert_eq!(rendered, defaults[index]);
            } else {
                snapshot.push(format!("{rendering:?}\n{rendered}"));
            }
        }
    }
    insta::assert_snapshot!(snapshot.join("\n\n---\n\n"));
}

fn sync_mention_popup(&mut self, target: MentionCompletionTarget) {
        let MentionCompletionTarget {
            range,
            query,
            prebuilt_mentions,
        } = target;
        if self
            .popups
            .dismissed_mention_token
            .as_ref()
            .is_some_and(|dismissed| dismissed.matches(&self.draft.textarea, &range, &query))
        {
            return;
        }

        let mentions = prebuilt_mentions.unwrap_or_else(|| self.mention_items());
        if mentions.is_empty() {
            self.popups.active = ActivePopup::None;
            return;
        }

        match &mut self.popups.active {
            ActivePopup::Skill(popup) => {
                popup.set_query(&query);
                popup.set_mentions(mentions);
            }
            _ => {
                let mut popup = SkillPopup::new(mentions);
                popup.set_query(&query);
                self.popups.active = ActivePopup::Skill(popup);
            }
        }
    }

fn appending_to_unchanged_history_tail_preserves_existing_rows() {
    let width = 52;
    let height = 8;
    let backend = VT100Backend::new(width, height);
    let mut terminal = Terminal::with_options(backend).expect("terminal");
    terminal.set_viewport_area(Rect::new(
        /*x*/ 0, /*y*/ 0, width, /*height*/ 2,
    ));
    insert_history_lines(
        &mut terminal,
        vec![Line::from("/status"), Line::from("Account: business")],
    )
    .expect("insert initial status card");
    let replacement = plain_hyperlink_lines(vec![Line::from("Thread usage: 50 credits")]);

    assert!(
        replace_visible_terminal_history_tail(
            &mut terminal,
            /*previous_lines*/ &[],
            &replacement,
            InsertHistoryMode::Standard,
            HistoryLineWrapPolicy::PreWrap,
        )
        .expect("append late billing details")
