fn live_selection_survives_commits_finalization_new_live_content_and_resize() {
    let mut cells = vec![agent(&["first"])];
    let mut view = TranscriptView::default();
    let tail =
        StreamingAgentTailCell::new(vec!["tail selected".into()], /*is_first_line*/ false);
    live(&mut view, &tail, /*revision*/ 1);
    render(&mut view, &cells, /*width*/ 32, /*height*/ 4);
    view.begin_selection(&cells, /*column*/ 4, /*row*/ 1, /*clicks*/ 3);
    release(&mut view, &cells, /*column*/ 4, /*row*/ 1);
    assert_eq!(view.selected_text(&cells), Some("tail selected".to_owned()));

    cells.push(Arc::new(AgentMessageCell::new(
        vec!["tail selected".into()],
        /*is_first_line*/ false,
    )));
    let finalized: Arc<dyn HistoryCell> = Arc::new(AgentMarkdownCell::new(
        "first\ntail selected".to_owned(),
        std::path::Path::new("."),
    ));
    view.replace_range(&cells, 0..2, &finalized);
    cells.splice(0..2, [finalized]);
    let unrelated = StreamingAgentTailCell::new(
        vec!["unrelated next tail".into()],
        /*is_first_line*/ true,
    );
    live(&mut view, &unrelated, /*revision*/ 2);
    insta::assert_snapshot!(render(&mut view, &cells, /*width*/ 32, /*height*/ 4), @"
    • first
      tail selected
    ");
    render(&mut view, &cells, /*width*/ 10, /*height*/ 6);
    assert_eq!(view.selected_text(&cells), Some("tail selected".to_owned()));

    cells.insert(/*index*/ 0, agent(&["older page"]));
    view.prepend_snapshot_history(&cells, 0..1);
    render(&mut view, &cells, /*width*/ 32, /*height*/ 5);
    assert_eq!(view.selected_text(&cells), Some("tail selected".to_owned()));
    assert_eq!(
        view.selection
            .as_ref()
            .expect("selection")
            .snapshot
            .cells
            .len(),
        2
    );
    view.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &cells);
    assert!(!view.is_following());
    assert!(view.selection.is_none());
    view.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &cells);
    assert!(view.is_following());
    assert!(render(&mut view, &cells, /*width*/ 32, /*height*/ 5).contains("unrelated next tail"));
}

fn search_skips_duplicate_persistent_matches() {
        let (tx, mut rx) = unbounded_channel::<AppEvent>();
        let tx = AppEventSender::new(tx);

        let mut history = ChatComposerHistory::new();
        history.set_metadata(test_thread_id(), /*log_id*/ 1, /*entry_count*/ 4);

        assert_eq!(
            HistorySearchResult::Pending,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ true,
                &tx
            )
        );
        let _ = rx.try_recv().expect("expected latest lookup");
        assert_eq!(
            HistoryEntryResponse::Search(HistorySearchResult::Found(HistoryEntry::new(
                "needle same".to_string()
            ))),
            history.on_entry_response(
                /*log_id*/ 1,
                /*offset*/ 3,
                Some("needle same".into()),
                &tx,
            )
        );

        assert_eq!(
            HistorySearchResult::Pending,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ false,
                &tx
            )
        );
        let _ = rx.try_recv().expect("expected duplicate lookup");
        assert_eq!(
            HistoryEntryResponse::Search(HistorySearchResult::Pending),
            history.on_entry_response(
                /*log_id*/ 1,
                /*offset*/ 2,
                Some("needle same".into()),
                &tx,
            )
        );
        let AppEvent::LookupMessageHistoryBatch { cursor, .. } =
            rx.try_recv().expect("expected next batch after duplicate")
        else {
            panic!("unexpected event variant");
        };
        assert_eq!(cursor.end_offset(), 1);
        assert_eq!(
            Some(HistorySearchResult::Found(HistoryEntry::new(
                "needle older".to_string()
            ))),
            history.on_batch_response(
                /*log_id*/ 1,
                cursor,
                vec![
                    batch_entry(/*offset*/ 1, "not a match"),
                    batch_entry(/*offset*/ 0, "needle older"),
                ],
                /*next_older_cursor*/ None,
                &tx,
            )
        );
        assert_eq!(
            HistorySearchResult::AtBoundary,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ false,
                &tx
            )
        );
        assert_eq!(
            HistorySearchResult::Found(HistoryEntry::new("needle same".to_string())),
            history.search(
                "needle",
                HistorySearchDirection::Newer,
                /*restart*/ false,
                &tx
            )
        );
    }

