fn move_select_rows(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        mut cursor: Anchor,
        rows: isize,
        column: Option<u16>,
    ) -> Option<Anchor> {
        let code = if rows < 0 { KeyCode::Up } else { KeyCode::Down };
        for _ in 0..rows.unsigned_abs() {
            let Some(mut next) = self.move_selection_endpoint(cells, cursor, code, column) else {
                break;
            };
            let index = self.resolve(cells, next);
            if let Some(layout) = self.layout(cells, index) {
                let row = layout
                    .row_for_offset(next.offset)
                    .saturating_add_signed(next.row_bias.saturating_neg());
                next.offset = layout.cursor_position_at(row, column.unwrap_or_default());
                next.row_bias = layout.row_for_offset(next.offset) as isize - row as isize;
            }
            if next == cursor {
                break;
            }
            cursor = next;
        }
        Some(cursor)
    }

fn render(view: &impl Renderable, width: u16) -> String {
    let area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        width,
        view.desired_height(width),
    );
    let mut buffer = Buffer::empty(area);
    view.render(area, &mut buffer);
    (0..area.height)
        .map(|y| {
            (0..area.width)
                .map(|x| buffer[(x, y)].symbol())
                .collect::<String>()
                .trim_end()
                .to_string()
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn navigation_supersedes_home_before_and_after_the_first_draw() {
    let mut tui = crate::tui::test_support::make_test_tui().expect("tui");
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 40, /*height*/ 10,
    );
    for rendered in [false, true] {
        for key in [
            KeyEvent::new(KeyCode::Up, KeyModifiers::NONE),
            KeyEvent::new(KeyCode::Down, KeyModifiers::NONE),
            KeyEvent::new(KeyCode::PageUp, KeyModifiers::NONE),
            KeyEvent::new(KeyCode::PageDown, KeyModifiers::NONE),
            KeyEvent::new(KeyCode::Char('u'), KeyModifiers::CONTROL),
            KeyEvent::new(KeyCode::Char('d'), KeyModifiers::CONTROL),
            KeyEvent::new(KeyCode::End, KeyModifiers::NONE),
        ] {
            let cells = vec![Arc::new(TestCell {
                lines: (0..30)
                    .map(|index| Line::from(format!("line {index}")))
                    .collect(),
            }) as Arc<dyn HistoryCell>];
            let mut expected = transcript_overlay(cells.clone());
            let mut actual = transcript_overlay(cells);
            actual.set_history_state(TranscriptHistoryState::Partial);
            if rendered {
                expected.render(area, &mut Buffer::empty(area));
                actual.render(area, &mut Buffer::empty(area));
            }
            expected
                .handle_event(&mut tui, TuiEvent::Key(key))
                .expect("navigate");
            actual
                .handle_event(
                    &mut tui,
                    TuiEvent::Key(KeyEvent::new(KeyCode::Home, KeyModifiers::NONE)),
                )
                .expect("Home");
            actual
                .handle_event(&mut tui, TuiEvent::Key(key))
                .expect("navigate");
            assert_eq!(actual.view.history, TranscriptHistoryState::LoadingOlder);
            actual.prepend(vec![Arc::new(TestCell {
                lines: vec!["received older history".into()],
            })]);
            actual.set_history_state(TranscriptHistoryState::Complete);
            let mut expected_buffer = Buffer::empty(area);
            let mut actual_buffer = Buffer::empty(area);
            expected.render(area, &mut expected_buffer);
            actual.render(area, &mut actual_buffer);
            assert_eq!(
                buffer_to_text(
                    &actual_buffer,
                    Rect::new(
                        /*x*/ 0, /*y*/ 1, /*width*/ 40, /*height*/ 5
                    )
                ),
                buffer_to_text(
                    &expected_buffer,
                    Rect::new(
                        /*x*/ 0, /*y*/ 1, /*width*/ 40, /*height*/ 5
                    )
                )
            );
        }
    }
}

fn startup_draft_applies_paste_burst_preferences_without_losing_buffered_input() {
    let codex_home = tempfile::tempdir().expect("create temporary Codex home");
    let config = ConfigBuilder::default()
        .codex_home(codex_home.path().to_path_buf())
        .build()
        .await
        .expect("build startup configuration");
    let mut settings = crate::local_settings::LocalSettings::from(&config);
    let mut pump = startup_test_pump(std::iter::empty());

    handle_startup_draft_key(
        &mut pump.bottom_pane,
        KeyEvent::new(KeyCode::Char('a'), KeyModifiers::NONE),
    )
    .expect("buffer input before startup configuration loads");
    assert!(pump.bottom_pane.is_in_paste_burst());
    assert_eq!(pump.bottom_pane.composer_text(), "");

    settings.tui.disable_paste_burst = Some(true);
    pump.apply_settings(&settings, config.cwd.as_path());
    assert_eq!(pump.bottom_pane.composer_text(), "a");
    assert!(!pump.bottom_pane.is_in_paste_burst());

    handle_startup_draft_key(
        &mut pump.bottom_pane,
        KeyEvent::new(KeyCode::Char('b'), KeyModifiers::NONE),
    )
    .expect("insert text immediately when paste detection is disabled");
    assert_eq!(pump.bottom_pane.composer_text(), "ab");
    assert!(!pump.bottom_pane.is_in_paste_burst());

    settings.tui.disable_paste_burst = Some(false);
    pump.apply_settings(&settings, config.cwd.as_path());
    handle_startup_draft_key(
        &mut pump.bottom_pane,
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::NONE),
    )
    .expect("restore paste detection after a later configuration change");
    assert_eq!(pump.bottom_pane.composer_text(), "ab");
    assert!(pump.bottom_pane.is_in_paste_burst());

    settings.tui.disable_paste_burst = Some(true);
    pump.apply_settings(&settings, config.cwd.as_path());
    assert_eq!(pump.bottom_pane.composer_text(), "abc");
    assert!(!pump.bottom_pane.is_in_paste_burst());
    assert!(pump.app_event_rx.try_recv().is_err());
}

