    if rows_all.is_empty() {
        if area.height > 0 {
            Line::from(empty_message.dim().italic()).render(area, buf);
        }
        // Count the placeholder line only when there is vertical space to draw it.
        return RenderedRows {
            lines: u16::from(area.height > 0),
            items: 0,
            ..Default::default()
        };
    }

    let visible_items = max_results
        .min(rows_all.len())
        .min(area.height.max(1) as usize);

    let mut start_idx = state.scroll_top.min(rows_all.len().saturating_sub(1));
    if let Some(sel) = state.selected_idx {
        if sel < start_idx {
            start_idx = sel;
        } else if visible_items > 0 {
            let bottom = start_idx + visible_items - 1;
            if sel > bottom {
                start_idx = sel + 1 - visible_items;
            }
        }
    }

    let desc_col = compute_desc_col(rows_all, start_idx, visible_items, area.width, column_width);

    let mut cur_y = area.y;
    let mut rendered_lines: u16 = 0;
    for (i, row) in rows_all
        .iter()
        .enumerate()
        .skip(start_idx)
        .take(visible_items)
    {
        if cur_y >= area.y + area.height {
            break;
        }

        let mut full_line =
            build_full_line(row, desc_col, area.width, column_width.description_layout);
        apply_row_state_style(
            std::slice::from_mut(&mut full_line),
            Some(i) == state.selected_idx && !row.is_disabled,
            row.is_disabled,
            row.selection_style,
        );

        let mut full_line = full_hyperlink_row(row, full_line);
        let clipped = line_width(&full_line.line) > usize::from(area.width);
        full_line.line =
            truncate_line_with_ellipsis_if_overflow(full_line.line, area.width as usize);
        let visible_width = line_width(&full_line.line).saturating_sub(usize::from(clipped));
        full_line.hyperlinks.retain_mut(|link| {
            link.columns.end = link.columns.end.min(visible_width);
            !link.columns.is_empty()
        });
        (&full_line).render(
            Rect {
                x: area.x,
                y: cur_y,
                width: area.width,
                height: 1,
            },
            buf,
        );
        cur_y = cur_y.saturating_add(1);
        rendered_lines = rendered_lines.saturating_add(1);
    }

    RenderedRows {
        lines: rendered_lines,
        items: rendered_lines as usize,
        has_above: start_idx > 0,
        has_below: start_idx + usize::from(rendered_lines) < rows_all.len(),
    }
}

