fn decode_console_default_colors(attributes: u16, color_table: &[u32; 16]) -> DefaultColors {
    let fg_index = (attributes & 0x0f) as usize;
    let bg_index = ((attributes >> 4) & 0x0f) as usize;
    // COMMON_LVB_REVERSE_VIDEO changes how cells render, but this probe is discovering the
    // configured default colors for palette blending. Keep the attribute fg/bg indices as-is.
    DefaultColors {
        fg: decode_color_ref(color_table[fg_index]),
        bg: decode_color_ref(color_table[bg_index]),
    }
}

fn regaining_focus_cancels_scheduled_check() {
    let mut state = RecapState::default();
    state.note_focus_lost(Instant::now());

    let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
    state.scheduled_check = Some(tokio::spawn(async move {
        tokio::time::sleep(RECAP_DELAY).await;
        task_tx.send(()).expect("scheduled recap event");
    }));

    tokio::task::yield_now().await;

    state.note_focus_gained();
    tokio::time::advance(RECAP_DELAY).await;
    tokio::task::yield_now().await;

    assert!(state.scheduled_check.is_none());
    assert!(matches!(
        task_rx.try_recv(),
        Err(tokio::sync::mpsc::error::TryRecvError::Disconnected)
    ));
}

fn keyboard_selection_moves_by_grapheme_and_keeps_its_column_across_short_lines() {
    let cells = vec![
        agent(&["A👨‍👩‍👧‍👦界e\u{301}Z", "x", "1234567890"]),
        agent(&["tail"]),
    ];
    let mut view = TranscriptView::default();
    render(&mut view, &cells, /*width*/ 32, /*height*/ 5);
    view.begin_selection(&cells, /*column*/ 2, /*row*/ 0, /*clicks*/ 1);
    for _ in 0..4 {
        view.selection_key(&cells, KeyCode::Right);
    }
    assert_eq!(view.selected_text(&cells).as_deref(), Some("A👨‍👩‍👧‍👦界e\u{301}"));
    let original = view.selection.as_ref().expect("selection").end;
    for key in [KeyCode::Down, KeyCode::Down, KeyCode::Up, KeyCode::Up] {
        view.selection_key(&cells, key);
    }
    assert_eq!(view.selection.as_ref().expect("selection").end, original);
    for _ in 0..10 {
        view.selection_key(&cells, KeyCode::Down);
    }
    let end = view.selection.as_ref().expect("selection").end;
    assert!(end.index < cells.len());
    let layout = view
        .layout(&cells, end.index)
        .expect("valid endpoint layout");
    assert!(layout.text().is_char_boundary(end.offset));
    for _ in 0..10 {
        view.selection_key(&cells, KeyCode::Up);
    }
    assert_eq!(view.selection.as_ref().expect("selection").end, original);
}

