fn invalidate_viewport_repaints_default_style_spaces_over_stale_terminal_cells() {
        let width = 32;
        let height = 2;
        let area = Rect::new(/*x*/ 0, /*y*/ 0, width, height);
        let mut terminal =
            Terminal::with_options(VT100Backend::new(width, height)).expect("terminal");
        terminal.set_viewport_area(area);

        // History insertion writes directly to the terminal, leaving cells that are absent from
        // the diff buffers. Interior default-style spaces must still overwrite those stale cells.
        write!(
            terminal.backend_mut(),
            "probe-08tcleantwords stale\r\nprobe-09xcleanxwords stale"
        )
        .expect("prefill terminal");
        assert!(
            terminal
                .backend()
                .vt100()
                .screen()
                .contents()
                .contains("probe-08tcleantwords")
        );

        terminal.invalidate_viewport();
        terminal
            .draw(|frame| {
                Paragraph::new(vec![
                    Line::from("probe-08 clean words"),
                    Line::from("probe-09 clean words"),
                ])
                .render(area, frame.buffer_mut());
            })
            .expect("redraw invalidated viewport");

        assert_snapshot!(terminal.backend().vt100().screen().contents(), @r"
        probe-08 clean words
        probe-09 clean words
        ");
    }

fn voice_terminal_title_tracks_capture_activity_and_user_settings() {
    let (mut chat, _sender, _events, _ops) = make_chatwidget_manual_with_sender().await;
    let thread_id = activate_voice(&mut chat);
    chat.local_settings.tui.animations = false;
    let check = |chat: &mut ChatWidget, expected: &str| {
        chat.refresh_terminal_title();
        assert_eq!(chat.last_terminal_title.as_deref(), Some(expected));
    };
    check(&mut chat, "● project");
    chat.bottom_pane.set_task_running(/*running*/ true);
    chat.local_settings.tui.animations = true;
    chat.refresh_terminal_title();
    assert!(chat.last_terminal_title.as_deref().is_some_and(|title| {
        title.starts_with("● ") && title.ends_with(" project") && title != "● project"
    }));
    chat.local_settings.tui.animations = false;
    check(&mut chat, "● project");
    chat.local_settings.tui.terminal_title = Some(vec!["project-name".to_string()]);
    check(&mut chat, "project");
    chat.local_settings.tui.terminal_title = None;
    use RealtimeConversationPhase as Phase;
    for phase in [Phase::Starting, Phase::Stopping, Phase::Inactive] {
        chat.realtime_conversation.phase = phase;
        check(&mut chat, "project");
    }
    chat.realtime_conversation.phase = RealtimeConversationPhase::Active;
    chat.realtime_conversation.microphone_muted = true;
    check(&mut chat, "project");
    chat.realtime_conversation.microphone_muted = false;
    chat.thread_id = Some(ThreadId::new());
    check(&mut chat, "project");
    chat.thread_id = Some(thread_id);
    check(&mut chat, "● project");
    chat.park_voice();
    let (mut restored, _, _, _) = make_chatwidget_manual_with_sender().await;
    restored.thread_id = Some(thread_id);
    restored.local_settings.tui.animations = false;
    restored.resume_background_voice(&mut chat);
    assert_eq!(restored.last_terminal_title.as_deref(), Some("● project"));
    chat = restored;
    chat.reset_realtime_conversation();
    assert_eq!(chat.last_terminal_title.as_deref(), Some("project"));
    activate_voice(&mut chat);
    check(&mut chat, "● project");
    chat.clear_managed_terminal_title().expect("title clears");
    chat.reset_realtime_conversation();
    assert!(chat.last_terminal_title.is_none());
}

fn is_private_realtime_agent_item(item: &ThreadItem) -> bool {
    if matches!(item, ThreadItem::Reasoning { .. }) {
        return true;
    }
    let ThreadItem::AgentMessage { text, phase, .. } = item else {
        return false;
    };
    let text = text.trim_start();
    matches!(phase, Some(MessagePhase::Commentary))
        || (!matches!(phase, Some(MessagePhase::FinalAnswer))
            && (text.starts_with("[ANALYSIS]") || text.starts_with("[COMMENTARY]")))
}

