fn read_text(
        &mut self,
        source: PasteSource,
        frames: FrameRequester,
    ) -> Result<Option<Arc<()>>, String> {
        if self.pending_read.is_some() || (source == PasteSource::Clipboard && self.is_busy()) {
            return Ok(None);
        }
        self.ensure_started(frames.clone())?;
        let deadline = Instant::now() + SETUP_TIMEOUT;
        let owner = Arc::new(());
        let wait = self.is_busy() || (source == PasteSource::Primary && self.primary.is_some());
        self.pending_read = Some(PendingRead {
            frames: frames.clone(),
            deadline,
            source,
            owner: Arc::downgrade(&owner),
            response: None,
            expired: false,
        });
        self.read_result = None;
        if !wait {
            self.start_read()?;
        }
        frames.schedule_frame_in(SETUP_TIMEOUT);
        Ok(Some(owner))
    }

fn inline_boundaries_preserve_selected_text_and_formatting() {
    let mut copies = Vec::new();
    for (source, selected, expected_html) in [
        (
            "_a **b**_**c**",
            "a bc",
            "<p><em>a</em> <strong><em>b</em>c</strong></p>\n",
        ),
        (
            "_a **b**_**c**",
            "bc",
            "<p><strong><em>b</em>c</strong></p>\n",
        ),
        (
            "*a **b***[**c**](/repo)",
            "a bc",
            "<p><em>a</em> <strong><em>b</em>c</strong></p>\n",
        ),
        ("_*a*_[_b_](/repo)", "ab", "<p><em>ab</em></p>\n"),
        (
            "*[a **b**](https://example.com) c*",
            "a b",
            "<p><a href=\"https://example.com\"><em>a</em> <strong><em>b</em></strong></a></p>\n",
        ),
        (
            "a*b*c a**b**c",
            "abc abc",
            "<p>a<em>b</em>c a<strong>b</strong>c</p>\n",
        ),
        ("&#97;_b_&#99;", "abc", "<p>a<em>b</em>c</p>\n"),
        ("&#97;__b__&#99;", "abc", "<p>a<strong>b</strong>c</p>\n"),
        ("&#769;_b_", "\u{301}b", "<p>\u{301}<em>b</em></p>\n"),
        ("&#97;*!*&#98;", "a!b", "<p>a<em>!</em>b</p>\n"),
        ("&#97;*&#12290;*&#98;", "a。b", "<p>a<em>。</em>b</p>\n"),
        (
            "&#97;**_b_**&#99;",
            "abc",
            "<p>a<strong><em>b</em></strong>c</p>\n",
        ),
        (
            "&#97;**`b`**&#99;",
            "abc",
            "<p>a<strong><code>b</code></strong>c</p>\n",
        ),
        ("_a_[b](/repo)", "ab", "<p><em>a</em>b</p>\n"),
        (
            "&#32;&#32;&#32;&#32;**hello**",
            "    hello",
            "<p>    <strong>hello</strong></p>\n",
        ),
    ] {
        let layout = markdown_layout(source, /*width*/ 80);
        let start = layout.text().find(selected).expect(source);
        let (copied, format) = payload(&layout, start..start + selected.len());
        assert_eq!(format, CopyFormat::Markdown);
        let html = crate::clipboard_html::render_markdown(&copied);
        assert_eq!(html, expected_html, "{source:?} => {copied:?}");
        copies.push(format!(
            "{source}\nSelected: {selected:?}\nMarkdown: {copied}\n{html}"
        ));
    }
    insta::assert_snapshot!(copies.join("\n"));
}

fn move_select_character(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        cursor: Anchor,
        code: KeyCode,
    ) -> Option<Anchor> {
        let mut index = self.resolve(cells, cursor);
        let layout = self.layout(cells, index)?;
        let offset = layout
            .text()
            .floor_char_boundary(cursor.offset.min(layout.text().len()));
        let local = match code {
            KeyCode::Left if offset > 0 => selectable_graphemes(&layout.text()[..offset])
                .rfind(|(offset, _)| layout.is_cursor_position(*offset))
                .map(|(offset, _)| offset),
            KeyCode::Right if offset < layout.text().len() => {
                selectable_graphemes(&layout.text()[offset..])
                    .filter(|(next, _)| layout.is_cursor_position(offset + *next))
                    .find(|(next, _)| cursor.row_bias != 0 || *next > 0)
                    .map(|(next, _)| offset + next)
            }
            _ => None,
        };
        if let Some(offset) = local {
            return Some(Anchor {
                key: self.entry_key(cells, index),
                index,
                offset,
                row_bias: 0,
            });
        }
        loop {
            index = match code {
                KeyCode::Left => index.checked_sub(1)?,
                KeyCode::Right => index + 1,
                _ => return None,
            };
            let next = self.layout(cells, index)?;
            let offset = match code {
                KeyCode::Left => selectable_graphemes(next.text())
                    .rfind(|(offset, _)| next.is_cursor_position(*offset))
                    .map(|(offset, _)| offset),
                KeyCode::Right => selectable_graphemes(next.text())
                    .find(|(offset, _)| next.is_cursor_position(*offset))
                    .map(|(offset, _)| offset),
                _ => None,
            };
            if let Some(offset) = offset {
                return Some(Anchor {
                    key: self.entry_key(cells, index),
                    index,
                    offset,
                    row_bias: 0,
                });
            }
        }
    }

fn thread_to_transcript_cells(
    thread: Thread,
    raw_reasoning_visibility: RawReasoningVisibility,
    config: Option<&Config>,
) -> TranscriptCells {
    let cwd = thread.cwd;
    let thread_id = ThreadId::from_string(&thread.id).ok();
    let mut cells = thread
        .turns
        .into_iter()
        .flat_map(|turn| {
            thread_items_to_transcript_cells(
                thread_id,
                &cwd,
                turn.items,
                raw_reasoning_visibility,
                config,
            )
        })
        .collect::<TranscriptCells>();
    if cells.is_empty() {
        cells.push(Arc::new(PlainHistoryCell::new(vec![
            "No transcript content available".italic().dim().into(),
        ])));
    }
    cells
}

