fn finalize_completed_assistant_message(&mut self, message: Option<&str>) {
        if self.stream_controller.is_none()
            && let Some(message) = message
            && !message.is_empty()
            && !self.completed_agent_message_was_flushed(message)
        {
            let displayed =
                parse_assistant_markdown(message, self.config.cwd.as_path()).visible_markdown;
            self.handle_streaming_delta(displayed);
        }
        // Item completion is authoritative. Use it for consolidation so any
        // deltas dropped by a saturated transport cannot truncate the transcript.
        self.flush_answer_stream(message);
        self.handle_stream_finished();
        self.request_redraw();
    }

fn server_version_notice_key(
    target: &AppServerTarget,
    server_home: Option<&str>,
    client: &str,
    server: Option<&str>,
) -> Option<String> {
    let server = server?;
    server_version_notice(client, Some(server))?;
    let mut hasher = Sha256::new();
    let endpoint = match target {
        AppServerTarget::Embedded => None,
        AppServerTarget::LocalDaemon { endpoint, .. } | AppServerTarget::Remote { endpoint } => {
            Some(endpoint)
        }
    };
    if let Some(server_home) = server_home {
        hash_identity_part(&mut hasher, b"server-home:", server_home.as_bytes());
    }
    match endpoint {
        Some(RemoteAppServerEndpoint::UnixSocket { socket_path }) => {
            hash_identity_part(
                &mut hasher,
                b"unix:",
                socket_path.as_path().as_os_str().as_encoded_bytes(),
            );
        }
        Some(RemoteAppServerEndpoint::WebSocket { websocket_url, .. }) => {
            if let Ok(mut url) = Url::parse(websocket_url) {
                let routing = url
                    .query_pairs()
                    .filter(|(name, _)| {
                        matches!(
                            name.to_ascii_lowercase().as_str(),
                            "workspace"
                                | "project"
                                | "tenant"
                                | "environment"
                                | "namespace"
                                | "organization"
                                | "org"
                                | "account"
                                | "route"
                                | "instance"
                                | "region"
                                | "deployment"
                                | "cluster"
                        )
                    })
                    .map(|(name, value)| (name.into_owned(), value.into_owned()))
                    .collect::<Vec<_>>();
                let _ = url.set_username("");
                let _ = url.set_password(None);
                url.set_query(None);
                url.set_fragment(None);
                if !routing.is_empty() {
                    url.query_pairs_mut().extend_pairs(routing);
                }
                hash_identity_part(&mut hasher, b"websocket:", url.as_str().as_bytes());
            }
        }
        None => hash_identity_part(&mut hasher, b"embedded:", b""),
    }
    Some(format!("{:x}:{client}-{server}", hasher.finalize()))
}

