fn render_aligned_field(
    out: &mut Vec<HyperlinkLine>,
    header: &TableCell,
    value: &TableCell,
    label_width: usize,
    available_width: Option<usize>,
    label_style: Style,
) {
    let value_indent = FIELD_LEADING_PADDING + label_width + FIELD_GAP;
    let value_width = available_width
        .map(|width| width.saturating_sub(value_indent).max(MIN_VALUE_WIDTH))
        .unwrap_or_else(|| cell_width(value).max(MIN_VALUE_WIDTH));
    let wrapped_value = wrap_cell(value, value_width);
    for (line_index, value_line) in wrapped_value.into_iter().enumerate() {
        let mut spans = Vec::new();
        let mut copy = None;
        if line_index == 0 {
            let label = header.plain_text();
            let label_source = label_line(header, label_style);
            if let Some(source) = &label_source.source {
                crate::markdown_copy::table::append(&mut copy, source, FIELD_LEADING_PADDING);
            }
            spans.push(Span::raw(" ".repeat(FIELD_LEADING_PADDING)));
            spans.push(Span::styled(label.clone(), label_style));
            spans.push(Span::raw(" ".repeat(
                label_width.saturating_sub(display_width(&label)) + FIELD_GAP,
            )));
        } else {
            spans.push(Span::raw(" ".repeat(value_indent)));
        }
        push_prefixed_value_line(out, spans, value_line, copy);
    }
}

fn transcript_lines(&self) -> impl Iterator<Item = Cow<'_, str>> {
        let omitted = self.total_lines().saturating_sub(self.retained_lines());
        if self.truncated {
            Either::Left(
                self.head
                    .iter()
                    .map(|line| Cow::Borrowed(line.as_str()))
                    .chain((omitted > 0).then(|| {
                        let noun = if omitted == 1 { "line" } else { "lines" };
                        Cow::Owned(format!("… +{omitted} {noun}"))
                    }))
                    .chain(self.tail.iter().map(|line| Cow::Borrowed(line.as_str())))
                    .chain(
                        self.has_partial_line
                            .then(|| Cow::Owned(self.render_partial_line())),
                    ),
            )
        } else {
            Either::Right(self.full_output.lines().map(Cow::Borrowed))
        }
    }

