fn short_history_entries_share_a_frame_without_starving_input() {
    let mut cells = vec![cell("needle in the oldest message")];
    cells.extend((0..64).map(|index| cell(format!("newer message {index}"))));
    let mut view = TranscriptView::default();
    view.begin_search();
    view.paste_search("needle");

    let mut frames = 1;
    while view.advance_search(&cells) {
        frames += 1;
        assert!(frames < 16, "short entries must not cost one frame each");
    }
    assert!(frames > 1, "large histories must still yield to input");
    let found = view.search.current.as_ref().expect("oldest match");
    assert_eq!(
        (found.anchor.index, found.anchor.offset..found.end),
        (0, 0..6)
    );
}

fn handle_streaming_delta(&mut self, delta: String) {
        if !delta.is_empty() {
            self.mark_safety_buffering_agent_message_started();
        }
        if self.stream_controller.is_none() {
            self.prepare_assistant_message();
            let inline_visualization_context = self.thread_id.and_then(|thread_id| {
                crate::inline_visualization::InlineVisualizationContext::from_config(
                    &self.config,
                    thread_id,
                )
            });
            self.stream_controller = Some(
                StreamController::new_with_inline_visualizations(
                    self.current_stream_width(/*reserved_cols*/ 2),
                    &self.config.cwd,
                    self.history_render_mode(),
                    inline_visualization_context,
                )
                .with_list_spacing(
                    if self.local_settings.transcript_mode.is_owned() {
                        ListSpacing::Compact
                    } else {
                        ListSpacing::AfterMultiline
                    },
                ),
            );
        }
        let changed = self
            .stream_controller
            .as_mut()
            .is_some_and(|controller| controller.push(&delta));
        if (changed || delta.contains('\n')) && self.sync_active_stream_tail() {
            self.request_redraw();
        }
        if changed {
            self.app_event_tx.send(AppEvent::StartCommitAnimation);
            self.run_catch_up_commit_tick();
        }
    }

