fn prepare_submission_text_with_options(
        &mut self,
        record_history: bool,
        slash_validation: SlashValidation,
        pending_paste_handling: PendingPasteHandling,
    ) -> Option<(String, Vec<TextElement>)> {
        let mut text = self.current_text();
        let original_input = text.clone();
        let original_text_elements = self.current_text_elements();
        let original_mention_bindings = self.snapshot_mention_bindings();
        let original_local_image_paths = self.attachments.local_image_paths();
        let original_pending_pastes = self.draft.pending_pastes.clone();
        let mut text_elements = original_text_elements.clone();
        let input_starts_with_space = original_input.starts_with(' ');
        self.draft.recent_submission_mention_bindings.clear();
        self.draft.textarea.set_text_clearing_elements("");
        self.draft.prompt_prefix = PromptPrefix::None;

        if pending_paste_handling == PendingPasteHandling::Expand
            && !self.draft.pending_pastes.is_empty()
        {
            // Expand placeholders so element byte ranges stay aligned.
            let (expanded, expanded_elements) =
                Self::expand_pending_pastes(&text, text_elements, &self.draft.pending_pastes);
            text = expanded;
            text_elements = expanded_elements;
        }

        if self.config.trim_submission {
            let expanded_input = text.clone();
            text = text.trim().to_string();
            text_elements = Self::trim_text_elements(&expanded_input, &text, text_elements);
        }

        if slash_validation == SlashValidation::Immediate
            && let SubmissionValidation::UnknownCommand(name) = self
                .slash_input()
                .validate_submission(&text, input_starts_with_space)
        {
            let message = format!(
                r#"Unrecognized command '/{name}'. Type "/" for a list of supported commands."#
            );
            self.app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
                history_cell::new_info_event(message, /*hint*/ None),
            )));
            self.set_text_content_with_mention_bindings(
                original_input.clone(),
                original_text_elements,
                original_local_image_paths,
                original_mention_bindings,
            );
            self.draft
                .pending_pastes
                .clone_from(&original_pending_pastes);
            self.draft.textarea.set_cursor(original_input.len());
            return None;
        }

        let actual_chars = text.chars().count();
        if actual_chars > MAX_USER_INPUT_TEXT_CHARS {
            let message = user_input_too_large_message(actual_chars);
            self.app_event_tx.send(AppEvent::InsertHistoryCell(Box::new(
                history_cell::new_error_event(message),
            )));
            self.set_text_content_with_mention_bindings(
                original_input.clone(),
                original_text_elements,
                original_local_image_paths,
                original_mention_bindings,
            );
            self.draft
                .pending_pastes
                .clone_from(&original_pending_pastes);
            self.draft.textarea.set_cursor(original_input.len());
            // Embedded composers may cover the transcript that receives the full error.
            if self.footer.hint_override.is_some() {
                self.show_footer_flash(
                    Line::from(
                        format!("Message too long; limit {MAX_USER_INPUT_TEXT_CHARS} characters")
                            .red(),
                    ),
                    Duration::from_secs(5),
                );
            }
            return None;
        }
        self.attachments
            .prune_local_images_for_submission(&text, &text_elements);
        if text.trim().is_empty() && self.attachments.is_empty() {
            return None;
        }
        self.draft.recent_submission_mention_bindings = original_mention_bindings.clone();
        if record_history && (!text.is_empty() || !self.attachments.is_empty()) {
            let preserve_literal_paste = self.slash_commands_enabled()
                && text.starts_with('!')
                && !original_input.trim_start().starts_with('!');
            let (history_text, history_text_elements) = if preserve_literal_paste {
                let history_text = original_input.trim().to_string();
                let history_text_elements = Self::trim_text_elements(
                    &original_input,
                    &history_text,
                    original_text_elements,
                );
                (history_text, history_text_elements)
            } else {
                (text.clone(), text_elements.clone())
            };
            self.history.record_local_submission(HistoryEntry {
                text: history_text,
                text_elements: history_text_elements,
                local_image_paths: self.attachments.local_image_paths(),
                remote_image_urls: self.attachments.remote_image_urls(),
                mention_bindings: original_mention_bindings,
                pending_pastes: if pending_paste_handling == PendingPasteHandling::Preserve
                    || preserve_literal_paste
                {
                    original_pending_pastes.clone()
                } else {
                    Vec::new()
                },
            });
        }
        self.draft.pending_pastes.clear();
        Some((text, text_elements))
    }

fn set_cursor_style_with_repair(
        &mut self,
        cursor_style: SetCursorStyle,
    ) -> io::Result<()> {
        if self.last_cursor_style == Some(cursor_style) {
            return Ok(());
        }
        // JediTerm before 3.56 prints DECSCUSR's space intermediate at the cursor.
        // Apply a changed style over an owned glyph, then repair it even on unchanged frames.
        // https://github.com/JetBrains/jediterm/commit/0c4524f2978bddae65a46c35f264bf89e2ed58fd
        let buffer = &self.buffers[self.current];
        let anchor = (0..buffer.area.height).find_map(|row| {
            let row_start = usize::from(row) * usize::from(buffer.area.width);
            let mut column = 0;
            while column < usize::from(buffer.area.width) {
                let cell = &buffer.content[row_start + column];
                let width = usize::from(cell.cell_width());
                let is_skip = cell.diff_option == CellDiffOption::Skip;
                if !is_skip && width > 0 && column + width <= usize::from(buffer.area.width) {
                    let (x, y) = buffer.pos_of(row_start + column);
                    return Some((Position { x, y }, cell.clone()));
                }
                column += width.max(1);
            }
            None
        });
        // Empty and externally owned viewports have no cell we can safely repair.
        if let Some((anchor, cell)) = anchor {
            if !self.hidden_cursor {
                self.hide_cursor()?;
            }
            self.set_cursor_position(anchor)?;
            self.set_cursor_style(cursor_style)?;
            let Position { x, y } = anchor;
            draw(
                &mut self.backend,
                std::iter::once(DrawCommand::Put { x, y, cell }),
            )?;
        }

        Ok(())
    }

fn owned_drag_stops_when_focus_or_input_ownership_is_lost() -> Result<()> {
    use crossterm::event::MouseButton;
    use crossterm::event::MouseEvent;
    use crossterm::event::MouseEventKind;

    let mut app = crate::app::test_support::make_test_app().await;
    attach_thread(&mut app, ThreadId::new());
    app.transcript_cells = vec![Arc::new(crate::history_cell::PlainHistoryCell::new(
        (0..40).map(|row| format!("row {row:02}").into()).collect(),
    ))];
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    let size = Size::new(/*width*/ 40, /*height*/ 12);
    app.chat_widget
        .apply_external_edit("retained draft 界".into());
    app.chat_widget.handle_key_event(KeyCode::Left.into());
    let draft = app.chat_widget.capture_thread_input_state();
    for owner in ["focus", "resume", "overlay", "popup"] {
        app.transcript_view = Default::default();
        app.overlay = None;
        app.render_owned_transcript(&mut tui, size)?;
        app.transcript_view
            .scroll(&app.transcript_cells, /*rows*/ -12);
        app.render_owned_transcript(&mut tui, size)?;
        for (kind, row) in [
            (MouseEventKind::Down(MouseButton::Left), 2),
            (MouseEventKind::Drag(MouseButton::Left), 0),
        ] {
            app.handle_owned_transcript_event(
                &mut tui,
                &mut app_server,
                &TuiEvent::Mouse(MouseEvent {
                    kind,
                    column: 3,
                    row,
                    modifiers: KeyModifiers::NONE,
                }),
            )?;
        }
        assert!(app.transcript_view.tick_selection(&app.transcript_cells));
        let selected = app.transcript_view.selected_text(&app.transcript_cells);
        let event = match owner {
            "focus" => TuiEvent::FocusLost,
            "resume" => TuiEvent::Resume,
            "overlay" => {
                app.overlay = Some(Overlay::new_static_with_lines(
                    vec!["overlay".into()],
                    "Overlay".to_string(),
                    app.keymap.pager.clone(),
                ));
                TuiEvent::Draw
            }
            "popup" => {
                app.chat_widget.open_feature_enable_prompt(Feature::Collab);
                TuiEvent::Draw
            }
            _ => unreachable!(),
        };
        if matches!(event, TuiEvent::Resume) {
            app.handle_tui_event(&mut tui, &mut app_server, event)
                .await?;
        } else {
            app.handle_owned_transcript_event(&mut tui, &mut app_server, &event)?;
        }
        assert_eq!(app.chat_widget.capture_thread_input_state(), draft);
        assert!(
            !app.transcript_view.tick_selection(&app.transcript_cells),
            "{owner}"
        );
        assert_eq!(
            app.transcript_view.selected_text(&app.transcript_cells),
            selected
        );
    }
    tui.set_owned_screen(/*owned*/ false)?;
    app_server.shutdown().await?;
    Ok(())
}

