fn vim_insert_uses_bar_cursor_style() {
        use crate::render::renderable::Renderable;
        use crossterm::cursor::SetCursorStyle;
        use crossterm::event::KeyCode;
        use crossterm::event::KeyEvent;
        use crossterm::event::KeyModifiers;
        use crossterm::queue;

        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ true,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );
        let area = Rect::new(0, 0, 80, 10);
        let style_output = |style| {
            let mut output = Vec::new();
            queue!(output, style).expect("queue cursor style");
            output
        };
        let default = style_output(SetCursorStyle::DefaultUserShape);
        let steady_bar = style_output(SetCursorStyle::SteadyBar);

        assert_eq!(style_output(composer.cursor_style(area)), default,);

        composer.set_vim_enabled(/*enabled*/ true);
        assert_eq!(style_output(composer.cursor_style(area)), default,);

        composer.handle_key_event(KeyEvent::new(KeyCode::Char('i'), KeyModifiers::NONE));
        composer.set_text_content("hey".to_string(), Vec::new(), Vec::new());
        assert_eq!(style_output(composer.cursor_style(area)), steady_bar);

        composer.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
        assert_eq!(style_output(composer.cursor_style(area)), default,);

        composer.handle_key_event(KeyEvent::new(KeyCode::Char('R'), KeyModifiers::NONE));
        assert_eq!(style_output(composer.cursor_style(area)), default,);
    }

fn terminal_draw_repairs_single_column_without_scrolling() {
    let mut terminal =
        Terminal::with_options(CaptureBackend::new(/*width*/ 1, /*height*/ 1)).expect("terminal");
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 1, /*height*/ 1,
    );
    terminal.set_viewport_area(area);
    let mut frames = Vec::new();
    let mut parser =
        vt100::Parser::new(/*rows*/ 1, /*cols*/ 1, /*scrollback_len*/ 1);
    for _ in 0..3 {
        terminal.backend_mut().output.clear();
        terminal
            .draw(|frame| {
                Paragraph::new("x")
                    .style(Style::default().bg(Color::Blue))
                    .render(area, frame.buffer_mut());
                frame.set_cursor_position((0, 0));
            })
            .expect("draw");
        parser.process(&terminal.backend().output);
        assert_eq!(parser.screen().contents(), "x");
        assert_eq!(parser.screen().cursor_position(), (0, 0));
        frames.push(terminal.backend().output().escape_debug().to_string());
    }
    parser.screen_mut().set_scrollback(/*rows*/ 1);
    assert_eq!(parser.screen().scrollback(), 0);
    assert_snapshot!("cursor_style_single_column_frames", frames.join("\n"));
}

