        let source = format!("{open}\\frac{{abcdefghijk}}{{lmnop}}");
        stream.push_delta(&source);
        let preview = stream.current_tail_lines();
        assert_eq!(preview.len(), 1);
        assert_eq!(preview[0].line.to_string(), source);
        if open == "$$" {
