        lines: &mut Vec<HyperlinkLine>,
        wrapped: Vec<HyperlinkLine>,
        overflow_line: Line<'static>,
    ) {
        let wrapped_len = wrapped.len();
        lines.extend(wrapped.into_iter().take(PREVIEW_LINE_LIMIT));
