    auth_plan: Option<PlanType>,
) -> SessionInfoCell {
    // Header rendered as history (so it appears at the very top).
    let header = SessionHeaderHistoryCell::new(
        model_display_name.to_string(),
        session.reasoning_effort.clone(),
        config.cwd.to_path_buf(),
        CODEX_CLI_VERSION,
    )
    .with_yolo_mode(has_yolo_permissions(
        session.approval_policy,
        &session.permission_profile,
    ));
    let mut parts: Vec<Box<dyn HistoryCell>> = vec![Box::new(header)];

    if is_first_event {
        // Help lines below the header (new copy and list)
        let help_lines: Vec<Line<'static>> = vec![
            "  To get started, describe a task or try one of these commands:"
                .dim()
                .into(),
            Line::from(""),
            Line::from(vec![
                "  ".into(),
                "/init".into(),
                " - create an AGENTS.md file with instructions for Codex".dim(),
            ]),
            Line::from(vec![
                "  ".into(),
                "/status".into(),
                " - show current session configuration".dim(),
            ]),
            Line::from(vec![
                "  ".into(),
                "/permissions".into(),
                " - choose what Codex is allowed to do".dim(),
            ]),
            Line::from(vec![
                "  ".into(),
                "/model".into(),
                " - choose what model and reasoning effort to use".dim(),
            ]),
            Line::from(vec![
                "  ".into(),
                "/review".into(),
                " - review any changes and find issues".dim(),
            ]),
        ];

        parts.push(Box::new(PlainHistoryCell { lines: help_lines }));
    } else {
        if local_settings.tui.show_tooltips
            && let Some(tooltips) = tooltip_override
                .or_else(|| tooltips::get_tooltip(auth_plan, &local_settings.tui.keymap))
                .map(|tip| TooltipHistoryCell::new(tip, &config.cwd))
        {
            parts.push(Box::new(tooltips));
        }
        if requested_model != session.model.as_str() {
            let lines = vec![
                "model changed:".magenta().bold().into(),
                format!("requested: {requested_model}").into(),
                format!("used: {}", session.model).into(),
            ];
            parts.push(Box::new(PlainHistoryCell { lines }));
        }
    }

    SessionInfoCell(CompositeHistoryCell { parts })
}

fn highlight_selection(
        &self,
        range: Range<usize>,
        next: Option<&Self>,
        area: Rect,
        buf: &mut Buffer,
        start_row: usize,
    ) {
        self.highlight(range.clone(), area, buf, start_row);
        for (screen_row, row) in self.visible_rows(area, start_row) {
            if row.source.is_empty() {
                continue;
            }
            let Some(end) = row.line_end else { continue };
            let selected = range.contains(&end)
                || (end == self.text.len()
                    && next.is_some_and(|next| self.separator_after(next).contains('\n')));
            let column = row.first_column
                + row.tabs.column_for_offset(
                    display_width(&self.text[row.source.clone()]),
                    row.source.len(),
                );
            if selected && column < usize::from(self.width) {
                buf[(area.x + column as u16, area.y + screen_row)]
                    .set_style(Style::default().add_modifier(Modifier::REVERSED));
            }
        }
    }

fn vim_word_text_objects_accept_cursor_at_word_end() {
        let mut t = ta_with("hello world");
