        ),
        (
            "single row",
            serde_json::json!({
                "page_up": [], "page_down": [],
                "scroll_up": "page-up", "scroll_down": "page-down"
            }),
            1,
        ),
        (
            "unbound",
            serde_json::json!({"page_up": [], "page_down": []}),
            0,
        ),
    ] {
        let config = serde_json::from_value(serde_json::json!({"pager": pager})).unwrap();
