fn decode_history_mentions_with_at_mentions(
    text: &str,
    at_mentions_enabled: bool,
) -> DecodedHistoryText {
    let bytes = text.as_bytes();
    let mut out = String::with_capacity(text.len());
    let mut mentions = Vec::new();
    let mut task_mention_ranges = Vec::new();
    let mut index = 0usize;

    while index < bytes.len() {
        if at_mentions_enabled
            && let Some((name, path, end_index)) =
                crate::task_mentions::parse_task_link(text, index)
        {
            let start = out.len();
            out.push('@');
            out.push_str(&name);
            task_mention_ranges.push(start..out.len());
            mentions.push(LinkedMention {
                sigil: '@',
                mention: name,
                path,
            });
            index = end_index;
            continue;
        }
        if bytes[index] == b'['
            && let Some((sigil, name, path, end_index)) =
                parse_history_linked_mention(text, index, at_mentions_enabled)
        {
            out.push(sigil);
            out.push_str(name);
            mentions.push(LinkedMention {
                sigil,
                mention: name.to_string(),
                path: path.to_string(),
            });
            index = end_index;
            continue;
        }

        let Some(ch) = text[index..].chars().next() else {
            break;
        };
        out.push(ch);
        index += ch.len_utf8();
    }

    DecodedHistoryText {
        text: out,
        mentions,
        task_mention_ranges,
    }
}

