fn draw_with_resize_reflow(
        &mut self,
        height: u16,
        screen_size: Size,
        draw_fn: impl FnOnce(&mut custom_terminal::Frame),
    ) -> Result<()> {
        // If we are resuming from ^Z, we need to prepare the resume action now so we can apply it
        // in the synchronized update.
        #[cfg(unix)]
        let mut prepared_resume = self
            .suspend_context
            .prepare_resume_action(&mut self.alt_saved_viewport);

        ensure_virtual_terminal_processing()?;

        stdout().sync_update(|_| {
            #[cfg(unix)]
            if let Some(prepared) = prepared_resume.take() {
                self.terminal.invalidate_cursor_state();
                prepared.apply(
                    &mut self.terminal,
                    screen_size,
                    self.owned_screen,
                    self.overlay_input.captures_mouse(self.owned_screen),
                )?;
            }

            if self.clear_thread_switch_on_draw {
                self.clear_for_thread_switch()?;
            }
            if self.owned_screen && !self.is_alt_screen_active() {
                self.enter_alt_screen()?;
            }

            let terminal = &mut self.terminal;
            let needs_full_repaint = Self::update_inline_viewport_for_resize_reflow(
                terminal,
                height,
                screen_size,
                self.scrollback,
            )?;
            // A zero- or one-row history region cannot isolate raw history writes from the
            // viewport, so replayed rows can leave stale cells inside the composer.
            let history_can_overlap_viewport =
                !self.pending_history_lines.is_empty() && terminal.viewport_area.top() <= 1;
            Self::flush_pending_history_lines(
                terminal,
                &mut self.pending_history_lines,
                self.scrollback,
                screen_size,
            )?;

            if needs_full_repaint || history_can_overlap_viewport {
                terminal.invalidate_viewport();
            }

            // Update the y position for suspending so Ctrl-Z can place the cursor correctly.
            #[cfg(unix)]
            {
                let area = terminal.viewport_area;
                let inline_area_bottom = if self.alt_screen_active.load(Ordering::Relaxed) {
                    self.alt_saved_viewport
                        .map(|r| r.bottom().saturating_sub(1))
                        .unwrap_or_else(|| area.bottom().saturating_sub(1))
                } else {
                    area.bottom().saturating_sub(1)
                };
                self.suspend_context.set_cursor_y(inline_area_bottom);
            }

            terminal.draw_with_size(screen_size, &mut self.transcript_images, |frame| {
                draw_fn(frame);
            })
        })??;
        Ok(())
    }

fn copy_resize_keeps_whole_user_padding_inside_context() {
    let user = |message: &str| -> Arc<dyn HistoryCell> {
        Arc::new(crate::history_cell::new_user_prompt(
            message.into(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        ))
    };
    let cells: Vec<Arc<dyn HistoryCell>> = vec![
        user("Earlier prompt"),
        Arc::new(AgentMarkdownCell::new(
            "Earlier context\n\n".repeat(12),
            Path::new("/"),
        )),
        user("One\nTwo\nThree\nFour\nFive\nSix"),
        Arc::new(AgentMarkdownCell::new(
            "Later context\n\n".repeat(12),
            Path::new("/"),
        )),
    ];
    let mut view = TranscriptView::default();
    render(&mut view, &cells, /*width*/ 50, /*height*/ 20);
    view.begin_copy_mode(&cells, /*guard*/ None);
    let len = view.layout(&cells, /*index*/ 2).unwrap().text().len();
    view.select_copy_range(&cells, /*index*/ 2, 0..len);
    render(&mut view, &cells, /*width*/ 50, /*height*/ 20);
    let buffer = render(&mut view, &cells, /*width*/ 50, /*height*/ 10);
    let selected = ratatui::buffer::Cell::default()
        .set_style(crate::style::selection_style())
        .style();
    let rows = buffer
        .content
        .chunks(50)
        .enumerate()
        .filter_map(|(row, cells)| {
            cells
                .iter()
                .any(|cell| cell.style() == selected)
                .then_some(row)
        })
        .collect::<Vec<_>>();
    assert!(!rows.is_empty());
    assert!(
        rows[0] > 0 && *rows.last().unwrap() < 9,
        "selected rows: {rows:?}"
    );
    insta::assert_snapshot!(text(&buffer));
}

