fn terminal_draw_repaints_the_cursor_anchor_only_when_its_style_needs_restoring() {
    let mut terminal =
        Terminal::with_options(CaptureBackend::new(/*width*/ 12, /*height*/ 2)).expect("terminal");
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 12, /*height*/ 2,
    );
    terminal.set_viewport_area(area);
    let render = |terminal: &mut Terminal<CaptureBackend>, marker| {
        terminal.backend_mut().output.clear();
        terminal
            .draw(|frame| {
                let buffer = frame.buffer_mut();
                buffer.set_string(0, 0, "transcript", Style::default());
                buffer.set_string(10, 1, marker, Style::default());
                frame.set_cursor_position((4, 1));
            })
            .expect("draw");
        terminal.backend().output()
    };

    let first = render(&mut terminal, "x");
    assert!(first.contains("\x1b[1;1H"));
    let next = render(&mut terminal, "y");
    assert!(next.contains("\x1b[2;11H"));
    assert!(!next.contains("\x1b[1;1H"));

    terminal.invalidate_cursor_state();
    let restored = render(&mut terminal, "y");
    assert!(restored.contains("\x1b[1;1H"));
    let unchanged = render(&mut terminal, "y");
    assert!(!unchanged.contains("\x1b[1;1H"));
}

fn overview_fork_keeps_idle_source_input_queued() -> Result<()> {
    for cached_primary in [false, true] {
        let (app, mut events, _) = make_test_app_with_channels().await;
        let mut app = Box::pin(app);
        trust_fixture_folders(&mut app);
        std::fs::write(
            app.config.codex_home.join("config.toml"),
            "[tui]\nresume_cwd = \"session\"\n",
        )?;
        let source = ThreadId::from_string(
            &app_test_support::create_fake_rollout(
                app.config.codex_home.as_path(),
                "2025-01-05T12-00-00",
                "2025-01-05T12:00:00Z",
                "Source task",
                Some(&app.config.model_provider_id),
                /*git_info*/ None,
            )
            .expect("saved rollout"),
        )?;
        let mut tui = crate::tui::test_support::make_test_tui()?;
        let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
        if cached_primary {
            Box::pin(app.select_agents_overview_thread(&mut tui, &mut server, source)).await?;
            assert_eq!(app.current_displayed_thread_id(), Some(source));
            app.store_active_thread_receiver().await;
        }
        app.chat_widget
            .set_queue_autosend_suppressed(/*suppressed*/ true);
        app.chat_widget.queue_user_message_with_options(
            "Keep this on the source".into(),
            crate::bottom_pane::QueuedInputAction::Plain,
            Vec::new(),
        );
        let input = app.chat_widget.capture_thread_input_state().unwrap();
        app.agents_overview
            .input_states
            .insert(source, input.clone());
        if cached_primary {
            app.ensure_thread_channel(source)
                .store
                .lock()
                .await
                .input_state = Some(input);
            let child = ThreadId::new();
            app.active_thread_id = Some(child);
            let mut session = app
                .ensure_thread_channel(source)
                .store
                .lock()
                .await
                .session
                .clone()
                .unwrap();
            session.thread_id = child;
            app.chat_widget.handle_thread_session(session);
        }
        while events.try_recv().is_ok() {}
        Box::pin(app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::ForkAgentsOverviewThread { thread_id: source },
        ))
        .await?;
        assert_eq!(
            app.current_displayed_thread_id(),
            Some(source),
            "{}",
            render_bottom_popup(&app.chat_widget, /*width*/ 96)
        );
        assert_eq!(
            app.chat_widget.queued_user_message_texts(),
            vec!["Keep this on the source"]
        );
        let retained = app.agents_overview.input_states[&source].clone();
        let mut ready = None;
        while let Ok(event) = events.try_recv() {
            assert!(!matches!(
                event,
                AppEvent::CodexOp(AppCommand::UserTurn { .. })
            ));
            if matches!(event, AppEvent::ForkAgentsOverviewThreadReady { .. }) {
                ready = Some(event);
            }
        }
        // Failed reattachment can leave the source displayed as a saved replay.
        app.app_server_target = AppServerTarget::LocalDaemon {
            allow_embedded_fallback: true,
            endpoint: crate::resolve_remote_addr("ws://127.0.0.1:4500")?,
        };
        app.ensure_thread_channel(source).mark_replay_only();
        let RequestId::Integer(request) = server.next_request_id() else {
            panic!("integer request ID")
        };
        Box::pin(app.handle_event(
            &mut tui,
            &mut server,
            AppEvent::ForkAgentsOverviewThreadReady { thread_id: source },
        ))
        .await?;
        assert_eq!(app.current_displayed_thread_id(), Some(source));
        assert_eq!(server.next_request_id(), RequestId::Integer(request + 1));
        assert!(!app.chat_widget.fork_in_progress);
        app.app_server_target = AppServerTarget::Embedded;
        Box::pin(app.handle_event(&mut tui, &mut server, ready.expect("fork continuation")))
            .await?;
        assert_ne!(app.current_displayed_thread_id(), Some(source));
        assert_eq!(app.agents_overview.input_states[&source], retained);
        assert!(app.chat_widget.queued_user_message_texts().is_empty());
        assert!(!app.chat_widget.fork_in_progress);
        server.shutdown().await?;
    }
    Ok(())
}

fn live_reader_survives_commit_new_tail_resize_and_selection_then_rejoins_latest() {
    let mut cells = vec![cell("before")];
    let original = cell("live zero\nlive one\nlive two\nlive three\nlive four\nlive five");
    let mut view = TranscriptView::default();
    view.sync_live_tail(/*width*/ 20, /*key*/ None, |width| {
        Some(original.display_hyperlink_lines(width))
    });
    render(&mut view, &cells, /*width*/ 20, /*height*/ 2);
    view.scroll(&cells, /*rows*/ -2);
    let before = text(&render(
        &mut view, &cells, /*width*/ 20, /*height*/ 2,
    ));
    let reading = view.position;
    cells.push(Arc::clone(&original));
    view.sync_live_tail(/*width*/ 20, /*key*/ None, |_| None);
    assert_eq!(
        text(&render(
            &mut view, &cells, /*width*/ 20, /*height*/ 2
        )),
        before
    );
    view.sync_live_tail(
        /*width*/ 20,
        /*key*/ None,
        |_| Some(vec![HyperlinkLine::from("new tail")]),
    );
    assert_eq!(
        text(&render(
            &mut view, &cells, /*width*/ 20, /*height*/ 2
        )),
        before
    );
    render(&mut view, &cells, /*width*/ 9, /*height*/ 2);
    assert_eq!(view.position, reading);
    assert!(
        view.status_line_with_navigation("", crate::motion::MotionMode::Reduced)
            .to_string()
            .contains("New activity")
    );
    view.begin_selection(&cells, /*column*/ 0, /*row*/ 0, /*clicks*/ 3);
    assert_eq!(view.selected_text(&cells), Some("live two\n".to_string()));
    view.begin_search();
    assert!(!view.advance_search(&cells));
    view.handle_key(KeyCode::Esc.into(), &cells);
    assert_eq!(
        text(&render(
            &mut view, &cells, /*width*/ 20, /*height*/ 2
        )),
        before
    );
    view.jump_to_latest();
    assert!(view.snapshot().is_none());
    insta::assert_snapshot!(text(&render(&mut view, &cells, /*width*/ 20, /*height*/ 2)), @"

    new tail
    ");
}

