fn append_recovered_drafts(&mut self, drafts: &str) {
        self.flush_pending_input();
        self.dismiss_sparkle();
        if self.draft.textarea.is_vim_operator_pending() {
            self.draft.textarea.enter_vim_normal_mode();
        }
        self.finish_vim_edit();
        let mut vim_state = VimPersistentState::default();
        self.draft
            .textarea
            .swap_vim_persistent_state(&mut vim_state);
        let started_vim_edit = self.begin_direct_vim_edit();
        // Recovered answers turn the draft into a prompt, so escape any command prefix
        // before appending them. Command modes store their prefix outside the textarea.
        let text = self.current_text();
        let slash_command_draft = self.slash_input().should_parse_on_dequeue(&text)
            && parse_slash_name(text.trim_start()).is_none_or(|(name, _, _)| !name.contains('/'));
        if self.draft.prompt_prefix == PromptPrefix::Shell
            || (self.draft.prompt_prefix == PromptPrefix::Slash && slash_command_draft)
        {
            self.unmark_slash_command_element();
            let prefix = self.draft.prompt_prefix.text();
            self.draft.prompt_prefix = PromptPrefix::None;
            self.draft
                .textarea
                .insert_str_at(/*pos*/ 0, &format!("\\{prefix}"));
        } else if self.is_bang_shell_command() || slash_command_draft {
            let prefix_len =
                self.draft.textarea.text().len() - self.draft.textarea.text().trim_start().len();
            self.draft.textarea.insert_str_at(prefix_len, "\\");
        }
        self.move_cursor_to_end();
        if !self.current_text().is_empty() {
            self.insert_str("\n\n");
        }
        let char_count = drafts.chars().count();
        if char_count > LARGE_PASTE_CHAR_THRESHOLD {
            let placeholder = self.next_large_paste_placeholder(char_count);
            self.draft.textarea.insert_element(&placeholder);
            self.draft.pending_pastes.push((placeholder, drafts.into()));
            self.sync_popups();
        } else {
            self.insert_str(drafts);
        }
        self.draft
            .textarea
            .swap_vim_persistent_state(&mut vim_state);
        if started_vim_edit {
            self.finish_vim_edit();
        }
    }

fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.height == 0 || area.width == 0 {
            return;
        }

        Block::default()
            .style(user_message_style())
            .render(area, buf);

        let actions_height = self.action_rows_height(area.width);
        let hint = Paragraph::new(self.hint_line())
            .dim()
            .wrap(Wrap { trim: false });
        let hint_height = hint.line_count(area.width.saturating_sub(/*rhs*/ 2)) as u16;
        let [content_area, actions_area, hint_area] = Layout::vertical([
            Constraint::Fill(1),
            Constraint::Length(actions_height),
            Constraint::Length(hint_height),
        ])
        .areas(area);

        let inner = content_area.inset(Insets::vh(/*v*/ 1, /*h*/ 2));
        let content_width = inner.width.max(1);
        let lines = self.content_lines(content_width);
        Paragraph::new(lines)
            .wrap(Wrap { trim: false })
            .render(inner, buf);
        crate::terminal_hyperlinks::mark_url_hyperlink(buf, inner, &self.url);

        if actions_area.height > 0 {
            let action_rows = self.action_rows();
            let action_state = self.action_state();
            render_rows(
                actions_area,
                buf,
                &action_rows,
                &action_state,
                action_rows.len().max(1),
                "No actions",
            );
        }

        if hint_area.height > 0 {
            let hint_area = Rect {
                x: hint_area.x.saturating_add(2),
                y: hint_area.y,
                width: hint_area.width.saturating_sub(2),
                height: hint_area.height,
            };
            hint.render(hint_area, buf);
        }
    }

