fn wrap_preview_lines(
    lines: impl IntoIterator<Item = Line<'static>>,
    options: RtOptions<'static>,
) -> Vec<HyperlinkLine> {
    lines
        .into_iter()
        .enumerate()
        .flat_map(|(index, line)| {
            let source = crate::terminal_hyperlinks::annotate_web_urls_in_line(line);
            let options = if index == 0 {
                options.clone()
            } else {
                options
                    .clone()
                    .initial_indent(options.subsequent_indent.clone())
            };
            let width = options.width;
            let wrapped = crate::wrapping::adaptive_wrap_line_with_source(&source.line, options);
            let mut lines = crate::terminal_hyperlinks::remap_source_wrapped_line(&source, wrapped);
            for line in &mut lines {
                line.line =
                    crate::line_truncation::truncate_line_to_width(line.line.clone(), width);
                let visible_width = crate::line_truncation::line_width(&line.line);
                line.hyperlinks.retain_mut(|link| {
                    link.columns.end = link.columns.end.min(visible_width);
                    !link.columns.is_empty()
                });
            }
            lines
        })
        .collect()
}

fn split_flap_frames_assemble_a_transcript_from_dark_tiles() {
    let board = cell("GATE 73", MotionMode::Animated);
    let frames = [0, 45, 90, 180, 285, 675]
        .into_iter()
        .map(|milliseconds| format!("{milliseconds:>3}ms {}", frame(&board, milliseconds)))
        .collect::<Vec<_>>()
        .join("\n");

    insta::assert_snapshot!(frames, @r"
      0ms ›
     45ms › T
     90ms › ATGG AG
    180ms › GGTT ET GAT
    285ms › GATE 73 TEG
    675ms › GATE 73
    ");

    let punctuated = cell("HELLO, WORLD?!", MotionMode::Animated);
    assert!(!frame(&punctuated, /*milliseconds*/ 90).contains(','));
    assert!(!frame(&punctuated, /*milliseconds*/ 180).contains(','));
    assert_eq!(frame(&punctuated, /*milliseconds*/ 285), "› HELLO, WORLD?!");
    assert_ne!(
        frame(&board, /*milliseconds*/ 285),
        frame(&board, /*milliseconds*/ 330)
    );

    let lowercase = cell("please keep going", MotionMode::Animated);
    assert!(lowercase.flap_sample.iter().all(u8::is_ascii_lowercase));
    for elapsed in [90, 285] {
        assert!(
            frame(&lowercase, elapsed)
                .chars()
                .all(|ch| !ch.is_ascii_uppercase())
        );
    }
}

