        let reason = if note.is_empty() { None } else { Some(note) };
        self.app_event_tx.send(AppEvent::SubmitFeedback {
            category: self.category,
            reason,
            turn_id: self.turn_id.clone(),
            include_logs: self.include_logs,
        });
        self.complete = true;
    }

fn take_text_result(&mut self) -> Option<Result<String, String>> {
        let (deadline, owner, result) = self.read_result.take()?;
        (owner.strong_count() > 0).then(|| {
            if Instant::now() >= deadline {
                Err("clipboard read timed out".into())
            } else {
                result
            }
        })
    }

