    let screen_size = terminal.last_known_screen_size;
    crate::insert_history::insert_history_hyperlink_lines_with_mode_and_wrap_policy(
        &mut terminal,
        &previous_lines,
        InsertHistoryMode::Standard,
        HistoryLineWrapPolicy::Terminal,
        screen_size,
