fn history_search_preserves_a_held_sparkle_command_without_reclassifying_it() {
    palette(|| {
        let now = Instant::now();
        let during = now + Duration::from_secs(/*secs*/ 4);
        let mut snapshots = Vec::new();
        for model in ["gpt-6-astra", "gpt-5.5"] {
            for cancel in ["escape", "control-c"] {
                let mut pane = pane();
                pane.composer.set_disable_paste_burst(/*disabled*/ false);
                pane.mark_fresh_task_for_sparkle(model, &enabled());
                pane.composer
                    .history
                    .record_local_submission(HistoryEntry::new("history prompt".into()));
                let initial = draw(&pane.composer, /*width*/ 80, now).0;
                let expected = draw(&pane.composer, /*width*/ 80, during).0;
                assert_eq!(dots(&initial).is_empty(), model == "gpt-5.5");
                key(&mut pane, KeyCode::Char('/'));
                assert!(pane.composer.is_in_paste_burst());
                assert_eq!(pane.composer.current_text(), "");
                assert_eq!(pane.composer.sparkle.draft.get(), SparkleDraft::Command);
                pane.handle_key_event(KeyEvent::new(KeyCode::Char('r'), KeyModifiers::CONTROL));
                assert!(pane.composer.history_search_active());
                assert_eq!(pane.composer.current_text(), "/");
                assert_eq!(pane.composer.sparkle.draft.get(), SparkleDraft::Command);
                pane.handle_paste("history".into());
                assert_eq!(pane.composer.current_text(), "history prompt");
                pane.set_composer_pending_pastes(Vec::new());
                assert_eq!(pane.composer.sparkle.draft.get(), SparkleDraft::Command);
                let searching = draw(&pane.composer, /*width*/ 80, during).0;
                assert!(dots(&searching).is_empty());

                if cancel == "escape" {
                    key(&mut pane, KeyCode::Esc);
                } else {
                    pane.on_ctrl_c();
                }
                assert_eq!(pane.composer.current_text(), "/");
                key(&mut pane, KeyCode::Backspace);
                assert_eq!(pane.composer.sparkle.draft.get(), SparkleDraft::Untouched);
                let erased = draw(&pane.composer, /*width*/ 80, during).0;
                assert_eq!(dots(&erased), dots(&expected));
                type_text(&mut pane, "/model");
                pane.composer
                    .handle_paste_burst_flush(now + Duration::from_secs(/*secs*/ 1));
                assert!(matches!(
                    key(&mut pane, KeyCode::Enter),
                    InputResult::Command(SlashCommand::Model)
                ));
                pane.select_sparkle_model("gpt-6-astra", &enabled());
                let selected = draw(&pane.composer, /*width*/ 80, during).0;
                assert!(!dots(&selected).is_empty());
                if cancel == "escape" {
                    snapshots.push(format!("{model}\nsearching with an explicit pasted query:\n{}\nafter canceling and erasing the slash:\n{}\nafter /model selects Astra:\n{}", text(&searching), text(&erased), text(&selected)));
                }
            }
        }
        insta::assert_snapshot!(snapshots.join("\n\n"));
    });
}

fn done_only_caption_cannot_retire_a_newer_voice_answer() {
    let (mut chat, _sender, mut events, mut ops) = make_chatwidget_manual_with_sender().await;
    let thread_id = activate_voice(&mut chat);
    let turn_id = "done-only-turn";
    start_item(
        &mut chat,
        thread_id,
        turn_id,
        user_item("<realtime_delegation><input>question</input></realtime_delegation>"),
    );
    let answer = agent_item("answer", "New answer", Some(MessagePhase::FinalAnswer));
    start_item(&mut chat, thread_id, turn_id, answer.clone());
    complete_item(&mut chat, thread_id, turn_id, answer.clone());
    finish_turn(
        &mut chat,
        thread_id,
        turn_id,
        vec![answer],
        TurnStatus::Completed,
    );
    let AppCommand::RealtimeConversationSpeech { delivery_id, .. } = ops.try_recv().unwrap() else {
        panic!("completed voice turn should queue speech");
    };
    while events.try_recv().is_ok() {}
    chat.accept_realtime_speech(delivery_id);
    assert!(
        chat.realtime_conversation
            .assistant_transcript_generation
            .is_none()
    );
    chat.on_realtime_transcript_done("assistant".into(), "Old done-only caption".into());
    assert_eq!(chat.realtime_conversation.pending_speech.len(), 1);
    chat.on_realtime_conversation_closed(Some("transport_closed".into()));
    let restored = std::iter::from_fn(|| events.try_recv().ok())
        .filter_map(|event| match event {
            AppEvent::InsertHistoryCell(cell) => Some(
                cell.display_lines(/*width*/ 80)
                    .into_iter()
                    .map(|line| line.to_string())
                    .collect::<Vec<_>>()
                    .join("\n"),
            ),
            _ => None,
        })
        .filter(|text| text.contains("New answer"))
        .count();
    assert_eq!(restored, 1);
}

fn focus_loss_stops_edge_drag_and_preserves_selection_after_focus_returns() -> Result<()> {
    use crossterm::event::KeyModifiers;
    use crossterm::event::MouseButton;
    use crossterm::event::MouseEvent;
    use crossterm::event::MouseEventKind;
    use ratatui::layout::Size;

    let mut overlay = transcript_overlay(vec![Arc::new(TestCell {
        lines: (0..30).map(|row| format!("row {row:02}").into()).collect(),
    })]);
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 40, /*height*/ 12,
    );
    overlay.render(area, &mut Buffer::empty(area));
    overlay.view.jump_to_entry(&overlay.cells, /*index*/ 0);
    overlay.render(area, &mut Buffer::empty(area));
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.terminal.resize(Size::new(area.width, area.height))?;
    for (kind, column, row) in [
        (MouseEventKind::Down(MouseButton::Left), 0, 2),
        (MouseEventKind::Drag(MouseButton::Left), 6, 7),
    ] {
        overlay.handle_event(
            &mut tui,
            TuiEvent::Mouse(MouseEvent {
                kind,
                column,
                row,
                modifiers: KeyModifiers::NONE,
            }),
        )?;
    }
    assert!(overlay.view.tick_selection(&overlay.cells));
    let mut before = Buffer::empty(area);
    overlay.render(area, &mut before);
    let selected = overlay.view.selected_text(&overlay.cells);
    assert_eq!(
        selected.as_deref(),
        Some("row 01\nrow 02\nrow 03\nrow 04\nrow 05\nrow 06\nrow 07")
    );
    tui.screen_size_for_event(&TuiEvent::Draw)?;
    overlay.draw(&mut tui)?;
    let mut repainted = Buffer::empty(area);
    overlay.render(area, &mut repainted);
    assert_eq!(repainted, before);

    for event in [
        TuiEvent::Resume,
        TuiEvent::FocusLost,
        TuiEvent::Draw,
        TuiEvent::FocusGained,
        TuiEvent::Draw,
    ] {
        let resumed = matches!(event, TuiEvent::Resume);
        tui.screen_size_for_event(&event)?;
        overlay.handle_event(&mut tui, event)?;
        if resumed {
            let rendered =
                crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal);
            assert!(buffer_to_text(rendered, rendered.area).contains("row 01"));
        }
        assert!(!overlay.view.tick_selection(&overlay.cells));
        let mut after = Buffer::empty(area);
        overlay.render(area, &mut after);
        assert_eq!(after, before);
        assert_eq!(overlay.view.selected_text(&overlay.cells), selected);
    }
    let content_and_status = Rect::new(
        /*x*/ 0, /*y*/ 1, /*width*/ 40, /*height*/ 8,
    );
    assert_snapshot!(buffer_to_text(&before, content_and_status), @"
    row 01
    row 02
    row 03
    row 04
    row 05
    row 06
    row 07
    enter copy & follow · esc clear
    ");
    overlay.view.jump_to_latest();
    overlay.render(area, &mut Buffer::empty(area));
    overlay.handle_event(
        &mut tui,
        TuiEvent::Mouse(MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Left),
            column: 1,
            row: 2,
            modifiers: KeyModifiers::NONE,
        }),
    )?;
    assert_eq!(overlay.view.selected_text(&overlay.cells), None);
    overlay.handle_event(&mut tui, TuiEvent::FocusLost)?;
    overlay.handle_event(&mut tui, TuiEvent::FocusGained)?;
    overlay.insert_cell(Arc::new(TestCell {
        lines: vec!["new output".into()],
    }));
    let mut after = Buffer::empty(area);
    overlay.render(area, &mut after);
    assert!(overlay.is_scrolled_to_bottom());
    assert_eq!(overlay.view.selected_text(&overlay.cells), None);
    assert!(buffer_to_text(&after, area).contains("new output"));
    Ok(())
}

