fn parse_osc_rgb(payload: &str) -> Option<(u8, u8, u8)> {
    let (prefix, values) = payload.trim().split_once(':')?;
    if !prefix.eq_ignore_ascii_case("rgb") && !prefix.eq_ignore_ascii_case("rgba") {
        return None;
    }

    let mut parts = values.split('/');
    let r = parse_osc_component(parts.next()?)?;
    let g = parse_osc_component(parts.next()?)?;
    let b = parse_osc_component(parts.next()?)?;
    if prefix.eq_ignore_ascii_case("rgba") {
        parse_osc_component(parts.next()?)?;
    }
    parts.next().is_none().then_some((r, g, b))
}

fn is_same_physical_key(self, other: Self) -> bool {
        let physical_code = |binding: Self| match binding.normalized_parts().0 {
            KeyCode::BackTab => KeyCode::Tab,
            code => code,
        };
        physical_code(self) == physical_code(other)
    }

fn default_vim_jump_top_uses_contextual_gg_chords() {
    let runtime = RuntimeKeymap::defaults();
    let g = key_event(key_hint::plain(KeyCode::Char('g')));

    for (context, action, target) in [
        (
            KeymapContext::VimNormal,
            "jump_top",
            runtime.vim_normal.jump_top.as_slice(),
        ),
        (
            KeymapContext::VimOperator,
            "motion_jump_top",
            runtime.vim_operator.motion_jump_top.as_slice(),
        ),
    ] {
        let action_id = keymap_action_id(context.config_name(), action).expect("known Vim action");
        assert!(runtime.chords.bindings.iter().any(|binding| {
            binding.action == action_id
                && binding.chord.prefix == key_hint::plain(KeyCode::Char('g'))
                && binding.chord.completion == key_hint::plain(KeyCode::Char('g'))
        }));
        assert!(matches!(
            runtime.primary_hint(context, action),
            Some(crate::key_hint::ShortcutHint::Chord { .. })
        ));

        let mut matcher = KeyChordMatcher::default();
        let contexts = KeymapContextSet::new(context);
        assert!(matches!(
            matcher.advance(g, &runtime.chords, contexts),
            KeyChordMatch::Pending(_)
        ));
        let KeyChordMatch::Completed(event) = matcher.advance(g, &runtime.chords, contexts) else {
            panic!("gg must dispatch the active Vim jump action");
        };
        assert!(target.is_pressed(event));
    }
}

fn long_paths_keep_distinguishing_filenames_and_original_selection() {
        let mut snapshots = Vec::new();
        for components in [
            vec!["src", "shared", "long_directory"],
            vec!["long_directory_name_that_fills_row"],
            vec!["長いディレクトリ名", "e\u{301}tudes"],
        ] {
            let parent: PathBuf = components.iter().collect();
            let paths: Vec<PathBuf> = ["parser_alpha.rs", "parser_beta.rs"]
                .into_iter()
                .map(|name| parent.join(name))
                .collect();
            let mut popup = FileSearchPopup::new();
            popup.set_query("parser");
            popup.set_matches(
                "parser",
                paths
                    .iter()
                    .enumerate()
                    .map(|(index, path)| {
                        let mut matched = file_match(index);
                        matched.path = path.clone();
                        matched.indices =
                            fuzzy_match(&path.to_string_lossy(), "parser").map(|(indices, _)| {
                                indices.into_iter().map(|index| index as u32).collect()
                            });
                        matched
                    })
                    .collect(),
            );
            for (selected, path) in paths.iter().enumerate() {
                for width in [28, 40, 80] {
                    let area = Rect::new(
                        /*x*/ 0,
                        /*y*/ 0,
                        width,
                        popup.calculate_required_height(),
                    );
                    let mut buf = Buffer::empty(area);
                    (&popup).render_ref(area, &mut buf);
                    let text = buf
                        .content
                        .chunks(usize::from(width))
                        .map(|row| {
                            row.iter()
                                .map(ratatui::buffer::Cell::symbol)
                                .collect::<String>()
                                .trim_end()
                                .replace(std::path::MAIN_SEPARATOR, "/")
                        })
                        .collect::<Vec<_>>()
                        .join("\n");
                    assert!(
                        text.contains("parser_alpha.rs") && text.contains("parser_beta.rs"),
                        "{text}"
                    );
                    assert_eq!(popup.selected_match(), Some(path));
                    let unselected_y = if selected == 0 { 2 } else { 1 };
                    let parser_x = (0..width.saturating_sub(/*rhs*/ 5))
                        .find(|&x| {
                            (x..x + 6)
                                .map(|column| buf[(column, unselected_y)].symbol())
                                .eq(["p", "a", "r", "s", "e", "r"])
                        })
                        .expect("visible filename match");
                    assert!(
                        buf[(parser_x, unselected_y)]
                            .modifier
                            .contains(ratatui::style::Modifier::BOLD)
                    );
                    if selected == 0 {
                        snapshots.push(format!("{components:?}, width {width}\n{text}"));
                    }
                }
                popup.move_down();
            }
        }
        insta::assert_snapshot!(snapshots.join("\n\n"));
    }

