fn recap_tabs_preserve_url_wrapping_and_source_across_resize() {
    let recap = "\thttps://example.com";
    let cell = ThreadRecapHistoryCell::new(recap.to_owned());
    let wide = TextLayout::new(
        cell.display_hyperlink_lines(/*width*/ 80),
        /*width*/ 80,
    );
    let narrow = wide.rewrap(/*width*/ 32);
    assert_eq!(narrow.text(), recap);
    assert_eq!(
        narrow
            .rows
            .iter()
            .map(|row| row.line.line.to_string())
            .collect::<Vec<_>>(),
        ["  ↳ Recap:      ", "           https://example.com"],
    );
    let area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        /*width*/ 32,
        narrow.row_count() as u16,
    );
    let mut buffer = Buffer::empty(area);
    narrow.render(area, &mut buffer, /*start_row*/ 0);
    let restored = narrow.rewrap(/*width*/ 80).rewrap(/*width*/ 32);
    let mut restored_buffer = Buffer::empty(area);
    restored.render(area, &mut restored_buffer, /*start_row*/ 0);
    assert_eq!(restored_buffer, buffer);
    let link_start = recap.find("https://").expect("URL in recap");
    assert_eq!(
        narrow.position_at(
            narrow.row_for_offset(link_start),
            narrow.column_for_offset(link_start)
        ),
        link_start,
    );
}

fn recovery_keeps_unselected_text_after_a_held_replace_key() {
    for (text, expected) in [("abcd", "aXd"), ("!abcd", "!aXd")] {
        let (mut composer, _rx) = new_test_composer();
        composer.set_text_content(text.into(), Vec::new(), Vec::new());
        composer.draft.textarea.set_cursor(/*pos*/ 0);
        composer.set_vim_enabled(/*enabled*/ true);
        composer.handle_key_event(KeyCode::Char('R').into());
        let area = Rect::new(
            /*x*/ 0, /*y*/ 0, /*width*/ 80, /*height*/ 4,
        );
        composer.render(area, &mut Buffer::empty(area));
        let (x, y) = composer.cursor_pos(area).unwrap();
        for (kind, column) in [
            (Down(Left), x + 1),
            (MouseEventKind::Drag(Left), x + 3),
            (Up(Left), x + 3),
        ] {
            mouse(&mut composer, area, kind, column, y);
        }
        let now = Instant::now();
        composer.handle_input_basic_with_time(KeyCode::Char('X').into(), now);
        let before = composer.draft_snapshot();
        assert_eq!(composer.recovery_snapshot().text, expected);
        assert_eq!(composer.draft_snapshot(), before);
        assert!(composer.handle_paste_burst_flush(now + PasteBurst::recommended_flush_delay()));
        assert_eq!(composer.current_text(), expected);
    }
}

fn parses_cursor_position_as_zero_based() {
            assert_eq!(
                parse_cursor_position(b"\x1B[20;10R"),
                Some(Position { x: 9, y: 19 })
            );
            assert_eq!(
                parse_cursor_position(b"\x1B[I\x1B[20;10R"),
                Some(Position { x: 9, y: 19 })
