            runtime_keymap: &'a RuntimeKeymap,
            context: &str,
            action: &str,
        ) -> Option<&'a [KeyBinding]> {
            match (context, action) {
                ("global", "leader") => Some(runtime_keymap.chords.leader.as_slice()),
