fn apply_selection(&mut self, actual_idx: usize) {
        if self.current_complete {
            return;
        }
        let Some(option) = self.options.get(actual_idx) else {
            return;
        };
        if let Some(request) = self.current_request.as_ref() {
            match (request, &option.decision) {
                (ApprovalRequest::Exec(request), ApprovalDecision::Command(decision)) => {
                    self.handle_exec_decision(&request.id, &request.command, decision.clone());
                }
                (
                    ApprovalRequest::Permissions(request),
                    ApprovalDecision::Permissions(decision),
                ) => {
                    self.handle_permissions_decision(
                        &request.call_id,
                        &request.permissions,
                        *decision,
                    );
                }
                (ApprovalRequest::ApplyPatch(request), ApprovalDecision::FileChange(decision)) => {
                    self.handle_patch_decision(&request.id, decision.clone());
                }
                (
                    ApprovalRequest::McpElicitation(request),
                    ApprovalDecision::McpElicitation(decision),
                ) => {
                    self.handle_elicitation_decision(
                        &request.server_name,
                        &request.request_id,
                        *decision,
                    );
                }
                _ => {}
            }
        }

        self.current_complete = true;
        self.advance_queue();
    }

fn format_action_binding_summary(
    runtime_keymap: &RuntimeKeymap,
    context: &str,
    action: &str,
) -> String {
    let specs = super::active_binding_specs(runtime_keymap, context, action).unwrap_or_else(|_| {
        bindings_for_action(runtime_keymap, context, action)
            .unwrap_or_default()
            .iter()
            .filter_map(|binding| super::binding_to_config_key_spec(*binding).ok())
            .collect()
    });
    let mut seen = BTreeSet::new();
    let specs = specs
        .into_iter()
        .filter(|spec| seen.insert(spec.clone()))
        .map(|spec| {
            let Some(completion) = spec.strip_prefix("leader ") else {
                return spec;
            };
            let resolved = runtime_keymap
                .chords
                .leader
                .iter()
                .filter_map(|prefix| super::binding_to_config_key_spec(*prefix).ok())
                .map(|prefix| format!("{prefix} {completion}"))
                .collect::<Vec<_>>();
            if resolved.is_empty() {
                format!("{spec} (inactive)")
            } else {
                format!("{spec} ({})", resolved.join(", "))
            }
        })
        .collect::<Vec<_>>();
    if specs.is_empty() {
        "unbound".to_string()
    } else {
        specs.join(", ")
    }
}

