fn render_disclosure(
        &self,
        ids: &[String],
        layout: &TextLayout,
        row: usize,
        area: Rect,
        buf: &mut Buffer,
    ) {
        let focused = self
            .disclosure
            .focused
            .as_ref()
            .is_some_and(|focused| ids.iter().any(|id| focused.contains(id)));
        if !focused || !layout.disclosure {
            return;
        }
        if layout.disclosure_row() == Some(row) {
            let columns = layout.disclosure_columns();
            buf.set_style(
                Rect::new(
                    area.x + columns.start,
                    area.y,
                    columns.end - columns.start,
                    /*height*/ 1,
                ),
                Style::default()
                    .fg(accent_color())
                    .bold()
                    .remove_modifier(Modifier::DIM),
            );
        } else if row == usize::from(layout.separated) {
            buf.set_style(area, Style::default().underlined());
        }
    }

fn fullscreen_session_lines(
    cell: &dyn HistoryCell,
    width: u16,
    detailed: bool,
    mode: HistoryRenderMode,
) -> Vec<HyperlinkLine> {
    if let Some(info) = cell.as_any().downcast_ref::<SessionInfoCell>() {
        let mut lines = Vec::new();
        for part in &info.0.parts {
            if part.as_any().is::<TooltipHistoryCell>() {
                continue;
            }
            let part_lines = fullscreen_session_lines(part.as_ref(), width, detailed, mode);
            if !part_lines.is_empty() {
                if !lines.is_empty() {
                    lines.push(HyperlinkLine::from(""));
                }
                lines.extend(part_lines);
            }
        }
        lines
    } else if detailed || mode == HistoryRenderMode::Rich {
        cell.retained_hyperlink_lines(width, detailed)
    } else {
        cell.display_hyperlink_lines_for_mode(width, mode)
    }
}

fn update_inline_viewport_for_resize_reflow(
        terminal: &mut Terminal,
        height: u16,
        screen_size: Size,
        scrollback: ScrollbackStrategy,
    ) -> Result<bool> {
        let terminal_height_shrank = screen_size.height < terminal.last_known_screen_size.height;
        let terminal_height_grew = screen_size.height > terminal.last_known_screen_size.height;
        let viewport_was_bottom_aligned =
            terminal.viewport_area.bottom() == terminal.last_known_screen_size.height;
        let previous_area = terminal.viewport_area;

        let mut area = terminal.viewport_area;
        area.height = height.min(screen_size.height);
        area.width = screen_size.width;
        let mut needs_full_repaint = false;

        if area.bottom() > screen_size.height {
            let scroll_by = area.bottom() - screen_size.height;
            if !terminal_height_shrank {
                scrollback.grow_viewport(terminal, area.top(), screen_size, scroll_by)?;
            }
            area.y = screen_size.height - area.height;
        } else if terminal_height_grew && viewport_was_bottom_aligned {
            area.y = screen_size.height - area.height;
        }

        if area != terminal.viewport_area {
            let clear_position = Position::new(/*x*/ 0, previous_area.y.min(area.y));
            terminal.set_viewport_area(area);
            terminal.clear_after_position(clear_position)?;
            needs_full_repaint = true;
        }

        Ok(needs_full_repaint)
    }

