fn selection_at_bottom_restores_footer_without_resuming_following() {
    let cells: Vec<Arc<dyn HistoryCell>> = vec![Arc::new(PlainHistoryCell::new(vec![
        "one".into(),
        "two".into(),
        "three".into(),
        "four".into(),
        "needle final".into(),
    ]))];
    let mut observations = Vec::new();
    for history in [
        TranscriptHistoryState::Partial,
        TranscriptHistoryState::Complete,
    ] {
        let mut view = TranscriptView {
            history,
            ..TranscriptView::default()
        };
        let initial = render(&mut view, &cells);
        assert!(view.tail_visible);
        assert!(view.is_following());
        assert!(view.footer(/*width*/ 120, MotionMode::Reduced).is_none());

        for (label, events) in [
            (
                "selected at bottom",
                vec![
                    (MouseEventKind::Down(MouseButton::Left), 0, 2),
                    (MouseEventKind::Drag(MouseButton::Left), 6, 2),
                    (MouseEventKind::Up(MouseButton::Left), 6, 2),
                ],
            ),
            (
                "clicked away",
                vec![
                    (MouseEventKind::Down(MouseButton::Left), 0, 1),
                    (MouseEventKind::Up(MouseButton::Left), 0, 1),
                ],
            ),
            (
                "scrolled down at bottom",
                vec![(MouseEventKind::ScrollDown, 0, 1)],
            ),
        ] {
            let mut buffer = initial.clone();
            for (kind, column, row) in events {
                view.handle_mouse(
                    MouseEvent {
                        kind,
                        column,
                        row,
                        modifiers: KeyModifiers::NONE,
                    },
                    &cells,
                );
                buffer = render(&mut view, &cells);
            }
            assert!(view.tail_visible);
            assert_eq!(
                crate::transcript_view::tests::text(&buffer),
                crate::transcript_view::tests::text(&initial),
            );
            let selected = label == "selected at bottom";
            assert_eq!(
                view.selected_text(&cells).as_deref(),
                selected.then_some("needle"),
            );
            assert_eq!(view.is_following(), label == "scrolled down at bottom");
            let footer = view.footer(/*width*/ 120, MotionMode::Reduced);
            let hint = footer.map_or_else(
                || "<composer hints>".to_owned(),
                |footer| footer.text.to_string(),
            );
            observations.push(format!("{history:?}, {label}: {hint}"));
        }
        view.scroll(&cells, /*rows*/ -1);
        render(&mut view, &cells);
        view.begin_selection(&cells, /*column*/ 0, /*row*/ 0, /*clicks*/ 3);
        view.end_drag();
        render(&mut view, &cells);
        assert!(!view.tail_visible);
        assert_eq!(view.selected_text(&cells).as_deref(), Some("two\n"));
        let footer = view.footer(/*width*/ 120, MotionMode::Reduced).unwrap();
        observations.push(format!(
            "{history:?}, selected above bottom: {}",
            footer.text
        ));
    }
    insta::assert_snapshot!(observations.join("\n"), @"
    Partial, selected at bottom: ⌃c copy · enter copy & follow · esc clear
    Partial, clicked away: <composer hints>
    Partial, scrolled down at bottom: <composer hints>
    Partial, selected above bottom: Earlier messages available.  ⌃c copy · enter copy & follow · esc clear
    Complete, selected at bottom: ⌃c copy · enter copy & follow · esc clear
    Complete, clicked away: <composer hints>
    Complete, scrolled down at bottom: <composer hints>
    Complete, selected above bottom: ⌃c copy · enter copy & follow · esc clear
    ");
}

fn find_owns_editor_chords_without_changing_the_composer_draft() -> Result<()> {
    let mut app = crate::app::test_support::make_test_app().await;
    app.transcript_cells = vec![user_cell("alpha beta")];
    app.chat_widget
        .apply_external_edit("draft remains intact".to_string());
    app.keymap = RuntimeKeymap::from_config(&serde_json::from_value(serde_json::json!({
        "global": {"find_transcript": "f4", "open_external_editor": "ctrl-g e"},
        "editor": {"move_line_start": "ctrl-x h"},
        "pager": {"find": "f4"}
    }))?)
    .expect("independent query bindings");
    let mut app_server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    for owned in [true, false] {
        tui.set_owned_screen(owned)?;
        if !owned {
            app.open_transcript_overlay(&mut tui);
        }
        for event in [
            TuiEvent::Key(KeyEvent::new(KeyCode::F(4), KeyModifiers::NONE)),
            TuiEvent::Draw,
            TuiEvent::Key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::CONTROL)),
            TuiEvent::Key(KeyEvent::new(KeyCode::Right, KeyModifiers::NONE)),
            TuiEvent::Paste("alpha beta".to_string()),
            // A global chord cannot own the next query character.
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::CONTROL)),
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE)),
            // Configured editor chords use the same query TextArea.
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::CONTROL)),
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('h'), KeyModifiers::NONE)),
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('f'), KeyModifiers::CONTROL)),
            TuiEvent::Key(KeyEvent::new(KeyCode::Delete, KeyModifiers::NONE)),
        ] {
            let pasted = matches!(event, TuiEvent::Paste(_));
            app.handle_tui_event(&mut tui, &mut app_server, event)
                .await?;
            if pasted {
                app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Draw)
                    .await?;
                let rendered = buffer_text(
                    crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal),
                );
                assert!(
                    rendered.contains("enter accept"),
                    "Find must resume after pasting over selection"
                );
            }
            if app.key_chord_matcher.is_pending() {
                app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Draw)
                    .await?;
                let rendered = buffer_text(
                    crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal),
                );
                let cursor = tui.terminal.last_known_cursor_pos;
                let query_row = rendered
                    .lines()
                    .nth(usize::from(cursor.y))
                    .expect("visible query caret");
                assert_eq!(query_row.trim(), "Find: alpha betax");
                assert!(rendered.contains("h move line start"));
                insta::assert_snapshot!(
                    "owned_find_pending_chord_footer",
                    rendered
                        .lines()
                        .skip(usize::from(cursor.y))
                        .take(/*n*/ 2)
                        .map(str::trim)
                        .collect::<Vec<_>>()
                        .join("\n")
                );
            }
        }
        app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Draw)
            .await?;
        let rendered = buffer_text(crate::custom_terminal::test_support::last_rendered_buffer(
            &tui.terminal,
        ));
        assert!(
            rendered
                .lines()
                .any(|line| line.trim() == "Find: apha betax")
        );
        assert_eq!(
            app.chat_widget.composer_text_with_pending(),
            "draft remains intact"
        );
        app.handle_tui_event(
            &mut tui,
            &mut app_server,
            TuiEvent::Key(KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL)),
        )
        .await?;
        assert!(!match &app.overlay {
            Some(Overlay::Transcript(overlay)) => overlay.is_search_editing(),
            _ => app.transcript_view.is_search_editing(),
        });
        assert_eq!(
            app.chat_widget.composer_text_with_pending(),
            "draft remains intact"
        );
        app.close_transcript_overlay(&mut tui);
    }
    tui.set_owned_screen(/*owned*/ false)?;
    app_server.shutdown().await?;
    Ok(())
}

