}

fn find_next_mention_token_range(text: &str, token: &str, from: usize) -> Option<Range<usize>> {
    if token.is_empty() || from >= text.len() {
        return None;
    }
    let bytes = text.as_bytes();
    let token_bytes = token.as_bytes();
    let sigil = *token_bytes.first()?;
    let mut index = from;

    while index < bytes.len() {
        if bytes[index] != sigil {
            index += 1;
            continue;
        }

        let end = index.saturating_add(token_bytes.len());
        if end > bytes.len() {
            return None;
        }
        if &bytes[index..end] != token_bytes {
            index += 1;
            continue;
        }

        // Fix for restored `@` mentions: rebinding must not attach to embedded substrings such
        // as email addresses, while preserving the existing `$` mention matching behavior.
        let starts_plaintext_mention = if sigil == b'@' {
            starts_plaintext_at_mention(text, index)
        } else {
            true
        };
        // Fix for restored `@` mentions: mirror history encoding's trailing boundary so path-like
        // text such as `@sample/pkg` is not rebound as the plain `@sample` mention.
        let ends_plaintext_mention = if sigil == b'@' {
            ends_plaintext_at_mention(bytes, end)
        } else {
            ends_plaintext_at_dollar_mention(bytes, end)
        };

        if starts_plaintext_mention && ends_plaintext_mention {
            return Some(index..end);
        }

        index = end;
    }

    None
}

fn render_ref(&self, area: Rect, buf: &mut Buffer) {
        // Convert matches to GenericDisplayRow, translating indices to usize at the UI boundary.
        let rows_all: Vec<GenericDisplayRow> = if self.matches.is_empty() {
            Vec::new()
        } else {
            self.matches
                .iter()
                .enumerate()
                .map(|(idx, m)| {
                    let path = m.path.to_string_lossy();
                    let width = usize::from(area.width.saturating_sub(/*rhs*/ 2));
                    let name = if display_width(&path) <= width {
                        path.to_string()
                    } else {
                        let filename = m
                            .path
                            .file_name()
                            .unwrap_or(m.path.as_os_str())
                            .to_string_lossy();
                        let filename_width = display_width(&filename);
                        if let Some(parent) = m.path.parent()
                            && filename_width + 2 <= width
                        {
                            let parent = truncate_line_with_ellipsis_if_overflow(
                                Line::from(parent.to_string_lossy().into_owned()),
                                width - filename_width - 1,
                            );
                            format!("{parent}{}{filename}", std::path::MAIN_SEPARATOR)
                        } else {
                            center_truncate_path(&filename, width)
                        }
                    };
                    let match_indices = if name == path {
                        m.indices
                            .as_ref()
                            .map(|indices| indices.iter().map(|&index| index as usize).collect())
                    } else {
                        fuzzy_match(&name, &self.display_query).map(|(indices, _)| indices)
                    };
                    GenericDisplayRow {
                        category_tag: None,
                        selection_style: Some(super::picker_style::selection_style()),
                        name,
                        name_prefix_spans: vec![
                            if self.state.selected_idx == Some(idx) {
                                "› "
                            } else {
                                "  "
                            }
                            .into(),
                        ],
                        match_indices,
                        display_shortcut: None,
                        description: None,
                        wrap_indent: None,
                        is_disabled: false,
                        disabled_reason: None,
                    }
                })
                .collect()
        };

        let empty_message = if self.waiting {
            "  loading..."
        } else {
            "  no matches"
        };

        render_rows_single_line(
            area,
            buf,
            &rows_all,
            &self.state,
            MAX_POPUP_ROWS,
            empty_message,
        );
    }

