fn pop_active_view_with_completion(&mut self, completion: Option<ViewCompletion>) {
        if self.view_stack.pop().is_some() {
            match completion {
                Some(ViewCompletion::Accepted) => {
                    while self
                        .view_stack
                        .last()
                        .is_some_and(|view| view.dismiss_after_child_accept())
                    {
                        self.view_stack.pop();
                    }
                }
                Some(ViewCompletion::Cancelled) => {
                    if let Some(view) = self.view_stack.last_mut() {
                        view.clear_dismiss_after_child_accept();
                    }
                }
                None => {}
            }
            self.on_view_stack_depth_decreased();
        }
    }

fn select_boundary(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        end: bool,
    ) -> Option<Anchor> {
        let count = cells.len() + usize::from(self.layout(cells, cells.len()).is_some());
        let mut index = if end { count.checked_sub(1)? } else { 0 };
        loop {
            let layout = self.layout(cells, index)?;
            let offset = if end {
                selectable_graphemes(layout.text())
                    .rfind(|(offset, _)| layout.is_cursor_position(*offset))
                    .map(|(offset, _)| offset)
            } else {
                selectable_graphemes(layout.text())
                    .find(|(offset, _)| layout.is_cursor_position(*offset))
                    .map(|(offset, _)| offset)
            };
            if let Some(offset) = offset {
                return Some(Anchor {
                    key: self.entry_key(cells, index),
                    index,
                    offset,
                    row_bias: 0,
                });
            }
            if end {
                index = index.checked_sub(1)?;
            } else {
                index += 1;
                if index >= count {
                    return None;
                }
            }
        }
    }

fn replacing_the_primary_thread_resets_progress_but_preserves_focus() {
    let now = Instant::now();
    let mut state = RecapState::default();
    state.note_focus_lost(now);
    state.seed_from_progress(
        RecapProgress {
            completed_turns: 3,
            last_recapped_turn_count: Some(3),
        },
