    assert!(!state.should_generate(replaced_at + RECAP_DELAY));
}

fn show_copy_feedback(
        &mut self,
        result: &Result<CopyStatus, String>,
        characters: usize,
    ) {
        if result == &Ok(CopyStatus::Busy)
            && self
                .copy_feedback
                .as_ref()
                .is_some_and(|feedback| matches!(feedback.result, Ok(CopyStatus::Pending(_))))
        {
            return;
        }
        self.copy_feedback = Some(CopyFeedback {
            result: result.as_ref().copied().map_err(|_| ()),
            characters,
            expires_at: (!matches!(result, Ok(CopyStatus::Pending(_))))
                .then(|| Instant::now() + Duration::from_secs(/*secs*/ 5)),
        });
    }

fn vim_word_end_exclusive(&self) -> usize {
        let end = self.end_of_next_word();
        let target = if end > self.cursor_pos {
            self.prev_atomic_boundary(end)
        } else {
            end
        };
        if target == self.cursor_pos && end < self.text.len() {
            self.end_of_next_word_from(end)
        } else {
            end
        }
    }

