fn detect_pet_image_support() -> PetImageSupport {
    if env::var_os("TMUX").is_some() || env::var_os("TMUX_PANE").is_some() {
        return PetImageSupport::Unsupported(PetImageUnsupportedReason::Tmux);
    }

    if env::var_os("ZELLIJ").is_some()
        || env::var_os("ZELLIJ_SESSION_NAME").is_some()
        || env::var_os("ZELLIJ_VERSION").is_some()
    {
        return PetImageSupport::Unsupported(PetImageUnsupportedReason::Zellij);
    }

    if env::var_os("KITTY_WINDOW_ID").is_some() {
        return PetImageSupport::Supported(ImageProtocol::Kitty);
    }

    if env::var_os("WEZTERM_EXECUTABLE").is_some() || env::var_os("WEZTERM_VERSION").is_some() {
        return PetImageSupport::Supported(ImageProtocol::Kitty);
    }

    pet_image_support_for_terminal(&terminal_info())
}

fn screen_size_for_event(&mut self, event: &TuiEvent) -> io::Result<Size> {
        if matches!(event, TuiEvent::Resize(_)) {
            self.schedule_screen_size_recheck(TRANSCRIPT_REFLOW_DEBOUNCE);
        } else if matches!(event, TuiEvent::Draw | TuiEvent::FocusGained)
            && let Some(deadline) = self.screen_size.pending_recheck_at
        {
            let now = Instant::now();
            if now < deadline {
                self.frame_requester.schedule_frame_in(deadline - now);
            } else {
                return self.screen_size_for_event(&TuiEvent::Resume);
            }
        }

        let cached = self.terminal.last_known_screen_size;
        let size = match event {
            TuiEvent::Resize(size) => {
                self.screen_size.deferred_size = None;
                *size
            }
            TuiEvent::Resume => {
                self.screen_size.pending_recheck_at = None;
                self.screen_size.deferred_size = None;
                self.terminal.size()?
            }
            TuiEvent::Draw | TuiEvent::FocusGained => {
                self.screen_size.deferred_size.take().unwrap_or(cached)
            }
            TuiEvent::Key(_) | TuiEvent::Mouse(_) | TuiEvent::Paste(_) | TuiEvent::FocusLost => {
                cached
            }
        };
        if matches!(event, TuiEvent::Resize(_) | TuiEvent::Resume)
            && let Some(monitor) = &self.event_broker.size_monitor
        {
            monitor.observe(size);
        }
        self.screen_size.pending_draw_size = (!matches!(
            event,
            TuiEvent::Key(_) | TuiEvent::Mouse(_) | TuiEvent::Paste(_) | TuiEvent::FocusLost
        ))
        .then_some(size);
        Ok(size)
    }

fn visible_export_items(turns: Vec<Turn>) -> Vec<ThreadItem> {
    let mut visible = Vec::new();
    let mut review_mode = false;
    let mut previous_turn = None;

    for turn in turns {
        let hidden_nested_review_turn = previous_turn.as_ref().is_some_and(|previous| {
            crate::app_backtrack::is_hidden_nested_review_turn(previous, &turn)
        });
        for item in turn.items.iter().cloned() {
            match item {
                ThreadItem::EnteredReviewMode { .. } | ThreadItem::ExitedReviewMode { .. } => {
                    review_mode = matches!(item, ThreadItem::EnteredReviewMode { .. });
                    visible.push(item);
                }
                ThreadItem::UserMessage { .. } if review_mode || hidden_nested_review_turn => {}
                _ => visible.push(item),
            }
        }
        previous_turn = Some(turn);
    }

    visible
}

