fn begin_history_search(&mut self) -> (InputResult, bool) {
        if let Some(pasted) = self.draft.paste_burst.flush_before_modified_input() {
            self.apply_paste(pasted);
        }
        self.draft.paste_burst.clear_window_after_non_char();

        if self.popups.current_file_query.is_some() {
            self.app_event_tx
                .send(AppEvent::StartFileSearch(String::new()));
            self.popups.current_file_query = None;
        }
        self.popups.active = ActivePopup::None;
        self.attachments.clear_remote_image_selection();
        let original_draft = self.snapshot_draft();
        let original_vim_history = std::mem::take(&mut self.vim_history);
        let mut original_vim_state = VimPersistentState::default();
        self.draft
            .textarea
            .swap_vim_persistent_state(&mut original_vim_state);
        self.history_search = Some(HistorySearchSession {
            preview_draft: None,
            original_draft,
            original_vim_history,
            original_vim_state,
            query: String::new(),
            status: HistorySearchStatus::Idle,
        });
        self.history.reset_search();
        (InputResult::None, true)
    }

fn clear_selection(&mut self) {
        if !self.has_options() {
            return;
        }
        if let Some(answer) = self.current_answer_mut() {
            answer.options_state.reset();
            answer.draft = ComposerDraft::default();
            answer.answer_committed = false;
            answer.notes_visible = false;
        }
        self.pending_submission_draft = None;
        self.composer
            .set_text_content(String::new(), Vec::new(), Vec::new());
        self.composer.move_cursor_to_end();
        self.sync_composer_placeholder();
    }

fn repaint_agents_overview(&mut self) {
        let Some(selected) = self
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
        else {
            return;
        };
        let previous_thread_id = self
            .agents_overview
            .visible_thread_ids
            .get(selected)
            .copied();
        let selected_thread_id = self
            .agents_overview
            .view_state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .rename_target
            .filter(|id| {
                self.agents_overview.threads.contains_key(id)
                    && !self.agents_overview.hidden_threads.contains(id)
            })
            .or(self.agents_overview.selection_after_removal.take())
            .or(previous_thread_id);
        let threads = self
            .agents_overview
            .threads
            .values()
            .flatten()
            .cloned()
            .collect();
        let view = self.agents_overview_view(threads, selected_thread_id);
        self.agents_overview.visible_thread_ids = view.thread_ids();
        let next_thread_id = view
            .selected_index()
            .and_then(|index| self.agents_overview.visible_thread_ids.get(index).copied());
        if (previous_thread_id.is_none() || previous_thread_id != next_thread_id)
            && self
                .chat_widget
                .selected_index_for_active_view(AGENTS_OVERVIEW_VIEW_ID)
                .is_some()
        {
            self.cancel_pending_key_chord();
        }
        if let Ok(mut state) = self.agents_overview.view_state.lock()
            && state
                .rename_target
                .is_some_and(|id| !self.agents_overview.visible_thread_ids.contains(&id))
        {
            self.chat_widget.add_info_message(
                format!(
                    "The rename target disappeared. Unsubmitted title: {}",
                    state.input.text()
                ),
                /*hint*/ None,
            );
            state.rename_target = None;
            state.input.set_text_clearing_elements("");
        }
        self.chat_widget
            .replace_bottom_pane_view_if_present(AGENTS_OVERVIEW_VIEW_ID, Box::new(view));
    }

