fn update_from_item(&self, item: ThreadItem) -> bool {
        let Some((call_id, data)) = DynamicToolCallData::from_item(item) else {
            return false;
        };
        if call_id != self.call_id {
            return false;
        }
        *self
            .data
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = data;
        true
    }

