fn tool_call_history_cell(
    item: &ThreadItem,
    cached_spawn_request: Option<&SpawnRequestSummary>,
    mut agent_metadata: impl FnMut(ThreadId) -> AgentMetadata,
) -> Option<PlainHistoryCell> {
    let ThreadItem::CollabAgentToolCall {
        tool,
        status,
        receiver_thread_ids,
        prompt,
        agents_states,
        ..
    } = item
    else {
        return None;
    };

    let first_receiver = receiver_thread_ids
        .first()
        .and_then(|id| parse_thread_id(id));
    let prompt = prompt.as_deref().unwrap_or_default();

    match tool {
        // V2 uses SubAgentActivity for display; these variants are analytics-only.
        CollabAgentTool::SendMessage
        | CollabAgentTool::FollowupTask
        | CollabAgentTool::InterruptAgent
        | CollabAgentTool::ListAgents => None,
        CollabAgentTool::SpawnAgent => {
            if matches!(status, CollabAgentToolCallStatus::InProgress) {
                return None;
            }
            let fallback_spawn_request = spawn_request_summary(item);
            let spawn_request = cached_spawn_request.or(fallback_spawn_request.as_ref());
            Some(spawn_end(
                first_receiver,
                prompt,
                spawn_request,
                &mut agent_metadata,
            ))
        }
        CollabAgentTool::SendInput => {
            if matches!(status, CollabAgentToolCallStatus::InProgress) {
                return None;
            }
            first_receiver.map(|receiver_thread_id| {
                interaction_end(receiver_thread_id, prompt, &mut agent_metadata)
            })
        }
        CollabAgentTool::ResumeAgent => first_receiver.map(|receiver_thread_id| {
            if matches!(status, CollabAgentToolCallStatus::InProgress) {
                resume_begin(receiver_thread_id, &mut agent_metadata)
            } else {
                let state = first_agent_state(receiver_thread_ids, agents_states);
                resume_end(
                    receiver_thread_id,
                    state,
                    "Agent resume failed",
                    &mut agent_metadata,
                )
            }
        }),
        CollabAgentTool::Wait => {
            if matches!(status, CollabAgentToolCallStatus::InProgress) {
                Some(waiting_begin(receiver_thread_ids, &mut agent_metadata))
            } else {
                Some(waiting_end(
                    receiver_thread_ids,
                    agents_states,
                    &mut agent_metadata,
                ))
            }
        }
        CollabAgentTool::CloseAgent => {
            if matches!(status, CollabAgentToolCallStatus::InProgress) {
                return None;
            }
            first_receiver
                .map(|receiver_thread_id| close_end(receiver_thread_id, &mut agent_metadata))
        }
    }
}

fn handle_vim_operator_command(
        &mut self,
        operator: VimOperator,
        event: KeyEvent,
    ) -> bool {
        if self
            .vim_operator_keymap
            .motion_find_forward
            .is_pressed(event)
        {
            self.start_vim_find(VimFindMotion::Forward, Some(operator));
        } else if self
            .vim_operator_keymap
            .motion_find_backward
            .is_pressed(event)
        {
            self.start_vim_find(VimFindMotion::Backward, Some(operator));
        } else if self
            .vim_operator_keymap
            .motion_till_forward
            .is_pressed(event)
        {
            self.start_vim_find(VimFindMotion::TillForward, Some(operator));
        } else if self
            .vim_operator_keymap
            .motion_till_backward
            .is_pressed(event)
        {
            self.start_vim_find(VimFindMotion::TillBackward, Some(operator));
        } else if self.vim_operator_keymap.motion_jump_top.is_pressed(event)
            || self
                .vim_operator_keymap
                .motion_jump_bottom
                .is_pressed(event)
        {
            let last = self
                .vim_operator_keymap
                .motion_jump_bottom
                .is_pressed(event);
            match operator {
                VimOperator::Delete => {
                    self.start_vim_edit(VimAction::Delete(VimEditTarget::BufferJump { last }));
                }
                VimOperator::Change => {
                    self.start_vim_edit(VimAction::Change(VimEditTarget::BufferJump { last }));
                }
                VimOperator::Yank => self.jump_to_vim_buffer_line(last, Some(operator)),
            }
        } else {
            return false;
        }
        true
    }

