fn take_history_insertion_prefix(
        &mut self,
        cell: &dyn HistoryCell,
    ) -> Option<Box<dyn HistoryCell>> {
        // Keep the placeholder session header as the active cell until real session info arrives,
        // so we can merge headers instead of committing a duplicate box to history.
        let keep_placeholder_header_active = !self.is_session_configured()
            && self
                .transcript
                .active_cell
                .as_ref()
                .is_some_and(|c| c.as_any().is::<history_cell::SessionHeaderHistoryCell>());
        let history_width = self
            .last_rendered_width
            .get()
            .map(|width| self.history_wrap_width(width))
            .unwrap_or(u16::MAX);

        if !keep_placeholder_header_active
            && !cell
                .display_lines_for_mode(history_width, self.history_render_mode())
                .is_empty()
        {
            // Only break exec grouping if the cell renders visible lines.
            if !self.has_active_stream_tail() {
                return self.transcript.take_active_cell();
            }
        } else if !keep_placeholder_header_active
            && self.has_completed_tool_activity()
            && !cell.transcript_lines(history_width).is_empty()
        {
            return self.transcript.take_active_cell();
        }
        None
    }

fn copy_input_guard_is_released_on_all_selector_exits() {
    let cells: Vec<Arc<dyn HistoryCell>> = vec![Arc::new(AgentMarkdownCell::new(
        "response".into(),
        Path::new("/"),
    ))];
    for exit in ["escape", "find", "mouse", "confirmed", "presentation"] {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let guard = Arc::new(crate::copy_input_guard::CopyInputGuard(
            crate::app_event_sender::AppEventSender::new(tx),
        ));
        let weak = Arc::downgrade(&guard);
        let mut view = TranscriptView::default();
        render(&mut view, &cells, /*width*/ 40, /*height*/ 5);
        view.begin_copy_mode(&cells, Some(guard));
        assert!(weak.upgrade().is_some());
        match exit {
            "escape" => {
                view.handle_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE), &cells);
            }
            "find" => view.begin_search(),
            "mouse" => {
                view.begin_selection(&cells, /*column*/ 2, /*row*/ 0, /*clicks*/ 1)
            }
            "confirmed" => {
                view.copy_selected_text_with(
                    &cells,
                    "response",
                    /*clear_selection*/ true,
                    |_, _| Ok(CopyStatus::Confirmed),
                )
                .unwrap();
            }
            "presentation" => view.set_presentation(
                /*detailed*/ true,
                crate::history_cell::HistoryRenderMode::Raw,
            ),
            _ => unreachable!(),
        }
        assert!(weak.upgrade().is_none(), "{exit}");
        assert!(matches!(
            rx.try_recv(),
            Ok(crate::app_event::AppEvent::TranscriptCopyClosed)
        ));
    }
}

fn validate(text: String, deadline: Instant) -> Result<String, String> {
    if Instant::now() >= deadline {
        Err("clipboard read timed out".into())
    } else if text.chars().count() > MAX_USER_INPUT_TEXT_CHARS {
        Err("clipboard text exceeds the message size limit".into())
    } else {
        Ok(text)
    }
}

