fn live_center_rename_retains_target_when_status_leaves_filter() -> Result<()> {
    let mut app = make_test_app().await;
    app.chat_widget.toggle_vim_mode_and_notify();
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    app.app_event_tx = AppEventSender::new(tx);
    let id = ThreadId::new();
    let other = ThreadId::new();
    let mut threads = vec![
        overview_thread(
            id,
            /*parent_thread_id*/ None,
            "Tar\nget",
            ThreadStatus::Idle,
        ),
        overview_thread(
            other,
            /*parent_thread_id*/ None,
            "Other",
            ThreadStatus::Idle,
        ),
    ];
    for key in [KeyCode::Esc, KeyCode::Enter] {
        threads[0].status = ThreadStatus::Idle;
        let mut view = app.agents_overview_view(threads.clone(), Some(id));
        // Reuse the Ready tab after the first iteration.
        if key == KeyCode::Esc {
            for _ in 0..3 {
                view.handle_key_event(KeyCode::Tab.into());
            }
        }
        view.handle_key_event(KeyCode::Char('r').into());
        assert_eq!(
            view.cursor_style(Rect::default()),
            crossterm::cursor::SetCursorStyle::SteadyBar
        );
        threads[0].status = ThreadStatus::SystemError;
        view = app.agents_overview_view(threads.clone(), Some(id));
        if key == KeyCode::Enter {
            for edit in [
                KeyCode::Esc,
                KeyCode::Char('0'),
                KeyCode::Char('c'),
                KeyCode::Char('w'),
            ] {
                view.handle_key_event(edit.into());
            }
            view.handle_paste("Target".into());
        }
        view.handle_key_event(KeyCode::Char('!').into());
        view.handle_key_event(key.into());
        if key == KeyCode::Esc {
            assert_eq!(
                view.cursor_style(Rect::default()),
                crossterm::cursor::SetCursorStyle::DefaultUserShape
            );
            view.handle_key_event(KeyCode::Esc.into());
        }
        assert_eq!(view.rows[view.selected_index().unwrap()].thread_id, other);
        if key == KeyCode::Enter {
            let rename = rx.try_recv().unwrap();
            assert!(
                matches!(&rename, AppEvent::RenameAgentsOverviewThread { thread_id, name } if *thread_id == id && name == "Target!")
            );
            app.agents_overview.threads = threads
                .iter()
                .map(|thread| {
                    (
                        ThreadId::from_string(&thread.id).unwrap(),
                        Some(thread.clone()),
                    )
                })
                .collect();
            app.agents_overview.visible_thread_ids = view.thread_ids();
            app.chat_widget.show_bottom_pane_view(Box::new(view));
            let mut server = crate::start_embedded_app_server_for_picker(&app.config).await?;
            let mut tui = crate::tui::test_support::make_test_tui()?;
            // Synthetic IDs have no rollout: the server rejects the rename.
            Box::pin(app.handle_event(&mut tui, &mut server, rename)).await?;
            let mut retry = app.agents_overview_view(threads.clone(), Some(other));
            assert_eq!(retry.rows[retry.selected_index().unwrap()].thread_id, id);
            retry.handle_key_event(KeyCode::Enter.into());
            assert!(std::iter::from_fn(|| rx.try_recv().ok()).any(|event| matches!(event, AppEvent::RenameAgentsOverviewThread { thread_id, name } if thread_id == id && name == "Target!")));
            server.shutdown().await?;
        } else {
            assert!(rx.try_recv().is_err());
        }
    }
    Ok(())
}

fn handle_copy_mode_key(
        &mut self,
        key: KeyEvent,
        cells: &[Arc<dyn HistoryCell>],
    ) -> Option<ViewAction> {
        self.copy_mode.as_ref()?;
        let code = match crate::key_hint::normalize_key_parts(key.code, key.modifiers) {
            (KeyCode::Char('k'), KeyModifiers::NONE) => KeyCode::Up,
            (KeyCode::Char('j'), KeyModifiers::NONE) => KeyCode::Down,
            (KeyCode::Char('g'), KeyModifiers::NONE) => KeyCode::Home,
            (KeyCode::Char('g'), KeyModifiers::SHIFT) => KeyCode::End,
            _ => key.code,
        };
        match code {
            KeyCode::Up | KeyCode::Down | KeyCode::Home | KeyCode::End => {
                self.move_copy_target(cells, code)
            }
            KeyCode::Esc => self.jump_to_latest(),
            _ if key.code == KeyCode::Enter || crate::text_selection::is_copy_key(key) => {
                return Some(ViewAction::CopyAndFollow(
                    self.selected_text(cells).unwrap_or_default(),
                ));
            }
            KeyCode::PageUp | KeyCode::PageDown => return self.handle_scroll_key(key, cells),
            _ => return Some(ViewAction::Changed),
        }
        Some(ViewAction::Changed)
    }

fn voice_toggle_chord_dispatches_in_overview_without_an_active_voice_session() {
    let config = toml::from_str::<TuiKeymap>(
        "[chat]\ntoggle_voice = 'f8 v'\n[global]\nopen_transcript = 'f8 t'",
    )
    .unwrap();
    let runtime = RuntimeKeymap::from_config(&config).unwrap();
    let mut matcher = KeyChordMatcher::default();
    let prefix = KeyEvent::new(KeyCode::F(8), KeyModifiers::NONE);
    for contexts in [
        KeymapContextSet::new(KeymapContext::List),
        KeymapContextSet::raw_key_capture().with_voice_toggle(&runtime),
    ] {
        assert_eq!(
            matcher.advance(prefix, &runtime.chords, contexts),
            KeyChordMatch::PassThrough
        );
    }
    for contexts in [
        KeymapContextSet::new(KeymapContext::Agents),
        KeymapContextSet::default(),
        KeymapContextSet::new(KeymapContext::Chat).with(KeymapContext::Global),
    ] {
        let contexts = contexts.with_voice_toggle(&runtime);
        assert!(matches!(
            matcher.advance(prefix, &runtime.chords, contexts),
            KeyChordMatch::Pending(_)
        ));
        let KeyChordMatch::Completed(dispatch) = matcher.advance(
            KeyEvent::new(KeyCode::Char('v'), KeyModifiers::NONE),
            &runtime.chords,
            contexts,
        ) else {
            panic!("voice toggle chord completes")
        };
        assert!(runtime.chat.toggle_voice.is_pressed(dispatch));
    }
}

fn paste_burst_tabs_preserve_multiline_draft() {
    for running in [false, true] {
        for first_line in ["x", "界", "first line\n"] {
            let (mut composer, _rx) = new_test_composer();
            composer.set_task_running(running);
            let mut now = Instant::now();
            let payload = format!("{first_line}\t\tsecond line\n\tthird line\n");

            for ch in payload.chars() {
                let (result, _) = match ch {
                    '\t' => {
                        assert!(composer.handle_paste_tab(KeyEvent::from(KeyCode::Tab), now));
                        (InputResult::None, true)
                    }
                    '\n' => composer.handle_submission_with_time(/*should_queue*/ false, now),
                    ch => composer
                        .handle_input_basic_with_time(KeyEvent::from(KeyCode::Char(ch)), now),
                };
                assert_eq!(result, InputResult::None);
                now += Duration::from_millis(/*millis*/ 1);
            }

            composer.handle_paste_burst_flush(now + PasteBurst::recommended_active_flush_delay());
            assert_eq!(composer.current_text(), payload);

            if running && first_line == "first line\n" {
                let mut terminal = Terminal::new(TestBackend::new(60, 8)).unwrap();
                terminal
                    .draw(|frame| composer.render(frame.area(), frame.buffer_mut()))
                    .unwrap();
                insta::assert_snapshot!("paste_burst_tab_indentation", terminal.backend());
            }

            let (result, _) = composer.handle_key_event(KeyEvent::from(KeyCode::Tab));
            let expected = if running {
                InputResult::Queued {
                    text: payload.trim().to_string(),
                    text_elements: Vec::new(),
                    action: QueuedInputAction::Plain,
                    pending_pastes: Vec::new(),
                }
            } else {
                InputResult::Submitted {
                    text: payload.trim().to_string(),
                    text_elements: Vec::new(),
                }
            };
            assert_eq!(result, expected);
        }
    }
}

