fn compact_patches_retain_full_changes_and_failure_details() {
    let patch = new_patch_event(
        HashMap::from([
            (
                PathBuf::from("new.txt"),
                FileChange::Add {
                    content: "one\ntwo\nthree\nfour\nfive\n".into(),
                },
            ),
            (
                PathBuf::from("existing.txt"),
                FileChange::Update {
                    unified_diff: "@@ -1,3 +1,3 @@\n context\n-before\n+after\n tail\n".into(),
                    move_path: None,
                },
            ),
        ]),
        Path::new("."),
    );
    let failure = new_patch_apply_failure("first\nsecond\nthird\nfourth diagnostic".into());
    let missing = new_patch_apply_failure(String::new());
    let mut snapshots = Vec::new();
    for (label, cell) in [
        ("patch", &patch as &dyn HistoryCell),
        ("failure", &failure),
        ("missing diagnostics", &missing),
    ] {
        let compact = visible_lines(cell.compact_hyperlink_lines(/*width*/ 40));
        let full = visible_lines(cell.transcript_hyperlink_lines(/*width*/ 40));
        snapshots.push(format!(
            "{label}\nCompact\n{}\nFull\n{}",
            Text::from(compact),
            Text::from(full)
        ));
    }
    insta::assert_snapshot!(snapshots.join("\n\n"));
}

fn resolve_theme_by_name(name: &str, codex_home: Option<&Path>) -> Option<Theme> {
    let ts = two_face::theme::extra();
    // Bundled theme?
    if let Some(embedded) = parse_theme_name(name) {
        return Some(ts.get(embedded).clone());
    }
    // Custom .tmTheme file?
    if let Some(home) = codex_home
        && custom_theme_path(name, home)
            .try_exists()
            .unwrap_or(/*default*/ true)
    {
        return load_custom_theme(name, home);
    }
    model_themes::resolve(name)
}

fn status_permissions_label(
    active_permission_profile: Option<&ActivePermissionProfile>,
    permission_profile: &PermissionProfile,
    approval_policy: AskForApproval,
    sandbox: &str,
    approval: &str,
    workspace_root_suffix: Option<&str>,
) -> String {
    let active_id = active_permission_profile.map(|active| active.id.as_str());
    match active_id {
        Some(BUILT_IN_PERMISSION_PROFILE_READ_ONLY) => {
            let label = if sandbox == "read-only with network access" {
                "Read Only with network access"
            } else {
                "Read Only"
            };
            return format!("{label} ({approval})");
        }
        Some(BUILT_IN_PERMISSION_PROFILE_WORKSPACE) => match sandbox {
            "workspace" => {
                return format!(
                    "Workspace{} ({approval})",
                    workspace_root_suffix.unwrap_or("")
                );
            }
            "workspace with network access" => {
                return format!(
                    "Workspace with network access{} ({approval})",
                    workspace_root_suffix.unwrap_or("")
                );
            }
            _ => {}
        },
        Some(BUILT_IN_PERMISSION_PROFILE_DANGER_FULL_ACCESS)
            if permission_profile == &PermissionProfile::Disabled =>
        {
            return if approval_policy == AskForApproval::Never {
                "Full Access".to_string()
            } else {
                format!("No Sandbox ({approval})")
            };
        }
        Some(id) => {
            let sandbox = decorate_workspace_sandbox_label(sandbox, workspace_root_suffix);
            return format!("Profile {id} ({sandbox}, {approval})");
        }
        None => {}
    }

    if sandbox == "read-only" {
        return format!("Read Only ({approval})");
    }
    if approval_policy == AskForApproval::OnRequest && sandbox == "workspace" {
        return format!(
            "Workspace{} ({approval})",
            workspace_root_suffix.unwrap_or("")
        );
    }
    if approval_policy == AskForApproval::Never
        && permission_profile == &PermissionProfile::Disabled
    {
        return "Full Access".to_string();
    }
    let sandbox = decorate_workspace_sandbox_label(sandbox, workspace_root_suffix);
    format!("Custom ({sandbox}, {approval})")
}

