fn deeply_nested_lazy_continuations_keep_bounded_relative_copy_prefixes() {
    let depth = 256;
    let continuation_count = 256;
    let markdown = format!(
        "{}text\n{}",
        "- ".repeat(depth),
        "a\n".repeat(continuation_count)
    );
    let lines =
        render_markdown_lines_with_width_and_cwd(&markdown, /*width*/ None, /*cwd*/ None);
    let copies = lines
        .iter()
        .filter_map(|line| line.source.as_ref())
        .filter_map(|source| source.copy.as_ref())
        .collect::<Vec<_>>();
    let continuation = "  ".repeat(MAX_COPY_DEPTH);
    let item_prefix = format!("{}- ", "  ".repeat(MAX_COPY_DEPTH - 1));
    assert_eq!(copies.len(), continuation_count + 1);
    assert!(
        copies
            .iter()
            .all(|copy| copy.continuation == continuation && copy.item_prefix == item_prefix)
    );
    assert_eq!(copies[0].prefix, item_prefix);
    assert!(copies[1..].iter().all(|copy| copy.prefix == continuation));
}

fn accepted_voice_answer_with_only_an_old_caption_returns_to_history_on_close() {
    let (mut chat, _sender, mut events, mut ops) = make_chatwidget_manual_with_sender().await;
    let thread_id = activate_voice(&mut chat);
    let turn_id = "accepted-turn";
    start_item(
        &mut chat,
        thread_id,
        turn_id,
        user_item("<realtime_delegation><input>question</input></realtime_delegation>"),
    );
    let answer = agent_item("answer", "Accepted answer", Some(MessagePhase::FinalAnswer));
    start_item(&mut chat, thread_id, turn_id, answer.clone());
    complete_item(&mut chat, thread_id, turn_id, answer.clone());
    finish_turn(
        &mut chat,
        thread_id,
        turn_id,
        vec![answer],
        TurnStatus::Completed,
    );
    let AppCommand::RealtimeConversationSpeech { delivery_id, .. } = ops.try_recv().unwrap() else {
        panic!("completed voice turn should queue speech");
    };
    while events.try_recv().is_ok() {}
    chat.accept_realtime_speech(delivery_id);
    assert!(!chat.has_pending_realtime_speech(delivery_id));
    chat.realtime_conversation.assistant_transcript_generation =
        Some(chat.realtime_conversation.input_generation.wrapping_sub(1));
    chat.on_realtime_transcript_done("assistant".into(), "Earlier speech".into());
    assert_eq!(chat.realtime_conversation.pending_speech.len(), 1);
    chat.on_realtime_conversation_closed(Some("transport_closed".into()));
    chat.restore_undelivered_realtime_speech(delivery_id);
    let mut answers = 0;
    commit_realtime_history_events(&mut chat, &mut events);
    while let Ok(event) = events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            let rendered = cell
                .display_lines(/*width*/ 80)
                .into_iter()
                .map(|line| line.to_string())
                .collect::<String>();
            answers += usize::from(rendered.contains("Accepted answer"));
        }
    }
    assert_eq!(answers, 1);
}

fn mouse_scroll_speed_scales_rows_and_accumulates_fractional_movement() {
    use crate::history_cell::PlainHistoryCell;
    use crate::transcript_view::tests::text;

    let cells: Vec<Arc<dyn HistoryCell>> = vec![Arc::new(PlainHistoryCell::new(
        (1..=24).map(|row| format!("row {row:02}").into()).collect(),
    ))];
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 12, /*height*/ 4,
    );
    let mut frames = Vec::new();
    for (speed, deltas) in [
        (None, vec![-1, 1]),
        (Some(0.5), vec![0, -1, 0, 0, 1]),
        (Some(1.5), vec![-1, -2, 1, 2]),
        (Some(3.0), vec![-3, 3]),
    ] {
        let mut view = TranscriptView::default();
        if let Some(speed) = speed {
            view.mouse_scroll_speed = speed;
        }
        let mut buffer = Buffer::empty(area);
        view.render(area, &mut buffer, &cells);
        view.scroll(&cells, /*rows*/ -8);
        view.render(area, &mut buffer, &cells);
        let (index, mut row) = view.start(&cells);
        let up_events = deltas.len().div_ceil(2);
        for (event_index, delta) in deltas.into_iter().enumerate() {
            let kind = if event_index < up_events {
                MouseEventKind::ScrollUp
            } else {
                MouseEventKind::ScrollDown
            };
            view.handle_mouse(mouse(kind, /*column*/ 1, /*row*/ 1), &cells);
            row = row.saturating_add_signed(delta);
            assert_eq!(view.start(&cells), (index, row));
            view.render(area, &mut buffer, &cells);
            if event_index + 1 == up_events {
                frames.push(format!(
                    "speed {speed:?}, {up_events} up events:\n{}",
                    text(&buffer)
                ));
            }
        }
    }
    insta::assert_snapshot!(frames.join("\n\n"));
}

