fn handle_key_event_at(&mut self, key_event: KeyEvent, now: Instant) {
        match key_event {
            KeyEvent {
                code: KeyCode::PageUp,
                ..
            } => {
                self.intro_scroll.set(
                    self.intro_scroll
                        .get()
                        .saturating_sub(self.intro_page_height.get()),
                );
            }
            KeyEvent {
                code: KeyCode::PageDown,
                ..
            } => {
                self.intro_scroll.set(
                    self.intro_scroll
                        .get()
                        .saturating_add(self.intro_page_height.get()),
                );
            }
            KeyEvent {
                code: KeyCode::Esc, ..
            } => {
                self.on_ctrl_c();
            }
            KeyEvent {
                code: KeyCode::Enter,
                modifiers,
                ..
            } => {
                if self.paste_burst.direct_insert_newline_should_insert(now) {
                    self.paste_burst.extend_window(now);
                    self.textarea.insert_str("\n");
                } else if modifiers == KeyModifiers::NONE {
                    self.submit();
                } else {
                    self.textarea.input(key_event);
                }
            }
            KeyEvent {
                code: KeyCode::Char(_),
                modifiers,
                ..
            } if !has_ctrl_or_alt(modifiers) => {
                let paste_like_burst = self.paste_burst.on_plain_char_no_hold(now).is_some();
                self.textarea.input(key_event);
                if paste_like_burst {
                    self.paste_burst.extend_window(now);
                }
            }
            KeyEvent {
                code: KeyCode::Tab,
                modifiers,
                ..
            } if !has_ctrl_or_alt(modifiers) => {
                let in_paste_burst = self.paste_burst.direct_insert_newline_should_insert(now);
                self.textarea.input(key_event);
                if in_paste_burst {
                    self.paste_burst.extend_window(now);
                }
            }
            other => {
                self.textarea.input(other);
                self.paste_burst.clear_after_explicit_paste();
            }
        }
    }

fn advance_older_search_with_batches_from(
        &mut self,
        mut cursor: HistoryBatchCursor,
        boundary_if_exhausted: bool,
        app_event_tx: &AppEventSender,
    ) -> HistorySearchResult {
        let mut offset = cursor.end_offset();
        loop {
            if let Some(entry) = self.entry_at_cached_offset(offset) {
                if self.search_matches(&entry) && self.search_result_is_unique(&entry) {
                    return self.search_match(offset, entry);
                }
            } else if !self.fetched_history.contains_key(&offset)
                && offset < self.persistent_entry_count
            {
                return self.request_older_search_batch(
                    cursor,
                    boundary_if_exhausted,
                    app_event_tx,
                );
            }

            let Some(next_offset) = offset.checked_sub(1) else {
                return self
                    .exhausted_search_result(HistorySearchDirection::Older, boundary_if_exhausted);
            };
            offset = next_offset;
            cursor = HistoryBatchCursor::new(offset);
        }
    }

