fn test_schedule_frame_immediate_triggers_once() {
        let (draw_tx, mut draw_rx) = broadcast::channel(16);
        let requester = FrameRequester::new(draw_tx);

        requester.schedule_frame();

        // Advance time minimally to let the scheduler process and hit the deadline == now.
        time::advance(Duration::from_millis(1)).await;

        // First draw should arrive.
        let first = draw_rx
            .recv()
            .timeout(Duration::from_millis(50))
            .await
            .expect("timed out waiting for first draw");
        assert!(first.is_ok(), "broadcast closed unexpectedly");

        // No second draw should arrive.
        let second = draw_rx.recv().timeout(Duration::from_millis(20)).await;
        assert!(second.is_err(), "unexpected extra draw received");
    }

fn sliding_uses_rendered_glyphs_instead_of_raw_byte_offsets() {
    let markdown = |text: &str| -> Box<dyn HistoryCell> {
        Box::new(crate::history_cell::AgentMarkdownCell::new_spoken(
            text.to_string(),
            std::path::Path::new("."),
        ))
    };
    for (render, text, discarded_bytes, discarded_tiles) in [
        (
            plain_transcript as fn(&str) -> Box<dyn HistoryCell>,
            "éGA 東京B",
            4,
            2,
        ),
        (markdown, "DROP [GATE](https://example.test) **73**", 5, 4),
    ] {
        let first = SplitFlapTranscriptCell::new(
            render,
            "user",
            text,
            /*previous*/ None,
            /*discarded_prefix_bytes*/ 0,
            MotionMode::Animated,
            FrameRequester::test_dummy(),
        );
        let target = format!("{} 9", &text[discarded_bytes..]);
        let shifted = SplitFlapTranscriptCell::new(
            render,
            "user",
            &target,
            Some(&first),
            discarded_bytes,
            MotionMode::Animated,
            FrameRequester::test_dummy(),
        );
        let retained_tiles = first.tile_arrivals.len() - discarded_tiles;

        assert_eq!(
            shifted.tile_arrivals[..retained_tiles],
            first.tile_arrivals[discarded_tiles..]
        );
        assert_eq!(shifted.raw_lines(), render(&target).raw_lines());
    }
}

fn parse_terminal_title_items<T>(ids: impl Iterator<Item = T>) -> Option<Vec<TerminalTitleItem>>
where
    T: AsRef<str>,
{
    // Treat parsing as all-or-nothing so preview/confirm callbacks never emit
    // a partially interpreted ordering. Invalid ids are ignored when building
    // the picker, but once the user is interacting with the picker we only want
    // to persist or preview a fully valid selection.
    ids.map(|id| id.as_ref().parse::<TerminalTitleItem>())
        .collect::<Result<Vec<_>, _>>()
        .ok()
}

