    thread_id: ThreadId,
    visibility: RawReasoningVisibility,
    config: Option<&Config>,
    visible_transcript: Vec<Arc<dyn HistoryCell>>,
) -> Result<Vec<Arc<dyn HistoryCell>>, String> {
