fn configured_legacy_bindings_prune_new_vim_defaults() {
        for (key, new_action) in [
            ("u", "undo"),
            ("ctrl-r", "redo"),
            ("shift-r", "enter_replace_mode"),
        ] {
            for (context, action, suffix) in [
                ("vim_normal", "move_left", ""),
                ("vim_normal", "move_left", " g"),
                ("vim_search", "forward", ""),
                ("vim_search", "forward", " g"),
                ("composer", "submit", ""),
                ("global", "submit", ""),
                ("global", "queue", ""),
                ("global", "toggle_shortcuts", ""),
            ] {
                let mut keymap: TuiKeymap = serde_json::from_value(serde_json::json!({
                    (context): { (action): format!("{key}{suffix}") }
                }))
                .expect("config should deserialize");
                if key == "ctrl-r"
                    && (!suffix.is_empty() || matches!(context, "composer" | "global"))
                {
                    // Ctrl+R chords and main-surface actions must unbind the older history key.
                    keymap.composer.history_search_previous = Some(KeybindingsSpec::Many(vec![]));
                }
                let runtime = RuntimeKeymap::from_config(&keymap).expect("config should parse");
                assert_eq!(
                    bindings_for_action(&runtime, "vim_normal", new_action),
                    Some([].as_slice()),
                    "{context}.{action} = {key}{suffix}"
                );
            }
        }
    }

fn hidden_banner_preserves_input_before_render_and_after_resize() {
    let (tx, mut rx) = unbounded_channel();
    let mut pane = test_pane_with_disable_paste_burst(
        AppEventSender::new(tx),
        /*disable_paste_burst*/ true,
    );
    pane.set_inline_banner(Some(ActionableBanner {
        title: "Usage limit reached".into(),
        actions: vec![SelectionItem {
            name: "View usage".into(),
            actions: vec![Box::new(|tx| {
                tx.send(AppEvent::OpenUrlInBrowser {
                    url: "https://example.com/usage".into(),
                });
            })],
            ..Default::default()
        }],
        ..Default::default()
    }));
    let width = 70;
    let hidden_area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        width,
        pane.composer.desired_height(width),
    );
    let visible_area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        width,
        pane.desired_height(width),
    );

    // Keys remain composer input before the first frame and after resizing a
    // previously visible banner out of view.
    for (render_hidden, composer_gap) in [
        (false, None),
        (true, None),
        (true, Some(super::super::ComposerGap::default())),
    ] {
        if render_hidden {
            let renderable = pane.as_renderable_with_options(ComposerRenderOptions {
                composer_gap: composer_gap.as_ref(),
                ..Default::default()
            });
            let rendered = render_snapshot(&renderable, hidden_area);
            assert!(!rendered.contains("View usage"));
        }
        pane.handle_key_event(KeyEvent::new(KeyCode::Char('1'), KeyModifiers::NONE));
        assert_eq!(pane.composer_text(), "1");
        assert!(rx.try_recv().is_err());
        pane.set_composer_text(String::new(), Vec::new(), Vec::new());
        assert!(pane.is_normal_backtrack_mode());
        pane.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));

        let rendered = {
            let renderable = pane.as_renderable_with_options(ComposerRenderOptions {
                composer_gap: composer_gap.as_ref(),
                ..Default::default()
            });
            render_snapshot(
                &renderable,
                Rect {
                    height: renderable.desired_height(width),
                    ..visible_area
                },
            )
        };
        if composer_gap.is_some() {
            assert_snapshot!("actionable_banner_with_composer_gap", rendered);
        }
        assert!(rendered.contains("View usage"));
        assert!(!pane.is_normal_backtrack_mode());
        pane.handle_key_event(KeyEvent::new(KeyCode::Char('1'), KeyModifiers::NONE));
        assert_eq!(pane.composer_text(), "");
        assert!(
            matches!(rx.try_recv(), Ok(AppEvent::OpenUrlInBrowser { url })
            if url == "https://example.com/usage")
        );
    }

    pane.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert!(pane.is_normal_backtrack_mode());
    assert!(!render_snapshot(&pane, visible_area).contains("View usage"));
}

