        let mut pairs = vec![(
            first_or_empty(&self.keymap, "close", &self.keymap.close),
            "close",
        )];
        if !self.keymap.find.is_empty() {
            pairs.push((
                first_or_empty(&self.keymap, "find", &self.keymap.find),
                "find",
            ));
        }
