fn terminal_draw_moves_cursor_before_showing_it() {
        let cursor_position = Position { x: 1, y: 0 };
        let mut terminal =
            Terminal::with_options(CaptureBackend::new(/*width*/ 2, /*height*/ 1))
                .expect("terminal");
        terminal.set_viewport_area(Rect::new(
            /*x*/ 0, /*y*/ 0, /*width*/ 2, /*height*/ 1,
        ));

        terminal
            .draw(|frame| frame.set_cursor_position(cursor_position))
            .expect("draw");

        let mut expected_move = Vec::new();
        queue!(expected_move, MoveTo(cursor_position.x, cursor_position.y)).expect("queue move");
        let expected_move = String::from_utf8(expected_move).expect("move utf8");
        let mut expected_show = Vec::new();
        queue!(expected_show, crossterm::cursor::Show).expect("queue show");
        let expected_show = String::from_utf8(expected_show).expect("show utf8");
        let actual = terminal.backend().output();
        let move_index = actual.find(&expected_move).expect("cursor move");
        let show_index = actual.find(&expected_show).expect("cursor show");

        assert!(
            move_index < show_index,
            "expected cursor move before show, got {actual:?}"
        );
        assert_snapshot!(
            actual[move_index..].escape_debug().to_string(),
            @r"\u{1b}[1;2H\u{1b}[?25h"
        );
    }

fn full_screen_viewport_growth_preserves_terminal_scrollback() {
    let width = 24;
    let height = 6;
    let backend = VT100Backend::with_scrollback(width, height, /*scrollback_len*/ 32);
    let mut terminal = Terminal::with_options(backend).expect("terminal with scrollback");
    terminal.set_viewport_area(Rect::new(
        /*x*/ 0,
        /*y*/ height - 2,
        width,
        /*height*/ 2,
    ));

    for (row, line) in [
        "oldest-history-row",
        "history-row-2",
        "history-row-3",
        "history-row-4",
        "stale-composer-1",
        "stale-composer-2",
    ]
    .into_iter()
    .enumerate()
    {
        queue!(
            terminal.backend_mut(),
            MoveTo(/*x*/ 0, row as u16),
            Print(line)
        )
        .expect("seed terminal row");
    }

    ScrollbackStrategy::FullScreen
        .grow_viewport(
            &mut terminal,
            /*viewport_top*/ height - 2,
            Size::new(width, height),
            /*scroll_by*/ 2,
        )
        .expect("grow viewport through full-screen scrolling");

    let visible = terminal.backend().vt100().screen().contents();
    let mut scrollback_screen = terminal.backend().vt100().screen().clone();
    scrollback_screen.set_scrollback(/*rows*/ usize::MAX);
    let scrollback = scrollback_screen.contents();

    insta::assert_snapshot!(format!("SCROLLBACK:\n{scrollback}\nVISIBLE:\n{visible}"), @r"
    SCROLLBACK:
    oldest-history-row
    history-row-2
    history-row-3
    history-row-4
    VISIBLE:
    history-row-3
    history-row-4
    ");
}

