fn enter_preserves_search_backtrack_and_modal_ownership_while_scrolled() -> Result<()> {
    let mut app = crate::app::test_support::make_test_app().await;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    let size = Size::new(/*width*/ 80, /*height*/ 12);
    app.transcript_cells = vec![Arc::new(PlainHistoryCell::new(
        (0..30).map(|row| format!("row {row}").into()).collect(),
    ))];
    app.render_owned_transcript(&mut tui, size)?;
    app.transcript_view
        .scroll(&app.transcript_cells, /*rows*/ -10);
    app.render_owned_transcript(&mut tui, size)?;
    let enter = TuiEvent::Key(KeyEvent::from(KeyCode::Enter));
    app.transcript_view.begin_search();
    assert!(app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    assert!(app.transcript_view.is_search_editing());
    assert!(!app.transcript_view.is_following());
    app.handle_owned_transcript_event(
        &mut tui,
        &mut server,
        &TuiEvent::Key(KeyEvent::from(KeyCode::Esc)),
    )?;

    // An empty selection anchor consumes Enter without accessing the host clipboard.
    app.handle_owned_transcript_event(
        &mut tui,
        &mut server,
        &TuiEvent::Key(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::CONTROL)),
    )?;
    assert!(app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    assert!(!app.transcript_view.is_following());
    app.handle_owned_transcript_event(
        &mut tui,
        &mut server,
        &TuiEvent::Key(KeyEvent::from(KeyCode::Esc)),
    )?;

    app.backtrack.primed = true;
    assert!(!app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    app.backtrack.primed = false;
    app.backtrack.overlay_preview_active = true;
    assert!(!app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    app.backtrack.overlay_preview_active = false;

    app.chat_widget
        .set_remote_image_urls(vec!["https://example.com/image.png".into()]);
    assert!(!app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    app.chat_widget.set_remote_image_urls(Vec::new());
    app.chat_widget.open_feature_enable_prompt(Feature::Collab);
    assert!(!app.handle_owned_transcript_event(&mut tui, &mut server, &enter)?);
    assert!(!app.transcript_view.is_following());

    tui.set_owned_screen(/*owned*/ false)?;
    server.shutdown().await?;
    Ok(())
}

fn missed_resize_recovers_and_slow_query_does_not_block_input() {
    let initial = Size::new(/*width*/ 12, /*height*/ 4);
    let resized = Size::new(/*width*/ 8, /*height*/ 4);
    let mut harness = Harness::new(initial);
    let mut stream = harness.stream();
    harness.next_query().await;
    // The worker is blocked waiting for a reply. Input still traverses the real event stream.
    assert!(matches!(
        timeout(Duration::from_millis(100), stream.next())
            .await
            .unwrap(),
        Some(TuiEvent::Key(KeyEvent {
            code: KeyCode::Char('x'),
            ..
        }))
    ));
    assert!(
        timeout(
            CHECK_INTERVAL + Duration::from_millis(50),
            harness.queries.recv()
        )
        .await
        .is_err()
    );
    harness.replies.send(Ok(resized)).unwrap();
    let event = timeout(Duration::from_secs(2), stream.next())
        .await
        .unwrap()
        .unwrap();
    let TuiEvent::Resize(size) = event else {
        panic!("expected recovered resize: {event:?}")
    };
    assert_eq!(size, resized);

    let mut terminal = Terminal::with_screen_size_and_cursor_position_for_test(
        VT100Backend::new(resized.width, resized.height),
        initial,
        Position { x: 0, y: 0 },
    );
    let area = Rect::new(/*x*/ 0, /*y*/ 0, size.width, size.height);
    terminal.set_viewport_area(area);
    terminal
        .draw_with_size(size, &mut Vec::new(), |frame| {
            Paragraph::new("alpha beta")
                .wrap(Wrap { trim: false })
                .render(area, frame.buffer_mut());
        })
        .unwrap();
    assert_eq!(terminal.last_known_screen_size, resized);
    insta::assert_snapshot!(terminal.backend().vt100().screen().contents(), @"alpha\nbeta");
}

fn unexpected_voice_close_preserves_partial_transcripts_once() {
    for (role, text) in [
        ("user", "Part of my request"),
        ("assistant", "Part of the answer"),
    ] {
        let (mut chat, _sender, mut events, _ops) = make_chatwidget_manual_with_sender().await;
        activate_voice(&mut chat);
        chat.on_realtime_transcript_delta(role.to_string(), text.to_string());

        chat.on_realtime_conversation_closed(/*reason*/ None);
        chat.on_realtime_transcript_done(role.to_string(), text.to_string());

        let mut appearances = 0;
        commit_realtime_history_events(&mut chat, &mut events);
        while let Ok(event) = events.try_recv() {
            if let AppEvent::InsertHistoryCell(cell) = event {
                appearances +=
                    cell.display_lines(/*width*/ 80)
                        .iter()
                        .any(|line| line.to_string().contains(text)) as usize;
            }
        }
        assert_eq!(appearances, 1, "{role} transcript should be preserved once");
        assert!(chat.active_cell_transcript_lines(/*width*/ 80).is_none());
        assert_eq!(
            chat.realtime_conversation.phase,
            RealtimeConversationPhase::Inactive
        );
    }
}

