fn handle_paste_burst_flush(&mut self, now: Instant) -> bool {
        match self.draft.paste_burst.flush_if_due(now) {
            FlushResult::Paste(pasted) => {
                self.apply_paste(pasted);
                true
            }
            FlushResult::Typed(ch) => {
