fn terminal_draw_repairs_styled_anchor_on_cursor_only_frames() {
    let mut terminal =
        Terminal::with_options(CaptureBackend::new(/*width*/ 12, /*height*/ 2)).expect("terminal");
    let area = Rect::new(
        /*x*/ 0, /*y*/ 1, /*width*/ 12, /*height*/ 1,
    );
