    let mut frames = Vec::new();
    let mut parser =
        vt100::Parser::new(/*rows*/ 2, /*cols*/ 12, /*scrollback_len*/ 0);

    for (x, style) in [
        (1, SetCursorStyle::DefaultUserShape),
