fn replay_preserves_drafts_and_does_not_reopen_handled_questions() {
    let mut original = editor();
    original.set_expanded(/*expanded*/ true);
    original.accept_answer();
    original.handle_key_event(KeyEvent::from(KeyCode::Char('2')));
