fn handle_paste_enter(&mut self, now: Instant) -> bool {
        let in_slash_context = self.slash_commands_enabled()
            && self.draft.prompt_prefix != PromptPrefix::Shell
            && (matches!(self.popups.active, ActivePopup::Command(_))
                || self
                    .current_text()
                    .lines()
                    .next()
                    .unwrap_or("")
                    .starts_with('/'));
        if !self.draft.disable_paste_burst
            && self.draft.paste_burst.is_active()
            && !in_slash_context
            && self
                .draft
                .paste_burst
                .append_control_char_if_active('\n', now)
        {
            return true;
        }
        if !in_slash_context
            && !self.draft.disable_paste_burst
            && self
                .draft
                .paste_burst
                .newline_should_insert_instead_of_submit(now)
        {
            self.draft.textarea.insert_str("\n");
            self.draft.paste_burst.extend_window(now);
            return true;
        }

        false
    }

fn context_transition_discards_prefix_before_routing_the_next_stroke() {
    let mut config = TuiKeymap::default();
    config.list.jump_top = Some(binding("ctrl-x home"));
    config.pager.jump_top = Some(binding("ctrl-x home"));
    let runtime =
        RuntimeKeymap::from_config(&config).expect("non-overlapping list and pager chords");
    let mut matcher = KeyChordMatcher::default();
    assert!(matches!(
        matcher.advance(
            key_event(key_hint::ctrl(KeyCode::Char('x'))),
            &runtime.chords,
            KeymapContextSet::new(KeymapContext::List),
        ),
        KeyChordMatch::Pending(_)
    ));
    assert_eq!(
        matcher.advance(
            KeyCode::Home.into(),
            &runtime.chords,
            KeymapContextSet::new(KeymapContext::Pager),
        ),
        KeyChordMatch::PassThrough
    );
    assert!(!matcher.is_pending());
}

fn default_colors(timeout: Duration) -> io::Result<Option<DefaultColors>> {
    let Ok(output) = std_handle(STD_OUTPUT_HANDLE) else {
        return Ok(None);
    };

    if let Ok(input) = std_handle(STD_INPUT_HANDLE)
        && let Ok(Some(colors)) = query_osc_default_colors(input, output, timeout)
    {
        tracing::debug!(
            foreground = ?colors.fg,
            background = ?colors.bg,
            "using Windows terminal OSC default colors"
        );
        return Ok(Some(colors));
    }

    // ConPTY's PseudoConsoleWindow can report itself as visible, but its palette does not
    // describe the renderer. Only the native ConsoleWindowClass owns the visible colors.
    // SAFETY: Both APIs inspect the process's console window without modifying it.
    let mut window_class = [0_u16; 32];
    let class_len = unsafe {
        GetClassNameW(
            GetConsoleWindow(),
            window_class.as_mut_ptr(),
            window_class.len() as i32,
        )
    };
    if class_len == 0
        || String::from_utf16_lossy(&window_class[..class_len as usize]) != "ConsoleWindowClass"
    {
        tracing::debug!("terminal colors unavailable; retaining terminal defaults");
        return Ok(None);
    }

    let colors = query_console_default_colors(output).ok().flatten();
    if let Some(colors) = colors {
        tracing::debug!(
            foreground = ?colors.fg,
            background = ?colors.bg,
            "using Windows console palette default colors"
        );
    }
    Ok(colors)
}

