fn history_search_highlights_matches_until_accepted() {
        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ true,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );
        composer
            .history
            .record_local_submission(HistoryEntry::new("cargo test".to_string()));
        composer
            .history
            .record_local_submission(HistoryEntry::new("git status".to_string()));

        let _ = composer.handle_key_event(KeyEvent::new(KeyCode::Char('r'), KeyModifiers::CONTROL));
        for ch in ['g', 'i', 't'] {
            let _ = composer.handle_key_event(KeyEvent::new(KeyCode::Char(ch), KeyModifiers::NONE));
        }

        let area = Rect::new(0, 0, 60, 8);
        let textarea_rect = composer
            .layout_with_options(area, Default::default())
            .textarea;
        let mut buf = Buffer::empty(area);
        composer.render(area, &mut buf);
        let x = textarea_rect.x;
        let y = textarea_rect.y;
        assert_eq!(buf[(x, y)].symbol(), "g");
        for offset in 0..3 {
            let modifier = buf[(x + offset, y)].style().add_modifier;
            assert!(modifier.contains(Modifier::REVERSED));
            assert!(modifier.contains(Modifier::BOLD));
        }
        assert!(
            !buf[(x + 3, y)]
                .style()
                .add_modifier
                .contains(Modifier::REVERSED)
        );

        let _ = composer.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        let accepted_textarea_rect = composer
            .layout_with_options(area, Default::default())
            .textarea;
        let mut accepted_buf = Buffer::empty(area);
        composer.render(area, &mut accepted_buf);
        for offset in 0..3 {
            let modifier = accepted_buf
                [(accepted_textarea_rect.x + offset, accepted_textarea_rect.y)]
                .style()
                .add_modifier;
            assert!(!modifier.contains(Modifier::REVERSED));
            assert!(!modifier.contains(Modifier::BOLD));
        }
    }

fn mcp_preview_shares_one_limit_across_blocks_and_preserves_transcript() {
    let mut cell = new_active_mcp_tool_call(
        "call-preview".into(),
        McpInvocation {
            server: "search".into(),
            tool: "lookup".into(),
            arguments: Some(json!({"title": "Search query"})),
        },
        /*animations_enabled*/ false,
    );
    cell.complete(
        Duration::ZERO,
        Ok(result(vec![
            json!({"type": "text", "text": "first\nsecond"}),
            json!({"type": "text", "text": "third\nfourth\nfifth"}),
        ])),
    );
    let display = cell.display_lines(/*width*/ 80);
    let transcript = cell.transcript_lines(/*width*/ 80);
    insta::assert_snapshot!(format!(
        "compact:\n{}\n\nhistory:\n{}\n\ntranscript:\n{}",
        visible_lines(cell.compact_hyperlink_lines(/*width*/ 80))
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
        display
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
        transcript
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    ));
    assert_eq!(
        cell.raw_lines()
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        [
            "Called search.lookup({\"title\":\"Search query\"})",
            "first",
            "second",
            "third",
            "fourth",
            "fifth"
        ],
    );
}

