fn transcript_export_excludes_hidden_review_prompts_and_nested_duplicates() {
    let user = |id: &str, text: &str| ThreadItem::UserMessage {
        id: id.to_string(),
        client_id: None,
        content: vec![UserInput::Text {
            text: text.to_string(),
            text_elements: Vec::new(),
        }],
    };
    let entered_review = ThreadItem::EnteredReviewMode {
        id: "review-enter".to_string(),
        review: "review".to_string(),
    };
    let exited_review = ThreadItem::ExitedReviewMode {
        id: "review-exit".to_string(),
        review: "review".to_string(),
    };
    let duplicate_one = user("duplicate-one", "duplicate review prompt");
    let duplicate_two = user("duplicate-two", "duplicate review prompt");
    let turn = |id: &str, items: Vec<ThreadItem>, status| Turn {
        id: id.to_string(),
        root_turn_id: None,
        items,
        items_view: TurnItemsView::Full,
        status,
        error: None,
        started_at: None,
        completed_at: None,
        duration_ms: None,
    };
    let review = turn(
        "review-turn",
        vec![
            entered_review.clone(),
            user("review-prompt", "hidden review prompt"),
            exited_review.clone(),
        ],
        TurnStatus::Completed,
    );
    let nested = turn(
        "nested-turn",
        vec![duplicate_one.clone(), duplicate_two.clone()],
        TurnStatus::Interrupted,
    );
    assert_eq!(
        visible_export_items(vec![review.clone(), nested]),
        vec![entered_review.clone(), exited_review.clone()],
    );
    let completed = turn(
        "completed-turn",
        vec![duplicate_one.clone(), duplicate_two.clone()],
        TurnStatus::Completed,
    );
    assert_eq!(
        visible_export_items(vec![review, completed]),
        vec![entered_review, exited_review, duplicate_one, duplicate_two],
    );
}

fn queued_voice_answers_return_to_history_once_if_voice_closes_before_delivery() {
    let (mut chat, _sender, mut events, mut ops) = make_chatwidget_manual_with_sender().await;
    let thread_id = activate_voice(&mut chat);
    let mut deliveries = Vec::new();
    for (turn_id, item_id, text) in [
        ("first-turn", "first-answer", "First answer"),
        ("second-turn", "second-answer", "Second answer"),
    ] {
        start_item(
            &mut chat,
            thread_id,
            turn_id,
            user_item("<realtime_delegation><input>question</input></realtime_delegation>"),
        );
        let answer = agent_item(item_id, text, Some(MessagePhase::FinalAnswer));
        start_item(&mut chat, thread_id, turn_id, answer.clone());
        complete_item(&mut chat, thread_id, turn_id, answer.clone());
        finish_turn(
            &mut chat,
            thread_id,
            turn_id,
            vec![answer],
            TurnStatus::Completed,
        );
        let AppCommand::RealtimeConversationSpeech { delivery_id, .. } = ops.try_recv().unwrap()
        else {
            panic!("completed voice turn should queue speech");
        };
        deliveries.push(delivery_id);
    }
    assert_eq!(chat.realtime_conversation.pending_speech.len(), 2);
    while events.try_recv().is_ok() {}

    chat.stop_realtime_conversation();
    chat.reset_realtime_conversation();
    for delivery_id in deliveries {
        chat.restore_undelivered_realtime_speech(delivery_id);
    }
    let mut rendered = Vec::new();
    while let Ok(event) = events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event {
            rendered.push(
                cell.display_lines(/*width*/ 80)
                    .into_iter()
                    .map(|line| line.to_string())
                    .collect::<String>(),
            );
        }
    }
    assert_eq!(
        rendered
            .iter()
            .filter(|line| line.contains("First answer"))
            .count(),
        1
    );
    assert_eq!(
        rendered
            .iter()
            .filter(|line| line.contains("Second answer"))
            .count(),
        1
    );
}

