fn begin_direct_vim_edit(&mut self) -> bool {
        if !self.draft.textarea.is_vim_enabled()
            || self.draft.textarea.is_vim_operator_pending()
            || self.vim_history.pending.is_some()
            || self.history_search.is_some()
        {
            return false;
        }

        self.begin_vim_edit_transaction();
        if self.vim_history.pending.is_none() {
            return false;
        }
        let mut vim_state = VimPersistentState::default();
        self.draft
            .textarea
            .swap_vim_persistent_state(&mut vim_state);
        vim_state.commands.last_change.clear();
        self.draft
            .textarea
            .swap_vim_persistent_state(&mut vim_state);
        true
    }

fn detailed_hyperlink_lines(
        &self,
        width: u16,
        mode: HistoryRenderMode,
    ) -> Vec<HyperlinkLine> {
        let mut lines: Vec<HyperlinkLine> = vec![];
        for (i, call) in self.iter_calls().enumerate() {
            if i > 0 {
                lines.push("".into());
            }
            let script = strip_bash_lc_and_escape(&call.command);
            let highlighted_script = highlight_bash_to_lines(&script);
            let cmd_display = adaptive_wrap_hyperlink_lines(
                &plain_hyperlink_lines(highlighted_script),
                RtOptions::new(width as usize)
                    .initial_indent("$ ".magenta().into())
                    .subsequent_indent("    ".into()),
            );
            lines.extend(cmd_display);

            if let Some(output) = call.output.as_ref() {
                if !call.is_unified_exec_interaction() {
                    let wrap_width = width.max(/*other*/ 1) as usize;
                    let wrap_opts = RtOptions::new(wrap_width);
                    for unwrapped in output
                        .transcript_lines()
                        .map(|line| ansi_escape_line(line.as_ref()))
                    {
                        lines.extend(adaptive_wrap_hyperlink_lines(
                            &[unwrapped.into()],
                            wrap_opts.clone(),
                        ));
                    }
                }
                if call.duration.is_some() || output.exit_code != 0 {
                    let mut result: Line = if output.exit_code == 0 {
                        Line::from("✓".green().bold())
                    } else {
                        Line::from(vec![
                            "✗".red().bold(),
                            format!(" ({})", output.exit_code).into(),
                        ])
                    };
                    if let Some(duration) = call.duration {
                        let duration = format_duration(duration);
                        result.push_span(format!(" • {duration}").dim());
                    }
                    lines.push(result.into());
                }
            }
            lines.extend(self.group.details.lines_after(i + 1, width, mode));
        }
        lines
    }

