fn with_restored<R, F, Fut>(&mut self, handoff: TerminalHandoff, f: F) -> R
    where
        F: FnOnce() -> Fut,
        Fut: Future<Output = R>,
    {
        // Pause crossterm events to avoid stdin conflicts with external program `f`.
        self.pause_events();

        // Restore both screens' input modes before giving the terminal to an editor. Repaint the
        // last frame on the alternate screen so separate-window editors leave Codex visible.
        let was_alt_screen = self.is_alt_screen_active();
        let visible_frame = (was_alt_screen && matches!(handoff, TerminalHandoff::KeepScreen))
            .then(|| self.terminal.previous_buffer().clone());
        let restore_result = if let Some(visible_frame) = visible_frame {
            stdout()
                .sync_update(|_| {
                    let leave_result = self.leave_alt_screen_for_handoff();
                    let main_result = restore_keep_raw(TerminalHandoff::Restore);
                    let enter_result = self.enter_alt_screen();
                    if !self.is_alt_screen_active() {
                        return leave_result.and(main_result).and(enter_result);
                    }
                    let draw_result = if enter_result.is_ok() {
                        self.terminal.draw(|frame| {
                            let area = frame.area().intersection(visible_frame.area);
                            for y in area.top()..area.bottom() {
                                for x in area.left()..area.right() {
                                    frame.buffer_mut()[(x, y)] = visible_frame[(x, y)].clone();
                                }
                            }
                        })
                    } else {
                        Ok(())
                    };
                    let input_result = restore_keep_raw(TerminalHandoff::KeepScreen);
                    leave_result
                        .and(main_result)
                        .and(enter_result)
                        .and(draw_result)
                        .and(input_result)
                })
                .and_then(std::convert::identity)
        } else {
            if was_alt_screen {
                let _ = self.leave_alt_screen_for_handoff();
            }
            restore_keep_raw(TerminalHandoff::Restore)
        };
        if let Err(err) = restore_result {
            tracing::warn!("failed to restore terminal modes before external program: {err}");
        }
        if let Err(err) = terminal_stderr::pause() {
            tracing::warn!("failed to restore terminal stderr before external program: {err}");
        }
        if let Err(err) = crate::terminal_program_status::clear_terminal_program_status() {
            tracing::debug!(error = %err, "failed to clear terminal program status before external program");
        }

        let output = f().await;

        if was_alt_screen && matches!(handoff, TerminalHandoff::KeepScreen) {
            // The editor may already have left the alternate screen. Return to the main screen
            // before reapplying its keyboard mode and entering the alternate screen again.
            let _ = self.leave_alt_screen_for_handoff();
        }

        if let Err(err) = terminal_stderr::resume() {
            tracing::warn!("failed to suppress terminal stderr after external program: {err}");
        }
        if let Err(err) = set_modes() {
            tracing::warn!("failed to re-enable terminal modes after external program: {err}");
        }
        self.terminal.invalidate_cursor_state();
        // After the external program `f` finishes, reset terminal state and flush any buffered keypresses.
        flush_terminal_input_buffer();

        if was_alt_screen {
            let _ = self.enter_alt_screen();
        }

        crate::terminal_program_status::invalidate_terminal_program_status();
        self.resume_events();
        self.schedule_screen_size_recheck(Duration::ZERO);
        output
    }

fn editor_handoff_blocks_input_until_acknowledged() {
    let (tx, mut rx) = unbounded_channel();
    let mut keymap = RuntimeKeymap::defaults().list;
    keymap.accept = vec![crate::key_hint::plain(KeyCode::BackTab)];
    let mut panel = ConfigPanel::new(&Tui::default(), AppEventSender::new(tx), keymap, STATUS);
    panel.handle_key_event(KeyEvent::from(KeyCode::Char('/')));
    assert!(panel.handle_paste("terminal title".to_string()));
    panel.handle_key_event(KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT));
    let AppEvent::OpenConfigEditor(handoff) = rx.try_recv().expect("open editor event") else {
        panic!("expected config editor handoff");
    };
    assert_eq!(
        (handoff.editor, handoff.activation_key),
        (
            ConfigEditor::TerminalTitle,
            crate::key_hint::plain(KeyCode::BackTab)
        )
    );
    let activated_at = handoff.active_at().expect("active handoff");

    panel.handle_key_event(KeyEvent::new_with_kind(
        KeyCode::Tab,
        KeyModifiers::NONE,
        KeyEventKind::Repeat,
    ));
    assert!(
        handoff
            .active_at()
            .is_some_and(|seen_at| seen_at > activated_at)
    );
    panel.handle_key_release(KeyEvent::new_with_kind(
        KeyCode::Tab,
        KeyModifiers::NONE,
        KeyEventKind::Release,
    ));
    assert_eq!(handoff.active_at(), None);
    panel.handle_key_event(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
    assert_eq!(panel.on_ctrl_c(), CancellationEvent::Handled);
    assert!(!panel.handle_paste(" ignored".to_string()));
    assert!(!panel.is_complete());
    assert!(rx.try_recv().is_err());

    panel.update_config_panel(&ConfigPanelUpdate {
        tui: Tui::default(),
        keymap: RuntimeKeymap::defaults().list,
        status: STATUS,
        notice: None,
    });
    panel.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
    assert!(rx.try_recv().is_err());

    panel.config_editor_opened();
    panel.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
    assert!(matches!(
        rx.try_recv().expect("reopened editor event"),
        AppEvent::OpenConfigEditor(handoff) if handoff.editor == ConfigEditor::TerminalTitle
    ));
}

