fn transcript_file_resolves_relative_paths_and_refuses_to_overwrite() {
    let directory = tempfile::tempdir().expect("temporary directory");
    let path = write_transcript(
        directory.path(),
        "conversation.md".as_ref(),
        "# First export\n",
    )
    .expect("write first export");

    assert_eq!(path, directory.path().join("conversation.md"));
    assert!(write_transcript(directory.path(), &path, "# Second export\n").is_err());
    assert_eq!(
        std::fs::read_to_string(&path).expect("read"),
        "# First export\n"
    );

    let directory_name = directory.path().file_name().expect("directory name");
    let requested = std::path::Path::new("~")
        .join(directory_name)
        .join("conversation.md");
    let error = write_transcript(directory.path(), &requested, "# Export\n")
        .expect_err("missing home-relative parent directory");
    assert!(error.contains(&dirs::home_dir().expect("home").display().to_string()));
}

fn status_line_right_indicator_line(
    collaboration_mode_indicator: Option<CollaborationModeIndicator>,
    goal_status_indicator: Option<&GoalStatusIndicator>,
    ide_context_active: bool,
    show_cycle_hint: bool,
) -> Option<Line<'static>> {
    let primary_indicator = mode_indicator_line(collaboration_mode_indicator, show_cycle_hint)
        .or_else(|| goal_status_indicator_line(goal_status_indicator));
    let ide_context_indicator = ide_context_active.then(|| Line::from(vec!["IDE context".cyan()]));
    let mut line: Option<Line<'static>> = None;

    for indicator in [primary_indicator, ide_context_indicator]
        .into_iter()
        .flatten()
    {
        if let Some(line) = line.as_mut() {
            line.push_span(" · ".set_style(secondary_text_style()));
            for span in indicator.spans {
                line.push_span(span);
            }
        } else {
            line = Some(indicator);
        }
    }

    line
}

