fn absorbing_older_history_keeps_live_readers_and_selections_on_their_displayed_revision() {
    for selecting in [false, true] {
        let mut cells = vec![cell("header")];
        let mut view = TranscriptView::default();
        live(
            &mut view,
            /*revision*/ 1,
            "zero\none\ntwo\nthree\nfour\nfive",
        );
        render(&mut view, &cells, /*width*/ 20);
        view.scroll(&cells, /*rows*/ -2);
        render(&mut view, &cells, /*width*/ 20);
        if selecting {
            view.begin_selection(&cells, /*column*/ 0, /*row*/ 0, /*clicks*/ 3);
            view.end_drag();
        }
        let before = render(&mut view, &cells, /*width*/ 20);
        let selected = view.selected_text(&cells);

        cells.extend([cell("older turn"), cell("older group")]);
        view.history_loaded(&cells, 1..3);
        view.absorb_tail_into_live(
            &cells, /*previous_revision*/ 1, /*hydrated_revision*/ 2,
        );
        cells.pop();
        live(
            &mut view,
            /*revision*/ 2,
            "hydrated group\ncurrent preview",
        );

        assert_eq!(render(&mut view, &cells, /*width*/ 20), before);
        assert_eq!(view.selected_text(&cells), selected);
        assert!(!view.unseen_activity);
        assert_eq!(view.snapshot_cells().expect("held revision").len(), 3);
        view.jump_to_latest();
        render(&mut view, &cells, /*width*/ 20);
        assert!(view.snapshot().is_none());
        assert_eq!(
            view.live.as_ref().expect("hydrated tail").text(),
            "hydrated group\ncurrent preview"
        );
    }
}

fn transcript_overlay_history_rebuild_preserves_only_the_live_tail() {
    for replace in [false, true] {
        for tail in [
            None,
            Some(Vec::new()),
            Some(vec![HyperlinkLine::from("live")]),
        ] {
            let mut overlay = transcript_overlay(
                ["first", "last"]
                    .map(|line| {
                        Arc::new(TestCell {
                            lines: vec![line.into()],
                        }) as Arc<dyn HistoryCell>
                    })
                    .to_vec(),
            );
            let key = tail.as_ref().map(|_| ActiveCellTranscriptKey {
                cacheable: true,
                revision: 1,
                is_stream_continuation: false,
                animation_tick: None,
            });
            overlay.sync_live_tail(/*width*/ 40, key, |_| tail.clone());
            let consolidated = Arc::new(TestCell {
                lines: vec!["first".into(), "last".into()],
            });
            if replace {
                overlay.replace_cells(vec![consolidated]);
            } else {
                overlay.consolidate_cells(0..2, consolidated);
            }
            // A draw may arrive after the active tail has already been cleared.
            overlay.sync_live_tail(/*width*/ 40, key, |_| tail.clone());
            let mut reopened = transcript_overlay(overlay.cells.clone());
            reopened.sync_live_tail(/*width*/ 40, key, |_| tail.clone());
            let area = Rect::new(
                /*x*/ 0, /*y*/ 0, /*width*/ 40, /*height*/ 10,
            );
            let mut actual = Buffer::empty(area);
            let mut expected = Buffer::empty(area);
            overlay.render(area, &mut actual);
            reopened.render(area, &mut expected);
            assert_eq!(actual, expected);
            if tail.is_none() {
                assert_snapshot!(
                    "transcript_overlay_completed_stream",
                    buffer_to_text(&actual, area)
                );
            }
        }
    }
}

fn sync_select_range(&mut self, cells: &[Arc<dyn HistoryCell>]) {
        let Some(mark) = self.select_mode.and_then(|mode| mode.mark) else {
            return;
        };
        let snapshot = self.snapshot_cells();
        let cells = snapshot.as_deref().unwrap_or(cells);
        let after_anchor = self.after_grapheme(cells, mark.anchor);
        let after_active = self.after_grapheme(cells, mark.active);
        let Some(mut selection) = self.selection.take() else {
            return;
        };
        let (start, end) =
            if self.anchor_order(cells, mark.anchor) <= self.anchor_order(cells, mark.active) {
                (mark.anchor, after_active)
            } else {
                (after_anchor, mark.active)
            };
        selection.set_keyboard_marked_range(
            start,
            end,
            (mark.anchor, after_anchor),
            SelectionUnit::Character,
        );
        self.pin_selection_range(cells, &mut selection);
        self.selection = Some(selection);
    }

