                (
                    "global.find_transcript",
                    self.app.find_transcript.as_slice(),
                ),
            ]),
        )?;

        validate_unique("agents", context_bindings(KeymapContext::Agents))?;
        validate_no_reserved(
            "agents",
            context_bindings(KeymapContext::Agents),
            MAIN_RESERVED_BINDINGS,
            [(
                "search",
                "fixed.slash_command",
                key_hint::plain(KeyCode::Char('/')),
            )],
        )?;
        for (action, bindings) in context_bindings(KeymapContext::Agents) {
            #[cfg(unix)]
            if bindings.contains(&key_hint::ctrl(KeyCode::Char('z'))) {
                return Err(format!(
                    "tui.keymap.agents.{action}: ctrl-z is reserved for suspend"
                ));
            }
            if bindings.iter().any(|binding| {
                let (code, modifiers) = binding.normalized_parts();
                (action != "delete"
                    && code == KeyCode::Backspace
                    && modifiers == KeyModifiers::NONE)
                    || (matches!(code, KeyCode::Char(_)) && crate::key_hint::is_altgr(modifiers))
            }) {
                return Err(format!(
                    "tui.keymap.agents.{action}: AltGr and backspace are reserved for editing"
                ));
            }
        }

        validate_unique("approval", context_bindings(KeymapContext::Approval))?;

        let mut seen: HashMap<(KeyCode, KeyModifiers), &'static str> = HashMap::new();
        for (action, bindings) in approval_overlay_bindings {
            for binding in bindings {
                let key = binding.normalized_parts();
                if let Some(previous) = seen.insert(key, action) {
                    // Approval overlays intentionally reserve Esc as a stable
                    // cancellation path even though decline options may also
                    // display it in contexts where that is safe.
                    if previous == "list.cancel"
                        && action == "approval.decline"
                        && key == (KeyCode::Esc, KeyModifiers::NONE)
                    {
                        continue;
                    }
                    return Err(format!(
                        "Ambiguous approval overlay keymap bindings: `{previous}` and `{action}` use the same key. \
Set unique keys in `~/.codex/config.toml` and retry. \
See the Codex keymap documentation for supported actions and examples."
                    ));
                }
            }
        }

        Ok(())
    }

fn table_renders_app_style_rows_with_themed_bold_header() {
    let md = "| A | B |\n|---|---|\n| 1 | 2 |\n";
    let text = render_markdown_text(md);
    let lines: Vec<String> = text
        .lines
        .iter()
        .map(|line| line.spans.iter().map(|span| span.content.clone()).collect())
        .collect();

    assert_eq!(
        lines,
        vec![
            " A      B".to_string(),
            "━━━━━  ━━━━━".to_string(),
            " 1      2".to_string(),
        ]
    );
    assert!(text.lines[0].style.add_modifier.contains(Modifier::BOLD));
    assert!(
        text.lines[0].style.fg.is_some(),
        "expected the syntax theme to provide a table header accent"
    );
    assert!(
        text.lines[1].spans[0]
            .style
            .add_modifier
            .contains(Modifier::DIM)
    );
    assert!(!text.lines[2].style.add_modifier.contains(Modifier::BOLD));
}

fn composer_with_history() -> ChatComposer {
    let (tx, _rx) = unbounded_channel();
    let mut composer = ChatComposer::new(
        /*has_input_focus*/ true,
        AppEventSender::new(tx),
        /*enhanced_keys_supported*/ false,
        "Ask Codex to do anything".to_string(),
        /*disable_paste_burst*/ false,
    );
    for entry in ["git status", "git log"] {
        composer
            .history
            .record_local_submission(HistoryEntry::new(entry.to_string()));
    }
    composer.set_text_content("draft".to_string(), Vec::new(), Vec::new());
    composer
}

fn partial_markup_is_balanced_and_preserves_selected_characters() {
    for (source, selected, expected) in [
        ("**hello café界**", "café界", "**café界**"),
        ("before * first *", "first", "first"),
        ("before **hello world** after", " world", "&#32;**world**"),
        (
            "**strong *nested* text**",
            "strong nested text",
            "**strong _nested_ text**",
        ),
        (
            r"escaped \![label](https://example.com)",
            "escaped !label",
            r"escaped \![label](<https://example.com>)",
        ),
        (
            "[documentation](https://example.com)",
            "ment",                          // codespell:ignore ment
            "[ment](<https://example.com>)", // codespell:ignore ment
        ),
        ("[**label**](/repo/file.rs)", "label", "**label**"),
        (
            "escaped \\*literal\\* &amp; `code`",
            "*literal* & code",
            "\\*literal\\* \\& `code`",
        ),
    ] {
        let layout = markdown_layout(source, /*width*/ 80);
        let start = layout.text().find(selected).expect(source);
        assert_eq!(
            payload(&layout, start..start + selected.len()),
            (expected.into(), CopyFormat::Markdown),
            "{source}"
        );
    }
}

