fn transcript_images_survive_unrelated_redraws_and_are_removed_for_overlays() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("viewed.png");
        image::RgbaImage::from_pixel(32, 32, image::Rgba([10, 110, 200, 255]))
            .save(&path)
            .unwrap();
        for protocol in [
            crate::pets::ImageProtocol::Kitty,
            crate::pets::ImageProtocol::KittyLocalFile,
        ] {
            let image = std::sync::Arc::new(
                crate::transcript_image::TranscriptImage::load(&path, /*width*/ 40, protocol)
                    .unwrap(),
            );
            let mut terminal =
                Terminal::with_options(CaptureBackend::new(/*width*/ 40, /*height*/ 12)).unwrap();
            let size = terminal.last_known_screen_size;
            terminal.set_viewport_area(Rect::new(
                /*x*/ 0,
                /*y*/ 0,
                size.width,
                size.height,
            ));
            let mut retained = Vec::new();
            for (index, text) in ["", "a", "ab", "ab"].into_iter().enumerate() {
                if index == 3 {
                    assert_eq!(terminal.backend().output().matches("_Ga=T").count(), 1);
                    terminal.clear().unwrap();
                }
                terminal
                    .draw_with_size(size, &mut retained, |frame| {
                        Line::from(text).render(
                            Rect::new(
                                /*x*/ 0, /*y*/ 10, /*width*/ 40, /*height*/ 1,
                            ),
                            frame.buffer_mut(),
                        );
                        frame
                            .transcript_images
                            .push(crate::transcript_image::ImagePlacement {
                                image: std::sync::Arc::clone(&image),
                                area: Rect::new(
                                    /*x*/ 2,
                                    /*y*/ 2,
                                    image.columns,
                                    image.rows,
                                ),
                                first_row: 0,
                                file: None,
                            });
                    })
                    .unwrap();
            }
            let output = terminal.backend().output();
            assert_eq!(output.matches("_Ga=T").count(), 2);
            assert_eq!(output.matches("_Ga=d").count(), 0);
            if protocol == crate::pets::ImageProtocol::KittyLocalFile {
                assert!(output.contains("t=f") && output.contains("C=1"));
                assert!(retained[0].file.as_ref().unwrap().path().exists());
            } else {
                assert!(retained[0].file.is_none());
            }
            terminal
                .draw_with_size(size, &mut retained, |_| {})
                .unwrap();
            assert_eq!(terminal.backend().output().matches("_Ga=d").count(), 1);
            assert!(retained.is_empty());
        }
    }

fn refreshed_mouse_policy_applies_to_fullscreen_and_overlays() {
    use super::super::OverlayInput;

    for owned in [false, true] {
        let screen = AlternateScreen::default();
        let mut output = Vec::new();
        let mut terminal = vt100::Parser::new(
            /*rows*/ 24, /*cols*/ 80, /*scrollback_len*/ 0,
        );
        let mut input = OverlayInput::Default;
        screen
            .enter(&mut output, input.captures_mouse(owned))
            .unwrap();
        for disabled in [true, false, true] {
            screen
                .mouse_capture_disabled
                .store(disabled, Ordering::Relaxed);
            for next in [
                OverlayInput::Transcript,
                OverlayInput::Usage,
                OverlayInput::Onboarding,
                OverlayInput::Default,
                OverlayInput::StaticPager,
            ] {
                input.apply(&screen, &mut output, next, owned).unwrap();
                terminal.process(&std::mem::take(&mut output));
                let capture = match next {
                    OverlayInput::Default => owned,
                    OverlayInput::Transcript | OverlayInput::Usage => true,
                    OverlayInput::StaticPager | OverlayInput::Onboarding => false,
                };
                let expected = if !disabled && capture {
                    vt100::MouseProtocolMode::AnyMotion
                } else {
                    vt100::MouseProtocolMode::None
                };
                assert_eq!(
                    (
                        terminal.screen().alternate_screen(),
                        terminal.screen().mouse_protocol_mode()
                    ),
                    (true, expected),
                );
            }
        }
        screen.leave(&mut output).unwrap();
    }
}

