fn mouse_selection_preserves_header_reservation_at_turn_boundaries() {
    let cells = vec![
        user("First question"),
        cell("first answer"),
        user("Second question"),
        cell("done 10:16 AM"),
    ];
    for width in [40, 15] {
        for height in [6, 7, 8] {
            for drag in [false, true] {
                let mut view = TranscriptView::default();
                let before = render(&mut view, &cells, width, height);
                let down = MouseEvent {
                    kind: MouseEventKind::Down(MouseButton::Left),
                    column: 5,
                    row: height - 1,
                    modifiers: KeyModifiers::NONE,
                };
                view.handle_mouse(down, &cells);
                assert_eq!(
                    render(&mut view, &cells, width, height),
                    before,
                    "mouse down at {width}x{height}"
                );
                if !drag {
                    view.handle_mouse(
                        MouseEvent {
                            kind: MouseEventKind::Up(MouseButton::Left),
                            ..down
                        },
                        &cells,
                    );
                    assert_eq!(
                        (
                            render(&mut view, &cells, width, height),
                            view.selected_text(&cells),
                            view.is_following(),
                        ),
                        (before, None, true),
                        "empty release at {width}x{height}"
                    );
                    continue;
                }
                let end = MouseEvent {
                    kind: MouseEventKind::Drag(MouseButton::Left),
                    column: 13,
                    ..down
                };
                view.handle_mouse(end, &cells);
                let selected = render(&mut view, &cells, width, height);
                assert_eq!(text(&selected), text(&before));
                assert_eq!(view.selected_text(&cells).as_deref(), Some("10:16 AM"));
                view.handle_mouse(
                    MouseEvent {
                        kind: MouseEventKind::Up(MouseButton::Left),
                        ..end
                    },
                    &cells,
                );
                assert_eq!(render(&mut view, &cells, width, height), selected);
                let Some(ViewAction::Copy(copied)) = view.handle_key(
                    KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
                    &cells,
                ) else {
                    panic!("copy selection at {width}x{height}");
                };
                assert_eq!(copied, "10:16 AM");
                assert_eq!(
                    selected
                        .content
                        .iter()
                        .filter(|cell| cell.modifier.contains(Modifier::REVERSED))
                        .map(ratatui::buffer::Cell::symbol)
                        .collect::<String>(),
                    copied
                );
            }
        }
    }
}

fn handle_event(&mut self, tui: &mut tui::Tui, event: TuiEvent) -> Result<()> {
        if let Some(completion) = tui.clipboard.poll()
            && let Some(follow) =
                self.view
                    .finish_copy(&self.cells, completion, /*current*/ true)
        {
            self.notice = Some(match &completion.1 {
                Ok(status) => status.message("selection"),
                Err(error) => format!("Copy failed: {error}"),
            });
            if follow {
                self.view.jump_to_latest();
                self.is_done = self.browsing_footer.is_some();
            }
        }
        if matches!(event, TuiEvent::Resume | TuiEvent::FocusLost) {
            self.view.cancel_primary();
            self.view.end_drag();
        }
        // Apply a queued prompt jump before navigation can move away from it.
        if self.pending_highlight.is_some()
            && (matches!(&event, TuiEvent::Key(key) if key.kind != KeyEventKind::Release)
                || matches!(&event, TuiEvent::Mouse(mouse) if mouse.kind != MouseEventKind::Moved))
        {
            self.draw(tui)?;
        }
        let action = match event {
            TuiEvent::Key(key) => self.handle_key(key),
            TuiEvent::Mouse(mut mouse) => {
                if matches!(
                    mouse.kind,
                    MouseEventKind::ScrollUp | MouseEventKind::ScrollDown
                ) {
                    mouse.column = self.content_area.x;
                    mouse.row = self.content_area.bottom().saturating_sub(1);
                }
                self.view.handle_mouse(mouse, &self.cells)
            }
            TuiEvent::Paste(text) => {
                if self.view.is_search_editing() {
                    self.view.end_selection(&self.cells);
                }
                self.view.paste_search(&text).then_some(ViewAction::Changed)
            }
            TuiEvent::Draw | TuiEvent::Resize(_) | TuiEvent::FocusGained | TuiEvent::Resume => {
                if matches!(event, TuiEvent::Draw) && self.view.tick_selection(&self.cells) {
                    tui.frame_requester()
                        .schedule_frame_in(crate::tui::TARGET_FRAME_INTERVAL);
                }
                self.draw(tui)?;
                return Ok(());
            }
            TuiEvent::FocusLost => None,
        };
        if let Some(action) = action {
            self.apply_action(tui, action);
            tui.frame_requester().schedule_frame();
        }
        Ok(())
    }

fn shortcut_help_hides_visible_sparkles_without_restarting_their_deadline() {
    palette(|| {
        let started = Instant::now();
        let during = started + Duration::from_secs(/*secs*/ 4);
        let expired = started + IDLE_TIMEOUT;
        let mut snapshots = Vec::new();
        for (scenario, input) in [
            (
                "unmodified",
                KeyEvent::new(KeyCode::Char('?'), KeyModifiers::NONE),
            ),
            (
                "shifted",
                KeyEvent::new(KeyCode::Char('?'), KeyModifiers::SHIFT),
            ),
            (
                "remapped",
                KeyEvent::new(KeyCode::Char('q'), KeyModifiers::NONE),
            ),
        ] {
            for close_at in [during, expired] {
                let mut pane = pane();
                if scenario == "remapped" {
                    pane.composer.toggle_shortcuts_keys =
                        vec![crate::key_hint::plain(KeyCode::Char('q'))];
                }
                pane.mark_fresh_task_for_sparkle("gpt-6-astra", &enabled());
                let active = draw(&pane.composer, /*width*/ 80, started).0;
                let expected = draw(&pane.composer, /*width*/ 80, during).0;
                assert!(!dots(&active).is_empty());
                assert!(!dots(&expected).is_empty());
                pane.handle_key_event(input);
                assert!(
                    matches!(pane.composer.sparkle.phase.get(), Phase::Visible(at) if at == started)
                );
                assert_eq!(pane.composer.current_text(), "");
                let help = draw(&pane.composer, /*width*/ 80, during).0;
                assert!(dots(&help).is_empty(), "{scenario}");
                if close_at == expired {
                    let still_open = draw(&pane.composer, /*width*/ 80, expired).0;
                    assert!(dots(&still_open).is_empty());
                    assert!(pane.composer.sparkle.phase.get() == Phase::Finished);
                }
                pane.handle_key_event(input);
                let closed = draw(&pane.composer, /*width*/ 80, close_at).0;
                assert_eq!(
                    dots(&closed),
                    if close_at == expired {
                        Vec::new()
                    } else {
                        dots(&expected)
                    },
                    "{scenario}"
                );
                if scenario == "unmodified" {
                    snapshots.push(format!(
                        "expires during help: {}\ninitial:\n{}\nshortcut help:\n{}\nafter closing:\n{}",
                        close_at == expired,
                        text(&active),
                        text(&help),
                        text(&closed)
                    ));
                }
            }
        }

        let mut waiting = pane();
        waiting.mark_fresh_task_for_sparkle("gpt-6-astra", &enabled());
        key(&mut waiting, KeyCode::Char('?'));
        let help = draw(&waiting.composer, /*width*/ 80, expired).0;
        assert!(dots(&help).is_empty());
        assert!(waiting.composer.sparkle.phase.get() == Phase::Waiting);
        key(&mut waiting, KeyCode::Char('?'));
        assert!(!dots(&draw(&waiting.composer, /*width*/ 80, expired).0).is_empty());

        let mut literal = pane();
        literal.mark_fresh_task_for_sparkle("gpt-6-astra", &enabled());
        assert!(!dots(&draw(&literal.composer, /*width*/ 80, started).0).is_empty());
        literal.handle_paste("?".into());
        assert_eq!(literal.composer.current_text(), "?");
        key(&mut literal, KeyCode::Backspace);
        assert!(dots(&draw(&literal.composer, /*width*/ 80, during).0).is_empty());
        insta::assert_snapshot!(snapshots.join("\n\n"));
    });
}

