fn render(source: &str, width: Option<usize>, theme: &Theme) -> Vec<Line<'static>> {
    let width = width.unwrap_or(120);
    let diagram = match codex_mermaid::render_spans(source, width) {
        Ok(diagram) => diagram,
        Err(error) => {
            let notice = match error {
                RenderError::Unsupported => {
                    "This Mermaid diagram uses features the terminal renderer doesn't support."
                }
                RenderError::TooWide => {
                    "This Mermaid diagram doesn't fit the current terminal width."
                }
                RenderError::Limit => {
                    "This Mermaid diagram exceeds the terminal renderer's size limits."
                }
            };
            let mut lines = textwrap::wrap(notice, width.max(/*other*/ 1))
                .into_iter()
                .map(|line| Line::from(line.into_owned().dim()))
                .collect::<Vec<_>>();
            lines.extend(highlight_code_to_lines(source, "mermaid"));
            return lines;
        }
    };
    let node = foreground_style_for_scopes_with_theme(
        theme,
        &["entity.name.type", "support.type", "variable"],
    )
    .unwrap_or_else(|| Style::default().cyan());
    let edge = foreground_style_for_scopes_with_theme(theme, &["comment"])
        .unwrap_or_else(|| Style::default().dim());
    diagram
        .into_iter()
        .map(|line| {
            Line::from(
                line.into_iter()
                    .map(|span| {
                        let style = match span.role {
                            Role::Node => node,
                            Role::Edge => edge,
                            Role::Text => Style::default(),
                        };
                        Span::styled(span.text, style)
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .collect()
}

fn bounded_query_paste_keeps_the_suffix_and_whole_graphemes() {
    let mut view = TranscriptView::default();
    view.begin_search();
    view.paste_search("X\r\nY\rZ");
    assert_eq!(view.search.editor.text(), "X\nY\nZ");
    view.cancel_search();
    view.begin_search();
    let original = format!("{}Z", "a".repeat(QUERY_BYTES - 2));
    view.paste_search(&original);
    view.handle_search_key(KeyEvent::new(KeyCode::Left, KeyModifiers::NONE), &[]);
    view.paste_search("e\u{301}");
    assert_eq!(
        (view.search.editor.text(), view.search.query_truncated),
        (original.as_str(), true)
    );
    view.paste_search("b");
    let full = format!("{}bZ", "a".repeat(QUERY_BYTES - 2));
    view.handle_search_key(KeyEvent::new(KeyCode::Char('c'), KeyModifiers::NONE), &[]);
    assert_eq!(
        (view.search.editor.text(), view.search.query_truncated),
        (full.as_str(), true)
    );
    insta::assert_snapshot!(view.search.status_line(/*width*/ 100, view.history).to_string(), @"Searching… · full transcript · esc cancel · query limited to 4 KiB");
    view.handle_search_key(KeyEvent::new(KeyCode::Delete, KeyModifiers::NONE), &[]);
    assert_eq!(view.search.editor.text(), &full[..full.len() - 1]);
}

