                    !configured_context_binding_is_used(&keymap.agents, *binding)
                        && !configured_context_binding_is_used(&keymap.list, *binding)
                        && !configured_context_binding_is_used(&keymap.global, *binding)
                        && !chords.bindings.iter().any(|chord| {
