            cancel: list_cancel,
            chord_hints: Arc::clone(&chords),
        };

        for (configured, bindings) in [
            (keymap.agents.resume.as_ref(), &mut agents.resume),
            (keymap.agents.search.as_ref(), &mut agents.search),
            (keymap.agents.new_task.as_ref(), &mut agents.new_task),
