        }

        let mut resolved = Self {
            app,
            chords,
            chat,
            composer,
            editor,
            vim_normal,
            vim_operator,
            vim_search: VimSearchKeymap {
                forward: resolve_local!(keymap, defaults, vim_search, forward),
                backward: resolve_local!(keymap, defaults, vim_search, backward),
                next: resolve_local!(keymap, defaults, vim_search, next),
                previous: resolve_local!(keymap, defaults, vim_search, previous),
            },
            vim_text_object,
            pager,
            list,
            agents,
            approval,
        };

        let configured: Vec<_> = runtime_action_bindings(&resolved)
            .filter(|action| {
                action.id.context.overlaps(KeymapContext::VimNormal)
                    && bindings::configured_binding_for_action(keymap, action.id)
                        .is_some_and(Option::is_some)
            })
            .flat_map(|action| action.bindings.iter().copied())
            .collect();
        for (setting, bindings) in [
            (
                keymap.vim_normal.undo.as_ref(),
                &mut resolved.vim_normal.undo,
            ),
            (
                keymap.vim_normal.redo.as_ref(),
                &mut resolved.vim_normal.redo,
            ),
            (
                keymap.vim_normal.enter_replace_mode.as_ref(),
                &mut resolved.vim_normal.enter_replace_mode,
            ),
        ] {
            if setting.is_none() {
                bindings.retain(|binding| {
                    let (code, modifiers) = binding.parts();
                    let event = KeyEvent::new(code, modifiers);
                    !configured.is_pressed(event)
                        && !resolved.chords.bindings.iter().any(|chord| {
                            chord.action.context.overlaps(KeymapContext::VimNormal)
                                && chord.chord.prefix.is_press(event)
                        })
                });
            }
        }
        resolved.configure_search(keymap)?;
        chords::quick_dial_defaults::register(keymap, &mut resolved);
        resolved.validate_conflicts()?;
        chords::validate_chord_conflicts(&resolved)?;
        chords::install_dispatch_bindings(&mut resolved)?;
        Ok(resolved)
    }

fn new(animations_enabled: bool) -> Self {
        Self {
            start_time: Instant::now(),
            animations_enabled,
        }
    }

fn buffered_typing_survives_vim_changes_and_cancellation() {
    let (mut composer, _rx) = new_test_composer();
    composer.handle_key_event(KeyCode::Char('x').into());
    composer.set_vim_enabled(/*enabled*/ true);
    assert_eq!(composer.current_text(), "x");
    composer.set_vim_enabled(/*enabled*/ false);
    composer.handle_key_event(KeyCode::Char('y').into());
    assert_eq!(composer.clear_for_ctrl_c(), Some("xy".into()));
    assert!(!composer.is_in_paste_burst());
    composer.handle_key_event(KeyCode::Up.into());
    assert_eq!(composer.current_text(), "xy");
}

fn new(
        terminal: Terminal,
        enhanced_keys_supported: bool,
        stderr_guard: terminal_stderr::TerminalStderrGuard,
    ) -> Self {
        let (draw_tx, _) = broadcast::channel(1);
        let frame_requester = FrameRequester::new(draw_tx.clone());

        // Cache this to avoid contention with the event reader.
        supports_color::on_cached(supports_color::Stream::Stdout);
        let _ = crate::terminal_palette::default_colors();
        let terminal_info = codex_terminal_detection::terminal_info();
        let scrollback = ScrollbackStrategy::detect(&terminal_info);
        let mut event_broker = EventBroker::new();
        event_broker.size_monitor = size_monitor::SizeMonitor::start(
            &terminal_info,
            terminal.last_known_screen_size,
            draw_tx.clone(),
        );

        Self {
            link_hover: link_pointer::LinkHover::default(),
            frame_requester,
            draw_tx,
            event_broker: Arc::new(event_broker),
            terminal_size_tags: Vec::new(),
            terminal,
            pending_history_lines: vec![],
            clear_thread_switch_on_draw: false,
            screen_size: ScreenSizePolicy::default(),
            ambient_pet_image_state: crate::pets::PetImageRenderState::default(),
            pet_picker_preview_image_state: crate::pets::PetImageRenderState::default(),
            transcript_images: Vec::new(),
            alt_saved_viewport: None,
            #[cfg(unix)]
            suspend_context: SuspendContext::new(),
            alt_screen_active: Arc::new(AtomicBool::new(false)),
            terminal_focused: Arc::new(AtomicBool::new(true)),
            enhanced_keys_supported,
            terminal_app_over_ssh: false,
            notification_backend: Some(detect_backend(NotificationMethod::default())),
            notification_condition: NotificationCondition::default(),
            scrollback,
            alt_screen_enabled: true,
            owned_screen: false,
            overlay_input: OverlayInput::Default,
            clipboard: Default::default(),
            _stderr_guard: stderr_guard,
        }
    }

