fn overview_cold_resume_honors_working_directory_selection() -> Result<()> {
    for (mode, cli_cwd, runtime_cwd) in [
        ("current", false, false),
        ("session", true, false),
        ("session", true, true),
        ("session", false, false),
    ] {
        // Keep the large setup and cold-resume futures off the Windows test stack.
        let mut app = Box::pin(make_test_app()).await;
        trust_fixture_folders(&mut app);
        let chosen = app.config.codex_home.join("chosen");
        let overridden = app.config.codex_home.join("overridden");
        std::fs::create_dir(&chosen)?;
        std::fs::create_dir(&overridden)?;
        std::fs::write(
            app.config.codex_home.join("config.toml"),
            format!("[tui]\nresume_cwd = \"{mode}\"\n"),
        )?;
        crate::legacy_core::config::set_project_trust_level(
            app.config.codex_home.as_path(),
            &chosen,
            codex_protocol::config_types::TrustLevel::Trusted,
        )
        .map_err(|error| color_eyre::eyre::eyre!(error.to_string()))?;
        let thread_id = ThreadId::from_string(
            &app_test_support::create_fake_rollout(
                &app.config.codex_home,
                "2025-01-01T12-00-00",
                "2025-01-01T12:00:00Z",
                "Historical session",
                Some(&app.config.model_provider_id),
                /*git_info*/ None,
            )
            .expect("create historical session"),
        )?;
        let mut app_server =
            Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
        app.launch_cwd = chosen.to_path_buf();
        app.harness_overrides.cwd = cli_cwd.then(|| {
            if runtime_cwd {
                overridden.to_path_buf()
            } else {
                chosen.to_path_buf()
            }
        });
        app.runtime_working_directory_override = runtime_cwd.then(|| chosen.to_path_buf());
        let expected_cwd = if mode == "current" || cli_cwd || runtime_cwd {
            chosen
        } else {
            test_path_buf("/").abs()
        };
        let mut tui = crate::tui::test_support::make_test_tui()?;
        // On this current-thread runtime, the server cannot answer until we yield. Cancel the
        // pending selection to release its terminal borrow and inspect what the user sees now.
        let mut selection =
            Box::pin(app.select_agents_overview_thread(&mut tui, &mut app_server, thread_id));
        assert!(futures::poll!(&mut selection).is_pending());
        drop(selection);
        let pending_loading =
            crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal).clone();
        Box::pin(app.select_agents_overview_thread(&mut tui, &mut app_server, thread_id)).await?;
        // The widget replacement clears the terminal; feedback must remain until the next draw.
        let loading =
            crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal).clone();
        assert_eq!(pending_loading, loading);
        let loading_text = loading
            .content
            .chunks(usize::from(loading.area.width))
            .map(|row| {
                row.iter()
                    .map(ratatui::buffer::Cell::symbol)
                    .collect::<String>()
            })
            .map(|line| line.trim_end().to_string())
            .collect::<Vec<_>>()
            .join("\n");
        insta::allow_duplicates! {
            insta::assert_snapshot!(loading_text.trim_end(), @"Loading task…");
        }
        Box::pin(app.handle_tui_event(&mut tui, &mut app_server, TuiEvent::Draw)).await?;
        assert_ne!(
            crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal),
            &loading,
        );
        let observed = Box::pin(app_server.resume_thread(
            &app.local_settings,
            app.config.clone(),
            thread_id,
            crate::app_server_session::ResumeModelSettings::PreserveExistingThread,
        ))
        .await?
        .session;
        assert_eq!(
            (app.config.cwd.clone(), observed.cwd),
            (expected_cwd.clone(), expected_cwd),
        );
        app_server.shutdown().await?;
    }
    Ok(())
}

fn new(
        mut initialized_terminal: tui::InitializedTerminal,
        terminal_restore_guard: TerminalRestoreGuard,
        initial_screen: StartupDraftInitialScreen,
        session_action: StartupDraftSessionAction,
        screen: StartupScreen,
    ) -> io::Result<Self> {
        initialized_terminal.terminal.clear()?;

        let mut tui = Tui::new(
            initialized_terminal.terminal,
            initialized_terminal.enhanced_keys_supported,
            initialized_terminal.stderr_guard,
        );
        tui.terminal_app_over_ssh = initialized_terminal.terminal_app_over_ssh;
        tui.set_alt_screen_enabled(screen.use_alt_screen);
        let mut pump = StartupDraftPump::new(&tui, initial_screen, session_action);
        pump.motion = screen.welcome_motion;
        pump.bottom_pane
            .set_status_line_enabled(screen.status_line_enabled);
        pump.bottom_pane.set_keymap_bindings(&screen.keymap);
        pump.bottom_pane
            .set_disable_paste_burst(screen.disable_paste_burst);
        pump.key_chords = screen.keymap.chords;
        let mut draft = Self {
            tui,
            terminal_restore_guard,
            pump,
        };
        // Present the screen switch and its first composer frame together.
        std::io::stdout().sync_update(|_| {
            draft
                .tui
                .set_owned_screen(screen.transcript_mode.is_owned())?;
            draft.pump.redraw_if_visible(&mut draft.tui)
        })??;
        Ok(draft)
    }

