fn detail_wrapped_lines(
    label: &str,
    value: &str,
    width: usize,
    max_lines: Option<usize>,
) -> Vec<crate::terminal_hyperlinks::HyperlinkLine> {
    let label_width = label.width().saturating_add(1).max(10);
    let available = width.saturating_sub(label_width).max(1);
    let mut first = true;
    let mut lines = value
        .split('\n')
        .flat_map(|text| {
            let source =
                crate::terminal_hyperlinks::annotate_web_urls_in_line(text.to_owned().dim().into());
            let wrapped = crate::wrapping::wrap_ranges_trim(text, available)
                .into_iter()
                .map(|range| {
                    let prefix = if first {
                        first = false;
                        format!("{label:<label_width$}")
                    } else {
                        " ".repeat(label_width)
                    };
                    crate::wrapping::WrappedLine {
                        line: vec![prefix.into(), text[range.clone()].to_owned().dim()].into(),
                        range,
                        prefix_bytes: label_width,
                    }
                })
                .collect();
            crate::terminal_hyperlinks::remap_source_wrapped_line(&source, wrapped)
        })
        .collect::<Vec<_>>();
    let Some(max_lines) = max_lines else {
        return lines;
    };
    if lines.len() <= max_lines {
        return lines;
    }

    lines.truncate(max_lines);
    if let Some(last_line) = lines.last_mut() {
        let prefix_width = last_line.line.spans[..last_line.line.spans.len().saturating_sub(1)]
            .iter()
            .map(ratatui::prelude::Span::width)
            .sum::<usize>();
        let max_width = width.saturating_sub(prefix_width);
        let Some(last_span) = last_line.line.spans.last_mut() else {
            return lines;
        };
        let truncated = truncate_line_with_ellipsis_if_overflow(
            Line::from(format!("{}…", last_span.content)),
            max_width,
        );
        let content = truncated
            .spans
            .into_iter()
            .map(|span| span.content.into_owned())
            .collect::<String>();
        let visible_end = prefix_width + crate::width::display_width(content.trim_end_matches('…'));
        last_span.content = content.into();
        last_line.hyperlinks.retain_mut(|link| {
            link.columns.end = link.columns.end.min(visible_end);
            !link.columns.is_empty()
        });
    }
    lines
}

fn prepare_images(
    images: Vec<LocalImageAttachment>,
    remote_bytes: usize,
) -> Result<Vec<UserInput>, String> {
    // Leave headroom below the WebSocket server's 64 MiB message limit.
    const MAX_IMAGE_BYTES: usize = 32 * 1024 * 1024;
    let mut remaining_image_bytes = MAX_IMAGE_BYTES.saturating_sub(remote_bytes);
    images
        .into_iter()
        .map(|image| {
            let mut input = CoreUserInput::LocalImage {
                path: image.path.clone(),
                // Preserve source pixels; core applies the model-specific resize policy.
                detail: Some(ImageDetail::Original),
            };
            let prepared = (|| -> std::io::Result<()> {
                let too_large =
                    || std::io::Error::other("image attachments exceed the 32 MiB transport limit");
                if std::fs::metadata(&image.path)?.len() > (remaining_image_bytes / 4 * 3) as u64 {
                    return Err(too_large());
                }
                snapshot_local_user_input(&mut input)?;
                if let CoreUserInput::Image {
                    image: ImageReference::Inline { image_url },
                    ..
                } = &input
                {
                    remaining_image_bytes = remaining_image_bytes
                        .checked_sub(image_url.len())
                        .ok_or_else(too_large)?;
                }
                Ok(())
            })();
            prepared.map_err(|error| {
                format!("Failed to prepare image: {}: {error}", image.path.display())
            })?;
            let mut input = UserInput::from(input);
            if let UserInput::Image { detail, .. } = &mut input {
                *detail = None;
            }
            Ok(input)
        })
        .collect()
}

