fn unicode_math_inline_stream_preserves_display_exclusion_boundaries() {
    let cwd = std::env::temp_dir();
    for delimiters in [("$$", "$$"), ("\\[", "\\]")] {
        let mut render = StreamingRender::new();
        let mut source = String::new();
        for chunk in [
            delimiters.0,
            "\n\nx^2\n\n",
            delimiters.1,
