fn new_agents_overview_worktree(
        &mut self,
        tui: &mut tui::Tui,
        app_server: &mut AppServerSession,
        cwd: Option<AbsolutePathBuf>,
    ) {
        if self.reconnect.offline
            || self.pending_managed_worktree_creation
            || self.windows_sandbox_blocks_thread_switch()
        {
            return;
        }
        if crate::uses_remote_workspace_or_environment(
            &self.app_server_target,
            self.environment_manager.as_ref(),
        ) {
            self.add_agents_overview_error(
                "Managed worktrees require local worktree support.".to_string(),
            );
            return;
        }
        let Some((config, _)) = self
            .agents_overview_session_config(tui, app_server, cwd, /*startup_draft*/ None)
            .await
        else {
            return;
        };
        let setup = async {
            anyhow::ensure!(
                !config.active_project.is_untrusted(),
                "The source project is not trusted."
            );
            let host = crate::legacy_core::config::load_config_toml_with_layer_stack(
                &self.config.codex_home,
                /*cwd*/ None,
                Vec::new(),
                codex_config::ConfigLoadOptions::default(),
            )
            .await?;
            let settings = codex_worktree::WorktreeSettings::for_cli(
                &self.config.codex_home,
                host.config_toml.desktop.as_ref(),
            )?;
            anyhow::Ok(codex_worktree::WorktreeManager::new(settings))
        }
        .await;
        let manager = match setup {
            Ok(value) => value,
            Err(error) => return self.add_agents_overview_error(error.to_string()),
        };
        self.pending_managed_worktree_creation = true;
        self.agents_overview
            .view_state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .creating_worktree = true;
        let sender = self.app_event_tx.clone();
        tokio::spawn(async move {
            let result = tokio::task::spawn_blocking(move || {
                codex_worktree::default_worktree_base(config.cwd.as_path())
                    .and_then(|base| {
                        manager.create(&codex_worktree::CreateWorktree {
                            source_cwd: config.cwd.to_path_buf(),
                            base: Some(base),
                        })
                    })
                    .map(|checkout| PendingWorktree {
                        manager,
                        checkout: Some(checkout),
                    })
                    .map_err(|error| error.to_string())
            })
            .await
            .unwrap_or_else(|error| Err(format!("Worktree creation task failed: {error}")));
            sender.send(AppEvent::AgentsOverviewWorktreeCreated(result));
        });
    }

fn encode_history_mentions_at_elements(
    text: &str,
    mentions: &[LinkedMention],
    elements: &[codex_protocol::user_input::TextElement],
) -> String {
    if mentions.is_empty() || text.is_empty() {
        return text.to_string();
    }

    let mut mentions_by_token: HashMap<(char, &str), VecDeque<&str>> = HashMap::new();
    for mention in mentions {
        if !matches!(
            mention.sigil,
            TOOL_MENTION_SIGIL | PLUGIN_TEXT_MENTION_SIGIL
        ) {
            continue;
        }
        mentions_by_token
            .entry((mention.sigil, mention.mention.as_str()))
            .or_default()
            .push_back(mention.path.as_str());
    }

    let bytes = text.as_bytes();
    let mut out = String::with_capacity(text.len());
    let mut index = 0usize;

    while index < bytes.len() {
        if matches!(
            bytes[index],
            byte if byte == TOOL_MENTION_SIGIL as u8 || byte == PLUGIN_TEXT_MENTION_SIGIL as u8
        ) {
            let sigil = bytes[index] as char;
            if sigil == PLUGIN_TEXT_MENTION_SIGIL
                && let Some(element) = elements
                    .iter()
                    .find(|element| element.byte_range.start == index)
                && let Some(name) = text.get(index + 1..element.byte_range.end)
                && mentions_by_token
                    .get(&(sigil, name))
                    .and_then(VecDeque::front)
                    .is_some_and(|path| crate::task_mentions::valid_thread_path(path).is_some())
                && let Some(path) = mentions_by_token
                    .get_mut(&(sigil, name))
                    .and_then(VecDeque::pop_front)
            {
                out.push_str(&crate::task_mentions::format_task_link(name, path));
                index += 1 + name.len();
                continue;
            }
            if sigil == TOOL_MENTION_SIGIL || starts_plaintext_mention(text, index) {
                let name_start = index + 1;
                if let Some(first) = bytes.get(name_start)
                    && is_mention_name_char(*first)
                {
                    let mut name_end = name_start + 1;
                    while let Some(next) = bytes.get(name_end)
                        && is_mention_name_char(*next)
                    {
                        name_end += 1;
                    }

                    let name = &text[name_start..name_end];
                    if (sigil == TOOL_MENTION_SIGIL || ends_plaintext_mention(bytes, name_end))
                        && mentions_by_token
                            .get(&(sigil, name))
                            .and_then(VecDeque::front)
                            .is_some_and(|path| {
                                crate::task_mentions::valid_thread_path(path).is_none()
                            })
                        && let Some(path) = mentions_by_token
                            .get_mut(&(sigil, name))
                            .and_then(VecDeque::pop_front)
                    {
                        out.push('[');
                        out.push(sigil);
                        out.push_str(name);
                        out.push_str("](");
                        out.push_str(path);
                        out.push(')');
                        index = name_end;
                        continue;
                    }
                }
            }
        }

        let Some(ch) = text[index..].chars().next() else {
            break;
        };
        out.push(ch);
        index += ch.len_utf8();
    }

    out
}

fn handle_paste(&mut self, pasted: String) -> bool {
