fn advance_queue(&mut self) {
        if let Some(next) = self.queue.pop() {
            self.set_current(next);
        } else {
            self.done = true;
        }
    }

fn push_truncated_str(&mut self, chunk: &str) {
        for part in chunk.split_inclusive('\n') {
            let Some(part) = part.strip_suffix('\n') else {
                if part.is_empty() {
                    continue;
                }
                if self.pending_carriage_return {
                    self.current.push_str("\r");
                    self.pending_carriage_return = false;
                }
                let part = if let Some(part) = part.strip_suffix('\r') {
                    self.pending_carriage_return = true;
                    part
                } else {
                    part
                };
                self.current.push_str(part);
                self.has_partial_line |= !part.is_empty() || self.pending_carriage_return;
                continue;
            };

            let has_carriage_return = part.ends_with('\r');
            let part = part.strip_suffix('\r').unwrap_or(part);
            if self.pending_carriage_return && (has_carriage_return || !part.is_empty()) {
                self.current.push_str("\r");
            }
            self.pending_carriage_return = false;
            self.current.push_str(part);
            self.completed_lines = self.completed_lines.saturating_add(1);
            self.has_partial_line = false;

            let line = std::mem::take(&mut self.current).render();
            if self.head.len() < LIVE_COMMAND_OUTPUT_MAX_LINES {
                self.head.push(line);
            } else {
                if self.tail.len() == LIVE_COMMAND_OUTPUT_MAX_LINES {
                    self.tail.pop_front();
                }
                self.tail.push_back(line);
            }
        }
    }

fn replace_visible_terminal_history_tail<B>(
    terminal: &mut CustomTerminal<B>,
    previous_lines: &[HyperlinkLine],
    replacement: &[HyperlinkLine],
    mode: InsertHistoryMode,
    wrap_policy: HistoryLineWrapPolicy,
) -> io::Result<bool>
where
    B: Backend<Error = io::Error> + Write,
{
    let screen_size = terminal.last_known_screen_size;
    let mut viewport = terminal.viewport_area;
    let wrap_width = usize::from(viewport.width.max(/*other*/ 1));
    let (_, previous_rows) = wrap_history_hyperlink_lines(previous_lines, wrap_width, wrap_policy);
    let Ok(previous_rows) = u16::try_from(previous_rows) else {
        return Ok(false);
    };
    if previous_rows > viewport.top() {
        return Ok(false);
    }

    viewport.y -= previous_rows;
    terminal.clear_after_position(Position::new(/*x*/ 0, viewport.y))?;
    terminal.set_viewport_area(viewport);
    terminal.invalidate_viewport();
    insert_history_hyperlink_lines_with_mode_and_wrap_policy(
        terminal,
        replacement,
        mode,
        wrap_policy,
        screen_size,
    )?;
    Ok(true)
}

