        |width| Some(live.display_hyperlink_lines(width)),
    );
    let before = render(&mut view, &cells, /*width*/ 20, /*height*/ 2);
    view.jump_to_beginning(&cells);
    cells.insert(/*index*/ 0, cell("older page"));
