    render(&mut view, &cells, /*width*/ 12, /*height*/ 3);
    assert_eq!(
        (view.position, view.history),
        (reading, TranscriptHistoryState::LoadingBeginning)
    );
    assert_eq!(
        render(&mut view, &cells, /*width*/ 20, /*height*/ 2),
        before
    );
}

