fn live_center_appends_arrivals_and_status_transitions() {
    let app = make_test_app().await;
    let [alpha, bravo, charlie, delta, child] = [1, 2, 3, 4, 5].map(ThreadId::from_u128);
    let working = ThreadStatus::Active {
        active_flags: vec![],
    };
    let mut threads = vec![
        overview_thread(
            alpha,
            /*parent_thread_id*/ None,
            "Alpha",
            working.clone(),
        ),
        overview_thread(
            bravo,
            /*parent_thread_id*/ None,
            "Bravo",
            working.clone(),
        ),
        overview_thread(
            charlie,
            /*parent_thread_id*/ None,
            "Charlie",
            ThreadStatus::Idle,
        ),
    ];
    assert_eq!(
        app.agents_overview_view(threads.clone(), Some(bravo))
            .thread_ids(),
        vec![alpha, bravo, charlie]
    );
    let mut arrival = overview_thread(delta, /*parent_thread_id*/ None, "Delta", working);
    arrival.updated_at += 100;
    threads.push(arrival);
    assert_eq!(
        app.agents_overview_view(threads.clone(), Some(bravo))
            .thread_ids(),
        vec![alpha, bravo, delta, charlie]
    );
    threads[1].status = ThreadStatus::Idle;
    assert_eq!(
        app.agents_overview_view(threads.clone(), Some(bravo))
            .thread_ids(),
        vec![alpha, delta, charlie, bravo]
    );
    // A descendant can change the root's effective group without changing its own status.
    threads.push(overview_thread(
        child,
        Some(bravo),
        "Child",
        ThreadStatus::SystemError,
    ));
    assert_eq!(
        app.agents_overview_view(threads.clone(), Some(bravo))
            .thread_ids(),
        vec![bravo, alpha, delta, charlie]
    );
    threads.pop();
    let view = app.agents_overview_view(threads.clone(), Some(bravo));
    assert_eq!(view.thread_ids(), vec![alpha, delta, charlie, bravo]);
    assert_eq!(view.rows[view.selected_index().unwrap()].thread_id, bravo);
    // Removed roots lose their rank, so rediscovery behaves like a new arrival.
    let removed = threads.remove(/*index*/ 0);
    assert_eq!(
        app.agents_overview_view(threads.clone(), Some(bravo))
            .thread_ids(),
        vec![delta, charlie, bravo]
    );
    threads.push(removed);
    assert_eq!(
        app.agents_overview_view(threads, Some(bravo)).thread_ids(),
        vec![delta, alpha, charlie, bravo]
    );
}

fn render(&self, area: Rect, buf: &mut Buffer) {
        let Some((view, previous)) = self.0.split_last() else {
            return;
        };
        if view.presentation() == ViewPresentation::Centered {
            Self(previous).render(area, buf);
            CenteredView(view.as_ref()).render(area, buf);
        } else {
            view.render(area, buf);
        }
    }

fn start_vim_edit(&mut self, action: VimAction) -> bool {
        let prior_len = self.text.len();
        self.vim_commands.pending_change = vec![VimEdit::Editor(VimEditorEdit(action.clone()))];
        self.vim_commands.changed = false;
        if !self.apply_vim_editor_action(action.clone()) {
            self.vim_commands.pending_change.clear();
            return false;
        }
        self.vim_commands.changed =
            self.text.len() != prior_len || matches!(action, VimAction::Replace(_));
        if self.vim_mode == VimMode::Normal {
            self.finish_pending_vim_change();
        }
        true
    }

