fn hanging_tabs_keep_cursor_scrolling_and_navigation_aligned() {
    let text = "abc\t a";
    let area = Rect::new(0, 0, /*width*/ 4, /*height*/ 2);
    let mut t = TextArea::new();
    t.insert_str(text);
    let cursors = (0..=text.len())
        .map(|pos| {
            t.set_cursor(pos);
            t.cursor_pos(area)
        })
        .collect::<Vec<_>>();
    assert_eq!(
        cursors,
        [(0, 0), (1, 0), (2, 0), (3, 0), (0, 1), (0, 1), (1, 1)].map(Some)
    );

    t.set_cursor(/*pos*/ 4);
    let mut state = TextAreaState::default();
    let mut terminal = Terminal::new(TestBackend::new(area.width, /*height*/ 1)).unwrap();
    terminal
        .draw(|frame| {
            StatefulWidgetRef::render_ref(&(&t), frame.area(), frame.buffer_mut(), &mut state);
        })
        .unwrap();
    let scrolled_cursor = t.cursor_pos_with_state(terminal.backend().buffer().area, state);
    assert_eq!((state.scroll, scrolled_cursor), (1, Some((0, 0))));
    insta::assert_snapshot!(
        "hanging_tab_cursor_and_scroll",
        format!(
            "cursors: {cursors:?}\nscroll: {}\ncursor: {scrolled_cursor:?}\n{}",
            state.scroll,
            terminal.backend()
        )
    );

    t.move_cursor_up();
    assert_eq!((t.cursor(), t.cursor_pos(area)), (0, Some((0, 0))));
    t.move_cursor_down();
    assert_eq!((t.cursor(), t.cursor_pos(area)), (5, Some((0, 1))));
    assert_eq!(t.text(), text);
}

fn sanitize_terminal_title(title: &str, encoding: TitleEncoding) -> String {
    let mut sanitized = String::new();
    let mut chars_written = 0;
    let mut pending_space = false;

    for ch in title.chars() {
        if ch.is_whitespace() {
            // Only set pending if we've already written content; this
            // strips leading whitespace without an extra trim pass.
            pending_space = !sanitized.is_empty();
            continue;
        }

        if is_disallowed_terminal_title_char(ch) {
            continue;
        }

        let ch = match (encoding, ch) {
            // Preserve a visible activity animation without allowing Screen to
            // turn, for example, U+2807 into BEL. Other Unicode title content
            // needs the same protection, including names made entirely of it.
            (TitleEncoding::Screen, '⠋' | '⠼' | '⠇') => '|',
            (TitleEncoding::Screen, '⠙' | '⠴' | '⠏') => '/',
            (TitleEncoding::Screen, '⠹' | '⠦') => '-',
            (TitleEncoding::Screen, '⠸' | '⠧') => '\\',
            (TitleEncoding::Screen, '●') => '*',
            (TitleEncoding::Screen, ch) if !ch.is_ascii() => '?',
            (_, ch) => ch,
        };

        if pending_space {
            let remaining = MAX_TERMINAL_TITLE_CHARS.saturating_sub(chars_written);
            if remaining > 1 {
                sanitized.push(' ');
                chars_written += 1;
                pending_space = false;
            }
        }

        if chars_written >= MAX_TERMINAL_TITLE_CHARS {
            break;
        }

        sanitized.push(ch);
        chars_written += 1;
    }

    sanitized
}

fn defer_or_handle<T>(
        &mut self,
        payload: T,
        push: impl FnOnce(&mut InterruptManager, T),
        handle: impl FnOnce(&mut Self, T),
    ) {
        // Preserve deterministic FIFO across queued interrupts: once anything
        // is queued due to an active write cycle, continue queueing until the
        // queue is flushed to avoid reordering (e.g., ExecEnd before ExecBegin).
        if self.stream_controller.is_some() || !self.interrupts.is_empty() {
            push(&mut self.interrupts, payload);
        } else {
            handle(self, payload);
        }
    }

