fn handle_mouse(&mut self, event: MouseEvent, state: TextAreaState) -> bool {
        let area = self.rendered_area.get();
        let dragging = self.mouse_selection.as_ref().is_some_and(|s| s.dragging);
        if area.is_empty() {
            self.end_mouse_drag();
            return false;
        }
        match event.kind {
            MouseEventKind::Down(MouseButton::Left)
                if event.modifiers.is_empty() && self.contains_mouse(event) => {}
            MouseEventKind::Drag(MouseButton::Left) | MouseEventKind::Up(MouseButton::Left)
                if dragging => {}
            _ => return false,
        }

        if matches!(event.kind, MouseEventKind::Up(MouseButton::Left))
            && self.mouse_selection.as_ref().is_some_and(|s| !s.moved)
        {
            self.end_mouse_drag();
            return true;
        }
        let line = {
            let lines = self.wrapped_lines(area.width);
            let row = usize::from(state.scroll)
                + usize::from(event.row.saturating_sub(area.y).min(area.height - 1));
            // Dragging beyond the viewport advances one wrapped row per event.
            let row = if event.row < area.y {
                row.saturating_sub(1)
            } else if event.row >= area.bottom() {
                row + 1
            } else {
                row
            };
            lines[row.min(lines.len() - 1)].clone()
        };
        let col = usize::from(event.column.saturating_sub(area.x).min(area.width));
        let pos = self.position_at_display_col_on_line(line.start, line.end - 1, col);
        let down = matches!(event.kind, MouseEventKind::Down(MouseButton::Left));
        let mut selection = if down {
            if self.mouse_selection.is_none() {
                self.last_click = None;
            }
            let clicks =
                crate::text_selection::click_count(&mut self.last_click, event.column, event.row);
            MouseSelection {
                pending_copy: None,
                primary_owner: None,
                origin: pos..pos,
                // Padding remains an insertion target on repeated clicks.
                unit: SelectionUnit::from_clicks(if pos == line.end - 1 { 1 } else { clicks }),
                dragging: true,
                moved: false,
            }
        } else if let Some(selection) = self.mouse_selection.take() {
            selection
        } else {
            return false;
        };
        let unit = selection.unit;
        let range = if unit == SelectionUnit::Character {
            let pos = self.clamp_pos_to_nearest_boundary(pos);
            pos..pos
        } else if unit == SelectionUnit::Word
            && let Some(element) = self.elements.iter().find(|e| e.range.contains(&pos))
        {
            element.range.clone()
        } else {
            self.expand_range_to_element_boundaries(unit.range(&self.text, pos))
        };
        self.preferred_col = None;
        self.clear_vim_replace_recovery();
        self.vim_pending = VimPending::None;
        if down {
            selection.origin = range.clone();
        }
        self.cursor_pos = if range.start < selection.origin.start {
            range.start
        } else {
            range.end
        };
        selection.moved |= !down;
        selection.dragging = !matches!(event.kind, MouseEventKind::Up(MouseButton::Left));
        self.mouse_selection = Some(selection);
        true
    }

fn take_realtime_transcript_history(&mut self) -> Vec<Box<dyn HistoryCell>> {
        if self.stream_controller.is_some()
            || self.plan_stream_controller.is_some()
            || self.pending_stream_consolidations > 0
        {
            return Vec::new();
        }
        let mut cells = Vec::new();
        while let Some(cell) = self.realtime_conversation.pending_history_cells.pop_front() {
            if let Some(active) = self.take_history_insertion_prefix(cell.as_ref()) {
                cells.push(active);
            }
            cells.push(cell);
        }
        if !cells.is_empty() {
            self.bump_active_cell_revision();
        }
        cells
    }

fn matching_chords_dispatches_the_active_context_action() {
    let mut config = TuiKeymap::default();
    config.global.open_transcript = Some(binding("ctrl-t ctrl-t"));
    config.editor.move_line_start = Some(binding("ctrl-x home"));
    config.list.jump_top = Some(binding("ctrl-x home"));
    let runtime = RuntimeKeymap::from_config(&config).expect("non-overlapping chord contexts");

    for (context, prefix, completion, target, other) in [
        (
            KeymapContext::Global,
            key_event(key_hint::ctrl(KeyCode::Char('t'))),
            key_event(key_hint::ctrl(KeyCode::Char('t'))),
            runtime.app.open_transcript.as_slice(),
            runtime.app.copy.as_slice(),
        ),
        (
            KeymapContext::Editor,
            key_event(key_hint::ctrl(KeyCode::Char('x'))),
            KeyEvent::new(KeyCode::Home, crossterm::event::KeyModifiers::NONE),
            runtime.editor.move_line_start.as_slice(),
            runtime.list.jump_top.as_slice(),
        ),
        (
            KeymapContext::List,
            key_event(key_hint::ctrl(KeyCode::Char('x'))),
            KeyEvent::new(KeyCode::Home, crossterm::event::KeyModifiers::NONE),
            runtime.list.jump_top.as_slice(),
            runtime.editor.move_line_start.as_slice(),
        ),
    ] {
        let mut matcher = KeyChordMatcher::default();
        assert!(matches!(
            matcher.advance(prefix, &runtime.chords, KeymapContextSet::new(context)),
            KeyChordMatch::Pending(_)
        ));
        let KeyChordMatch::Completed(dispatch_event) =
            matcher.advance(completion, &runtime.chords, KeymapContextSet::new(context))
        else {
            panic!("second stroke must complete the active context chord");
        };
        assert!(target.is_pressed(dispatch_event));
        assert!(!other.is_pressed(dispatch_event));
    }
}

