fn parse_keybinding(spec: &str) -> Option<KeyBinding> {
    let mut parts = spec.split('-');
    let mut modifiers = KeyModifiers::NONE;
    let mut key_name = None;

    for part in parts.by_ref() {
        match part {
            "ctrl" => modifiers |= KeyModifiers::CONTROL,
            "alt" => modifiers |= KeyModifiers::ALT,
            "shift" => modifiers |= KeyModifiers::SHIFT,
            "super" => modifiers |= KeyModifiers::SUPER,
            other => {
                key_name = Some(other.to_string());
                break;
            }
        }
    }

    let mut key_name = key_name?;
    for trailing in parts {
        key_name.push('-');
        key_name.push_str(trailing);
    }

    let key = match key_name.as_str() {
        "enter" => KeyCode::Enter,
        "tab" => KeyCode::Tab,
        "backspace" => KeyCode::Backspace,
        "esc" => KeyCode::Esc,
        "delete" => KeyCode::Delete,
        "up" => KeyCode::Up,
        "down" => KeyCode::Down,
        "left" => KeyCode::Left,
        "right" => KeyCode::Right,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "page-up" => KeyCode::PageUp,
        "page-down" => KeyCode::PageDown,
        "space" => KeyCode::Char(' '),
        "minus" => KeyCode::Char('-'),
        other if other.len() == 1 => KeyCode::Char(char::from(other.as_bytes()[0])),
        other if other.starts_with('f') => {
            let number = other[1..].parse::<u8>().ok()?;
            if (1..=MAX_FUNCTION_KEY).contains(&number) {
                KeyCode::F(number)
            } else {
                return None;
            }
        }
        _ => return None,
    };

    Some(KeyBinding::new(key, modifiers))
}

fn ascii_burst_treats_enter_as_newline_even_when_parent_owned() {
        use crossterm::event::KeyCode;
        use crossterm::event::KeyEvent;
        use crossterm::event::KeyModifiers;

        for parent_owned in [false, true] {
            let (mut composer, _rx) = new_test_composer();
            if parent_owned {
                composer.set_parent_owned_thread();
            }
            let mut now = Instant::now();
            let step = Duration::from_millis(1);

            let _ = composer.handle_input_basic_with_time(
                KeyEvent::new(KeyCode::Char('h'), KeyModifiers::NONE),
                now,
            );
            now += step;
            let _ = composer.handle_input_basic_with_time(
                KeyEvent::new(KeyCode::Char('i'), KeyModifiers::NONE),
                now,
            );
            now += step;

            let (result, _) =
                composer.handle_submission_with_time(/*should_queue*/ false, now);
            assert!(
                matches!(result, InputResult::None),
                "Enter during a burst should insert newline, not submit"
            );

            for ch in ['t', 'h', 'e', 'r', 'e'] {
                now += step;
                let _ = composer.handle_input_basic_with_time(
                    KeyEvent::new(KeyCode::Char(ch), KeyModifiers::NONE),
                    now,
                );
            }

            assert!(composer.draft.textarea.text().is_empty());
            let flush_time = now + PasteBurst::recommended_active_flush_delay() + step;
            let flushed = composer.handle_paste_burst_flush(flush_time);
            assert!(flushed, "expected paste burst to flush");
            assert_eq!(composer.draft.textarea.text(), "hi\nthere");
        }
    }

fn inline_code_and_file_paths_follow_syntax_theme() {
    let markdown = "# Heading\n\n**Bold** *Italic* [Link](https://example.com)\n\n> Quote\n\n1. Ordered\n\n- Unordered\n\nUse `src/main.rs` and [](./src/lib.rs).";
    let mut rendered = Vec::new();
    for (name, background) in [
        ("catppuccin-mocha", "dark"),
        ("catppuccin-mocha", "light"),
        ("catppuccin-latte", "light"),
        ("nord", "dark"),
        ("ansi", "dark"),
        ("no-markup-color", "dark"),
    ] {
        let theme = if name == "no-markup-color" {
            syntect::highlighting::Theme::default()
        } else {
            crate::render::highlight::resolve_theme_by_name(name, /*codex_home*/ None)
                .expect("bundled theme")
        };
        let colors = if background == "light" {
            crate::terminal_probe::DefaultColors {
                fg: (30, 30, 30),
                bg: (255, 255, 255),
            }
        } else {
            crate::terminal_probe::DefaultColors {
                fg: (220, 220, 220),
                bg: (20, 20, 20),
            }
        };
        crate::terminal_palette::with_test_default_colors(colors, || {
            let styles = MarkdownStyles::for_theme(&theme);
            let code_style = styles.code;
            let parser = pulldown_cmark::Parser::new(markdown).into_offset_iter();
            let mut writer = super::Writer::new(
                markdown,
                /*wrap_width*/ Some(24),
                /*cwd*/ None,
                &|_| false,
            );
            writer.styles = styles;
            let mut parser = parser;
            writer.run(&mut parser);
            let lines = crate::terminal_hyperlinks::visible_lines(writer.text);
            let paths = lines
                .iter()
                .flat_map(|line| &line.spans)
                .filter(|span| matches!(span.content.as_ref(), "src/main.rs" | "src/lib.rs"))
                .cloned()
                .collect::<Vec<_>>();
            assert_eq!(
                paths,
                vec![
                    Span::styled("src/main.rs", code_style),
                    Span::styled("src/lib.rs", code_style),
                ],
            );
            if name == "no-markup-color" {
                assert_eq!(code_style, ratatui::style::Style::new().fg(accent_color()));
            } else {
                rendered.push((name, background, lines));
            }
        });
    }
    assert_debug_snapshot!(rendered);
}

