fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.is_empty() {
            return;
        }
        let [panel, footer] =
            Layout::vertical([Constraint::Fill(1), Constraint::Length(1)]).areas(area);
        let content = render_menu_surface(panel, buf);
        if content.is_empty() {
            self.render_footer(footer, buf);
            return;
        }
        let (header, rows) = match self.page {
            HooksBrowserPage::Events => self.event_parts(content.width),
            HooksBrowserPage::Handlers(event) => (
                Self::handler_header_lines(event, self.review_needed_count(event)),
                self.handler_row_lines(event, usize::from(area.width)),
            ),
        };
        let header = Paragraph::new(header).wrap(Wrap { trim: false });
        let header_height =
            (header.line_count(content.width) as u16).min(content.height.saturating_sub(/*rhs*/ 3));
        let [header_area, body] =
            Layout::vertical([Constraint::Length(header_height), Constraint::Fill(1)])
                .areas(content);
        header.render(header_area, buf);
        let body = Rect::new(area.x, body.y, area.width, body.height);
        match self.page {
            HooksBrowserPage::Events => render_line_rows(body, buf, rows, self.state),
            HooksBrowserPage::Handlers(event) => {
                if rows.is_empty() {
                    Paragraph::new("  No hooks installed for this event.")
                        .dim()
                        .render(body, buf);
                } else {
                    let desired = rows.len().min(MAX_POPUP_ROWS) as u16 + 2;
                    let list_height = desired
                        .min(body.height.saturating_sub(/*rhs*/ 3).max(/*other*/ 3))
                        .min(body.height);
                    let [list, details] =
                        Layout::vertical([Constraint::Length(list_height), Constraint::Fill(1)])
                            .areas(body);
                    render_line_rows(list, buf, rows, self.state);
                    crate::terminal_hyperlinks::HyperlinkParagraph::new(
                        &self.detail_lines(event, usize::from(content.width)),
                        ratatui::style::Style::default(),
                    )
                    .render(details.inset(Insets::vh(/*v*/ 0, /*h*/ 2)), buf);
                }
            }
        }
        self.render_footer(footer, buf);
    }

fn advance_search_after(
        &mut self,
        offset: usize,
        direction: HistorySearchDirection,
        boundary_if_exhausted: bool,
        app_event_tx: &AppEventSender,
    ) -> HistorySearchResult {
        let next_offset = match direction {
            HistorySearchDirection::Older => offset.checked_sub(1),
            HistorySearchDirection::Newer => offset
                .checked_add(1)
                .filter(|next| *next < self.total_entries()),
        };
        let Some(next_offset) = next_offset else {
            return self.exhausted_search_result(direction, boundary_if_exhausted);
        };
        let result =
            self.advance_search_from(next_offset, direction, boundary_if_exhausted, app_event_tx);
        if matches!(result, HistorySearchResult::NotFound) {
            self.exhausted_search_result(direction, boundary_if_exhausted)
        } else {
            result
        }
    }

struct BottomPane {
    /// Composer is retained even when a BottomPaneView is displayed so the
    /// input state is retained when the view is closed.
    composer: ChatComposer,

    /// Stack of views displayed instead of the composer (e.g. popups/modals).
    view_stack: Vec<Box<dyn BottomPaneView>>,
    pub(crate) key_chord_reset_requested: bool,
    warnings_view: Option<warnings_view::WarningsView>,
    /// A keep press can close the viewer; its remaining repeats must not edit the draft.
    pub(crate) suppress_warning_keep_repeat: bool,
    view_transition_key_guard: Option<crate::activation_key_guard::ActivationKeyGuard>,
    pub(crate) questions: Option<Box<AsyncQuestions>>,
    delayed_approval_requests: VecDeque<DelayedApprovalRequest>,
    last_composer_activity_at: Option<Instant>,

    app_event_tx: AppEventSender,
    frame_requester: FrameRequester,
    thread_id: Option<ThreadId>,

    has_input_focus: bool,
    enhanced_keys_supported: bool,
    disable_paste_burst: bool,
    is_task_running: bool,
    esc_backtrack_hint: bool,
    animations_enabled: bool,
    effects: codex_config::types::TuiEffects,

    /// Inline status indicator shown above the composer while a task is running.
    status: Option<StatusIndicatorWidget>,
