            items: vec![voice_request.clone()],
            items_view: TurnItemsView::Full,
            status: TurnStatus::InProgress,
            error: None,
            started_at: None,
            completed_at: None,
            duration_ms: None,
        }],
        ReplayKind::ThreadSnapshot,
    );
    chat.handle_server_notification(
        ServerNotification::ItemStarted(ItemStartedNotification {
