fn burst_paste_fast_large_inserts_placeholder_on_flush() {
        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ false,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );

        let count = LARGE_PASTE_CHAR_THRESHOLD + 1; // > threshold to trigger placeholder
        let mut now = Instant::now();
        let step = Duration::from_millis(/*millis*/ 1);
        for _ in 0..count {
            let _ = composer.handle_input_basic_with_time(
                KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
                now,
            );
            now += step;
        }

        // Nothing should appear until we stop and flush
        assert!(composer.draft.textarea.text().is_empty());
        let flush_time = now + PasteBurst::recommended_active_flush_delay() + step;
        let flushed = composer.handle_paste_burst_flush(flush_time);
        assert!(flushed, "expected flush after stopping fast input");

        let expected_placeholder = format!("[Pasted Content {count} chars]");
        assert_eq!(composer.draft.textarea.text(), expected_placeholder);
        assert_eq!(composer.draft.pending_pastes.len(), 1);
        assert_eq!(composer.draft.pending_pastes[0].0, expected_placeholder);
        assert_eq!(composer.draft.pending_pastes[0].1.len(), count);
        assert!(composer.draft.pending_pastes[0].1.chars().all(|c| c == 'x'));
    }

fn tick_selection(&mut self, cells: &[Arc<dyn HistoryCell>]) -> bool {
        let snapshot = self.snapshot_cells();
        let cells = snapshot.as_deref().unwrap_or(cells);
        let Some(selection) = self
            .selection
            .as_ref()
            // Horizontal selection on an edge row must not move the text under the pointer.
            .filter(|selection| selection.dragging && selection.moved_vertically)
        else {
            return false;
        };
        let Some(pointer) = selection.pointer else {
            return false;
        };
        let direction = if pointer.y <= self.area.top() {
            -1
        } else if pointer.y >= self.area.bottom().saturating_sub(/*rhs*/ 1) {
            1
        } else {
            return false;
        };
        let previous = self.position;
        self.scroll(cells, direction);
        previous != self.position
    }

fn stalled_input_and_stalled_exit_are_reaped_before_returning() {
    let dir = tempfile::tempdir().unwrap();
    // Large input blocks on the pipe; small input fits, so the worker reaches the exit wait.
    for (stage, text, script) in [
        (
            "input",
            "x".repeat(/*n*/ 1_048_576),
            "echo $$ > \"$1\"; exec sleep 30",
        ),
        ("exit", "small".into(), "echo $$ > \"$1\"; exec sleep 30"),
        // An adapter waiting on a subprocess must stop that subprocess too.
        (
            "subprocess",
            String::new(),
            "sh -c 'echo $$ > \"$1\"; exec sleep 30' sh \"$1\"; wait",
        ),
    ] {
        let pid_path = dir.path().join(format!("{stage}.pid"));
        let mut command = tokio::process::Command::new("sh");
        command.args(["-c", script, "sh"]).arg(&pid_path);
        let started = Instant::now();
        assert_eq!(
            write_command(command, &text, started + Duration::from_secs(/*secs*/ 1)).await,
            Err("Windows clipboard writer timed out".into())
        );
        assert!(
            started.elapsed() < Duration::from_secs(/*secs*/ 10),
            "{stage}: cleanup exceeded its budget: {:?}",
            started.elapsed()
        );
        let pid: libc::pid_t = std::fs::read_to_string(&pid_path)
            .unwrap()
            .trim()
            .parse()
            .unwrap();
        if stage == "subprocess" {
            // The grandchild must be stopped; only init can reap it. A zombie is
            // acceptable here and still responds to kill(pid, 0) until reaped.
            let output = std::process::Command::new("ps")
                .args(["-o", "stat=", "-p", &pid.to_string()])
                .output()
                .unwrap();
            let state = String::from_utf8(output.stdout).unwrap();
            let state = state.trim();
            assert!(state.is_empty() || state.starts_with('Z'), "state: {state}");
        } else {
            // SAFETY: Signal 0 observes this disposable child without modifying it.
            assert_eq!(unsafe { libc::kill(pid, 0) }, -1);
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::ESRCH)
            );
        }
    }
}

