fn selection_key(&mut self, cells: &[Arc<dyn HistoryCell>], code: KeyCode) -> bool {
        if !matches!(
            code,
            KeyCode::Up | KeyCode::Down | KeyCode::Left | KeyCode::Right
        ) {
            return false;
        }
        let Some(end) = self.selection.as_ref().map(|selection| selection.end) else {
            return false;
        };
        let snapshot = self.snapshot_cells();
        let cells = snapshot.as_deref().unwrap_or(cells);
        let column = if matches!(code, KeyCode::Up | KeyCode::Down) {
            let Some(layout) = self.layout(cells, self.resolve(cells, end)) else {
                return true;
            };
            Some(
                self.selection
                    .as_ref()
                    .and_then(|selection| selection.preferred_column)
                    .unwrap_or_else(|| layout.column_for_offset(end.offset)),
            )
        } else {
            None
        };
        let Some(next) = self.move_selection_endpoint(cells, end, code, column) else {
            return true;
        };
        if let Some(mut selection) = self.selection.take() {
            if selection.end != next {
                selection.primary_owner = None;
            }
            selection.end = next;
            selection.dragging = false;
            selection.preferred_column = column;
            self.pin_selection_range(cells, &mut selection);
            self.selection = Some(selection);
        }
        let row = self
            .layout(cells, next.index)
            .map_or(/*default*/ 0, |layout| {
                layout
                    .row_for_offset(next.offset)
                    .saturating_add_signed(next.row_bias.saturating_neg())
            });
        if !self
            .visible
            .iter()
            .any(|visible| visible.index == next.index && visible.row == row)
        {
            self.position = Position::Reading(next);
        }
        true
    }

fn completed_user_caption_stays_visible_until_history_commit() {
    let (mut chat, _sender, mut events, _ops) = make_chatwidget_manual_with_sender().await;
    activate_voice(&mut chat);
    chat.local_settings.tui.animations = false;
    chat.on_realtime_transcript_delta("user".into(), "Keep these words visible".into());
    chat.on_realtime_transcript_done("user".into(), "Keep these words visible.".into());

    // A scheduled draw must not clear the caption before its queued history event runs.
    chat.pre_draw_tick();
    let visible = chat.active_cell_transcript_lines(/*width*/ 80).unwrap();
    insta::assert_snapshot!(visible.iter().map(ToString::to_string).collect::<Vec<_>>().join("\n"), @r"

    › Keep these words visible.
    ");
    assert!(chat.active_cell_transcript_key().is_some());
    let viewport = render_bottom_popup(&chat, /*width*/ 80);
    assert!(viewport.contains("Keep these words visible."));

    // Streaming output can postpone insertion, but must not postpone display.
    chat.on_agent_message_delta("An earlier answer".into());
    assert!(chat.take_realtime_transcript_history().is_empty());
    assert!(render_bottom_popup(&chat, /*width*/ 80).contains("Keep these words visible."));
    chat.finalize_completed_assistant_message(Some("An earlier answer"));
    chat.note_stream_consolidation_completed();
    commit_realtime_history_events(&mut chat, &mut events);
    let history = std::iter::from_fn(|| events.try_recv().ok())
        .filter_map(|event| {
            if let AppEvent::InsertHistoryCell(cell) = event {
                Some(cell)
            } else {
                None
            }
        })
        .flat_map(|cell| cell.display_lines(/*width*/ 80))
        .map(|line| line.to_string())
        .collect::<Vec<_>>()
        .join("\n");
    assert_eq!(history.matches("Keep these words visible.").count(), 1);
    assert!(!render_bottom_popup(&chat, /*width*/ 80).contains("Keep these words visible."));
}

