fn selected_hard_breaks_survive_surrounding_blocks() {
    let source = "First paragraph.\n\nSecond paragraph with a hard break:  \nnext line.\n\n> quoted **words**  \n> next quote line\n\nFinal paragraph.";
    let mut stream = crate::streaming::controller::StreamController::new(
        Some(78),
        Path::new("/"),
        crate::history_cell::HistoryRenderMode::Rich,
    );
    let mut cells: Vec<Arc<dyn HistoryCell>> = Vec::new();
    for chunk in source.split_inclusive('\n') {
        stream.push(chunk);
        while let Some(cell) = stream.on_commit_tick_batch(/*max_lines*/ 1).0 {
            cells.push(cell.into());
        }
    }
    if let Some(cell) = stream.finalize().0 {
        cells.push(cell.into());
    }
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 80, /*height*/ 40,
    );
    let mut view = TranscriptView::default();
    view.render(area, &mut Buffer::empty(area), &cells);
    view.begin_selection(&cells, /*column*/ 2, /*row*/ 0, /*clicks*/ 1);
    view.extend_selection(/*column*/ 79, /*row*/ 39);
    let plain = view.selected_text(&cells).unwrap();
    view.copy_selected_text_with(&cells, &plain, /*clear_selection*/ true, |text, format| {
        let CopyFormat::MarkdownSelection(source) = format else {
            panic!("expected rich selection");
        };
        assert_eq!(text, "First paragraph.\n\nSecond paragraph with a hard break:\nnext line.\n\n> quoted words\n> next quote line\n\nFinal paragraph.");
        assert_eq!(
            crate::clipboard_html::render_markdown(&source),
            "<p>First paragraph.</p>\n<p>Second paragraph with a hard break:<br />\nnext line.</p>\n<blockquote>\n<p>quoted <strong>words</strong><br />\nnext quote line</p>\n</blockquote>\n<p>Final paragraph.</p>\n"
        );
        Ok(crate::clipboard_copy::CopyStatus::Confirmed)
    }).unwrap();
}

fn render_stacked_field(
    out: &mut Vec<HyperlinkLine>,
    header: &TableCell,
    value: &TableCell,
    available_width: Option<usize>,
    label_style: Style,
) {
    let label_width = available_width
        .map(|width| width.saturating_sub(FIELD_LEADING_PADDING).max(1))
        .unwrap_or_else(|| display_width(&header.plain_text()).max(1));
    let label = label_line(header, label_style);
    let mut wrapped_labels = Vec::new();
    push_owned_lines(
        &word_wrap_line(&label.line, RtOptions::new(label_width)),
        &mut wrapped_labels,
    );
    for label_line in remap_wrapped_line(&label, wrapped_labels) {
        let mut spans = vec![Span::raw(" ".repeat(FIELD_LEADING_PADDING))];
        let mut copy = None;
        if let Some(source) = &label_line.source {
            crate::markdown_copy::table::append(&mut copy, source, FIELD_LEADING_PADDING);
        }
        spans.extend(label_line.line.spans);
        let mut line = HyperlinkLine::new(Line::from(spans));
        crate::markdown_copy::table::attach(&mut line, copy);
        out.push(line);
    }

    let value_width = available_width
        .map(|width| width.saturating_sub(STACKED_VALUE_INDENT).max(1))
        .unwrap_or_else(|| cell_width(value).max(1));
    for value_line in wrap_cell(value, value_width) {
        push_prefixed_value_line(
            out,
            vec![Span::raw(" ".repeat(STACKED_VALUE_INDENT))],
            value_line,
            /*copy*/ None,
        );
    }
}

