fn render(&self, area: Rect, buf: &mut Buffer) {
        let content = render_menu_surface(area, buf);
        let commands = self.command_lines(content.width);
        let command_height = u16::try_from(commands.len())
            .unwrap_or(u16::MAX)
            .min(content.height);
        let gap = content
            .height
            .saturating_sub(command_height)
            .min(/*other*/ 1);
        let body = Rect {
            height: content.height.saturating_sub(command_height + gap),
            ..content
        };
        let command_area = Rect {
            y: content.bottom().saturating_sub(command_height),
            height: command_height,
            ..content
        };
        render_clipped(self.body_lines(content.width), body, buf);
        Paragraph::new(commands).render(command_area, buf);
    }

fn render_lines(
        &self,
        width: u16,
        list_spacing: crate::markdown_render::ListSpacing,
    ) -> Vec<HyperlinkLine> {
        self.rendered_lines.render(width, list_spacing, || {
            let mut lines = vec![
                HyperlinkLine::new(vec!["• ".dim(), "Proposed Plan".bold()].into()),
                HyperlinkLine::new(Line::from(" ")),
            ];

            let mut plan_lines = vec![HyperlinkLine::new(Line::from(" "))];
            let plan_style = proposed_plan_style();
            let wrap_width = width.saturating_sub(4).max(1) as usize;
            let mut body = crate::markdown::render_markdown_agent_with_list_spacing(
                &self.plan_markdown,
                Some(wrap_width),
                Some(self.cwd.as_path()),
                /*inline_visualization_context*/ None,
                list_spacing,
            );
            if body.is_empty() {
                body.push(HyperlinkLine::new(Line::from("(empty)".dim().italic())));
            }
            plan_lines.extend(prefix_hyperlink_lines(body, "  ".into(), "  ".into()));
            plan_lines.push(HyperlinkLine::new(Line::from(" ")));

            lines.extend(
                plan_lines
                    .into_iter()
                    .map(|line| style_proposed_plan_line(line, plan_style)),
            );
            lines
        })
    }

