    assert!(view.held_reading.is_some());
    cells.push(Arc::clone(&original));
    view.sync_live_tail(/*width*/ 20, /*key*/ None, |_| None);
    view.scroll(&cells, /*rows*/ -100);
    assert!(view.held_reading.is_none());
    view.scroll(&cells, /*rows*/ 100);
