fn preview(text: &str, width: usize) -> String {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    let (prefix, rest, _) = take_prefix_by_width(&normalized, width);
    if rest.is_empty() {
        prefix
    } else if width == 0 {
        String::new()
    } else {
        let (prefix, _, _) = take_prefix_by_width(&normalized, width.saturating_sub(1));
        format!("{prefix}…")
    }
}

fn show_quit_shortcut_hint(&mut self, key: KeyBinding) {
        if !DOUBLE_PRESS_QUIT_SHORTCUT_ENABLED {
            return;
        }

        self.composer
            .show_quit_shortcut_hint(key, self.has_input_focus);
        let frame_requester = self.frame_requester.clone();
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            handle.spawn(async move {
                tokio::time::sleep(QUIT_SHORTCUT_TIMEOUT).await;
                frame_requester.schedule_frame();
            });
        } else {
            // In tests (and other non-Tokio contexts), fall back to a thread so
            // the hint can still expire without requiring an explicit draw.
            std::thread::spawn(move || {
                std::thread::sleep(QUIT_SHORTCUT_TIMEOUT);
                frame_requester.schedule_frame();
            });
        }
        self.request_redraw();
    }

