fn deleting_one_of_duplicate_image_placeholders_removes_one_entry() {
        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ false,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );

        let path1 = PathBuf::from("/tmp/image_dup1.png");
        let path2 = PathBuf::from("/tmp/image_dup2.png");

        composer.attach_image(path1);
        // separate placeholders with a space for clarity
        composer.handle_paste(" ".into());
        composer.attach_image(path2.clone());

        let placeholder1 = composer.attachments.local_images[0].placeholder.clone();
        let placeholder2 = composer.attachments.local_images[1].placeholder.clone();
        let text = composer.draft.textarea.text().to_string();
        let start1 = text.find(&placeholder1).expect("first placeholder present");
        let end1 = start1 + placeholder1.len();
        composer.draft.textarea.set_cursor(end1);

        // Backspace should delete the first placeholder and its mapping.
        composer.handle_key_event(KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE));

        let new_text = composer.draft.textarea.text().to_string();
        assert_eq!(
            1,
            new_text.matches(&placeholder1).count(),
            "one placeholder remains after deletion"
        );
        assert_eq!(
            0,
            new_text.matches(&placeholder2).count(),
            "second placeholder was relabeled"
        );
        assert_eq!(
            1,
            new_text.matches("[Image #1]").count(),
            "remaining placeholder relabeled to #1"
        );
        assert_eq!(
            vec![AttachedImage {
                path: path2,
                placeholder: "[Image #1]".to_string()
            }],
            composer.attachments.local_images,
            "one image mapping remains"
        );
    }

fn code_block_with_inner_triple_backticks_outer_four() {
    let md = r#"````text
Here is a code block that shows another fenced block:

```md
# Inside fence
- bullet
- `inline code`
```
````
"#;
    let text = render_markdown_text(md);
    let lines: Vec<String> = text
        .lines
        .iter()
        .map(|l| {
            l.spans
                .iter()
                .map(|s| s.content.clone())
                .collect::<String>()
        })
        .collect();
    // Filter empty trailing lines for stability; the code block may or may
    // not emit a trailing blank depending on the highlighting path.
    let trimmed: Vec<&str> = {
        let mut v: Vec<&str> = lines.iter().map(std::string::String::as_str).collect();
        while v.last() == Some(&"") {
            v.pop();
        }
        v
    };
    assert_eq!(
        trimmed,
        vec![
            "Here is a code block that shows another fenced block:",
            "",
            "```md",
            "# Inside fence",
            "- bullet",
            "- `inline code`",
            "```",
        ]
    );
}

fn active_binding_specs(
    runtime_keymap: &RuntimeKeymap,
    context: &str,
    action: &str,
) -> Result<Vec<String>, String> {
    let action_id = keymap_action_id(context, action);
    if let Some(action_id) = action_id
        && let Some(specs) = runtime_keymap.chords.configured_specs(action_id)
    {
        return Ok(specs.to_vec());
    }

    let bindings = bindings_for_action(runtime_keymap, context, action).ok_or_else(|| {
        format!("Unknown keymap action `{context}.{action}`. Reopen /keymap and choose an action.")
    })?;
    let mut specs = bindings
        .iter()
        .filter(|binding| !crate::keymap::is_dispatch_token(**binding))
        .map(|binding| binding_to_config_key_spec(*binding))
        .collect::<Result<Vec<_>, _>>()?;
    if let Some(action_id) = action_id {
        let chords: Vec<_> = runtime_keymap
            .chords
            .bindings
            .iter()
            .filter(|binding| binding.action == action_id)
            .collect();
        let available: std::collections::HashSet<_> = chords
            .iter()
            .map(|binding| (binding.chord.prefix, binding.chord.completion))
            .collect();
        for binding in &chords {
            // An implicit default can yield to a different action on some leader aliases.
            // Only persist the symbolic form when all aliases remain available.
            let partial_leader = binding.spec.starts_with("leader ")
                && runtime_keymap
                    .chords
                    .leader
                    .iter()
                    .any(|prefix| !available.contains(&(*prefix, binding.chord.completion)));
            specs.push(if partial_leader {
                format!(
                    "{} {}",
                    binding_to_config_key_spec(binding.chord.prefix)?,
                    binding_to_config_key_spec(binding.chord.completion)?
                )
            } else {
                binding.spec.clone()
            });
        }
    }
    Ok(dedup_bindings(specs))
}

fn replace_visible_history_tail(
        &mut self,
        previous_lines: &[HyperlinkLine],
        replacement: &[HyperlinkLine],
        wrap_policy: HistoryLineWrapPolicy,
    ) -> io::Result<bool> {
        let screen_size = self.terminal.last_known_screen_size;
        Self::flush_pending_history_lines(
            &mut self.terminal,
            &mut self.pending_history_lines,
            self.scrollback,
            screen_size,
        )?;
        let mode = self.scrollback.history_insertion_mode(wrap_policy);
        let replaced = replace_visible_terminal_history_tail(
            &mut self.terminal,
            previous_lines,
            replacement,
            mode,
            wrap_policy,
        )?;
        if replaced {
            self.frame_requester().schedule_frame();
        }
        Ok(replaced)
    }

