fn render_filled_tab_bar(
    labels: &[&str],
    active_idx: usize,
    area: Rect,
    buf: &mut Buffer,
) -> Vec<(usize, Rect)> {
    if labels.is_empty() || area.is_empty() {
        return Vec::new();
    }
    let active_idx = active_idx.min(labels.len() - 1);
    let widths = labels
        .iter()
        .map(|label| Line::from(*label).width() + 2)
        .collect::<Vec<_>>();
    let occupied = |start: usize, end: usize| {
        widths[start..end].iter().sum::<usize>() + end - start - 1
            + usize::from(start > 0) * 2
            + usize::from(end < labels.len()) * 2
    };
    let mut start = active_idx;
    let mut end = active_idx + 1;
    while start > 0 && occupied(start - 1, end) <= usize::from(area.width) {
        start -= 1;
    }
    while end < labels.len() && occupied(start, end + 1) <= usize::from(area.width) {
        end += 1;
    }

    // Tiny strips prioritize a readable active label over navigation hints.
    let show_left = start > 0 && area.width >= 5;
    let show_right = end < labels.len() && area.width >= 7;
    let mut x = area.x;
    if show_left {
        Line::from("‹")
            .dim()
            .render(Rect::new(x, area.y, /*width*/ 1, /*height*/ 1), buf);
        x += 2;
    }
    let right = area.right().saturating_sub(u16::from(show_right) * 2);
    let mut regions = Vec::new();
    for idx in start..end {
        let width = widths[idx].min(usize::from(right.saturating_sub(x))) as u16;
        let line = Line::from(format!(" {} ", labels[idx]));
        let line = truncate_line_with_ellipsis_if_overflow(line, usize::from(width));
        let line = if idx == active_idx {
            line.style(active_tab_style())
        } else {
            line.dim()
        };
        let tab = Rect::new(x, area.y, width, /*height*/ 1);
        line.render(tab, buf);
        regions.push((idx, tab));
        x = x.saturating_add(width).saturating_add(/*rhs*/ 1);
    }
    if show_right {
        Line::from("›").dim().render(
            Rect::new(
                area.right() - 1,
                area.y,
                /*width*/ 1,
                /*height*/ 1,
            ),
            buf,
        );
    }
    regions
}

fn choice_labels_and_descriptions_keep_complete_url_destinations() {
    let label = "https://github.com/openai/codex/pull/12345?diff=split";
    let description = "https://example.com/releases/review/complete-destination";
    let mut snapshots = Vec::new();
    for prefix_label in [false, true] {
        for wrap_indent in [Some(0), None] {
            let mut row = GenericDisplayRow {
                name: format!("日本語 {label}"),
                description: Some(description.into()),
                wrap_indent,
                ..Default::default()
            };
            if prefix_label {
                row.name_prefix_spans = vec!["1. ".into(), std::mem::take(&mut row.name).bold()];
                row.description = None;
            }
            let rows = [row];
            for single_line in [false, true] {
                let area = Rect::new(0, 0, 48, if single_line { 1 } else { 12 });
                let mut buf = Buffer::empty(area);
                if single_line {
                    render_rows_single_line_with_col_width_mode(
                        area,
                        &mut buf,
                        &rows,
                        &ScrollState::new(),
                        /*max_results*/ 1,
                        "",
                        ColumnWidthConfig::default(),
                    );
                } else {
                    render_rows(
                        area,
                        &mut buf,
                        &rows,
                        &ScrollState::new(),
                        /*max_results*/ 1,
                        "",
                    );
                }
                let mut linked = 0;
                for cell in &buf.content {
                    if cell.symbol().contains("\x1b]8;;") {
                        linked += 1;
                        assert!(
                            [label, description].iter().any(|url| cell
                                .symbol()
                                .starts_with(&format!("\x1b]8;;{url}\x07")))
                        );
                        assert_ne!(crate::terminal_hyperlinks::strip_osc8(cell.symbol()), "…");
                    }
                }
                assert!(linked > 0);
                let urls = if prefix_label {
                    vec![label]
                } else {
                    vec![label, description]
                };
                for url in urls {
                    let visible = buf
                        .content
                        .iter()
                        .filter(|cell| cell.symbol().starts_with(&format!("\x1b]8;;{url}\x07")))
                        .map(|cell| crate::terminal_hyperlinks::strip_osc8(cell.symbol()))
                        .collect::<String>();
                    assert!(!visible.is_empty() && url.starts_with(&visible));
                }
                let visible = buf
                    .content
                    .chunks(48)
                    .map(|row| {
                        row.iter()
                            .map(|cell| crate::terminal_hyperlinks::strip_osc8(cell.symbol()))
                            .collect::<String>()
                            .trim_end()
                            .to_owned()
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                snapshots.push(format!(
                "prefix label: {prefix_label}, wrapped label: {}, single line: {single_line}\n{visible}",
                wrap_indent.is_some()
            ));
            }
        }
    }
    insta::assert_snapshot!("choice_wrapped_urls", snapshots.join("\n\n"));
}

