        name: "Mic".into(),
        channels: 4,
        is_default: true,
    });
    chat.bottom_pane
        .handle_key_event(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE));
    chat.bottom_pane
        .handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
