fn terminal_draw_coalesces_wrapped_hyperlink_output() {
        let auth_url = format!(
            "https://auth.openai.com/oauth/authorize?response_type=code&state={}",
            "x".repeat(/*n*/ 400)
        );
        let width = 44;
        let height = 20;
        let area = Rect::new(0, 0, width, height);
        let mut terminal =
            Terminal::with_options(CaptureBackend::new(width, height)).expect("terminal");
        terminal.set_viewport_area(area);

        terminal
            .draw(|frame| {
                Paragraph::new(vec![
                    Line::from(vec!["  ".into(), auth_url.as_str().cyan().underlined()]),
                    "".into(),
                    "  Press Esc to cancel".into(),
                ])
                .wrap(Wrap { trim: false })
                .render(area, frame.buffer_mut());
                crate::terminal_hyperlinks::mark_url_hyperlink(frame.buffer_mut(), area, &auth_url);
            })
            .expect("draw");

        let output = terminal.backend().output();
        let open = format!("\x1b]8;;{auth_url}\x07");
        let close = "\x1b]8;;\x07";
        assert_eq!(output.matches(&open).count(), 1);
        assert_eq!(output.matches(close).count(), 1);
        let footer = output.find("Press").expect("footer");
        assert!(output.find(close).expect("hyperlink close") < footer);
    }

fn rename_key(&mut self, key: KeyEvent) -> bool {
        let mut state = self.state();
        if state.rename_target.is_none() {
            return false;
        }
        let input = &mut state.input;
        let editing = input.should_handle_vim_insert_escape(key) || input.is_vim_operator_pending();
        if !editing {
            match self.keymap.action_for(key) {
                Some(ListAction::Cancel) => {
                    drop(state);
                    self.on_ctrl_c();
                    return true;
                }
                Some(ListAction::Accept) if !is_plain_text_key_event(key) => {
                    let online = state.connection_notice.is_none() && !state.creating_worktree;
                    drop(state);
                    if online {
                        self.activate();
                    }
                    return true;
                }
                _ => {}
            }
        }
        let editor_binding = crate::keymap::keymap_action_ids()
            .filter(|action| action.context == input.keymap_context())
            .any(|action| {
                crate::keymap::bindings_for_action(
                    &self.editor_keymap,
                    action.context.config_name(),
                    action.action,
                )
                .is_some_and(|bindings| bindings.is_pressed(key))
            });
        if editing
            || is_plain_text_key_event(key)
            || editor_binding
            || !self.center_shortcut_keys.is_pressed(key)
        {
            input.input(key);
            return !crate::keymap::is_dispatch_token_event(key);
        }
        false
    }

