fn mermaid_stream_closes_resizes_and_preserves_raw_source() {
    let cwd = std::env::temp_dir();
    let mut render = StreamingRender::new();
    let mut source = String::new();
    let mut stages = Vec::new();
    for chunk in [
        "Before.\n\n```mermaid\n",
        "flowchart LR\nA[\"Codex reply<br/>completed\"] --> B[\"Rendered in Ghostty\"]\n",
        "```\n",
        "\nAfter.\n",
    ] {
        source.push_str(chunk);
        render.append(
            &source,
            chunk,
            Some(80),
            &cwd,
            HistoryRenderMode::Rich,
            /*inline_visualization_context*/ None,
        );
        assert_eq!(
            render.lines,
            super::render::render_source(
                &source,
                Some(80),
                &cwd,
                HistoryRenderMode::Rich,
                /*inline_visualization_context*/ None
            )
        );
        stages.push(
            render
                .lines
                .iter()
                .map(|line| line.line.to_string())
                .collect::<Vec<_>>()
                .join("\n"),
        );
    }
    for (width, mode) in [
        (8, HistoryRenderMode::Rich),
        (80, HistoryRenderMode::Raw),
        (80, HistoryRenderMode::Rich),
    ] {
        render.recompute(
            &source,
            Some(width),
            &cwd,
            mode,
            /*inline_visualization_context*/ None,
        );
        assert_eq!(
            render.lines,
            super::render::render_source(
                &source,
                Some(width),
                &cwd,
                mode,
                /*inline_visualization_context*/ None
            )
        );
        stages.push(
            render
                .lines
                .iter()
                .map(|line| line.line.to_string())
                .collect::<Vec<_>>()
                .join("\n"),
        );
    }
    assert_snapshot!(stages.join("\n\n---\n\n"));
}

