fn full_screen_request_is_available_before_and_during_verification() {
    for state in [
        UserVerificationState::Prompt,
        UserVerificationState::Waiting,
    ] {
        let (mut view, mut decisions) = make_view();
        let (app_tx, mut app_rx) = unbounded_channel();
        view.app_event_tx = AppEventSender::new(app_tx);
        view.approval_keymap.open_fullscreen = vec![crate::key_hint::ctrl(KeyCode::Char('v'))];
        view.state = state;
        view.handle_key_event(KeyEvent::new(KeyCode::Char('v'), KeyModifiers::CONTROL));
        let crate::app_event::AppEvent::FullScreenUserVerificationRequest(request) =
            app_rx.try_recv().expect("full-screen request")
        else {
            panic!("expected full-screen request");
        };
        assert_eq!(request.description, view.request.description);
        assert!(decisions.try_recv().is_err());
        assert!(!view.is_complete());
        assert!(view.terminal_title_requires_action());
    }
}

fn drop(&mut self) {
        if self.active {
            let _ = finish();
            self.active = false;
        }
    }

fn handle_key_event(&mut self, key_event: KeyEvent) {
        if key_event.kind == KeyEventKind::Release {
            return;
        }

        if matches!(key_event.code, KeyCode::Esc)
            || self.current_field_is_select()
                && self.list_keymap.action_for(key_event) == Some(ListAction::Cancel)
        {
            self.dispatch_cancel();
            self.done = true;
            return;
        }

        match key_event {
            KeyEvent {
                code: KeyCode::Char('p'),
                modifiers: KeyModifiers::CONTROL,
                ..
            }
            | KeyEvent {
                code: KeyCode::PageUp,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.move_field(/*next*/ false);
                return;
            }
            KeyEvent {
                code: KeyCode::Char('n'),
                modifiers: KeyModifiers::CONTROL,
                ..
            }
            | KeyEvent {
                code: KeyCode::PageDown,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.move_field(/*next*/ true);
                return;
            }
            KeyEvent {
                code: KeyCode::Left,
                modifiers: KeyModifiers::NONE,
                ..
            }
            | KeyEvent {
                code: KeyCode::Char('h'),
                modifiers: KeyModifiers::NONE,
                ..
            } if self.current_field_is_select() => {
                self.move_field(/*next*/ false);
                return;
            }
            _ if self.current_field_is_select()
                && self.list_keymap.action_for(key_event) == Some(ListAction::MoveLeft) =>
            {
                self.move_field(/*next*/ false);
                return;
            }
            KeyEvent {
                code: KeyCode::Right,
                modifiers: KeyModifiers::NONE,
                ..
            }
            | KeyEvent {
                code: KeyCode::Char('l'),
                modifiers: KeyModifiers::NONE,
                ..
            } if self.current_field_is_select() => {
                self.move_field(/*next*/ true);
                return;
            }
            _ if self.current_field_is_select()
                && self.list_keymap.action_for(key_event) == Some(ListAction::MoveRight) =>
            {
                self.move_field(/*next*/ true);
                return;
            }
            _ => {}
        }

        if self.current_field_is_select() {
            self.validation_error = None;
            let options_len = self.options_len();
            match (self.list_keymap.action_for(key_event), key_event.code) {
                (Some(ListAction::MoveUp), _) | (_, KeyCode::Up | KeyCode::Char('k')) => {
                    if let Some(answer) = self.current_answer_mut() {
                        answer.selection.move_up_wrap(options_len);
                        answer.answer_committed = false;
                    }
                }
                (Some(ListAction::MoveDown), _) | (_, KeyCode::Down | KeyCode::Char('j')) => {
                    if let Some(answer) = self.current_answer_mut() {
                        answer.selection.move_down_wrap(options_len);
                        answer.answer_committed = false;
                    }
                }
                (_, KeyCode::Backspace | KeyCode::Delete) => self.clear_selection(),
                (_, KeyCode::Char(' ')) => self.select_current_option(/*committed*/ true),
                (Some(ListAction::Accept), _) | (_, KeyCode::Enter) => {
                    if self.selected_option_index().is_some() {
                        self.select_current_option(/*committed*/ true);
                    }
                    self.go_next_or_submit();
                }
                (_, KeyCode::Char(ch)) => {
                    if let Some(option_idx) = self.option_index_for_digit(ch) {
                        if let Some(answer) = self.current_answer_mut() {
                            answer.selection.selected_idx = Some(option_idx);
                        }
                        self.select_current_option(/*committed*/ true);
                        self.go_next_or_submit();
                    }
                }
                _ => {}
            }
            return;
        }

        let before = self.capture_composer_draft();
        let (result, _) = self.composer.handle_key_event(key_event);
        let submitted = self.handle_composer_input_result(result);
        if submitted {
            return;
        }
        let after = self.capture_composer_draft();
        if before != after {
            self.validation_error = None;
            if let Some(answer) = self.current_answer_mut() {
                answer.answer_committed = false;
            }
        }
    }

