fn render_limit_progress_bar(percent_remaining: f64, segments: usize) -> String {
    let ratio = (percent_remaining / 100.0).clamp(0.0, 1.0);
    let filled = (ratio * segments as f64).round() as usize;
    let filled = filled.min(segments);
    let empty = segments.saturating_sub(filled);
    format!(
        "[{}{}]",
        STATUS_LIMIT_BAR_FILLED.repeat(filled),
        STATUS_LIMIT_BAR_EMPTY.repeat(empty)
    )
}

fn raw_lines_from_source(source: &str) -> Vec<Line<'static>> {
    if source.is_empty() {
        return Vec::new();
    }

    let mut parts = source.split('\n').collect::<Vec<_>>();
    if source.ends_with('\n') {
        parts.pop();
    }

    parts
        .into_iter()
        .map(|line| Line::from(line.to_string()))
        .collect()
}

fn append_voice_history(
    spans: &mut Vec<Span<'static>>,
    samples: &[u8],
    meter_width: usize,
    color: Color,
    muted: bool,
) {
    let samples = &samples[samples.len().saturating_sub(meter_width)..];
    for intensity in std::iter::repeat_n(/*element*/ 0, meter_width - samples.len())
        .chain(samples.iter().copied())
    {
        let height = if muted {
            0
        } else {
            usize::from(intensity)
                .saturating_mul(/*rhs*/ 7)
                .div_ceil(/*rhs*/ 255)
        };
        let style = Style::new().fg(if height == 0 { Color::DarkGray } else { color });
        spans.push(Span::styled(
            ["▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"][height],
            style,
        ));
    }
}

