fn delegation_started_before_peer_connection_keeps_its_voice_origin() {
    let (mut chat, _sender, mut events, mut ops) = make_chatwidget_manual_with_sender().await;
    let thread_id = activate_voice(&mut chat);
    chat.realtime_conversation.phase = RealtimeConversationPhase::Starting;
    chat.realtime_conversation.backend_started = true;
    chat.realtime_conversation.webrtc_connected = false;
    let turn_id = "startup-delegation";
    chat.turn_lifecycle.agent_turn_running = true;
    chat.turn_lifecycle.last_turn_id = Some(turn_id.to_string());
    let delegation =
        user_item("<realtime_delegation><input>spoken question</input></realtime_delegation>");
    start_item(&mut chat, thread_id, turn_id, delegation.clone());
    complete_item(&mut chat, thread_id, turn_id, delegation);

    chat.on_realtime_webrtc_connected(chat.realtime_conversation.attempt_id, Ok(()));
    let final_answer = agent_item(
        "startup-final",
        "[FINAL] Spoken answer",
        /*phase*/ None,
    );
    start_item(&mut chat, thread_id, turn_id, final_answer.clone());
    complete_item(&mut chat, thread_id, turn_id, final_answer.clone());
    finish_turn(
        &mut chat,
        thread_id,
        turn_id,
        vec![final_answer],
        TurnStatus::Completed,
    );

    assert!(matches!(
        ops.try_recv(),
        Ok(AppCommand::RealtimeConversationSpeech { text, .. }) if text.as_str() == "Spoken answer"
    ));
    assert!(ops.try_recv().is_err());
    commit_realtime_history_events(&mut chat, &mut events);
    while let Ok(event) = events.try_recv() {
        if let AppEvent::InsertHistoryCell(cell) = event
            && !cell.as_any().is::<FinalMessageSeparator>()
        {
            let rendered = cell
                .transcript_lines(/*width*/ 80)
                .iter()
                .map(ToString::to_string)
                .collect::<String>();
            assert!(!rendered.contains("Spoken answer"));
            assert!(!rendered.contains("<realtime_delegation>"));
        }
    }
}

fn history_search_paste_appends_query_and_accepts_match() {
    let mut composer = composer_with_history();
    composer.handle_key_event(KeyEvent::new(KeyCode::Char('r'), KeyModifiers::CONTROL));
    assert!(composer.handle_paste("git".to_string()));
    assert_eq!(composer.draft.textarea.text(), "git log");

    composer.handle_key_event(KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE));
    let paste_target = composer.clipboard_paste_target(Some(KeyCode::Insert));
    // A background history lookup changes the preview, not the query being edited.
    composer.apply_history_search_result(HistorySearchResult::Found(HistoryEntry::new(
        "git diff".into(),
    )));
    assert_eq!(
        composer.clipboard_paste_target(Some(KeyCode::Insert)),
        paste_target
    );
    assert!(composer.handle_paste("status".to_string()));
    assert_ne!(
        composer.clipboard_paste_target(Some(KeyCode::Insert)),
        paste_target
    );
    assert_eq!(
        composer.history_search.as_ref().unwrap().query,
        "git status"
    );
    assert_eq!(composer.draft.textarea.text(), "git status");

    let terminal = render_composer(&composer, /*width*/ 70);
    insta::assert_snapshot!("history_search_pasted_query", terminal.backend());

    let (result, _) = composer.handle_key_event(KeyCode::Enter.into());
    assert!(matches!(result, InputResult::None));
    assert!(!composer.history_search_active());
    assert_eq!(composer.draft.textarea.text(), "git status");
}

