fn suppressed_submission_restores_pending_paste_payload() {
        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ false,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );

        composer
            .draft
            .textarea
            .set_text_clearing_elements("/unknown ");
        composer.draft.textarea.set_cursor("/unknown ".len());
        let large_content = "x".repeat(LARGE_PASTE_CHAR_THRESHOLD + 5);
        composer.handle_paste(large_content.clone());
        let placeholder = composer
            .draft
            .pending_pastes
            .first()
            .expect("expected pending paste")
            .0
            .clone();

        let (result, _) =
            composer.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert!(matches!(result, InputResult::None));
        assert_eq!(composer.draft.pending_pastes.len(), 1);
        assert_eq!(composer.current_text(), format!("/unknown {placeholder}"));

        composer.draft.textarea.set_cursor(/*pos*/ 0);
        composer.handle_key_event(KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE));
        composer.draft.textarea.insert_str(" /");
        let (result, _) =
            composer.handle_key_event(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        match result {
            InputResult::Submitted {
                text,
                text_elements,
            } => {
                assert_eq!(text, format!("/unknown {large_content}"));
                assert!(text_elements.is_empty());
            }
            _ => panic!("expected Submitted"),
        }
        assert!(composer.draft.pending_pastes.is_empty());
    }

fn standard_viewport_growth_preserves_composer_and_cursor() {
    for scroll_by in [1, 3, 4] {
        let width = 24;
        let height = 6;
        let backend = VT100Backend::with_scrollback(width, height, /*scrollback_len*/ 32);
        let mut terminal = Terminal::with_options(backend).expect("terminal with scrollback");
        let viewport_top = 4;
        terminal.set_viewport_area(Rect::new(
            /*x*/ 0,
            viewport_top,
            width,
            /*height*/ 2,
        ));
        for (row, text) in [
            "history-1",
            "history-2",
            "history-3",
            "history-4",
            "composer-1",
            "composer-2",
        ]
        .into_iter()
        .enumerate()
        {
            queue!(
                terminal.backend_mut(),
                MoveTo(/*x*/ 0, row as u16),
                Print(text)
            )
            .expect("seed terminal row");
        }
        let cursor = Position::new(/*x*/ 7, /*y*/ 5);
        terminal
            .set_cursor_position(cursor)
            .expect("position cursor");

        ScrollbackStrategy::Standard
            .grow_viewport(
                &mut terminal,
                viewport_top,
                Size::new(width, height),
                scroll_by,
            )
            .expect("grow standard viewport");

        let screen = terminal.backend().vt100().screen();
        assert_eq!(
            (screen.cursor_position(), terminal.last_known_cursor_pos),
            ((cursor.y, cursor.x), cursor)
        );
        // vt100 intentionally omits scrollback for partial regions, even for newlines. Snapshot
        // visible geometry here; the wire test below and real-terminal smoke cover scrollback.
        insta::assert_snapshot!(
            format!("standard_viewport_growth_{scroll_by}"),
            screen.contents()
        );

        // A newline at the physical bottom must scroll the full screen after the region reset.
        queue!(
            terminal.backend_mut(),
            MoveTo(/*x*/ 0, height - 1),
            Print("\r\nnext-row")
        )
        .expect("write after restoring the scroll region");
        assert_eq!(
            terminal
                .backend()
                .vt100()
                .screen()
                .rows(/*start*/ 0, width)
                .collect::<Vec<_>>()[4..],
            ["composer-2", "next-row"]
        );
    }
}

