fn complete_plan_turn(app: &mut App) {
    app.chat_widget
        .set_feature_enabled(Feature::CollaborationModes, /*enabled*/ true);
    app.chat_widget.set_collaboration_mask(
        crate::collaboration_modes::plan_mask(app.model_catalog.as_ref()).unwrap(),
    );
    let thread_id = ThreadId::new().to_string();
    let turn = Turn {
        id: "plan-turn".into(),
        root_turn_id: None,
        items_view: TurnItemsView::Full,
        items: Vec::new(),
        status: TurnStatus::InProgress,
        error: None,
        started_at: None,
        completed_at: None,
        duration_ms: None,
    };
    for notification in [
        ServerNotification::TurnStarted(TurnStartedNotification {
            thread_id: thread_id.clone(),
            turn: turn.clone(),
        }),
        ServerNotification::ItemCompleted(ItemCompletedNotification {
            thread_id: thread_id.clone(),
            turn_id: turn.id.clone(),
            completed_at_ms: 0,
            item: ThreadItem::Plan {
                id: "plan".into(),
                text: (1..=40)
                    .map(|row| format!("- Plan step {row:02}\n"))
                    .collect(),
            },
        }),
        ServerNotification::TurnCompleted(TurnCompletedNotification {
            thread_id,
            turn: Turn {
                status: TurnStatus::Completed,
                ..turn
            },
        }),
    ] {
        app.chat_widget
            .handle_server_notification(notification, /*replay_kind*/ None);
    }
    assert!(app.chat_widget.has_active_modal());
}

