fn recovered_answers_undo_as_one_vim_edit() {
    for answer in [
        "answer".to_owned(),
        "x".repeat(LARGE_PASTE_CHAR_THRESHOLD + 1),
    ] {
        let mut composer = vim_composer("abc");
        keys(&mut composer, "iX");
        escape(&mut composer);
        let before = composer.draft_snapshot();
        composer.append_recovered_drafts(&answer);
        keys(&mut composer, "u");
        assert_eq!(composer.draft_snapshot(), before);
        keys(&mut composer, ".");
        assert_eq!(composer.current_text(), "XXabc");

        for (command, mode, edited) in [("iX", "Insert", "Xabc"), ("RX", "Replace", "Xbc")] {
            let mut composer = vim_composer("abc");
            let before = composer.draft_snapshot();
            keys(&mut composer, command);
            composer.append_recovered_drafts(&answer);
            assert_eq!(
                (
                    composer.current_text_with_pending(),
                    composer.draft.textarea.vim_mode_label(),
                ),
                (format!("{edited}\n\n{answer}"), Some(mode))
            );
            escape(&mut composer);
            let after = composer.draft_snapshot();
            keys(&mut composer, "u");
            assert_eq!(composer.draft_snapshot(), before);
            ctrl_r(&mut composer);
            assert_eq!(composer.draft_snapshot(), after);
            keys(&mut composer, "u");
            keys(&mut composer, ".");
            assert_eq!(composer.current_text(), edited);
        }
        for command in ["", "d", "/draft", "?draft", "d/draft", "c?draft", "y/draft"] {
            let mut composer = vim_composer("existing draft");
            let before = composer.draft_snapshot();
            keys(&mut composer, command);
            composer.append_recovered_drafts(&answer);
            assert_eq!(
                (
                    composer.current_text_with_pending(),
                    composer.draft.textarea.vim_query().is_some(),
                    composer.draft.textarea.is_vim_operator_pending(),
                ),
                (format!("existing draft\n\n{answer}"), false, false)
            );
            let after = composer.draft_snapshot();
            keys(&mut composer, "u");
            assert_eq!(composer.draft_snapshot(), before);
            ctrl_r(&mut composer);
            assert_eq!(composer.draft_snapshot(), after);
        }

        let mut composer = vim_composer("abc");
        composer
            .history
            .record_local_submission(HistoryEntry::new("archived prompt".into()));
        keys(&mut composer, "x");
        let before = composer.draft_snapshot();
        keys(&mut composer, "d");
        ctrl_r(&mut composer);
        keys(&mut composer, "archive");
        composer.edit_stored_draft(|composer| composer.append_recovered_drafts(&answer));
        assert_eq!(composer.current_text(), "archived prompt");
        assert!(composer.history_search_active());
        escape(&mut composer);
        assert_eq!(
            composer.current_text_with_pending(),
            format!("bc\n\n{answer}")
        );
        let after = composer.draft_snapshot();
        keys(&mut composer, "u");
        assert_eq!(composer.draft_snapshot(), before);
        ctrl_r(&mut composer);
        assert_eq!(composer.draft_snapshot(), after);
    }
    for command in ["!echo", "/diff", "/review "] {
        let mut composer = vim_composer(command);
        composer.move_cursor_to_end();
        composer.sync_popups();
        let before = composer.draft_snapshot();
        composer.append_recovered_drafts("answer");
        assert_eq!(composer.current_text(), format!("\\{command}\n\nanswer"));
        assert!(composer.draft.textarea.text_elements().is_empty());
        keys(&mut composer, "u");
        assert_eq!(composer.draft_snapshot(), before);
    }
    let mut composer = vim_composer("echo");
    composer.draft.prompt_prefix = PromptPrefix::Shell;
    let before = composer.draft_snapshot();
    composer.append_recovered_drafts("answer");
    assert_eq!(composer.current_text(), "\\!echo\n\nanswer");
    keys(&mut composer, "u");
    assert_eq!(composer.draft_snapshot(), before);
    snapshot_composer_state_with_width(
        "recovered_answer_cancels_vim_search",
        /*width*/ 40,
        /*enhanced_keys_supported*/ false,
        |composer| {
            composer.set_disable_paste_burst(/*disabled*/ true);
            composer.set_text_content("existing draft".into(), Vec::new(), Vec::new());
            composer.set_vim_enabled(/*enabled*/ true);
            keys(composer, "d/draft");
            composer.append_recovered_drafts("answer");
        },
    );
}

fn controller_keeps_pre_table_lines_queued_when_table_is_confirmed() {
        let mut ctrl = stream_controller(Some(80));

        ctrl.push("Intro line before table.\n");
        assert_eq!(ctrl.queued_lines(), 1);

        ctrl.push("| Key | Value |\n");
        ctrl.push("| --- | --- |\n");
        assert_eq!(
            ctrl.queued_lines(),
            1,
            "pre-table line should remain queued after table confirmation",
        );

        let (cell, idle) = ctrl.on_commit_tick();
        let committed = cell
            .map(|cell| lines_to_plain_strings(&cell.transcript_lines(u16::MAX)))
            .unwrap_or_default();
        assert!(
            committed
                .iter()
                .any(|line| line.contains("Intro line before table.")),
            "expected pre-table line to commit independently: {committed:?}",
        );
        assert!(idle, "only pre-table content should have been queued");

        ctrl.push(
            "| first | row |\n\nAfter table.\n\n| Next | Table |\n| --- | --- |\n| second | row |\n",
        );
        let (cell, idle) = ctrl.on_commit_tick_batch(usize::MAX);
        let committed = cell.expect("completed table and prose should enter scrollback");
        assert!(idle);
        assert!(ctrl.has_live_tail(), "the later table must stay mutable");
        insta::assert_debug_snapshot!(
            "completed_table_scrollback",
            lines_to_plain_strings(&committed.transcript_lines(u16::MAX)),
        );

        let context = InlineVisualizationContext::new(&test_cwd(), codex_protocol::ThreadId::new())
            .expect("visualization context");
        for (context, definition) in [
            (None, "[ref]: https://example.com\n"),
            (Some(context), "[ref]: https://example.com\n"),
            (None, "[ref]: https://example.com"),
        ] {
            let mut ctrl = StreamController::new_with_inline_visualizations(
                Some(80),
                &test_cwd(),
                HistoryRenderMode::Rich,
                context,
            );
            let mut committed = Vec::new();
            for delta in [
                "| Key | Value |\n| --- | --- |\n| [A][ref] | row |\n",
                "\nAfter table.\n\n",
                definition,
            ] {
                ctrl.push(delta);
                if let (Some(cell), _) = ctrl.on_commit_tick_batch(usize::MAX) {
                    committed.extend(lines_to_plain_strings(&cell.transcript_lines(u16::MAX)));
                }
            }
            assert!(committed.iter().any(|line| line.contains("[A][ref]")));
            assert!(
                !ctrl.has_live_tail(),
                "the completed table should be released"
            );
            assert!(
                ctrl.needs_scrollback_reflow(),
                "late definitions must repair scrollback"
            );
            let (_, source) = ctrl.finalize();
            let rendered = render_source(
                source.as_deref().unwrap(),
                Some(80),
                &test_cwd(),
                HistoryRenderMode::Rich,
                /*inline_visualization_context*/ None,
            );
            insta::assert_debug_snapshot!(
                "completed_table_reference",
                lines_to_plain_strings(&visible_lines(rendered))
            );
        }
    }

