fn stationary_clicks_are_deferred_but_dragging_back_does_not_activate() {
    let area = Rect::new(
        /*x*/ 0, /*y*/ 0, /*width*/ 20, /*height*/ 1,
    );
    let mut buffer = Buffer::empty(area);
    "⚠ 2 warnings".render(area, &mut buffer);
    let mut selection = RenderedSelection::default();
    selection.register(area, /*invalidate*/ false);
    assert!(matches!(
        selection.handle_event(&mouse(Down(Left), /*column*/ 2, /*row*/ 0), &buffer),
        Some(RegionAction::Selection(_))
    ));
    assert!(matches!(
        selection.handle_event(&mouse(Up(Left), /*column*/ 2, /*row*/ 0), &buffer),
        Some(RegionAction::Click(_))
    ));
    selection.handle_event(&mouse(Down(Left), /*column*/ 5, /*row*/ 0), &buffer);
    selection.handle_event(&mouse(Drag(Left), /*column*/ 7, /*row*/ 0), &buffer);
    assert!(!matches!(
        selection.handle_event(&mouse(Up(Left), /*column*/ 5, /*row*/ 0), &buffer),
        Some(RegionAction::Click(_))
    ));
    // A stationary click after a selection releases the frozen revision.
    for event in [
        mouse(Down(Left), /*column*/ 0, /*row*/ 0),
        mouse(Drag(Left), /*column*/ 3, /*row*/ 0),
        mouse(Up(Left), /*column*/ 3, /*row*/ 0),
    ] {
        selection.handle_event(&event, &buffer);
    }
    assert!(selection.view.has_selection_range());
    selection.handle_event(&mouse(Down(Left), /*column*/ 10, /*row*/ 0), &buffer);
    assert!(matches!(
        selection.handle_event(&mouse(Up(Left), /*column*/ 10, /*row*/ 0), &buffer),
        Some(RegionAction::Click(_))
    ));
    assert!(!selection.view.has_active_interaction());
}

fn validate_chord_conflicts(keymap: &RuntimeKeymap) -> Result<(), String> {
    for (index, binding) in keymap.chords.bindings.iter().enumerate() {
        validate_binding_shape(binding)?;
        validate_reserved_strokes(binding)?;
        if binding.chord.completion == binding.chord.prefix
            && ((keymap.chords.leader.contains(&binding.chord.prefix)
                && binding.action.context.overlaps(KeymapContext::Global))
                || keymap.chords.bindings.iter().any(|leader| {
                    leader.is_leader()
                        && leader.chord.prefix == binding.chord.prefix
                        && leader.overlaps(binding.action)
                }))
        {
            return Err(format!(
                "Ambiguous `{}` = `{}`: repeating the leader is reserved for cancellation.",
                binding.action.config_path(),
                binding.spec,
            ));
        }

        if let Some(conflict) = runtime_action_bindings(keymap)
            .filter(|candidate| binding.overlaps(candidate.id))
            .find(|candidate| {
                candidate.bindings.iter().any(|single| {
                    normalize_chord_binding(*single).parts() == binding.chord.prefix.parts()
                })
            })
        {
            return Err(format!(
                "Ambiguous `{}` = `{}`: its prefix shadows `{}`. \
Unbind or remap the existing shortcut before using it as a chord prefix.",
                binding.action.config_path(),
                binding.spec,
                conflict.id.config_path(),
            ));
        }

        for previous in &keymap.chords.bindings[..index] {
            if previous.action != binding.action
                && (previous.overlaps(binding.action) || binding.overlaps(previous.action))
                && previous.chord == binding.chord
            {
                return Err(format!(
                    "Ambiguous `{}` = `{}`: the same chord is already assigned to `{}`. \
Choose a unique chord and retry.",
                    binding.action.config_path(),
                    binding.spec,
                    previous.action.config_path(),
                ));
            }
        }
    }

    Ok(())
}

