fn format_tool_approval_display_message(
    message: &str,
    approval_display_params: &[McpToolApprovalDisplayParam],
) -> String {
    let message = message.trim();
    if approval_display_params.is_empty() {
        return message.to_string();
    }

    let mut sections = Vec::new();
    if !message.is_empty() {
        sections.push(message.to_string());
    }
    let param_lines = approval_display_params
        .iter()
        .take(APPROVAL_TOOL_PARAM_DISPLAY_LIMIT)
        .map(format_tool_approval_display_param_line)
        .collect::<Vec<_>>();
    if !param_lines.is_empty() {
        sections.push(param_lines.join("\n"));
    }
    let mut message = sections.join("\n\n");
    message.push('\n');
    message
}

fn resize_uses_the_passage_from_the_current_live_or_replaced_entry() {
    for entry_kind in ["live", "replaced"] {
        let initial = (0..40)
            .map(|index| format!("old{index:02}"))
            .collect::<Vec<_>>()
            .join(" ");
        let revised = (0..40)
            .map(|index| format!("café{index:02}"))
            .collect::<Vec<_>>()
            .join(" ");
        let mut view = TranscriptView::default();
        let mut cells = Vec::new();
        if entry_kind == "live" {
            view.sync_live_tail(/*width*/ 18, /*key*/ None, |_| {
                Some(crate::terminal_hyperlinks::plain_hyperlink_lines(vec![
                    initial.into(),
                ]))
            });
        } else {
            cells.push(cell(initial));
        }
        render(&mut view, &cells, /*width*/ 18, /*height*/ 3);
        view.scroll(&cells, /*rows*/ -5);
        if entry_kind == "live" {
            view.sync_live_tail(/*width*/ 18, /*key*/ None, |_| {
                Some(crate::terminal_hyperlinks::plain_hyperlink_lines(vec![
                    revised.clone().into(),
                ]))
            });
        } else {
            cells[0] = cell(revised.clone());
        }
        let current = render(&mut view, &cells, /*width*/ 18, /*height*/ 3);
        let current_text = text(&current);
        let first_word = current_text.split_whitespace().next().unwrap();
        if entry_kind == "live" {
            view.sync_live_tail(/*width*/ 34, /*key*/ None, |_| {
                Some(crate::terminal_hyperlinks::plain_hyperlink_lines(vec![
                    revised.clone().into(),
                ]))
            });
        }
        let wide = render(&mut view, &cells, /*width*/ 34, /*height*/ 3);
        assert!(text(&wide).contains(first_word), "{entry_kind}");
        if entry_kind == "live" {
            view.sync_live_tail(/*width*/ 18, /*key*/ None, |_| {
                Some(crate::terminal_hyperlinks::plain_hyperlink_lines(vec![
                    revised.into(),
                ]))
            });
        }
        assert_eq!(
            render(&mut view, &cells, /*width*/ 18, /*height*/ 3),
            current,
            "{entry_kind}"
        );
    }
}

