fn handle_follow_control_mouse(&mut self, event: MouseEvent) -> Option<ViewAction> {
        let control = &mut self.follow_control;
        let area = control.area?;
        let point = ScreenPosition::new(event.column, event.row);
        let was_hovered = control.pointer.is_some_and(|point| area.contains(point));
        let inside = area.contains(point);
        control.pointer = Some(point);
        match event.kind {
            MouseEventKind::Down(MouseButton::Left) if inside => {
                control.pressed = true;
                Some(ViewAction::Changed)
            }
            MouseEventKind::Up(MouseButton::Left) if control.pressed => {
                control.pressed = false;
                if inside {
                    self.jump_to_latest();
                }
                Some(ViewAction::Changed)
            }
            MouseEventKind::Drag(MouseButton::Left) if control.pressed => Some(ViewAction::Changed),
            MouseEventKind::Moved if inside != was_hovered => Some(ViewAction::Changed),
            _ => None,
        }
    }

fn schedule_recap_check(&mut self, thread_id: ThreadId, now: Instant) {
        if let Some(task) = self.recap.scheduled_check.take() {
            task.abort();
        }

        if !self.local_settings.tui.auto_recap {
            return;
        }
        let Some(deadline) = self.recap.next_check_deadline() else {
            return;
        };
        let delay = deadline.saturating_duration_since(now);
        let sleep = tokio::time::sleep(delay);
        let app_event_tx = self.app_event_tx.clone();

        self.recap.scheduled_check = Some(tokio::spawn(async move {
            sleep.await;
            app_event_tx.send(AppEvent::CheckRecap { thread_id });
        }));
    }

fn render_with_turn_tip_space(
        &mut self,
        area: Rect,
        buf: &mut Buffer,
        cells: &[Arc<dyn HistoryCell>],
        tip: Option<&TurnTip>,
    ) -> Option<Rect> {
        let tip = tip.filter(|_| area.height > 1);
        self.turn_tip_key = tip.and_then(|_| {
            cells
                .last()
                .filter(|cell| {
                    cell.as_any()
                        .is::<crate::history_cell::FinalMessageSeparator>()
                        && !cell.display_lines(area.width).is_empty()
                })
                .map(EntryKey::cell)
        });
        self.render(
            Rect {
                height: area.height - u16::from(tip.is_some() && self.turn_tip_key.is_none()),
                ..area
            },
            buf,
            cells,
        );
        // The final viewport includes prompt-header and footer reservations. Let the tip yield
        // rather than leave only completion metadata visible on a short terminal.
        if let Some(key) = self.turn_tip_key
            && self.visible.first().is_none_or(|row| row.key == key)
        {
            self.turn_tip_key = None;
            self.render(area, buf, cells);
            return None;
        }
        tip?;
        let row = match self.turn_tip_key {
            Some(key) => self
                .visible
                .iter()
                .position(|row| row.key == key && row.row == 0)?,
            None => self.visible.len(),
        };
        let y = self.area.y.saturating_add(row as u16);
        (self.tail_visible && !self.visible.is_empty() && y < area.bottom()).then_some(Rect::new(
            self.area.x,
            y,
            self.area.width,
            /*height*/ 1,
        ))
    }

fn speak_completed_realtime_delegation(&mut self, turn_id: &str, item: &ThreadItem) {
        let ThreadItem::AgentMessage {
            id: item_id, text, ..
        } = item
        else {
            return;
        };
        let Some(RealtimeAgentItemOrigin::Delegated {
            may_speak: true,
            completed: true,
            suppressed_nonfinal,
            input_generation,
        }) = self
            .realtime_conversation
            .agent_items
            .get(&(turn_id.to_string(), item_id.to_string()))
        else {
            return;
        };
        let input_generation = *input_generation;
        let suppressed_nonfinal = *suppressed_nonfinal;
        if input_generation != self.realtime_conversation.input_generation {
            return;
        }
        let trimmed = text.trim();
        if is_private_realtime_agent_item(item)
            || trimmed.is_empty()
            || !self.realtime_conversation.latest_input_was_voice
        {
            return;
        }
        let Some(thread_id) = self.realtime_conversation.thread_id else {
            return;
        };
        if self.thread_id() != Some(thread_id) {
            return;
        }
        let text = trimmed
            .strip_prefix("[FINAL]")
            .map(str::trim_start)
            .unwrap_or(trimmed)
            .to_string();
        if text.is_empty() {
            return;
        }
        let Some(RealtimeTurnOrigin::Delegated {
            may_speak,
            input_generation: turn_input_generation,
        }) = self.realtime_conversation.turn_origins.get_mut(turn_id)
        else {
            return;
        };
        if !*may_speak || *turn_input_generation != input_generation {
            return;
        }
        *may_speak = false;
        if !can_retain_realtime_speech(turn_id, item)
            || codex_utils_string::approx_token_count(&text) > MAX_SPEAKABLE_FINAL_TOKENS
        {
            self.remove_waiting_realtime_speech(turn_id, item_id);
            self.finish_realtime_turn(turn_id);
            self.handle_thread_item(
                item.clone(),
                turn_id.to_string(),
                super::ThreadItemRenderSource::Live,
            );
            return;
        }
        let delivery_id = NEXT_REALTIME_SPEECH_DELIVERY_ID.fetch_add(1, Ordering::Relaxed);
        let index = self
            .realtime_conversation
            .pending_speech
            .iter_mut()
            .position(|pending| {
                pending.turn_id == turn_id
                    && matches!(&pending.item, ThreadItem::AgentMessage { id, .. } if id == item_id)
                    && pending.state == PendingSpeechState::AwaitingTurn
            });
        let index = match index {
            Some(index) => index,
            None if suppressed_nonfinal => {
                if self.realtime_conversation.pending_speech.len() >= MAX_PENDING_SPEECH_DELIVERIES
                    && let Some(oldest) = self.realtime_conversation.pending_speech.pop_front()
                {
                    self.restore_realtime_speech(oldest);
                }
                self.realtime_conversation
                    .pending_speech
                    .push_back(PendingRealtimeSpeech {
                        state: PendingSpeechState::AwaitingTurn,
                        captioned: false,
                        input_generation,
                        thread_id,
                        turn_id: turn_id.to_string(),
                        item: item.clone(),
                    });
                self.realtime_conversation.pending_speech.len() - 1
            }
            None => return,
        };
        let pending = &mut self.realtime_conversation.pending_speech[index];
        pending.item = item.clone();
        pending.state = PendingSpeechState::Queued(delivery_id);
        if !self.submit_op(AppCommand::RealtimeConversationSpeech {
            thread_id,
            attempt_id: self.realtime_conversation.attempt_id,
            input_generation,
            delivery_id,
            text: text.into(),
        }) {
            self.restore_undelivered_realtime_speech(delivery_id);
            self.on_realtime_error(
                "Failed to deliver the voice response.".to_string(),
                RealtimeFailureCause::SpeechDelivery,
            );
        } else {
            self.realtime_conversation.pending_speech.retain(|pending| {
                pending.turn_id != turn_id || pending.state != PendingSpeechState::AwaitingTurn
            });
        }
    }

