fn history_search_highlight_ranges(&self) -> Vec<Range<usize>> {
        let Some(search) = self.history_search.as_ref() else {
            return Vec::new();
        };
        if !matches!(search.status, HistorySearchStatus::Match) || search.query.is_empty() {
            return Vec::new();
        }
        let prefix_len = self.draft.prompt_prefix.len();
        Self::case_insensitive_match_ranges(&self.current_text(), &search.query)
            .into_iter()
            .filter_map(|range| {
                let start = range.start.saturating_sub(prefix_len);
                let end = range.end.saturating_sub(prefix_len);
                (start < end).then_some(start..end)
            })
            .collect()
    }

fn cancel_beginning(&mut self) {
        if self.history == TranscriptHistoryState::LoadingBeginning {
            // Keep the in-flight page, but let the user's new navigation supersede the jump.
            self.history = TranscriptHistoryState::LoadingOlder;
        }
    }

