fn handle_scroll_key(
        &mut self,
        key: KeyEvent,
        cells: &[Arc<dyn HistoryCell>],
    ) -> Option<ViewAction> {
        let jump = JumpTarget::from_key(key);
        match (key.code, key.modifiers) {
            (KeyCode::PageUp | KeyCode::PageDown, KeyModifiers::NONE) => {
                // Share page-key configuration without taking the pager's typing shortcuts.
                // Full pages retain the main view's existing one-row overlap.
                let keymap = &self.disclosure.keymap.pager;
                let height = self.area.height.max(/*other*/ 1) as isize;
                let page = (height - 1).max(/*other*/ 1);
                let half = (height + 1) / 2;
                let delta = [
                    (&keymap.scroll_up, -1),
                    (&keymap.scroll_down, 1),
                    (&keymap.page_up, -page),
                    (&keymap.page_down, page),
                    (&keymap.half_page_up, -half),
                    (&keymap.half_page_down, half),
                ]
                .into_iter()
                .find_map(|(bindings, delta)| bindings.is_pressed(key).then_some(delta))?;
                self.scroll(cells, delta);
            }
            (KeyCode::Esc, KeyModifiers::NONE) if self.can_return_to_latest() => {
                self.jump_to_latest();
            }
            _ if jump == Some(JumpTarget::Beginning) => {
                self.jump_to_beginning(cells);
            }
            _ if jump == Some(JumpTarget::Latest) => self.jump_to_latest(),
            _ => return None,
        }
        Some(ViewAction::Changed)
    }

fn cursor_pos(&self, area: Rect) -> Option<(u16, u16)> {
        if !self.focus_is_notes() {
            return None;
        }
        let content_area = menu_surface_inset(area);
        if content_area.width == 0 || content_area.height == 0 {
            return None;
        }
        let sections = self.layout_sections(content_area);
        let input_area = if self.other_selected() {
            self.other_input_area(sections.options_area)
        } else {
            sections.notes_area
        };
        if input_area.width == 0 || input_area.height == 0 {
            return None;
        }
        self.composer.inline_cursor_pos(input_area)
    }

fn new_mcp_tools_output_from_statuses(
    statuses: &[McpServerStatus],
    detail: McpServerStatusDetail,
) -> PlainHistoryCell {
    let mut lines: Vec<Line<'static>> = vec![
        "/mcp".magenta().into(),
        "".into(),
        vec!["🔌  ".into(), "MCP Tools".bold()].into(),
        "".into(),
    ];

    let mut statuses = statuses.iter().collect::<Vec<_>>();
    statuses.sort_by(|a, b| a.name.cmp(&b.name));

    let has_any_tools = statuses.iter().any(|status| !status.tools.is_empty());
    if !has_any_tools && matches!(detail, McpServerStatusDetail::Full) {
        lines.push("  • No MCP tools available.".italic().into());
        lines.push("".into());
    }

    for status in statuses {
        let (label, style) = match status.runtime_status {
            Some(McpServerConnectionStatus::Connected) => {
                ("connected", status_style(StatusTone::Success))
            }
            Some(McpServerConnectionStatus::Starting) => ("starting", accent_style()),
            Some(McpServerConnectionStatus::AuthenticationRequired) => (
                "authentication required",
                status_style(StatusTone::Attention),
            ),
            Some(McpServerConnectionStatus::Failed) => {
                ("failed", status_style(StatusTone::Failure))
            }
            Some(McpServerConnectionStatus::NotStarted) => ("not started", Style::default().dim()),
            Some(McpServerConnectionStatus::Disabled) => ("disabled", Style::default().dim()),
            Some(McpServerConnectionStatus::Cancelled) => ("cancelled", Style::default().dim()),
            None if matches!(
                status.auth_status,
                codex_app_server_protocol::McpAuthStatus::NotLoggedIn
            ) =>
            {
                (
                    "authentication required",
                    status_style(StatusTone::Attention),
                )
            }
            None => ("unknown", Style::default().dim()),
        };
        let count = status.tools.len();
        let unit = if count == 1 { "tool" } else { "tools" };
        lines.push(
            vec![
                "  • ".set_style(style),
                status.name.clone().bold(),
                ": ".into(),
                label.set_style(style),
                format!(" ({count} {unit})").dim(),
            ]
            .into(),
        );
        if matches!(detail, McpServerStatusDetail::ToolsAndAuthOnly) {
            continue;
        }
        let auth_status = match status.auth_status {
            codex_app_server_protocol::McpAuthStatus::Unknown => McpAuthStatus::Unknown,
            codex_app_server_protocol::McpAuthStatus::Unsupported => McpAuthStatus::Unsupported,
            codex_app_server_protocol::McpAuthStatus::NotLoggedIn => McpAuthStatus::NotLoggedIn,
            codex_app_server_protocol::McpAuthStatus::BearerToken => McpAuthStatus::BearerToken,
            codex_app_server_protocol::McpAuthStatus::OAuth => McpAuthStatus::OAuth,
        };
        lines.push(
            vec![
                "    • Auth: ".into(),
                mcp_auth_status_label(auth_status).into(),
            ]
            .into(),
        );

        let mut names = status.tools.keys().cloned().collect::<Vec<_>>();
        names.sort();
        if names.is_empty() {
            lines.push("    • Tools: (none)".into());
        } else {
            lines.push(vec!["    • Tools: ".into(), names.join(", ").into()].into());
        }

        if matches!(detail, McpServerStatusDetail::Full) {
            let server_resources = status.resources.clone();
            if server_resources.is_empty() {
                lines.push("    • Resources: (none)".into());
            } else {
                let mut spans: Vec<Span<'static>> = vec!["    • Resources: ".into()];

                for (idx, resource) in server_resources.iter().enumerate() {
                    if idx > 0 {
                        spans.push(", ".into());
                    }

                    let label = resource.title.as_ref().unwrap_or(&resource.name);
                    spans.push(label.clone().into());
                    spans.push(" ".into());
                    spans.push(format!("({})", resource.uri).dim());
                }

                lines.push(spans.into());
            }

            let server_templates = status.resource_templates.clone();
            if server_templates.is_empty() {
                lines.push("    • Resource templates: (none)".into());
            } else {
                let mut spans: Vec<Span<'static>> = vec!["    • Resource templates: ".into()];

                for (idx, template) in server_templates.iter().enumerate() {
                    if idx > 0 {
                        spans.push(", ".into());
                    }

                    let label = template.title.as_ref().unwrap_or(&template.name);
                    spans.push(label.clone().into());
                    spans.push(" ".into());
                    spans.push(format!("({})", template.uri_template).dim());
                }

                lines.push(spans.into());
            }
        }

        lines.push(Line::from(""));
    }

    if matches!(detail, McpServerStatusDetail::ToolsAndAuthOnly) {
        lines.push("".into());
        lines.push("  Use /mcp verbose for tools and resources.".dim().into());
    }

    PlainHistoryCell { lines }
}

