fn sync_search_live_tail(
        &mut self,
        width: u16,
        key: Option<ActiveCellTranscriptKey>,
        lines: impl FnOnce(u16) -> Option<Vec<HyperlinkLine>>,
    ) -> bool {
        if !self.search.is_active() || self.detailed {
            return false;
        }
        let next = key.map(|key| (width, key));
        if key.is_some_and(|key| key.cacheable) && self.search.live_key == next {
            return false;
        }
        self.search.live_key = next;
        let live = lines(width).map(|lines| Arc::new(TextLayout::new(lines, width)));
        let changed = self.search.live.as_ref().map(|layout| layout.text())
            != live.as_ref().map(|layout| layout.text());
        if changed {
            self.invalidate_live_search();
        }
        self.search.live = live;
        changed
    }

fn initialize_file(
    path: &Path,
    animations_configured: bool,
    probe: impl std::future::Future<Output = bool>,
) -> anyhow::Result<()> {
    let mut doc = read_config(path)?;
    if doc
        .get("tui")
        .and_then(|tui| tui.get("screen_reader_detection_done"))
        .is_some()
    {
        return Ok(());
    }
    let detected = tokio::time::timeout(DETECTION_TIMEOUT, probe)
        .await
        .unwrap_or(false);
    // Re-read after the probe so preferences saved during detection are preserved.
    doc = read_config(path)?;
    if doc
        .get("tui")
        .and_then(|tui| tui.get("screen_reader_detection_done"))
        .is_some()
    {
        return Ok(());
    }
    doc.entry("tui")
        .or_insert_with(|| toml_edit::Item::Table(toml_edit::Table::new()));
    if detected
        && !animations_configured
        && doc
            .get("tui")
            .and_then(|tui| tui.get("animations"))
            .is_none()
    {
        doc["tui"]["animations"] = value(false);
    }
    doc["tui"]["screen_reader_detection_done"] = value(true);
    let paths = resolve_symlink_write_paths(path)?;
    write_atomically(&paths.write_path, &doc.to_string())?;
    Ok(())
}

fn for_status(status: &ThreadStatus) -> Self {
        match status {
            ThreadStatus::Active { active_flags }
                if active_flags.contains(&ThreadActiveFlag::WaitingOnApproval)
                    || active_flags.contains(&ThreadActiveFlag::WaitingOnUserInput) =>
            {
                Self::NeedsYou
            }
            ThreadStatus::Active { .. } => Self::Working,
            ThreadStatus::Idle => Self::Ready,
            ThreadStatus::SystemError => Self::NeedsYou,
            ThreadStatus::NotLoaded => Self::Finished,
        }
    }

