fn render_picker(&self, area: Rect, buf: &mut Buffer) {
        let areas = self.picker_areas(area);
        Clear.render(area, buf);
        Block::default()
            .style(user_message_style())
            .render(areas.panel, buf);
        self.picker_header().render(areas.header, buf);
        if !areas.input.is_empty() {
            let mut state = self.textarea_state.borrow_mut();
            StatefulWidgetRef::render_ref(&(&self.textarea), areas.input, buf, &mut state);
            if self.textarea.text().is_empty() {
                Paragraph::new(self.placeholder.as_str().dim()).render(areas.input, buf);
            }
            Line::from("›".fg(accent_color())).render(
                Rect {
                    x: area.x,
                    width: 1,
                    height: 1,
                    ..areas.input
                },
                buf,
            );
        }

        let cancel_label = if self.prefer_esc_to_handle_key_event() {
            " normal mode"
        } else {
            " back"
        };
        let hint = Line::from(vec![
            key_hint::plain(KeyCode::Enter).into(),
            format!(" {} · ", self.submit_label).dim(),
            key_hint::plain(KeyCode::Esc).into(),
            cancel_label.dim(),
        ]);
        let vim_mode = self.textarea.vim_mode_indicator_span().map(Line::from);
        Paragraph::new(hint.clone()).render(areas.footer, buf);
        if let Some(mode) = vim_mode
            && max_left_width_for_right(areas.footer, mode.width() as u16)
                .is_some_and(|width| usize::from(width) >= hint.width())
        {
            render_context_right(areas.footer, buf, &mode);
        }
    }

fn pin_selection_range(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        selection: &mut Selection,
    ) {
        selection.start.index = self.resolve(cells, selection.start);
        selection.end.index = self.resolve(cells, selection.end);
        for index in selection.start.index.min(selection.end.index)
            ..=selection.start.index.max(selection.end.index)
        {
            let key = self.entry_key(cells, index);
            if !selection.snapshot.pinned.contains_key(&key)
                && let Some(layout) = self.layout(cells, index)
            {
                selection.snapshot.pinned.insert(key, layout);
            }
        }
    }

fn load_config_with_worktree_source_policy(
    cli_kv_overrides: Vec<(String, toml::Value)>,
    overrides: ConfigOverrides,
    loader_overrides: LoaderOverrides,
    cloud_config_bundle: CloudConfigBundleLoader,
    strict_config: bool,
    fallback_cwd: Option<PathBuf>,
    worktree: Option<&ManagedTuiWorktree>,
) -> std::io::Result<Config> {
    let config = ConfigBuilder::default()
        .cli_overrides(cli_kv_overrides.clone())
        .harness_overrides(overrides.clone())
        .loader_overrides(loader_overrides.clone())
        .strict_config(strict_config)
        .cloud_config_bundle(cloud_config_bundle.clone())
        .fallback_cwd(fallback_cwd)
        .build()
        .await
        .map_err(std::io::Error::other)?;
    if let Some(worktree) = worktree {
        worktree
            .check_source_policy(
                &cli_kv_overrides,
                &overrides,
                &loader_overrides,
                &cloud_config_bundle,
                strict_config,
            )
            .await?;
    }
    Ok(config)
}

