fn cursor_style(&self, area: Rect) -> SetCursorStyle {
        let mut y = area.y;
        for child in &self.children {
            let child_area = Rect::new(area.x, y, area.width, child.desired_height(area.width))
                .intersection(area);
            if !child_area.is_empty() && child.cursor_pos(child_area).is_some() {
                return child.cursor_style(child_area);
            }
            y += child_area.height;
        }
        SetCursorStyle::DefaultUserShape
    }

fn select_copy_range(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        index: usize,
        range: std::ops::Range<usize>,
    ) {
        let Some(layout) = self.layout(cells, index) else {
            return;
        };
        let key = self.entry_key(cells, index);
        let start = Anchor {
            key,
            index,
            offset: range.start,
            row_bias: 0,
        };
        let end = Anchor {
            offset: range.end,
            ..start
        };
        let mut snapshot = self.capture_snapshot(cells);
        snapshot.pinned.retain(|key, _| *key == EntryKey::Live);
        snapshot.pinned.insert(key, layout);
        self.selection = Some(Selection {
            pending_copy: None,
            primary_owner: None,
            snapshot,
            start,
            end,
            dragging: false,
            moved: false,
            moved_vertically: false,
            pointer_origin_row: 0,
            resume_on_empty: false,
            pointer: None,
            pressed_link: None,
            origin: (start, end),
            unit: SelectionUnit::Character,
            preferred_column: None,
        });
        self.reveal_copy_context(cells);
    }

fn running_status_summary(&self) -> Option<String> {
        let mut messages = self
            .runs
            .iter()
            .filter(|run| matches!(run.state, HookRunState::VisibleRunning { .. }))
            .map(|run| {
                run.status_message
                    .as_deref()
                    .map(str::trim)
                    .filter(|message| !message.is_empty())
            })
            .peekable();
        let message = messages.next()?;
        let multiple = messages.peek().is_some();
        Some(
            if let Some(message) = message
                && messages.all(|other| other == Some(message))
            {
                message.to_string()
            } else if multiple {
                "Running hooks".to_string()
            } else {
                "Running hook".to_string()
            },
        )
    }

