fn populate_history_at_index(
        &mut self,
        global_idx: usize,
        direction: HistorySearchDirection,
        app_event_tx: &AppEventSender,
    ) -> Option<HistoryEntry> {
        let mut global_idx = global_idx;
        loop {
            if let Some(entry) = self.entry_at_cached_offset(global_idx) {
                if global_idx < self.persistent_entry_count
                    && self.persistent_entry_duplicates_local(&entry)
                {
                    let Some(next_idx) = self.next_history_offset(global_idx, direction) else {
                        self.pending_navigation_direction = None;
                        return None;
                    };
                    self.history_cursor = Some(next_idx as isize);
                    global_idx = next_idx;
                    continue;
                }
                self.pending_navigation_direction = None;
                self.record_recalled_text(entry.text.clone());
                return Some(entry);
            }

            if global_idx >= self.persistent_entry_count {
                return None;
            }

            if let (Some(thread_id), Some(log_id)) = (self.thread_id, self.persistent_log_id) {
                self.pending_navigation_direction = Some(direction);
                app_event_tx.send(AppEvent::LookupMessageHistoryEntry {
                    thread_id,
                    offset: global_idx,
                    log_id,
                });
            }
            return None;
        }
    }

struct RuntimeChordKeymap {
    pub(crate) leader: Vec<KeyBinding>,
    pub(crate) bindings: Vec<RuntimeChordBinding>,
    configured_specs: Vec<(KeymapActionId, Vec<String>)>,
}

fn new(text: &str, lines: &[Range<usize>]) -> Self {
        let display_text = text_for_display(text);
        let hyperlinks = web_links_in_text(display_text.as_ref());
        if hyperlinks.is_empty() {
            return Self::default();
        }

        let mut source_column = 0;
        let mut previous_start = 0;
        let source_columns = lines
            .iter()
            .map(|line| {
                source_column += display_width(&display_text[previous_start..line.start]);
                previous_start = line.start;
                source_column
            })
            .collect();

        Self {
            hyperlinks,
            source_columns,
        }
    }

