fn from_config(keymap: &TuiKeymap) -> Result<Self, String> {
        let mut keymap_chords = Self::default();
        let mut leader_bindings = Vec::new();
        for action in keymap_action_ids() {
            let Some(configured) = effective_configured_binding(keymap, action) else {
                continue;
            };
            let mut configured_specs = Vec::new();
            for spec in configured.specs() {
                let raw = spec.as_str();
                if configured_specs.iter().any(|configured| configured == raw) {
                    continue;
                }
                if let Some(completion) = raw.strip_prefix("leader ") {
                    let invalid_binding = || {
                        format!(
                            "Invalid `{}` = `{raw}`. Use `leader` followed by one key, such as \
`leader c`.",
                            action.config_path()
                        )
                    };
                    leader_bindings.push((
                        action,
                        normalize_chord_binding(
                            parse_keybinding(completion).ok_or_else(invalid_binding)?,
                        ),
                        raw.to_string(),
                    ));
                } else if let Some((prefix, completion)) = raw.split_once(' ') {
                    let invalid_binding = || {
                        format!(
                            "Invalid `{}` = `{raw}`. Use a single key such as `ctrl-a` \
or a two-stroke chord such as `ctrl-x ctrl-t`.",
                            action.config_path()
                        )
                    };
                    keymap_chords.bindings.push(RuntimeChordBinding {
                        action,
                        chord: KeyChord {
                            prefix: normalize_chord_binding(
                                parse_keybinding(prefix).ok_or_else(invalid_binding)?,
                            ),
                            completion: normalize_chord_binding(
                                parse_keybinding(completion).ok_or_else(invalid_binding)?,
                            ),
                        },
                        spec: raw.to_string(),
                    });
                }
                configured_specs.push(raw.to_string());
            }
            keymap_chords
                .configured_specs
                .push((action, configured_specs));
        }

        let g = crate::key_hint::plain(KeyCode::Char('g'));
        let jump_top = KeyChord {
            prefix: g,
            completion: g,
        };
        for action in keymap_action_ids().filter(|action| {
            matches!(
                (action.context, action.action),
                (KeymapContext::VimNormal, "jump_top")
                    | (KeymapContext::VimOperator, "motion_jump_top")
            )
        }) {
            if effective_configured_binding(keymap, action).is_some()
                || keymap_chords.bindings.iter().any(|configured| {
                    action.context.overlaps(configured.action.context)
                        && configured.chord == jump_top
                })
                || keymap_action_ids()
                    .filter(|configured| action.context.overlaps(configured.context))
                    .filter_map(|configured| effective_configured_binding(keymap, configured))
                    .flat_map(KeybindingsSpec::specs)
                    .any(|spec| {
                        parse_keybinding(spec.as_str())
                            .is_some_and(|binding| binding.parts() == g.parts())
                    })
            {
                continue;
            }

            keymap_chords.bindings.push(RuntimeChordBinding {
                action,
                chord: jump_top,
                spec: "g g".to_string(),
            });
        }
        super::leader::resolve(keymap, &mut keymap_chords)?;
        let explicit_count = leader_bindings
            .len()
            .saturating_mul(keymap_chords.leader.len());
        if explicit_count > MAX_LEADER_CHORD_BINDINGS {
            return Err(format!(
                "Too many leader shortcut combinations (maximum {MAX_LEADER_CHORD_BINDINGS}). \
Reduce `tui.keymap.global.leader` alternatives or `leader ...` bindings."
            ));
        }
        for (action, completion, spec) in leader_bindings {
            for &prefix in &keymap_chords.leader {
                let chord = KeyChord { prefix, completion };
                if let Some(existing) = keymap_chords
                    .bindings
                    .iter_mut()
                    .find(|existing| existing.action == action && existing.chord == chord)
                {
                    existing.spec.clone_from(&spec);
                } else {
                    keymap_chords.bindings.push(RuntimeChordBinding {
                        action,
                        chord,
                        spec: spec.clone(),
                    });
                }
            }
        }
        Ok(keymap_chords)
    }

fn new(input: &'a str, options: Options, width: Option<usize>) -> Self {
        let mut result = Self {
            markdown: Cow::Borrowed(input),
            pending_start: None,
            display_ranges: Vec::new(),
            replacements: Vec::new(),
        };
        if !input.contains('$') && !input.contains("\\(") && !input.contains("\\[") {
            return result;
        }
        let parser = Parser::new_ext(input, options);
        let mut protected: Vec<_> = parser
            .reference_definitions()
            .iter()
            .map(|(_, def)| def.span.clone())
            .collect();
        let mut containers = Vec::new();
        protected.extend(parser.into_offset_iter().filter_map(|(event, range)| {
            if matches!(event, Event::Start(Tag::List(_) | Tag::BlockQuote)) {
                containers.push(range.clone());
            }
            matches!(
                event,
                Event::Code(_)
                    | Event::Html(_)
                    | Event::InlineHtml(_)
                    | Event::Start(Tag::CodeBlock(_) | Tag::Link { .. } | Tag::Image { .. })
            )
            .then_some(range)
        }));
        protected.sort_unstable_by_key(|range| range.start);
        let mut protected = protected.iter().peekable();
        containers.sort_unstable_by_key(|range| range.start);
        let mut containers = containers.into_iter().peekable();
        let mut offset = 0;
        let mut scanned = 0;
        let mut line_start = 0;
        let mut line_has_text = false;
        while offset < input.len() {
            if let Some(index) = input[scanned..offset].rfind('\n') {
                line_start = scanned + index + 1;
                line_has_text = false;
            }
            line_has_text |= !input[scanned.max(line_start)..offset].trim().is_empty();
            scanned = offset;
            while protected.next_if(|range| range.end <= offset).is_some() {}
            while containers.next_if(|range| range.end <= offset).is_some() {}
            if let Some(range) = protected.peek()
                && range.contains(&offset)
            {
                offset = range.end;
                continue;
            }
            let rest = &input[offset..];
            let (open, close, display) = if rest.starts_with("$$") {
                ("$$", "$$", true)
            } else if rest.starts_with("\\[") {
                ("\\[", "\\]", true)
            } else if rest.starts_with("\\(") {
                ("\\(", "\\)", false)
            } else if rest.starts_with('$') {
                ("$", "$", false)
            } else {
                let Some(ch) = rest.chars().next() else {
                    break;
                };
                offset += ch.len_utf8();
                continue;
            };
            let start = offset;
            offset += open.len();
            if escaped(input, start) {
                continue;
            }
            let body = &input[offset..];
            if open == "$"
                && (body.starts_with(char::is_whitespace) || body.starts_with(['(', '{']))
            {
                continue;
            }
            let limit = body
                .char_indices()
                .map(|(i, _)| i)
                .find(|i| *i >= MAX_MATH_BYTES)
                .unwrap_or(body.len());
            let rejected_display = display && line_has_text;
            // Only standalone displays can retain an arbitrarily distant closer.
            let search = if display && !rejected_display {
                body
            } else {
                &body[..limit]
            };
            let mut multiline_close = false;
            let mut closing_protected = protected.clone();
            let mut rejected_close = false;
            let end = search.match_indices(&close[..1]).find_map(|(index, _)| {
                let end = offset + index;
                if !search[index..].starts_with(close) || escaped(input, end) {
                    return None;
                }
                if display {
                    while closing_protected
                        .next_if(|range| range.end <= end)
                        .is_some()
                    {}
                    if closing_protected
                        .peek()
                        .is_some_and(|range| range.start < end + close.len())
                    {
                        return None;
                    }
                    if !rejected_display
                        && input[end + close.len()..]
                            .chars()
                            .take_while(|ch| *ch != '\n')
                            .any(|ch| !ch.is_whitespace())
                    {
                        if multiline_close || input[offset..end].contains('\n') {
                            multiline_close = true;
                            return None;
                        }
                        rejected_close = true;
                    }
                }
                Some(end)
            });
            if display && (!rejected_display || end.is_some() || body.len() < MAX_MATH_BYTES) {
                result
                    .display_ranges
                    .push(start..end.map_or(input.len(), |end| end + close.len()));
            }
            // Retain rejected pairing only within the lookahead window, so shell PID dollars
            // cannot keep the entire streamed response mutable in the rendering cache.
            if rejected_display || rejected_close {
                if let Some(end) = end
                    && !input[offset..end].trim().is_empty()
                {
                    // A later line's opening $$ must remain available to its own equation.
                    if rejected_display
                        && open == "$$"
                        && input[offset..end]
                            .rsplit_once('\n')
                            .is_some_and(|(_, prefix)| prefix.trim().is_empty())
                        && input[end + close.len()..]
                            .chars()
                            .take_while(|ch| *ch != '\n')
                            .any(|ch| !ch.is_whitespace())
                    {
                        continue;
                    }
                    offset = end + close.len();
                } else if end.is_none() && open == "\\[" && body.len() < MAX_MATH_BYTES {
                    break;
                }
                continue;
            }
            let Some(end) = end else {
                if display {
                    if body.len() < MAX_MATH_BYTES {
                        result.pending_start.get_or_insert(line_start);
                    }
                    let span = start..input.len();
                    result
                        .markdown
                        .to_mut()
                        .replace_range(span.clone(), &"$".repeat(span.len()));
                    result.replacements.push((span, input[start..].to_owned()));
                    break;
                }
                continue;
            };
            let span = start..end + close.len();
            let formula = &input[offset..end];
            // Every matched display owns its closer, including rejected expressions.
            if display {
                offset = span.end;
            }
            if protected.peek().is_some_and(|range| range.start < span.end) {
                continue;
            }
            if !display && formula.contains('\n') {
                continue;
            }
            if open == "$" {
                let next = input[span.end..].chars().next();
                if formula.ends_with(char::is_whitespace) || next.is_some_and(char::is_alphanumeric)
                {
                    continue;
                }
                if formula != "0"
                    && formula.starts_with(|ch: char| ch.is_ascii_digit())
                    && !formula.contains(['\\', '^', '_', '=', '+', '-', '*', '/', '<', '>'])
                    || formula.len() > 1 && formula.chars().all(|ch| ch.is_ascii_uppercase())
                {
                    offset = span.end;
                    continue;
                }
            }
            let rendered = if super::preferences::current().math && formula.len() < MAX_MATH_BYTES {
                render::render(formula, display)
            } else {
                None
            };
            let rendered = rendered
                .filter(|text| {
                    // Nested Markdown prefixes have their own width; keep spatial layouts at the top level.
                    // Never wrap a spatial layout into misleading pieces.
                    !text.contains('\n')
                        || !containers
                            .peek()
                            .is_some_and(|range| range.contains(&start))
                            && width.is_none_or(|width| {
                                text.lines().all(|line| {
                                    crate::width::display_width(line)
                                        <= width.saturating_sub(/*rhs*/ 4)
                                })
                            })
                })
                .unwrap_or_else(|| input[span.clone()].to_owned());
            // Dollars are ordinary text in the Markdown parser and cannot form an HTML tag.
            result
                .markdown
                .to_mut()
                .replace_range(span.clone(), &"$".repeat(span.len()));
            offset = span.end;
            result.replacements.push((span, rendered));
        }
        result
    }

fn voice_becomes_active_only_after_backend_and_current_peer_are_ready() {
    let (mut chat, _sender, mut events, _ops) = make_chatwidget_manual_with_sender().await;
    chat.realtime_conversation.phase = RealtimeConversationPhase::Starting;
    chat.realtime_conversation.attempt_id = 2;

    chat.on_realtime_webrtc_connected(/*attempt_id*/ 1, Ok(()));
    assert_eq!(
        chat.realtime_conversation.phase,
        RealtimeConversationPhase::Starting
    );

    chat.on_realtime_webrtc_connected(/*attempt_id*/ 2, Ok(()));
    assert_eq!(
        chat.realtime_conversation.phase,
        RealtimeConversationPhase::Starting
    );

    chat.on_realtime_conversation_started();
    assert_eq!(
        chat.realtime_conversation.phase,
        RealtimeConversationPhase::Active
    );
    commit_realtime_history_events(&mut chat, &mut events);
    let Ok(AppEvent::InsertHistoryCell(cell)) = events.try_recv() else {
        panic!("voice start should insert its history banner");
    };
    insta::assert_snapshot!(
        "voice_start_banner",
        cell.display_lines(/*width*/ 80)
            .into_iter()
            .map(|line| line.to_string())
            .collect::<Vec<_>>()
            .join("\n")
    );
}

fn voice_controls_follow_configured_mute_binding_and_unbinding() {
    let mut strip = active_strip();
    let mut layouts = Vec::new();
    for (binding, expected) in [
        ("'f8'", "f8 mute"),
        ("'ctrl-x m'", "⌃x m mute"),
        ("[]", "/voice mute"),
    ] {
        let config = toml::from_str(&format!("[chat]\ntoggle_voice_mute = {binding}")).unwrap();
        strip.state.mute_hint = crate::keymap::RuntimeKeymap::from_config(&config)
            .unwrap()
            .chat
            .voice_mute_hint();
        let (text, _) = rows(&strip, /*width*/ 80);
        assert!(text.contains(expected));
        assert!(text.contains("/voice stop"));
        for muted in [false, true] {
            strip.state.microphone_muted = muted;
            strip.state.activity = if muted { "muted" } else { "listening" };
            for width in [80, 22] {
                let (text, _) = rows(&strip, width);
                layouts.push(format!("{binding}, muted={muted}, width={width}:\n{text}"));
            }
        }
        strip.state.microphone_muted = false;
        strip.state.activity = "listening";
    }
    insta::assert_snapshot!(layouts.join("\n\n"));
}

fn maybe_probe_default_daemon_socket(codex_home: &Path) -> Option<AbsolutePathBuf> {
    let socket_path = codex_app_server_client::app_server_control_socket_path(codex_home).ok()?;
    #[cfg(windows)]
    let (validated_path, _directory) =
        codex_uds::validate_private_socket_path(socket_path.as_path()).ok()?;
    #[cfg(windows)]
    let validated_path = AbsolutePathBuf::from_absolute_path_checked(validated_path).ok()?;
    #[cfg(windows)]
    let probe_path = validated_path.as_path();
    #[cfg(not(windows))]
    let probe_path = socket_path.as_path();
    match tokio::time::timeout(
        AUTO_CONNECT_DAEMON_CONNECT_TIMEOUT,
        codex_uds::UnixStream::connect(probe_path),
    )
    .await
    {
        Ok(Ok(_stream)) => {
            #[cfg(windows)]
            _stream.ensure_non_elevated_peer().ok()?;
            Some(socket_path)
        }
        Ok(Err(err)) => {
            tracing::debug!(%err, socket_path = %socket_path.display(), "skipping default app-server daemon socket");
            None
        }
        Err(_) => {
            tracing::debug!(
                socket_path = %socket_path.display(),
                timeout_ms = AUTO_CONNECT_DAEMON_CONNECT_TIMEOUT.as_millis(),
                "timed out probing default app-server daemon socket"
            );
            None
        }
    }
}

fn take_question_drafts(&mut self) -> Option<Vec<String>> {
        let questions = self.questions.as_mut()?;
        // The question editor closes at turn end; recover its typed answer, not a history preview.
        questions.composer.cancel_history_search();
        let drafts = questions.take_pending_drafts();
        if !drafts.is_empty() && !self.composer.history_search_active() {
            self.composer.flush_pending_input();
        }
        Some(drafts)
    }

fn target_replaces_forward_and_backward_selections() {
    for (anchor, cursor) in [(1, 4), (4, 1)] {
        let mut textarea = TextArea::new();
        textarea.insert_str("abcdef");
        let area = Rect::new(
            /*x*/ 0, /*y*/ 0, /*width*/ 20, /*height*/ 2,
        );
        let mut state = TextAreaState::default();
        StatefulWidgetRef::render_ref(&&textarea, area, &mut Buffer::empty(area), &mut state);
        for (kind, column) in [
            (MouseEventKind::Down(MouseButton::Left), anchor),
            (MouseEventKind::Drag(MouseButton::Left), cursor),
        ] {
            assert!(textarea.handle_mouse(
                MouseEvent {
                    kind,
                    column,
                    row: 0,
                    modifiers: KeyModifiers::NONE
                },
                state,
            ));
        }
        let target = textarea.edit_target();
        assert_eq!(&textarea.text()[..target.start()], "a");
        textarea.insert_str_at_target(target, "界");
        assert_eq!((textarea.text(), textarea.cursor()), ("a界ef", "a界".len()));
        assert_eq!(textarea.mouse_selection_range(), None);
    }
}

fn insert_selected_file_path(&mut self, token_range: Range<usize>, selected_path: &str) {
        let started_vim_edit = self.begin_direct_vim_edit();
        let token_range = self.separate_completion_from_adjacent_element(token_range);
        if Self::is_image_path(selected_path) {
            let path_buf = PathBuf::from(selected_path);
            match image::image_dimensions(&path_buf) {
                Ok((width, height)) => {
                    tracing::debug!("selected image dimensions={}x{}", width, height);
                    let start_idx = token_range.start;
                    self.draft.textarea.replace_range(token_range, "");
                    self.draft.textarea.set_cursor(start_idx);
                    self.attach_image(path_buf);
                    self.advance_past_completion_separator();
                }
                Err(err) => {
                    tracing::trace!("image dimensions lookup failed: {err}");
                    self.insert_selected_path(token_range, selected_path);
                }
            }
        } else {
            self.insert_selected_path(token_range, selected_path);
        }
        if started_vim_edit {
            self.finish_vim_edit();
        }
    }

fn search_batch_match_preserves_cursor_for_next_older_search() {
    let (mut history, tx, mut rx) = history(/*entry_count*/ 7);
    let cursor = start_older_search(
        &mut history,
        &tx,
        &mut rx,
        "needle",
        /*newest_offset*/ 6,
    );
    let continuation = HistoryBatchCursor::new(/*end_offset*/ 2);

    assert_eq!(
        history.on_batch_response(
            /*log_id*/ 42,
            cursor,
            vec![
                batch_entry(/*offset*/ 5, "unrelated newer"),
                batch_entry(/*offset*/ 4, "needle first"),
                batch_entry(/*offset*/ 3, "unrelated older"),
            ],
            Some(continuation),
            &tx,
        ),
        Some(found("needle first"))
    );

    assert_eq!(
        history.search(
            "needle",
            HistorySearchDirection::Older,
            /*restart*/ false,
            &tx,
        ),
        HistorySearchResult::Pending
    );
    let (requested_cursor, _) = recv_batch_request(&mut rx);
    assert_eq!(requested_cursor, continuation);
    assert!(rx.try_recv().is_err());

    assert_eq!(
        history.on_batch_response(
            /*log_id*/ 42,
            continuation,
            vec![batch_entry(/*offset*/ 2, "needle second")],
            /*next_older_cursor*/ None,
            &tx,
        ),
        Some(found("needle second"))
    );
}

