fn default_daemon_auto_connect_probes_socket_only() -> color_eyre::Result<()> {
        let codex_home = TempDir::new()?;
        let socket_path =
            codex_app_server_client::app_server_control_socket_path(codex_home.path())?;
        #[cfg(windows)]
        {
            let parent = socket_path.as_path().parent().expect("socket parent");
            std::fs::create_dir_all(parent)?;
            let listener = codex_uds::UnixListener::bind(socket_path.as_path()).await?;
            assert!(
                maybe_probe_default_daemon_socket(codex_home.path())
                    .await
                    .is_none()
            );
            drop(listener);
            std::fs::remove_dir_all(parent)?;
        }
        codex_uds::prepare_private_socket_directory(
            socket_path.as_path().parent().expect("socket parent"),
        )
        .await?;
        let _listener = codex_uds::UnixListener::bind(socket_path.as_path()).await?;

        let expected = Some(socket_path);
        #[cfg(windows)]
        let expected = {
            // Existing Windows CI may run elevated; an elevated listener must
            // never be selected implicitly, even when its directory is private.
            let output = std::process::Command::new("powershell.exe")
                .args(["-NoProfile", "-NonInteractive", "-Command", "([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)"])
                .output()?;
            assert!(output.status.success());
            match String::from_utf8(output.stdout)?.trim() {
                "True" => None,
                "False" => expected,
                other => panic!("unexpected elevation result: {other}"),
            }
        };
        assert_eq!(
            maybe_probe_default_daemon_socket(codex_home.path()).await,
            expected
        );
        Ok(())
    }

fn render_hints(&self, area: Rect, buf: &mut Buffer) {
        let line1 = Rect::new(area.x, area.y, area.width, 1);
        let line2 = Rect::new(area.x, area.y.saturating_add(1), area.width, 1);
        render_navigation_hints(line1, buf, &self.view.keymap);
        let pairs: Vec<(Vec<ShortcutHint>, &str)> = vec![(
            first_or_empty(&self.view.keymap, "close", &self.view.keymap.close),
            "close",
        )];
        render_key_hints(line2, buf, &pairs);
    }

fn spawn_search(
    handle: AppServerRequestHandle,
    query: String,
    current_thread_id: ThreadId,
    cwd: PathBuf,
    generation: Arc<AtomicU64>,
    app_event_tx: AppEventSender,
) {
    let request_generation = generation.fetch_add(1, Ordering::Relaxed) + 1;
    if query.trim().is_empty() {
        app_event_tx.send(AppEvent::TaskSearchResult {
            thread_id: current_thread_id,
            query,
            matches: Vec::new(),
        });
        return;
    }

    tokio::spawn(async move {
        tokio::time::sleep(SEARCH_DEBOUNCE).await;
        if generation.load(Ordering::Relaxed) != request_generation {
            return;
        }

        let timeout = Duration::from_secs(/*secs*/ 10);
        let (response, titled_threads) = tokio::join!(
            tokio::time::timeout(
                timeout,
                handle.request_typed::<ThreadSearchResponse>(ClientRequest::ThreadSearch {
                    request_id: RequestId::String(format!("task-search-{request_generation}")),
                    params: ThreadSearchParams {
                        cursor: None,
                        limit: Some(MAX_SEARCH_RESULTS),
                        sort_key: Some(ThreadSearchSortKey::RecencyAt),
                        sort_direction: Some(SortDirection::Desc),
                        source_kinds: Some(Vec::new()),
                        archived: Some(false),
                        search_term: query.trim().to_string(),
                    },
                })
            ),
            tokio::time::timeout(
                timeout,
                handle.request_typed::<ThreadListResponse>(ClientRequest::ThreadList {
                    request_id: RequestId::String(format!(
                        "task-title-search-{request_generation}"
                    )),
                    params: ThreadListParams {
                        excluded_thread_ids: None,
                        originators: None,
                        cursor: None,
                        limit: Some(MAX_SEARCH_RESULTS),
                        sort_key: Some(ThreadSortKey::UpdatedAt),
                        sort_direction: Some(SortDirection::Desc),
                        model_providers: Some(Vec::new()),
                        source_kinds: Some(Vec::new()),
                        archived: Some(false),
                        section_id: None,
                        project_id: None,
                        cwd: None,
                        use_state_db_only: true,
                        search_term: None,
                        parent_thread_id: None,
                        ancestor_thread_id: None,
                    },
                })
            )
        );

        if generation.load(Ordering::Relaxed) != request_generation {
            return;
        }

        let response = response.ok().and_then(Result::ok);
        let titled_threads = titled_threads.ok().and_then(Result::ok);
        if response.is_none() && titled_threads.is_none() {
            return;
        }
        let mut results = response.map(|response| response.data).unwrap_or_default();
        if let Some(response) = titled_threads {
            for thread in response.data {
                if results.iter().all(|result| result.thread.id != thread.id) {
                    results.push(ThreadSearchResult {
                        thread,
                        snippet: String::new(),
                    });
                }
            }
        }
        let mut matches = results
            .into_iter()
            .filter_map(|result| {
                let thread = result.thread;
                if thread.id == current_thread_id.to_string()
                    || thread.ephemeral
                    || matches!(
                        thread.thread_source,
                        Some(ThreadSource::Feature(ref source)) if source == "ambient_suggestions"
                    )
                {
                    return None;
                }
                let title = [
                    thread.name.as_deref(),
                    Some(thread.preview.as_str()),
                    Some(thread.id.as_str()),
                ]
                .into_iter()
                .flatten()
                .map(str::trim)
                .find(|title| !title.is_empty())?
                .to_string();
                Some(TaskMention {
                    thread_id: thread.id,
                    title,
                    cwd: thread.cwd.to_string_lossy().into_owned(),
                    snippet: result.snippet,
                })
            })
            .take(MAX_SEARCH_RESULTS as usize)
            .collect::<Vec<_>>();
        let cwd = cwd.to_string_lossy();
        let windows_cwd = cwd.as_bytes().get(1) == Some(&b':') || cwd.starts_with(r"\\");
        matches.sort_by_key(|task| {
            let Some((prefix, suffix)) = task.cwd.get(..cwd.len()).zip(task.cwd.get(cwd.len()..))
            else {
                return true;
            };
            !(prefix == cwd.as_ref() || windows_cwd && prefix.eq_ignore_ascii_case(cwd.as_ref()))
                || !(suffix.is_empty() || suffix.starts_with(['/', '\\']))
        });
        app_event_tx.send(AppEvent::TaskSearchResult {
            thread_id: current_thread_id,
            query,
            matches,
        });
    });
}

fn resume_picker_loads_complete_paginated_and_legacy_transcripts()
    -> color_eyre::Result<()> {
        let temp_dir = TempDir::new()?;
        let mut config = build_config(&temp_dir).await?;
        config.terminal_resize_reflow.max_rows =
            crate::legacy_core::config::TerminalResizeReflowMaxRows::Limit(2);
        let mut app_server = AppServerSession::new(
            crate::backend_id::BackendId::new(),
            AppServerClient::InProcess(start_test_embedded_app_server(config.clone()).await?),
            ThreadParamsMode::Embedded,
        );
        let filename_ts = "2025-01-05T12-00-00";
        let rollout_line = |ordinal: usize, payload: serde_json::Value| {
            serde_json::json!({
                "timestamp": "2025-01-05T12:00:00Z",
                "type": "event_msg",
                "payload": payload,
                "ordinal": ordinal,
            })
        };
        for (history_mode, create_rollout) in [
            app_test_support::create_fake_rollout,
            app_test_support::create_fake_paginated_rollout,
        ]
        .into_iter()
        .enumerate()
        {
            let thread_id = create_rollout(
                temp_dir.path(),
                filename_ts,
                "2025-01-05T12:00:00Z",
                "message 0",
                Some(config.model_provider_id.as_str()),
                /*git_info*/ None,
            )
            .expect("create session rollout");
            let path = app_test_support::rollout_path(temp_dir.path(), filename_ts, &thread_id);
            let mut contents = std::fs::read_to_string(&path)?;
            let started = rollout_line(
                /*ordinal*/ 3,
                serde_json::json!({ "type": "task_started", "turn_id": "history-turn", "model_context_window": null }),
            );
            contents.push_str(&format!("{started}\n"));
            for index in 0..=100 {
                let message = format!("message {index}");
                let payload = if history_mode == 1 {
                    serde_json::json!({
                        "type": "item_completed",
                        "thread_id": thread_id,
                        "turn_id": "history-turn",
                        "item": { "type": "UserMessage", "id": format!("user-{index}"),
                            "content": [{ "type": "text", "text": message }] },
                    })
                } else {
                    serde_json::json!({ "type": "user_message", "message": message })
                };
                let item = rollout_line(index + 4, payload);
                contents.push_str(&format!("{item}\n"));
            }
            if history_mode == 1 {
                for index in 0..125 {
                    let item = rollout_line(
                        index + 105,
                        serde_json::json!({
                            "type": "item_completed",
                            "thread_id": thread_id,
                            "turn_id": "history-turn",
                            "item": { "type": "Reasoning", "id": format!("hidden-{index}"),
                                "summary_text": [], "raw_content": [] },
                        }),
                    );
                    contents.push_str(&format!("{item}\n"));
                }
            }
            std::fs::write(path, contents)?;
            let thread_id = ThreadId::from_string(&thread_id)?;
            let started = app_server
                .resume_thread(
                    &crate::local_settings::LocalSettings::from(&config),
                    config.clone(),
                    thread_id,
                    app_server_session::ResumeModelSettings::RestoreFromThread,
                )
                .await?;
            if history_mode == 1 {
                assert!(
                    started
                        .turns
                        .iter()
                        .flat_map(|turn| &turn.items)
                        .any(|item| {
                            matches!(
                                item,
                                codex_app_server_protocol::ThreadItem::UserMessage { .. }
                            )
                        })
                );
                let preview = crate::resume_picker::load_transcript_preview(
                    &mut app_server,
                    thread_id,
                    /*config*/ None,
                )
                .await?;
                assert!(!preview.is_empty());
            }
            let cells = crate::thread_transcript::load_session_transcript(
                &mut app_server,
                thread_id,
                crate::thread_transcript::RawReasoningVisibility::Hidden,
                /*config*/ None,
            )
            .await?;
            assert!(cells.len() > 100);
        }
        app_server.shutdown().await?;
        Ok(())
    }

