    thread.preview = "[Prompt](https://example.com/prompt)".into();
    app.agents_overview.last_messages.insert(
        thread_id,
        format!("Opened [a pull request with a label that wraps across rows]({destination}).\n\nMore context that should be clipped in a short preview.\n\nAdditional details."),
    );
    let view = app.agents_overview_view(vec![thread], Some(thread_id));
    for height in [40, 22] {
        let area =
            ratatui::layout::Rect::new(/*x*/ 0, /*y*/ 0, /*width*/ 96, height);
        let mut buffer = ratatui::buffer::Buffer::empty(area);
        view.render(area, &mut buffer);
        let mut linked_rows = Vec::new();
        for y in 0..height {
            let linked = (0..area.width)
                .map(|x| buffer[(x, y)].symbol())
                .filter(|symbol| symbol.starts_with(&format!("\x1b]8;;{destination}\x07")))
                .map(crate::terminal_hyperlinks::strip_osc8)
                .collect::<String>();
            if !linked.is_empty() {
                linked_rows.push(linked);
            }
        }
        assert!(linked_rows.len() >= 2, "link must span multiple rows");
        assert!(buffer.content.iter().all(|cell| {
            crate::terminal_hyperlinks::strip_osc8(cell.symbol()) != "…"
                || !cell.symbol().contains("\x1b]8;;")
        }));
        if height == 40 {
            insta::assert_snapshot!("agents_overview_link_rows", linked_rows.join("\n"));
            assert!(buffer.content.iter().any(|cell| {
                cell.symbol()
                    .starts_with("\x1b]8;;https://example.com/prompt\x07")
            }));
        } else {
            assert!(buffer.content.iter().any(|cell| cell.symbol() == "…"));
        }
    }
}

fn display_hyperlink_lines(&self, width: u16) -> Vec<HyperlinkLine> {
        let render_note = |text: &str| -> Vec<HyperlinkLine> {
            let wrap_width = width.saturating_sub(4).max(1) as usize;
            let note = HyperlinkLine::new(Line::from(text.to_string().dim().italic()));
            crate::terminal_hyperlinks::adaptive_wrap_hyperlink_lines(
                &[note],
                RtOptions::new(wrap_width),
            )
        };

        let render_step = |status: &StepStatus, text: &str| -> Vec<HyperlinkLine> {
            let (box_str, step_style) = match status {
                StepStatus::Completed => ("✔ ", Style::default().crossed_out().dim()),
                StepStatus::InProgress => ("□ ", Style::default().fg(accent_color()).bold()),
                StepStatus::Pending => ("□ ", Style::default().dim()),
            };

            let opts = RtOptions::new(width.saturating_sub(4).max(1) as usize)
                .initial_indent(box_str.into())
                .subsequent_indent("  ".into());
            let step = HyperlinkLine::new(Line::from(text.to_string().set_style(step_style)));
            let mut wrapped =
                crate::terminal_hyperlinks::adaptive_wrap_hyperlink_lines(&[step], opts);
            crate::terminal_hyperlinks::retain_initial_prefix(&mut wrapped, box_str);
            wrapped
        };

        let mut lines = vec![HyperlinkLine::new(
            vec!["• ".dim(), "Updated Plan".bold()].into(),
        )];

        let mut indented_lines = vec![];
        let note = self
            .explanation
            .as_ref()
            .map(|s| s.trim())
            .filter(|t| !t.is_empty());
        if let Some(expl) = note {
            indented_lines.extend(render_note(expl));
        };

        if self.plan.is_empty() {
            indented_lines.push(HyperlinkLine::new(Line::from(
                "(no steps provided)".dim().italic(),
            )));
        } else {
            for PlanItemArg { step, status } in self.plan.iter() {
                indented_lines.extend(render_step(status, step));
            }
        }
        lines.extend(prefix_hyperlink_lines(
            indented_lines,
            "  └ ".dim(),
            "    ".into(),
        ));

        lines
    }

