fn copy_selection(
        &mut self,
        event: &TuiEvent,
        copy: impl FnOnce(&str) -> Result<CopyStatus, String>,
    ) -> Option<(usize, Result<CopyStatus, String>)> {
        let copy_requested = matches!(event, TuiEvent::Key(key) if crate::text_selection::is_copy_key(*key))
            || matches!(event, TuiEvent::Mouse(mouse)
                    if mouse.kind == MouseEventKind::Down(MouseButton::Right)
                        && self.draft.textarea.contains_mouse(*mouse));
        if !copy_requested
            || !self.draft.input_enabled
            || self.history_search.is_some()
            || self.draft.textarea.vim_query().is_some()
        {
            return None;
        }
        if let Some(pasted) = self.draft.paste_burst.flush_before_modified_input() {
            self.apply_paste(pasted);
        }
        self.draft.paste_burst.clear_window_after_non_char();
        let range = self.draft.textarea.mouse_selection_range()?;
        self.end_mouse_drag();
        let text = &self.draft.textarea.text()[range];
        let char_count = text.chars().count();
        let result = copy(text);
        if let Ok(CopyStatus::Pending(id)) = result {
            self.draft.textarea.defer_copy(id);
        }
        if result == Ok(CopyStatus::Confirmed) {
            self.draft.textarea.set_cursor(self.draft.textarea.cursor());
        }
        Some((char_count, result))
    }

fn handle_vim_text_object(
        &mut self,
        op: VimOperator,
        scope: VimTextObjectScope,
        event: KeyEvent,
    ) -> bool {
        if self.vim_text_object_keymap.cancel.is_pressed(event) {
            return true;
        }
        let Some(object) = self.vim_text_object_for_event(event) else {
            return false;
        };
        match op {
            VimOperator::Delete => {
                self.start_vim_edit(VimAction::Delete(VimEditTarget::TextObject {
                    scope,
                    object,
                }));
            }
            VimOperator::Change => {
                self.start_vim_edit(VimAction::Change(VimEditTarget::TextObject {
                    scope,
                    object,
                }));
            }
            VimOperator::Yank => {
                if let Some(range) = self.text_object_range(object, scope) {
                    self.apply_vim_operator_to_range(op, range);
                }
            }
        }
        true
    }

