        ExecCall {
            call_id: "copy-test".into(),
            command: vec!["bash".into(), "-lc".into(), command.into()],
            parsed: Vec::new(),
            output: Some(CommandOutput::new(/*exit_code*/ 0, output.into())),
            source: codex_app_server_protocol::CommandExecutionSource::Agent,
