fn reveal_copy_context(&mut self, cells: &[Arc<dyn HistoryCell>]) {
        if self.copy_mode.is_none() {
            return;
        }
        let Some(selection) = &self.selection else {
            return;
        };
        let (start, end) = (selection.start, selection.end);
        let index = self.resolve(cells, start);
        let Some(layout) = self.layout(cells, index) else {
            return;
        };
        let first = layout.row_for_offset(start.offset);
        // Match block painting: whole-entry highlights include final padding.
        let finish = if start.offset == 0 && end.offset == layout.text().len() {
            end.offset
        } else {
            end.offset.saturating_sub(/*rhs*/ 1)
        };
        let last = layout.row_for_offset(finish);
        let height = usize::from(self.area.height);
        if height == 0 {
            return;
        }
        let target_height = last.saturating_sub(first) + 1;
        // Reserve a quarter of the viewport, reducing the margin for taller targets.
        let margin = (height / 4)
            .max(1)
            .min(height.saturating_sub(target_height) / 2);
        let bottom_margin = (height / 4)
            .max(1)
            .min(height.saturating_sub(target_height).div_ceil(2));
        let top = self.start(cells);
        let inner_top = self.move_rows(cells, top.0, top.1, margin as isize);
        let inner_bottom = self.move_rows(
            cells,
            top.0,
            top.1,
            height.saturating_sub(bottom_margin + 1) as isize,
        );
        if target_height < height && (index, first) >= inner_top && (index, last) <= inner_bottom {
            return;
        }
        let inset = if target_height >= height {
            height / 4
        } else if (index, first) < inner_top {
            margin
        } else {
            height - bottom_margin - target_height
        };
        let (index, row) = self.move_rows(cells, index, first, -(inset as isize));
        if let Some(layout) = self.layout(cells, index) {
            let offset = layout.position_at(row, /*column*/ 0);
            self.position = Position::Reading(Anchor {
                key: self.entry_key(cells, index),
                index,
                offset,
                row_bias: layout.row_for_offset(offset) as isize - row as isize,
            });
        }
    }

fn task_reference_context_deduplicates_and_merges_with_ide_context() {
    let title = "Review the migration";
    let visible = format!("Compare plain @{title} with plugin @{title} and selected @{title}x");
    let binding = MentionBinding {
        sigil: '@',
        mention: title.to_string(),
        path: "thread://task-123".to_string(),
    };
    let text = format!("# IDE: @{title}\n## My request for Codex:\n{visible}");
    let plugin_start = text.find("plugin @").expect("plugin mention") + "plugin ".len();
    let selected_start = text.rfind(&format!("@{title}")).expect("selected task");
    let mut items = vec![UserInput::Text {
        text,
        text_elements: [plugin_start, selected_start]
            .into_iter()
            .map(|start| {
                codex_app_server_protocol::TextElement::new(
                    ByteRange {
                        start,
                        end: start + title.len() + 1,
                    },
                    Some(format!("@{title}")),
                )
            })
            .collect(),
    }];

    apply_task_references(
        &mut items,
        &[
            MentionBinding {
                sigil: '@',
                mention: title.to_string(),
                path: "plugin://sample@test".to_string(),
            },
            binding.clone(),
            binding,
        ],
        /*current_thread_id*/ None,
    );

    let [UserInput::Text { text, .. }] = items.as_slice() else {
        panic!("expected text with deduplicated task references");
    };
    assert!(text.starts_with("# IDE: @Review the migration\n## Referenced chats"));
    assert_eq!(text.matches("## My request for Codex:").count(), 1);
    assert_eq!(text.matches("\"threadId\":\"task-123\"").count(), 1);
    assert!(text.contains("MUST call `read_thread`"));
    assert!(text.ends_with(
        "Compare plain @Review the migration with plugin @Review the migration and selected [@Review the migration](thread://task-123)x"
    ));

    for id_len in [36, 64] {
        let bindings = (0..MAX_REFERENCED_TASKS)
            .map(|index| MentionBinding {
                sigil: '@',
                mention: "task".to_string(),
                path: format!("thread://{index:0id_len$}"),
            })
            .collect::<Vec<_>>();
        let mut items = [UserInput::Text {
            text: String::new(),
            text_elements: Vec::new(),
        }];
        apply_task_references(&mut items, &bindings, /*current_thread_id*/ None);
        let UserInput::Text { text, .. } = &items[0] else {
            unreachable!();
        };
        assert_eq!(
            text.matches("\"threadId\":").count(),
            MAX_REFERENCED_TASKS.min(MAX_REFERENCED_THREAD_ID_BYTES / id_len)
        );
    }
}

