fn build_theme_picker_params(
    current_name: Option<&str>,
    codex_home: Option<&Path>,
    terminal_width: Option<u16>,
) -> SelectionViewParams {
    // Snapshot the current theme so we can restore on cancel.
    let original_theme = highlight::current_syntax_theme();

    let entries = highlight::list_available_themes(codex_home);
    let codex_home_owned = codex_home.map(Path::to_path_buf);

    // Resolve the effective theme name: honor explicit config only when it is
    // currently available; otherwise fall back to configured/default selection
    // so opening `/theme` does not auto-preview an unrelated first entry.
    let effective_name = if let Some(name) = current_name
        && entries.iter().any(|entry| entry.name == name)
    {
        name.to_string()
    } else {
        highlight::configured_theme_name()
    };

    // Track the index of the current theme so we can preselect it.
    let mut initial_idx = None;

    let items: Vec<SelectionItem> = entries
        .iter()
        .enumerate()
        .map(|(idx, entry)| {
            let display_name = if entry.is_custom {
                format!("{} (custom)", entry.name)
            } else {
                entry.name.clone()
            };
            let is_current = entry.name == effective_name;
            if is_current {
                initial_idx = Some(idx);
            }
            let name_for_action = entry.name.clone();
            SelectionItem {
                name: display_name,
                is_current,
                dismiss_on_select: true,
                search_value: Some(entry.name.clone()),
                actions: vec![Box::new(move |tx| {
                    tx.send(AppEvent::SyntaxThemeSelected {
                        name: name_for_action.clone(),
                    });
                })],
                ..Default::default()
            }
        })
        .collect();

    // Derive preview targets from the final `items` list (not from `entries`)
    // so preview ordering stays aligned if item construction/sorting changes.
    let preview_theme_names: Vec<Option<String>> =
        items.iter().map(|item| item.search_value.clone()).collect();
    let preview_home = codex_home_owned.clone();
    let on_selection_changed = Some(Box::new(
        move |idx: usize, tx: &crate::app_event_sender::AppEventSender| {
            if let Some(Some(name)) = preview_theme_names.get(idx)
                && let Some(theme) = highlight::resolve_theme_by_name(name, preview_home.as_deref())
            {
                highlight::set_syntax_theme(theme);
                tx.send(AppEvent::SyntaxThemePreviewed);
            }
        },
    )
        as Box<dyn Fn(usize, &crate::app_event_sender::AppEventSender) + Send + Sync>);

    // Restore original theme on cancel.
    let on_cancel = Some(
        Box::new(move |tx: &crate::app_event_sender::AppEventSender| {
            highlight::set_syntax_theme(original_theme.clone());
            tx.send(AppEvent::SyntaxThemePreviewed);
        }) as Box<dyn Fn(&crate::app_event_sender::AppEventSender) + Send + Sync>,
    );
    SelectionViewParams {
        allow_input_when_disconnected: true,
        title: Some("Select Syntax Theme".to_string()),
        subtitle: Some(theme_picker_subtitle(
            codex_home_owned.as_deref(),
            terminal_width,
        )),
        footer_hint: Some(standard_popup_hint_line()),
        items,
        is_searchable: true,
        search_placeholder: Some("Type to filter themes...".to_string()),
        initial_selected_idx: initial_idx,
        side_content: Box::new(ThemePreviewWideRenderable),
        side_content_width: SideContentWidth::Half,
        side_content_min_width: WIDE_PREVIEW_MIN_WIDTH,
        stacked_side_content: Some(Box::new(ThemePreviewNarrowRenderable)),
        preserve_side_content_bg: true,
        on_selection_changed,
        on_cancel,
        ..SelectionViewParams::picker()
    }
}

fn keys(textarea: &mut TextArea, keys: &str) {
    let keymap = RuntimeKeymap::defaults();
    let mut matcher = KeyChordMatcher::default();
    for key in keys.chars() {
        let code = match key {
            '\n' => KeyCode::Enter,
            '\x1b' => KeyCode::Esc,
            ch => KeyCode::Char(ch),
        };
        let event = KeyEvent::new(code, KeyModifiers::NONE);
        match matcher.advance(event, &keymap.chords, textarea.keymap_contexts()) {
            KeyChordMatch::PassThrough => textarea.input(event),
            KeyChordMatch::Completed(event) => textarea.input(event),
            KeyChordMatch::Pending(_) | KeyChordMatch::Cancelled | KeyChordMatch::Ignored => {}
        }
    }
}

fn handle_vim_pending_command(&mut self, pending: VimPending, event: KeyEvent) {
        match pending {
            VimPending::Replace => {
                if let Some(ch) = vim_command_char(event)
                    && !(self.single_line && matches!(ch, '\r' | '\n'))
                {
                    self.start_vim_edit(VimAction::Replace(ch));
                }
            }
            VimPending::Find { motion, operator } => {
                if let Some(ch) = vim_command_char(event) {
                    match operator {
                        Some(VimOperator::Delete) => {
                            self.start_vim_edit(VimAction::Delete(VimEditTarget::Find {
                                motion,
                                target: ch,
                            }));
                        }
                        Some(VimOperator::Change) => {
                            self.start_vim_edit(VimAction::Change(VimEditTarget::Find {
                                motion,
                                target: ch,
                            }));
                        }
                        Some(VimOperator::Yank) | None => {
                            self.find_vim_character(motion, operator, ch);
                        }
                    }
                }
            }
            VimPending::None | VimPending::Operator(_) | VimPending::TextObject { .. } => {}
        }
    }

fn capture_view() -> (KeymapCaptureView, UnboundedReceiver<AppEvent>) {
    let (tx, rx) = unbounded_channel();
    let view = KeymapCaptureView::new(
        "list".to_string(),
        "jump_top".to_string(),
        KeymapEditIntent::AddAlternate,
        KeymapCaptureMode::Chord,
        "Jump Top".to_string(),
        "home".to_string(),
        AppEventSender::new(tx),
    );
    (view, rx)
}

struct AppKeymap {
    /// Open the daemon-wide agent-session overview.
    pub(crate) open_agents: Vec<KeyBinding>,
    /// Open transcript overlay.
    pub(crate) open_transcript: Vec<KeyBinding>,
    /// Find text in the full transcript.
    pub(crate) find_transcript: Vec<KeyBinding>,
    /// Focus activity groups in the owned transcript to inspect their details.
    pub(crate) focus_activity: Vec<KeyBinding>,
    /// Open retained warnings without replacing the composer.
    pub(crate) open_warnings: Vec<KeyBinding>,
    /// Open external editor for the current draft.
    pub(crate) open_external_editor: Vec<KeyBinding>,
    /// Copy the last agent response to the clipboard.
    pub(crate) copy: Vec<KeyBinding>,
    /// Clear the terminal UI.
    pub(crate) clear_terminal: Vec<KeyBinding>,
    /// Toggle Vim mode for the composer input.
    pub(crate) toggle_vim_mode: Vec<KeyBinding>,
    /// Toggle Fast mode.
    pub(crate) toggle_fast_mode: Vec<KeyBinding>,
    /// Toggle raw scrollback mode for copy-friendly transcript selection.
    pub(crate) toggle_raw_output: Vec<KeyBinding>,
    /// Switch between a side conversation and its parent without closing either.
    pub(crate) toggle_side_conversation: Vec<KeyBinding>,
}

fn handle_tui_event(
        &mut self,
        tui: &mut tui::Tui,
        app_server: &mut AppServerSession,
        event: TuiEvent,
    ) -> Result<AppRunControl> {
        tui.link_hover.observe(&event);
        self.refresh_link_hover(tui)?;
        self.invalidate_right_click_paste(&event);
        self.finish_clipboard(tui, &event);
        let event = self.finish_right_click_paste(tui, event);
        if self.startup_protected_input_boundary
            && self.startup_pending_protected_request
            && self.chat_widget.has_active_modal()
            && matches!(
                &event,
                TuiEvent::Key(_) | TuiEvent::Paste(_) | TuiEvent::Mouse(_)
            )
        {
            self.discard_startup_modal_input(tui)?;
            return Ok(AppRunControl::Continue);
        }
        if matches!(&event, TuiEvent::Key(key) if key.kind != KeyEventKind::Release)
            || matches!(&event, TuiEvent::Paste(text) if !text.is_empty())
            || matches!(&event, TuiEvent::Mouse(mouse) if mouse.kind != crossterm::event::MouseEventKind::Moved)
        {
            self.chat_widget.acknowledge_program_status();
        }
        let idle_draw = matches!(event, TuiEvent::Draw);
        if self.handle_rendered_selection_event(tui, &event)? {
            return Ok(AppRunControl::Continue);
        }
        if matches!(&event, TuiEvent::Key(_))
            && self.handle_composer_copy_event(tui, &event, |tui, text| {
                tui.copy_transcript_selection(text, crate::clipboard_copy::CopyFormat::PlainText)
            })
        {
            return Ok(AppRunControl::Continue);
        }
        // Resume arrives after suspension; retain the last painted phase across hidden owners.
        if matches!(&event, TuiEvent::Resume) || !tui.is_owned_screen() || self.overlay.is_some() {
            self.chat_widget
                .empty_state_animation
                .borrow_mut()
                .pause_clock();
        }
        let transcript_owns_input = match (&event, &self.overlay) {
            (TuiEvent::Key(key), Some(Overlay::Transcript(overlay))) => {
                overlay.owns_interaction_key(*key)
            }
            (TuiEvent::Key(key), None) => {
                tui.is_owned_screen()
                    && self.chat_widget.no_modal_or_popup_active()
                    && self.transcript_view.owns_interaction_key(*key)
            }
            _ => false,
        };
        if self.reconnect.offline
            && !transcript_owns_input
            && !self.chat_widget.keymap_contexts().is_warnings()
            && !self
                .chat_widget
                .active_view_accepts_input_when_disconnected()
            && let TuiEvent::Key(key) = &event
            && matches!(key.kind, KeyEventKind::Press | KeyEventKind::Repeat)
            && key.modifiers.contains(KeyModifiers::CONTROL)
            && let KeyCode::Char(character) = key.code
            && (character.eq_ignore_ascii_case(&'c')
                || (character.eq_ignore_ascii_case(&'d')
                    && self.chat_widget.composer_is_empty()
                    && self.chat_widget.no_modal_or_popup_active()))
        {
            return Ok(AppRunControl::Exit(ExitReason::UserRequested));
        }
        let screen_size = tui.screen_size_for_event(&event)?;
        if !matches!(
            &event,
            TuiEvent::Key(_) | TuiEvent::Mouse(_) | TuiEvent::Paste(_) | TuiEvent::FocusLost
        ) {
            self.expire_pending_key_chord();
            self.handle_draw_pre_render(tui, screen_size)?;
        }

        if matches!(&event, TuiEvent::Paste(_) | TuiEvent::FocusLost)
            || matches!(&event, TuiEvent::Mouse(mouse) if mouse.kind != crossterm::event::MouseEventKind::Moved)
        {
            self.cancel_pending_key_chord();
        }
        if matches!(&event, TuiEvent::FocusLost)
            || matches!(&event, TuiEvent::Mouse(mouse) if mouse.kind != crossterm::event::MouseEventKind::Moved)
        {
            self.chat_widget.interrupt_config_editor_transition();
        }

        if self.overlay.is_none()
            && self
                .chat_widget
                .handle_warning_event(&event, &self.transcript_cells)
        {
            self.cancel_primed_browsing_for_event(&event);
            return Ok(AppRunControl::Continue);
        }

        let mut event = if let TuiEvent::Key(mut key_event) = event {
            let escape = KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE);
            if self.should_recover_vim_insert_escape(key_event)
                && !(tui.is_owned_screen()
                    && crate::transcript_view::JumpTarget::from_key(key_event).is_some())
            {
                // Restore both strokes before chords or global shortcuts can consume them.
                if let Some(escape) = self.route_key_chord_event(tui, escape) {
                    self.handle_key_event(tui, app_server, escape).await;
                }
                key_event.modifiers.remove(KeyModifiers::ALT);
            }

            let Some(key_event) = self.route_key_chord_event(tui, key_event) else {
                return Ok(AppRunControl::Continue);
            };
            TuiEvent::Key(key_event)
        } else {
            event
        };

        self.cancel_primed_browsing_for_event(&event);
        let voice_toggle = |app: &Self, key: KeyEvent| {
            key.kind == KeyEventKind::Press
                && app
                    .active_keymap_contexts()
                    .contains_action(crate::keymap::KeymapActionId {
                        context: crate::keymap::KeymapContext::Chat,
                        action: "toggle_voice",
                    })
                && app.keymap.chat.toggle_voice.is_pressed(key)
        };
        // Find consumes otherwise-unhandled keys; let enabled voice controls reach App.
        if !matches!(&event, TuiEvent::Key(key)
            if voice_toggle(self, *key) && !self.transcript_view.owns_interaction_key(*key))
            && self.handle_owned_transcript_event(tui, app_server, &event)?
        {
            return Ok(AppRunControl::Continue);
        }
        // Leave browsing before unhandled editing input reaches shortcuts or offline input.
        // Offline Enter cannot confirm a rewind and leaves the preview available to read.
        if tui.is_owned_screen()
            && self.overlay.is_none()
            && self.backtrack.overlay_preview_active
            && (matches!(&event, TuiEvent::Key(key)
                if matches!(key.kind, KeyEventKind::Press | KeyEventKind::Repeat)
                    && !(self.reconnect.offline && key.code == KeyCode::Enter))
                || matches!(&event, TuiEvent::Paste(text) if !text.is_empty()))
        {
            self.cancel_transcript_browsing(tui);
            // The first lookup used browsing contexts; retry after restoring composer contexts.
            // Completed chords already identify an action and must not be matched again.
            if let TuiEvent::Key(key) = event
                && !crate::keymap::is_dispatch_token_event(key)
            {
                let Some(key) = self.route_key_chord_event(tui, key) else {
                    return Ok(AppRunControl::Continue);
                };
                event = TuiEvent::Key(key);
            }
        }
        if let TuiEvent::Key(key_event) = &event
            && voice_toggle(self, *key_event)
        {
            self.cancel_transcript_browsing(tui);
            if !self.chat_widget.handle_startup_submission_key(*key_event) {
                self.control_voice(crate::app_event::VoiceControl::Toggle);
            }
            return Ok(AppRunControl::Continue);
        }
        if let TuiEvent::Key(key_event) = &event
            && key_event.kind == KeyEventKind::Press
            && self
                .active_keymap_contexts()
                .contains(crate::keymap::KeymapContext::Voice)
            && self.keymap.chat.toggle_voice_mute.is_pressed(*key_event)
        {
            if !self.chat_widget.handle_startup_submission_key(*key_event) {
                self.control_voice(crate::app_event::VoiceControl::Mute);
            }
            return Ok(AppRunControl::Continue);
        }
        if self.reconnect.offline
            && !self.chat_widget.keymap_contexts().is_warnings()
            && !matches!(&self.overlay, Some(Overlay::Transcript(_)))
            && let TuiEvent::Key(key) = &event
            && !(self.overlay.is_none()
                && self.chat_widget.no_modal_or_popup_active()
                && self.keymap.app.open_warnings.is_pressed(*key))
        {
            if self.overlay.is_none()
                && self.chat_widget.no_modal_or_popup_active()
                && self.chat_widget.is_external_writer_view()
                && (crate::key_hint::plain(KeyCode::Esc).is_press(*key)
                    || (crate::key_hint::plain(KeyCode::Left).is_press(*key)
                        && self.chat_widget.agents_navigation_key_available()))
            {
                self.open_agents_overview(app_server);
            } else if self
                .chat_widget
                .active_view_accepts_input_when_disconnected()
                || (self.reconnect.presentation == reconnect::ReconnectPresentation::Overview
                    && self
                        .chat_widget
                        .active_view_is(agents_overview::AGENTS_OVERVIEW_VIEW_ID))
            {
                let activation_key = self.routed_key_activation.take();
                self.chat_widget
                    .handle_disconnected_view_key(*key, activation_key);
                if self.reconnect.presentation == reconnect::ReconnectPresentation::Overview
                    && self
                        .chat_widget
                        .selected_index_for_present_view(agents_overview::AGENTS_OVERVIEW_VIEW_ID)
                        .is_none()
                {
                    self.reconnect.presentation = reconnect::ReconnectPresentation::Conversation;
                }
            } else {
                if self.reconnect.presentation == reconnect::ReconnectPresentation::Overview {
                    self.reconnect.presentation = reconnect::ReconnectPresentation::Conversation;
                }
                self.chat_widget
                    .handle_restricted_key(*key, RestrictedInputMode::Disconnected);
            }
            return Ok(AppRunControl::Continue);
        }

        match &event {
            TuiEvent::FocusLost => {
                self.chat_widget
                    .set_sparkle_terminal_focus(/*focused*/ false);
                let now = Instant::now();
                let thread_id = self.current_displayed_thread_id();

                self.recap.note_focus_lost(now);

                if let Some(thread_id) = thread_id {
                    self.schedule_recap_check(thread_id, now);
                }
            }
            TuiEvent::FocusGained => {
                self.recap.note_focus_gained();
            }
            _ => {}
        }

        if self.overlay.is_some() {
            let _ = self
                .handle_backtrack_overlay_event(tui, app_server, event)
                .await?;
        } else {
            match event {
                TuiEvent::Key(key_event) => {
                    self.handle_key_event(tui, app_server, key_event).await;
                }
                TuiEvent::Paste(pasted) => {
                    // Pasted text may contain CRLF pairs or bare CRs (e.g., from iTerm2),
                    // but tui-textarea expects LF. Normalize CRLF pairs before bare CRs so
                    // each pasted line break becomes one LF and existing LFs stay unchanged.
                    // [tui-textarea]: https://github.com/rhysd/tui-textarea/blob/4d18622eeac13b309e0ff6a55a46ac6706da68cf/src/textarea.rs#L782-L783
                    // [iTerm2]: https://github.com/gnachman/iTerm2/blob/5d0c0d9f68523cbd0494dad5422998964a2ecd8d/sources/iTermPasteHelper.m#L206-L216
                    let pasted = pasted.replace("\r\n", "\n").replace('\r', "\n");
                    if self.backtrack.primed && !pasted.is_empty() {
                        if self.backtrack.overlay_preview_active {
                            self.cancel_transcript_browsing(tui);
                        } else {
                            self.reset_backtrack_state();
                        }
                    }
                    let restrict_disconnected_input = self.reconnect.offline
                        && !self.chat_widget.keymap_contexts().is_warnings()
                        && self.reconnect.presentation
                            == reconnect::ReconnectPresentation::Conversation
                        && !self
                            .chat_widget
                            .active_view_accepts_input_when_disconnected();
                    self.chat_widget.handle_paste(pasted);
                    if restrict_disconnected_input {
                        self.chat_widget.handle_restricted_key(
                            KeyEvent::new(KeyCode::Null, KeyModifiers::NONE),
                            RestrictedInputMode::Disconnected,
                        );
                    }
                }
                TuiEvent::Draw | TuiEvent::Resume | TuiEvent::Resize(_) | TuiEvent::FocusGained => {
                    if self.backtrack_render_pending && !tui.is_owned_screen() {
                        self.rebuild_transcript_after_backtrack(tui, screen_size.into())?;
                        self.backtrack_render_pending = false;
                    }
                    self.chat_widget.maybe_post_pending_notification(tui);
                    if self
                        .chat_widget
                        .handle_paste_burst_tick(tui.frame_requester())
                    {
                        tui.defer_screen_size(screen_size);
                        return Ok(AppRunControl::Continue);
                    }
                    // Allow widgets to process any pending timers before rendering.
                    let had_active_modal = self.chat_widget.has_active_modal();
                    if let Some(owner) = self.background_voice.as_mut() {
                        owner.refresh_realtime_microphone_level();
                    }
                    self.chat_widget.pre_draw_tick();
                    self.refresh_agents_overview_usage(app_server, tui.frame_requester());
                    let rendered_area = self.render_chat_widget_frame(tui, screen_size)?;
                    if tui.is_owned_screen()
                        && self.transcript_view.history
                            != crate::pager_overlay::TranscriptHistoryState::Failed
                    {
                        self.request_owned_history(tui, app_server);
                    }
                    if !had_active_modal
                        && self.chat_widget.has_active_modal()
                        && self.startup_protected_input_boundary
                    {
                        self.discard_startup_modal_input(tui)?;
                    }
                    if self.chat_widget.ambient_pet_image_enabled() {
                        let ambient_pet_area = Rect::new(
                            /*x*/ 0,
                            /*y*/ 0,
                            screen_size.width,
                            screen_size.height,
                        );
                        if let Err(err) = tui.draw_ambient_pet_image(
                            self.chat_widget
                                .ambient_pet_draw(ambient_pet_area, rendered_area.bottom()),
                        ) {
                            self.handle_ambient_pet_image_render_error(tui, err)?;
                        }
                    }
                    if let Some(request) = self.chat_widget.pet_picker_preview_draw() {
                        if let Err(err) = tui.draw_pet_picker_preview_image(Some(request)) {
                            self.handle_pet_picker_preview_image_render_error(tui, err)?;
                        }
                    } else if self.chat_widget.should_clear_pet_picker_preview_image()
                        && let Err(err) = tui.draw_pet_picker_preview_image(/*request*/ None)
                    {
                        self.handle_pet_picker_preview_image_render_error(tui, err)?;
                    }
                    if self.chat_widget.external_editor_state() == ExternalEditorState::Requested {
                        self.chat_widget
                            .set_external_editor_state(ExternalEditorState::Active);
                        self.app_event_tx.send(AppEvent::LaunchExternalEditor);
                    }
                }
                TuiEvent::Mouse(mouse) => self.start_right_click_paste(tui, mouse),
                TuiEvent::FocusLost => {}
            }
        }
        // Both transcript owners must consume completions before automatic work advances.
        if idle_draw {
            tui.clipboard.advance(tui.frame_requester());
        }
        Ok(AppRunControl::Continue)
    }

fn failed_patch_keeps_diagnostics_beyond_the_legacy_preview() {
    let diagnostics = (1..=12)
        .map(|line| format!("diagnostic line {line}"))
        .collect::<Vec<_>>()
        .join("\n");
    let cell = new_patch_apply_failure(diagnostics.clone());
    assert_eq!(
        cell.raw_lines(),
        std::iter::once(Line::from("Failed to apply patch"))
            .chain(diagnostics.lines().map(|line| Line::from(line.to_owned())))
            .collect::<Vec<_>>()
    );
}

fn live_center_keeps_status_order_across_progress_refreshes() {
    let mut app = make_test_app().await;
    app.agents_overview.view_state.lock().unwrap().grouping = AgentsOverviewGrouping::Status;
    let ids = [1, 2, 3, 4, 5].map(ThreadId::from_u128);
    let mut threads = [
        (
            "Alpha",
            ThreadStatus::Active {
                active_flags: vec![],
            },
            10,
        ),
        (
            "Bravo",
            ThreadStatus::Active {
                active_flags: vec![],
            },
            20,
        ),
        (
            "Charlie",
            ThreadStatus::Active {
                active_flags: vec![],
            },
            20,
        ),
        ("Ready task", ThreadStatus::Idle, 40),
        ("Needs input", ThreadStatus::SystemError, 0),
    ]
    .into_iter()
    .zip(ids)
    .map(|((name, status, updated_at), id)| {
        let mut thread = overview_thread(id, /*parent_thread_id*/ None, name, status);
        // Future timestamps render as "now", keeping the visual fixture clock-independent.
        thread.updated_at = 4_000_000_000 + updated_at;
        thread
    })
    .collect::<Vec<_>>();
    threads.reverse();
    let view = app.agents_overview_view(threads.clone(), Some(ids[0]));
    let expected = vec![ids[4], ids[1], ids[2], ids[0], ids[3]];
    assert_eq!(view.thread_ids(), expected);
    let before = screen(&view, /*width*/ 100, /*height*/ 18);
    app.agents_overview.visible_thread_ids = view.thread_ids();
    app.chat_widget.show_bottom_pane_view(Box::new(view));

    for (step, id) in [ids[0], ids[2], ids[1], ids[0]].into_iter().enumerate() {
        let thread = threads
            .iter_mut()
            .find(|thread| thread.id == id.to_string())
            .unwrap();
        thread.updated_at = 4_000_000_100 + step as i64;
        thread.preview = format!("Progress update {step}");
        threads.rotate_left(/*mid*/ 1);
        app.agents_overview.threads = threads
            .iter()
            .cloned()
            .map(|thread| (ThreadId::from_string(&thread.id).unwrap(), Some(thread)))
            .collect();
        app.repaint_agents_overview();
        assert_eq!(app.agents_overview.visible_thread_ids, expected);
        let selected = app
            .chat_widget
            .selected_index_for_present_view(AGENTS_OVERVIEW_VIEW_ID)
            .unwrap();
        assert_eq!(app.agents_overview.visible_thread_ids[selected], ids[0]);
    }
    let view = app.agents_overview_view(threads, Some(ids[0]));
    let after = screen(&view, /*width*/ 100, /*height*/ 18);
    insta::assert_snapshot!(format!(
        "Initial display:\n{before}\n\nAfter progress updates:\n{after}"
    ));
}

fn halfwidth_sound_marks_wrap_and_align_with_the_cursor() {
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut snapshots = Vec::new();
        for (label, text, width, height, cursor, cells) in [
            ("dakuten", "12ｶﾞx", 4, 2, (1, 1), [(2, 0, "ｶﾞ"), (0, 1, "x")]),
            (
                "handakuten",
                "abﾊﾟc",
                3,
                3,
                (0, 2),
                [(0, 1, "ﾊﾟ"), (2, 1, "c")],
            ),
            ("standalone", "a ﾞb", 2, 3, (0, 2), [(0, 1, "ﾞ"), (1, 1, "b")]),
        ] {
            let mut t = ta_with(text);
            t.set_cursor(text.len());
            let area = Rect::new(0, 0, width, height);
            let mut terminal = Terminal::new(TestBackend::new(area.width, area.height)).unwrap();
            terminal
                .draw(|frame| {
                    ratatui::widgets::WidgetRef::render_ref(
                        &(&t),
                        frame.area(),
                        frame.buffer_mut(),
                    );
                })
                .unwrap();

            assert_eq!(t.desired_height(area.width), height);
            assert_eq!(t.cursor_pos(area), Some(cursor));
            for (x, y, expected) in cells {
                assert_eq!(terminal.backend().buffer()[(x, y)].symbol(), expected);
            }
            snapshots.push(format!(
                "{label}\ncursor: {:?}\n{}",
                t.cursor_pos(area),
                terminal.backend()
            ));
        }

        insta::assert_snapshot!(
            "textarea_halfwidth_sound_marks_wrap_and_align_with_cursor",
            snapshots.join("\n\n")
        );
    }

fn on_history_entry_response(
        &mut self,
        log_id: u64,
        offset: usize,
        entry: Option<String>,
    ) -> bool {
        match self
            .history
            .on_entry_response(log_id, offset, entry, &self.app_event_tx)
        {
            HistoryEntryResponse::Found(entry) => {
                // Persistent ↑/↓ history is text-only (backwards-compatible and avoids persisting
                // attachments), but local in-session ↑/↓ history can rehydrate elements and image paths.
                self.apply_history_entry(entry);
                true
            }
            HistoryEntryResponse::Search(result) => {
                self.apply_history_search_result(result);
                true
            }
            HistoryEntryResponse::Ignored => false,
        }
    }

fn status_line_segments_soften_rgb_theme_styles_without_dimming_text() {
        let colors = crate::terminal_probe::DefaultColors {
            fg: (255, 255, 255),
            bg: (0, 0, 0),
        };
        crate::terminal_palette::with_test_default_colors(colors, || {
            let line = status_line_from_segments_with_resolver(
                [(StatusLineItem::ModelName, "gpt-5".to_string())],
                /*use_theme_colors*/ true,
                /*thread_id*/ None,
                |_| Some(Style::default().fg(Color::Rgb(255, 0, 0))),
