fn vim_redo_keeps_its_binding_when_history_is_empty() {
    let mut composer = vim_composer("abc");
    let before = composer.draft_snapshot();
    ctrl_r(&mut composer);
    assert_eq!(composer.draft_snapshot(), before);
    assert!(!composer.history_search_active());
    keys(&mut composer, "xu");
    assert_eq!(composer.current_text(), "abc");
    ctrl_r(&mut composer);
    assert_eq!(composer.current_text(), "bc");
    assert!(!composer.history_search_active());
    let after = composer.draft_snapshot();
    ctrl_r(&mut composer);
    assert_eq!(composer.draft_snapshot(), after);
    assert!(composer.draft.textarea.is_vim_normal_mode());
    assert!(!composer.history_search_active());
    super::super::tests::snapshot_composer_state_with_width(
        "vim_empty_redo_stays_normal",
        /*width*/ 60,
        /*enhanced_keys_supported*/ true,
        |target| *target = composer,
    );

    let original = "a".repeat(super::MAX_VIM_UNDO_BYTES / 2 + 1);
    let mut composer = vim_composer(&original);
    keys(&mut composer, "xu");
    for command in ["d", "i"] {
        keys(&mut composer, command);
        escape(&mut composer);
        assert_eq!(composer.vim_history.redo.len(), 1);
    }
    ctrl_r(&mut composer);
    assert_eq!(composer.current_text(), original[1..]);
    assert!(!composer.history_search_active());

    keys(&mut composer, "uiZ");
    escape(&mut composer);
    assert!(composer.vim_history.redo.is_empty());
    keys(&mut composer, "x");
    assert_eq!(composer.vim_history.undo.len(), 1);
    keys(&mut composer, "u");
    assert_eq!(composer.current_text(), format!("Z{original}"));
}

fn handle_history_search_key(&mut self, key_event: KeyEvent) -> (InputResult, bool) {
        if key_event.kind == KeyEventKind::Release {
            return (InputResult::None, false);
        }

        if Self::is_history_search_key(&key_event, &self.history_search_previous_keys)
            || matches!(key_event.code, KeyCode::Up)
        {
            let result = self.history_search_in_direction(HistorySearchDirection::Older);
            return (result, true);
        }

        if Self::is_history_search_forward_key(&key_event, &self.history_search_next_keys)
            || matches!(key_event.code, KeyCode::Down)
        {
            let result = self.history_search_in_direction(HistorySearchDirection::Newer);
            return (result, true);
        }

        match key_event {
            KeyEvent {
                code: KeyCode::Esc, ..
            } => {
                self.cancel_history_search();
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Char(c),
                modifiers,
                ..
            } if modifiers.contains(KeyModifiers::CONTROL) && c.eq_ignore_ascii_case(&'c') => {
                self.cancel_history_search();
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Char('\u{0003}'),
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.cancel_history_search();
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Enter,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                if self
                    .history_search
                    .as_ref()
                    .is_some_and(|search| matches!(search.status, HistorySearchStatus::Match))
                {
                    self.history_search = None;
                    if !self.is_empty() {
                        self.dismiss_sparkle();
                    }
                    self.history.reset_search();
                    self.footer.mode = reset_mode_after_activity(self.footer.mode);
                    self.move_cursor_to_end();
                }
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Backspace,
                ..
            }
            | KeyEvent {
                code: KeyCode::Char('h'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                self.update_history_search_query(|query| {
                    query.pop();
                });
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Char('u'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                self.update_history_search_query(String::clear);
                (InputResult::None, true)
            }
            KeyEvent {
                code: KeyCode::Char(ch),
                modifiers,
                ..
            } if !has_ctrl_or_alt(modifiers) => {
                self.update_history_search_query(|query| query.push(ch));
                (InputResult::None, true)
            }
            _ => (InputResult::None, true),
        }
    }

