fn rescheduling_check_cancels_the_earlier_timer() {
    let thread_id = ThreadId::new();
    let first_turn = Instant::now();
    let mut app = make_test_app().await;
    let (event_tx, mut event_rx) = tokio::sync::mpsc::unbounded_channel();
    app.app_event_tx = AppEventSender::new(event_tx);

    app.recap.note_focus_lost(first_turn);
    for _ in 0..3 {
        app.recap
            .note_turn_finished(&TurnStatus::Completed, first_turn);
    }
    app.schedule_recap_check(thread_id, first_turn);
    tokio::task::yield_now().await;

    let elapsed = Duration::from_secs(/*secs*/ 1);
    tokio::time::advance(elapsed).await;
    let later_turn = first_turn + elapsed;
    app.recap
        .note_turn_finished(&TurnStatus::Completed, later_turn);
    app.schedule_recap_check(thread_id, later_turn);
    tokio::task::yield_now().await;

    tokio::time::advance(RECAP_DELAY - elapsed).await;
    tokio::task::yield_now().await;
    assert!(matches!(event_rx.try_recv(), Err(TryRecvError::Empty)));

    tokio::time::advance(elapsed).await;
    tokio::task::yield_now().await;
    assert!(matches!(
        event_rx.try_recv(),
        Ok(AppEvent::CheckRecap {
            thread_id: event_thread_id,
        }) if event_thread_id == thread_id
    ));
}

fn focus_activity(&mut self, cells: &[Arc<dyn HistoryCell>], index: usize) -> bool {
        if self
            .current_layout(cells, index)
            .is_none_or(|layout| !layout.disclosure)
        {
            return false;
        }
        let ids = self.activity_ids(cells, index);
        let header_visible = self.visible.iter().any(|row| {
            row.layout.disclosure
                && row.activity_ids.iter().any(|id| ids.contains(id))
                && row.row == usize::from(row.layout.separated)
        });
        self.disclosure.focused = Some(ids);
        if !header_visible {
            self.jump_to_entry(cells, index);
        }
        true
    }

