fn selection_highlights_hard_breaks_within_and_between_entries() {
    let mut frames = Vec::new();
    for (lines, end_row) in [
        (vec![vec!["code", "next"]], 1),
        (vec![vec!["code"], vec!["next"]], 2),
    ] {
        let cells: Vec<Arc<dyn HistoryCell>> = lines
            .into_iter()
            .map(|lines| {
                Arc::new(PlainHistoryCell::new(
                    lines.into_iter().map(Line::from).collect(),
                )) as _
            })
            .collect();
        let area = Rect::new(
            /*x*/ 0, /*y*/ 0, /*width*/ 8, /*height*/ 3,
        );
        let mut view = TranscriptView::default();
        let mut buffer = Buffer::empty(area);
        view.render(area, &mut buffer, &cells);
        view.begin_selection(&cells, /*column*/ 0, /*row*/ 0, /*clicks*/ 1);
        view.extend_selection(/*column*/ 7, /*row*/ 0);
        view.render(area, &mut buffer, &cells);
        assert_eq!(view.selected_text(&cells).as_deref(), Some("code"));
        assert!(
            !buffer[(4, 0)]
                .modifier
                .contains(ratatui::style::Modifier::REVERSED)
        );
        view.extend_selection(/*column*/ 0, end_row);
        view.render(area, &mut buffer, &cells);
        assert_eq!(view.selected_text(&cells).as_deref(), Some("code\n"));
        frames.push(format!("{buffer:?}"));
    }
    insta::assert_snapshot!(frames.join("\n"));
}

fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.height == 0 || area.width == 0 {
            return;
        }

        let hint_lines = super::selection_popup_common::wrap_styled_line(
            &self.footer_hint,
            area.width.saturating_sub(/*rhs*/ 2),
        );
        let [content_area, footer_area] = Layout::vertical([
            Constraint::Fill(1),
            Constraint::Length(hint_lines.len() as u16),
        ])
        .areas(area);

        Block::default()
            .style(user_message_style())
            .render(content_area, buf);

        let header_height = self
            .header
            .desired_height(content_area.width.saturating_sub(4));
        let rows = self.build_rows();
        let rows_height = self.rows_height(&rows);
        let [header_area, search_area, render_area] =
            super::picker_rows::layout(content_area, header_height, /*search*/ 1, rows_height);

        self.header.render(header_area, buf);

        if search_area.height > 0 {
            let query_span = if self.search_query.is_empty() {
                SEARCH_PLACEHOLDER.dim()
            } else {
                self.search_query.clone().into()
            };
            Line::from(query_span).render(search_area, buf);
        }

        if render_area.height > 0 {
            render_rows_single_line(
                render_area,
                buf,
                &rows,
                &self.state,
                render_area.height as usize,
                "no matches",
            );
        }

        let hint_area = Rect {
            x: footer_area.x + 2,
            y: footer_area.y,
            width: footer_area.width.saturating_sub(2),
            height: footer_area.height,
        };
        Paragraph::new(hint_lines).dim().render(hint_area, buf);
    }

