fn resolve_answers(&mut self, question_ids: &[String]) -> bool {
        // History can arrive before live questions or before restoring local drafts.
        self.state.answered_ids.extend(question_ids.iter().cloned());
        // Older desktop replies identify the whole source message instead of one question.
        let answered = |question: &PendingQuestion| {
            question_ids.contains(&question.question_id)
                || question_ids.contains(&question.message_id)
        };
        if !self.state.pending.iter().any(answered) {
            return false;
        }
        let current_answered = self.current_answer().is_some_and(answered);
        let displayed_answer_changed = self.expanded && current_answered;
        if current_answered {
            self.composer.flush_pending_input();
        }
        let current_idx = self
            .state
            .pending
            .iter()
            .take(self.state.current_idx)
            .filter(|question| !answered(question))
            .count();
        self.state.pending.retain(|question| !answered(question));
        self.state.current_idx = if current_idx < self.state.pending.len() {
            current_idx
        } else {
            0
        };
        self.expanded &= !self.state.pending.is_empty();
        self.visible_options.set((0, 0));
        if current_answered {
            self.restore_current_draft();
            self.composer.reset_vim_mode();
        }
        displayed_answer_changed
    }

fn controller_set_width_partial_drain_keeps_pending_queue() {
        let mut ctrl = stream_controller(Some(40));
        ctrl.push("AAAA BBBB CCCC DDDD EEEE FFFF GGGG HHHH IIII JJJJ\n");
        ctrl.push("second line\n");

        let (cell, idle) = ctrl.on_commit_tick();
        assert!(cell.is_some(), "expected 1 emitted line");
        assert!(!idle, "queue should still have lines");
        assert!(ctrl.queued_lines() > 0, "expected pending queued lines");

        ctrl.set_width(Some(20));

        assert!(
            ctrl.queued_lines() > 0,
            "resize must preserve pending queued lines"
        );

        let mut drained = Vec::new();
        for _ in 0..64 {
            let (cell, is_idle) = ctrl.on_commit_tick();
            if let Some(cell) = cell {
                drained.extend(lines_to_plain_strings(&cell.transcript_lines(u16::MAX)));
            }
            if is_idle {
                break;
            }
        }

        assert!(
            drained.iter().any(|l| l.contains("second line")),
            "pending lines should continue draining after resize; got {drained:?}",
        );
    }

