                                render_rows_single_line_with_col_width_mode(
                                    area,
                                    &mut buffer,
                                    &rows,
                                    &state,
                                    /*max_results*/ 1,
                                    "",
                                    ColumnWidthConfig::default(),
                                );
                            } else {
                                render_rows(
                                    area,
                                    &mut buffer,
                                    &rows,
                                    &state,
                                    /*max_results*/ 1,
                                    "",
                                );
                            }
                            let line = buffer
                                .content
                                .iter()
                                .map(ratatui::buffer::Cell::symbol)
                                .collect::<String>();
                            let status = &buffer[(3, 0)];
                            let description_x =
                                line.find("secondary").expect("visible secondary text") as u16;
                            assert_eq!(
                                (
                                    buffer[(0, 0)].modifier,
                                    status.modifier,
                                    buffer[(description_x, 0)].modifier
                                ),
                                (
                                    Modifier::BOLD
                                        | Modifier::UNDERLINED
                                        | (selected.add_modifier & Modifier::REVERSED),
                                    Modifier::BOLD
                                        | Modifier::ITALIC
                                        | (selected.add_modifier & Modifier::REVERSED),
                                    selected.add_modifier & Modifier::REVERSED,
