        let mut lines = Vec::new();
        if self.entry.warnings.is_empty() && self.entry.errors.is_empty() {
            return lines;
        }

        lines.push("Issues".bold().into());
        lines.extend(
            self.entry
                .warnings
                .iter()
                .map(|warning| format!("⚠ {warning}").into()),
        );
        lines.extend(self.entry.errors.iter().map(|error| {
