fn feedback_releases_navigation_targets_and_expiry_restores_them() {
    let cells = vec![cell("one\ntwo\nthree\nfour\nfive")];
    let mut view = TranscriptView::default();
    render(&mut view, &cells, /*width*/ 60, /*height*/ 3);
    view.scroll(&cells, /*rows*/ -2);
    render(&mut view, &cells, /*width*/ 60, /*height*/ 3);
    let area = Rect::new(
        /*x*/ 0, /*y*/ 3, /*width*/ 60, /*height*/ 1,
    );
    let mut buffer = Buffer::empty(area);
    assert!(view.composer_gap_has_content(area.width, /*hint*/ None, Instant::now()));
    view.render_composer_gap(Some(area), /*hint*/ None, &mut buffer, Instant::now());
    assert!(text(&buffer).contains("Back to bottom"));
    view.show_copy_feedback(&Ok(CopyStatus::Unconfirmed), /*characters*/ 3);
    buffer.reset();
    view.render_composer_gap(Some(area), /*hint*/ None, &mut buffer, Instant::now());
    assert!(!text(&buffer).contains("Back to bottom"));
    assert!(!view.is_following());
    view.copy_feedback.as_mut().unwrap().expires_at = Some(Instant::now());
    buffer.reset();
    assert_eq!(
        view.render_composer_gap(Some(area), /*hint*/ None, &mut buffer, Instant::now()),
        None
    );
    assert!(text(&buffer).contains("Back to bottom"));
    view.jump_to_latest();
    render(&mut view, &cells, /*width*/ 60, /*height*/ 3);
    assert!(!view.composer_gap_has_content(area.width, /*hint*/ None, Instant::now()));
}

fn copy_shortcuts_clear_selection_only_after_confirmed_delivery() {
    use crate::clipboard_copy::CopyStatus;

    let cells: Vec<Arc<dyn HistoryCell>> = vec![Arc::new(PlainHistoryCell::new(vec![
        "selected\tca\rfé\x1b\u{85}".into(),
    ]))];
    for key in [
        KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
        KeyEvent::new(KeyCode::Char('c'), KeyModifiers::SUPER),
        KeyEvent::new(
            KeyCode::Char('c'),
            KeyModifiers::CONTROL | KeyModifiers::SHIFT,
        ),
        KeyEvent::new(
            KeyCode::Char('C'),
            KeyModifiers::CONTROL | KeyModifiers::SHIFT,
        ),
        KeyEvent::new(KeyCode::Char('C'), KeyModifiers::CONTROL),
    ] {
        for status in [CopyStatus::Confirmed, CopyStatus::Unconfirmed] {
            for searching in [false, true] {
                let mut view = TranscriptView::default();
                render(&mut view, &cells, /*width*/ 32, /*height*/ 3);
                if searching {
                    view.begin_search();
                }
                view.begin_selection(&cells, /*column*/ 0, /*row*/ 0, /*clicks*/ 3);
                let action = view.handle_key(key, &cells);
                assert_eq!(
                    matches!(&action, Some(ViewAction::CopyAndFollow(_))),
                    key.code == KeyCode::Enter
                );
                let Some(ViewAction::Copy(text) | ViewAction::CopyAndFollow(text)) = action else {
                    panic!("selection key must request a copy");
                };
                assert_eq!(text, "selected\tcafé");
                let failed = view.copy_selected_text_with(
                    &cells,
                    &text,
                    /*clear_selection*/ true,
                    |text, _format| {
                        assert_eq!(text, "selected\tcafé");
                        Err("clipboard unavailable".to_string())
                    },
                );
                assert_eq!(failed, Err("clipboard unavailable".to_string()));
                assert_eq!(
                    view.selected_text(&cells).as_deref(),
                    Some("selected\tcafé")
                );

                let Some(ViewAction::Copy(text) | ViewAction::CopyAndFollow(text)) =
                    view.handle_key(key, &cells)
                else {
                    panic!("failed copy must remain retryable");
                };
                let copied = view.copy_selected_text_with(
                    &cells,
                    &text,
                    /*clear_selection*/ true,
                    |text, _format| {
                        assert_eq!(text, "selected\tcafé");
                        Ok(status)
                    },
                );
                assert_eq!(copied, Ok(status));
                assert_eq!(
                    (view.selected_text(&cells), view.is_search_editing()),
                    (
                        (status == CopyStatus::Unconfirmed).then(|| text.clone()),
                        searching
                    )
                );
                assert_eq!(view.selection.is_none(), status == CopyStatus::Confirmed);
                if !searching && status == CopyStatus::Confirmed {
                    assert!(
                        view.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE), &cells)
                            .is_none()
                    );
                }
            }
        }
    }
}

fn validate_no_shadow_with_allowed_overlaps<const N: usize, const M: usize, const A: usize>(
    context: &str,
    primary: [(&'static str, &[KeyBinding]); N],
    shadowed: [(&'static str, &[KeyBinding]); M],
    allowed_overlaps: [(&'static str, &'static str, KeyBinding); A],
) -> Result<(), String> {
    let mut seen: HashMap<(KeyCode, KeyModifiers), &'static str> = HashMap::new();
    for (action, bindings) in primary {
        for binding in bindings {
            seen.insert(binding.normalized_parts(), action);
        }
    }
    for (action, bindings) in shadowed {
        for binding in bindings {
            let key = binding.normalized_parts();
            if let Some(previous) = seen.get(&key) {
                if allowed_overlaps.iter().any(
                    |(allowed_primary, allowed_shadowed, allowed_binding)| {
                        *allowed_primary == *previous
                            && *allowed_shadowed == action
                            && allowed_binding.normalized_parts() == key
                    },
                ) {
                    continue;
                }
                return Err(format!(
                    "Ambiguous `tui.keymap.{context}` bindings: `{previous}` shadows `{action}` with the same key. \
Set unique keys in `~/.codex/config.toml` and retry. \
See the Codex keymap documentation for supported actions and examples."
                ));
            }
        }
    }
    Ok(())
}

