fn clipped_exec_approval_opens_the_complete_command() {
    let command = format!(
        "{}printf destructive_suffix",
        "printf benign\n".repeat(/*n*/ 20)
    );
    let reason = format!(
        "{}reason_suffix",
        "A reason requiring review.\n".repeat(/*n*/ 20)
    );
    let mut snapshots = Vec::new();
    for binding in [Some(key_hint::ctrl(KeyCode::Char('g'))), None] {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let mut keymap = RuntimeKeymap::defaults();
        keymap.approval.open_fullscreen = binding.into_iter().collect();
        let mut view = ApprovalOverlay::new(
            ApprovalRequest::Exec(ExecApprovalRequest {
                kind: Default::default(),
                thread_id: ThreadId::new(),
                thread_label: None,
                id: "clipped-approval".into(),
                environment_id: Some("local".into()),
                command: vec!["sh".into(), "-c".into(), command.clone()],
                reason: Some(reason.clone()),
                available_decisions: vec![
                    CommandExecutionApprovalDecision::Accept,
                    CommandExecutionApprovalDecision::Cancel,
                ],
                network_approval_context: None,
                additional_permissions: None,
            }),
            AppEventSender::new(tx),
            Features::with_defaults(),
            keymap.approval,
            keymap.list,
        );
        for (width, height) in [(80, 14), (40, 10), (40, 8), (40, 7)] {
            let area = Rect::new(/*x*/ 0, /*y*/ 0, width, height);
            let mut buffer = Buffer::empty(area);
            view.render(area, &mut buffer);
            let rows: Vec<String> = (0..height)
                .map(|y| {
                    (0..width)
                        .map(|x| buffer[(x, y)].symbol())
                        .collect::<String>()
                        .trim_end()
                        .to_owned()
                })
                .collect();
            let elision = rows.iter().find(|row| row.contains("[…")).unwrap();
            assert_eq!(elision.contains("⌃g view all"), binding.is_some());
            assert!(rows.last().unwrap().contains("cancel"));
            assert!(!rows.iter().any(|row| row.contains("destructive_suffix")));
            assert!(!rows.iter().any(|row| row.contains("reason_suffix")));
            assert!(rows.iter().any(|row| row.contains("Yes, proceed")));
            snapshots.push(format!(
                "bound={} {width}x{height}\n{}",
                binding.is_some(),
                rows.join("\n")
            ));
        }
        let area = Rect::new(
            /*x*/ 0,
            /*y*/ 0,
            /*width*/ 80,
            view.desired_height(/*width*/ 80),
        );
        let mut buffer = Buffer::empty(area);
        view.render(area, &mut buffer);
        let complete = buffer
            .content
            .iter()
            .map(ratatui::buffer::Cell::symbol)
            .collect::<String>();
        assert!(complete.contains("destructive_suffix"));
        assert!(complete.contains("reason_suffix"));
        assert!(!complete.contains("[…"));
        if binding.is_some() {
            view.handle_key_event(KeyEvent::new(KeyCode::Char('g'), KeyModifiers::CONTROL));
            let AppEvent::FullScreenApprovalRequest(ApprovalRequest::Exec(request)) =
                rx.try_recv().unwrap()
            else {
                panic!("fullscreen should open the original approval");
            };
            assert_eq!(
                request.command,
                vec!["sh".to_owned(), "-c".to_owned(), command.clone()]
            );
            assert_eq!(request.reason, Some(reason.clone()));
            assert!(!view.is_complete());
            assert!(rx.try_recv().is_err());
        }
    }
    insta::assert_snapshot!(snapshots.join("\n\n"));
}

fn hook_status_reflows_without_displacing_controls_or_details() {
        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let mut w = StatusIndicatorWidget::new(
            AppEventSender::new(tx),
            crate::tui::FrameRequester::test_dummy(),
            /*animations_enabled*/ false,
            Default::default(),
        );
        let mut timer = StatusTimer::default();
        timer.pause_at(timer.last_resume_at);
        w.update_hook_status_message(Some("checking 日本語 ｶﾞﾊﾟ policy".to_string()));
        w.update_details(
            Some("existing details".to_string()),
            StatusDetailsCapitalization::Preserve,
            STATUS_DETAILS_DEFAULT_MAX_LINES,
        );

        for (background, snapshot) in [
            (None, "hook_status_reflows_without_background_activity"),
            (
                Some("1 background terminal running · /ps to view · /stop to close"),
                "hook_status_reflows_with_background_activity",
            ),
        ] {
            w.update_inline_message(background.map(str::to_string));
            let mut expected = "Working (0s • esc to interrupt)".to_string();
            if let Some(background) = background {
                expected.push_str(&format!(" · {background}"));
            }
            expected.push_str(" · checking 日本語 ｶﾞﾊﾟ policy");
            let fit_width = display_width(&expected) as u16;
            let mut frames = Vec::new();
            for width in [fit_width, fit_width - 1, 24, fit_width] {
                let height = w.with_timer(&timer).desired_height(width);
                assert_eq!(height, if width >= fit_width { 2 } else { 3 });
                let mut terminal =
                    Terminal::new(TestBackend::new(width, height)).expect("terminal");
                terminal
                    .draw(|f| w.with_timer(&timer).render(f.area(), f.buffer_mut()))
                    .expect("draw");
                frames.push(format!("{width} columns:\n{}", terminal.backend()));
            }
            insta::assert_snapshot!(snapshot, frames.join("\n"));
        }
    }

fn copy(text: &str, deadline: Instant) -> Result<(), String> {
    static DISCOVERY: Pending<(PathBuf, OsString)> = Mutex::new(None);
    let (executable, path) = read_only_setup(&DISCOVERY, deadline, || {
        let executable = codex_utils_path::system_executable("powershell.exe")
            .ok_or("PowerShell is unavailable in the system PATH")?;
        let path = codex_utils_path::system_path()
            .map_err(|error| format!("failed to resolve system PATH: {error}"))?;
        Ok((executable, path))
    })?;
    let status = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .map_err(|error| format!("could not start Windows clipboard writer: {error}"))?
        .block_on(write_command(command(&executable, &path), text, deadline))?;
    if status.success() {
        Ok(())
    } else {
        Err(format!("powershell.exe exited with status {status}"))
    }
}

