fn active_event_source_mut(&mut self) -> Option<&mut S> {
        match self {
            EventBrokerState::Paused => None,
            EventBrokerState::Start => {
                *self = EventBrokerState::Running(S::default());
                match self {
                    EventBrokerState::Running(events) => Some(events),
                    EventBrokerState::Paused | EventBrokerState::Start => unreachable!(),
                }
            }
            EventBrokerState::Running(events) => Some(events),
        }
    }

fn render(
        &self,
        width: u16,
        list_spacing: ListSpacing,
        render: impl FnOnce() -> Vec<HyperlinkLine>,
    ) -> Vec<HyperlinkLine> {
        let key = MarkdownRenderCacheKey {
            width,
            list_spacing,
            syntax_theme_revision: crate::render::highlight::syntax_theme_revision(),
            terminal_fg: crate::terminal_palette::default_fg(),
            terminal_bg: crate::terminal_palette::default_bg(),
            color_level: crate::terminal_palette::stdout_color_level(),
        };
        let mut cached = self.cached.lock().unwrap_or_else(PoisonError::into_inner);
        if let Some((cached_key, lines)) = cached.as_ref()
            && *cached_key == key
        {
            return lines.clone();
        }

        let lines = render();
        *cached = Some((key, lines.clone()));
        lines
    }

fn render_markdown(markdown: &str) -> String {
    let normalized = crate::markdown::unwrap_markdown_fences(markdown);
    let options = Options::ENABLE_STRIKETHROUGH | Options::ENABLE_TABLES;
    let mut link_destinations = Vec::new();
    let events = Parser::new_ext(&normalized, options).filter_map(|event| {
        Some(match event {
            Event::Html(text) | Event::InlineHtml(text) => Event::Text(text),
            Event::Start(Tag::Image { .. }) | Event::End(TagEnd::Image) => return None,
            Event::Start(mut tag) => {
                if let Tag::Link { dest_url, .. } = &mut tag {
                    if let Some(destination) = crate::terminal_hyperlinks::web_destination(dest_url)
                    {
                        *dest_url = destination.into();
                        link_destinations.push(/*value*/ None);
                    } else {
                        link_destinations.push(Some(dest_url.clone()));
                        return None;
                    }
                }
                Event::Start(tag)
            }
            Event::End(TagEnd::Link) => match link_destinations.pop().flatten() {
                Some(destination) => Event::Text(format!(" ({destination})").into()),
                None => Event::End(TagEnd::Link),
            },
            event => event,
        })
    });
    let mut html = String::new();
    pulldown_cmark::html::push_html(&mut html, events);
    html
}

