fn key_modifiers_debug_label(modifiers: KeyModifiers) -> String {
    if modifiers.is_empty() {
        return "none".to_string();
    }

    let mut parts = Vec::new();
    if modifiers.contains(KeyModifiers::CONTROL) {
        parts.push("ctrl".to_string());
    }
    if modifiers.contains(KeyModifiers::ALT) {
        parts.push("alt".to_string());
    }
    if modifiers.contains(KeyModifiers::SHIFT) {
        parts.push("shift".to_string());
    }

    let known_modifiers = KeyModifiers::CONTROL | KeyModifiers::ALT | KeyModifiers::SHIFT;
    let other_modifiers = modifiers.difference(known_modifiers);
    if !other_modifiers.is_empty() {
        parts.push(format!("{other_modifiers:?}"));
    }
    parts.join("|")
}

fn push_str(&mut self, chunk: &str) {
        if !self.truncated {
            if self.full_output.len().saturating_add(chunk.len()) <= LIVE_COMMAND_OUTPUT_MAX_BYTES {
                self.full_output.push_str(chunk);
                self.completed_lines = self
                    .completed_lines
                    .saturating_add(chunk.bytes().filter(|byte| *byte == b'\n').count());
                if !chunk.is_empty() {
                    self.has_partial_line = !chunk.ends_with('\n');
                }
                return;
            }

            self.truncated = true;
            let full_output = std::mem::take(&mut self.full_output);
            self.completed_lines = 0;
            self.has_partial_line = false;
            self.push_truncated_str(&full_output);
        }

        self.push_truncated_str(chunk);
    }

fn remove_agents_overview_thread(&mut self, thread_id: ThreadId) {
        self.prepare_agents_overview_removal(&std::collections::HashSet::from([thread_id]));
        self.agents_overview.removed_threads.insert(thread_id);
        if let Some(Some(thread)) = self.agents_overview.threads.remove(&thread_id)
            && !thread.ephemeral
            && thread.parent_thread_id.is_none()
            && !matches!(
                thread.source,
                SessionSource::SubAgent(SubAgentSource::ThreadSpawn { .. })
            )
            && !self.agents_overview.hidden_threads.contains(&thread_id)
        {
            self.agents_overview.refill_count += 1;
