fn render_markdown_agent_with_list_spacing(
    markdown_source: &str,
    width: Option<usize>,
    cwd: Option<&Path>,
    inline_visualization_context: Option<&InlineVisualizationContext>,
    list_spacing: ListSpacing,
) -> Vec<HyperlinkLine> {
    let rewritten = rewrite_inline_visualizations(markdown_source, inline_visualization_context);
    let mut code_sources = Vec::new();
    let normalized = if crate::markdown_render::preferences::current().tables {
        unwrap_markdown_fences_with_sources(&rewritten.markdown, &mut code_sources)
    } else {
        Cow::Borrowed(rewritten.markdown.as_ref())
    };
    let is_hidden_link_destination = |destination: &str| {
        rewritten.trusted_file_links.contains_key(destination)
            || crate::markdown_render::hide_web_link_destination(destination)
    };
    let mut lines = crate::markdown_render::render_with_copy_sources(
        &normalized,
        width,
        cwd,
        &is_hidden_link_destination,
        list_spacing,
        code_sources,
    )
    .lines;
    for hyperlink in lines.iter_mut().flat_map(|line| &mut line.hyperlinks) {
        if let Some(link) = rewritten.trusted_file_links.get(&hyperlink.destination) {
            hyperlink.retarget_to_trusted_file(&link.destination);
        }
    }
    lines
}

fn startup_replay_omits_terminal_color_replies_interleaved_with_bracketed_paste() {
    let input = b"prefix\x1b[200~hello\x1b]10;rgb:eeee/eeee/eeee\x07 \
        \x1b]11;rgb:1111/1111/1111\x1b\\world\x1b[201~suffix";

    assert_eq!(
        startup_replay_input(input),
        b"prefix\x1b[200~hello world\x1b[201~suffix"
    );

    let unfinished_paste = b"\x1b[200~hello\x1b]10;rgb:eeee/eeee/eeee\x07 world";
    assert_eq!(
        startup_replay_input(unfinished_paste),
        b"\x1b[200~hello world"
    );

    let unrelated_osc = b"\x1b[200~\x1b]52;preserve me\x07\x1b[201~";
    assert_eq!(startup_replay_input(unrelated_osc), unrelated_osc);

    let response_after_paste = b"\x1b[200~\x1b]10;unfinished\x1b[201~suffix\x07";
    assert_eq!(
        startup_replay_input(response_after_paste),
        response_after_paste
    );
}

