fn should_handle_navigation(&self, text: &str, cursor: usize) -> bool {
        if self.persistent_entry_count == 0 && self.local_history.is_empty() {
            return false;
        }

        if text.is_empty() {
            return true;
        }

        // Textarea is not empty – only navigate when text matches the last
        // recalled history entry and the cursor is at a line boundary. This
        // keeps shell-like Up/Down recall working while still allowing normal
        // multiline cursor movement from interior positions.
        if cursor != 0 && cursor != text.len() {
            return false;
        }

        matches!(&self.last_history_text, Some(prev) if prev == text)
    }

fn copy_navigation_leaves_context_and_preserves_the_center_band() {
    let context = (0..12)
        .map(|i| format!("Context {i}\n\n"))
        .collect::<String>();
    let source = format!(
        "{context}```sh\nfirst target\n```\n\n{context}```sh\nsecond target\n```\n\n{context}"
    );
    let cells: Vec<Arc<dyn HistoryCell>> =
        vec![Arc::new(AgentMarkdownCell::new(source, Path::new("/")))];
    let mut view = TranscriptView::default();
    render(&mut view, &cells, /*width*/ 50, /*height*/ 16);
    view.begin_copy_mode(&cells, /*guard*/ None);
    for (key, expected_row) in [(KeyCode::Up, 11), (KeyCode::Up, 4), (KeyCode::Down, 11)] {
        view.move_copy_target(&cells, key);
        let buffer = render(&mut view, &cells, /*width*/ 50, /*height*/ 16);
        let selection_style = ratatui::buffer::Cell::default()
            .set_style(crate::style::selection_style())
            .style();
        let selected_rows = buffer
            .content
            .chunks(50)
            .enumerate()
            .filter_map(|(row, cells)| {
                cells
                    .iter()
                    .any(|cell| cell.style() == selection_style)
                    .then_some(row)
            })
            .collect::<Vec<_>>();
        assert_eq!(selected_rows, vec![expected_row]);
        let before = text(&buffer);
        view.reveal_copy_context(&cells);
        assert_eq!(
            text(&render(
                &mut view, &cells, /*width*/ 50, /*height*/ 16
            )),
            before
        );
    }
    let buffer = render(&mut view, &cells, /*width*/ 50, /*height*/ 10);
    insta::assert_snapshot!(text(&buffer));
}

fn render_snapshot(view: &AppLinkView, area: Rect) -> String {
        let mut buf = Buffer::empty(area);
        view.render(area, &mut buf);
        (0..area.height)
            .map(|y| {
                (0..area.width)
                    .map(|x| {
                        let symbol = buf[(x, y)].symbol();
                        if symbol.is_empty() {
                            ' '
                        } else {
                            crate::terminal_hyperlinks::strip_osc8(symbol)
                                .chars()
                                .next()
                                .unwrap_or(' ')
                        }
                    })
                    .collect::<String>()
                    .trim_end()
                    .to_string()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

