    ");
    overlay.handle_event(
        &mut tui,
        TuiEvent::Key(KeyEvent::new(
            KeyCode::End,
            crossterm::event::KeyModifiers::NONE,
        )),
    )?;
    overlay.handle_event(&mut tui, TuiEvent::Key(home))?;
    overlay.render(area, &mut pending);
    assert_eq!(pending, complete);
    Ok(())
}

