fn normalize_keybinding_spec(raw: &str) -> Result<String, String> {
    let strokes = raw.split_whitespace().collect::<Vec<_>>();
    if strokes.is_empty() {
        return normalize_keybinding_stroke(raw);
    }
    if strokes.len() > MAX_KEY_CHORD_STROKES {
        return Err(format!(
            "invalid keybinding `{raw}`: key chords may contain at most \
{MAX_KEY_CHORD_STROKES} strokes (for example `ctrl-x ctrl-s`)."
        ));
    }

    if strokes[0].eq_ignore_ascii_case("leader") {
        let [_, completion] = strokes.as_slice() else {
            return Err(format!(
                "invalid keybinding `{raw}`: `leader` must be followed by one key \
(for example `leader c`)."
            ));
        };
        return normalize_keybinding_stroke(completion)
            .map(|completion| format!("leader {completion}"));
    }

    strokes
        .into_iter()
        .map(normalize_keybinding_stroke)
        .collect::<Result<Vec<_>, _>>()
        .map(|normalized| normalized.join(" "))
}

fn apply_paste(&mut self, pasted: String) -> bool {
        let pasted = pasted.replace("\r\n", "\n").replace('\r', "\n");
        let pasted = sanitize_user_text(pasted.into());
        if self.history_search.is_some() {
            if !pasted.is_empty() {
                self.update_history_search_query(|query| query.push_str(&pasted));
            }
            return true;
        }
        if let Some(query) = self.draft.textarea.vim_query_mut() {
            query.editor.insert_str(&pasted);
            return true;
        }
        self.draft.textarea_state.get_mut().follow_cursor();
        let started_vim_edit = self.begin_direct_vim_edit();
        let elements_before = self.draft.textarea.element_payloads();
        let target = self.draft.textarea.edit_target();
        let before_cursor = &self.draft.textarea.text()[..target.start()];
        let current_line = before_cursor.rsplit('\n').next().unwrap_or_default();
        let is_blockquote = self.config.blockquote_paste_enabled
            && !self.is_bang_shell_command()
            && current_line.starts_with("> ")
            && pasted.contains('\n');
        let pasted = if is_blockquote {
            let pasted = pasted
                .strip_suffix('\n')
                .filter(|pasted| !pasted.is_empty())
                .unwrap_or(pasted.as_ref());
            std::borrow::Cow::Owned(pasted.replace('\n', "\n> "))
        } else {
            pasted
        };
        let char_count = pasted.chars().count();
        if char_count > LARGE_PASTE_CHAR_THRESHOLD {
            let placeholder = self.next_large_paste_placeholder(char_count);
            self.draft
                .textarea
                .insert_element_at_target(target, &placeholder);
            self.draft
                .pending_pastes
                .push((placeholder, pasted.into_owned()));
        } else if char_count > 1
            && self.image_paste_enabled()
            && self.handle_paste_image_path(&pasted)
        {
            let cursor = self.draft.textarea.cursor();
            self.draft.textarea.insert_str_at(cursor, " ");
        } else {
            self.insert_str_at_target(target, &pasted);
        }
        if is_blockquote {
            let textarea = &mut self.draft.textarea;
            textarea.insert_str_at(textarea.cursor(), "\n\n");
        }
        self.draft.paste_burst.clear_after_explicit_paste();
        self.reconcile_deleted_elements(elements_before);
        self.sync_popups();
        if started_vim_edit {
            self.finish_vim_edit();
        }
        true
    }

