fn historical_command_fallbacks_preserve_status_output_and_group_boundaries() {
    let cwd = test_path_buf("/workspace").abs();
    let exploration = |call_id: &str| {
        let mut item = command_item(CommandExecutionStatus::Completed);
        if let ThreadItem::CommandExecution {
            id,
            command,
            command_actions,
            ..
        } = &mut item
        {
            *id = call_id.to_owned();
            *command = "cat README.md".to_owned();
            *command_actions = vec![CommandAction::Read {
                command: command.clone(),
                name: "README.md".to_owned(),
                path: LegacyAppPathString::from_string("/workspace/README.md"),
            }];
        }
        item
    };
    let mut snapshots = Vec::new();
    for (source, status, recorded_exit, label) in [
        (
            CommandExecutionSource::Agent,
            CommandExecutionStatus::Declined,
            None,
            "declined",
        ),
        (
            CommandExecutionSource::Agent,
            CommandExecutionStatus::Completed,
            Some(0),
            "opaque command",
        ),
        (
            CommandExecutionSource::Agent,
            CommandExecutionStatus::Completed,
            Some(0),
            "UNC command",
        ),
        (
            CommandExecutionSource::UnifiedExecInteraction,
            CommandExecutionStatus::Completed,
            Some(0),
            "completed interaction",
        ),
        (
            CommandExecutionSource::UnifiedExecInteraction,
            CommandExecutionStatus::Failed,
            Some(7),
            "failed interaction",
        ),
        (
            CommandExecutionSource::UnifiedExecInteraction,
            CommandExecutionStatus::Failed,
            None,
            "failed interaction without exit code",
        ),
        (
            CommandExecutionSource::UnifiedExecInteraction,
            CommandExecutionStatus::InProgress,
            None,
            "pending interaction",
        ),
    ] {
        let mut item = command_item(status);
        if let ThreadItem::CommandExecution {
            source: item_source,
            command,
            aggregated_output,
            exit_code,
            ..
        } = &mut item
        {
            *item_source = source;
            if label == "opaque command" {
                *command = r#"C:\Program Files\Git\bin\bash.exe -lc "echo hi""#.to_owned();
            } else if label == "UNC command" {
                *command = r"\\server\share\tool.exe -arg".to_owned();
            }
            *aggregated_output = Some("first line\n  indented output\nlast line".to_owned());
            *exit_code = recorded_exit;
        }
        let cells = thread_items_to_transcript_cells(
            /*thread_id*/ None,
            &cwd,
            [exploration("before"), item, exploration("after")],
            RawReasoningVisibility::Hidden,
            /*config*/ None,
        );
        assert_eq!(cells.len(), 3);
        for cell in [&cells[0], &cells[2]] {
            assert!(
                cell.as_any()
                    .downcast_ref::<ExecCell>()
                    .unwrap()
                    .is_exploring_cell()
            );
        }
        let [compact, detailed, raw] = [
            cells[1].display_lines(/*width*/ 80),
            cells[1].transcript_lines(/*width*/ 80),
            cells[1].raw_lines(),
        ]
        .map(|lines| {
            lines
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join("\n")
        });
        assert_eq!((&detailed, &raw), (&compact, &compact));
        snapshots.push(format!("{label}\n{compact}"));
    }
    insta::assert_snapshot!(snapshots.join("\n\n"));
}

fn insert_history_hyperlink_lines_with_mode_and_wrap_policy<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: &[HyperlinkLine],
    mode: InsertHistoryMode,
    wrap_policy: HistoryLineWrapPolicy,
    screen_size: Size,
) -> io::Result<()>
where
    B: Backend<Error = io::Error> + Write,
{
    let mut area = terminal.viewport_area;
    let mut should_update_area = false;
    let last_cursor_pos = terminal.last_known_cursor_pos;

    // Pre-wrap lines for terminal scrollback. Three paths:
    //
    // - URL-only-ish lines are kept intact (no hard newlines inserted) so that
    //   terminal emulators can match them as clickable links. The
    //   terminal will character-wrap these lines at the viewport
    //   boundary.
    // - Mixed lines (URL + non-URL prose) are adaptively wrapped so
    //   non-URL text still wraps naturally while URL tokens remain
    //   unsplit.
    // - Non-URL lines also flow through adaptive wrapping; behavior is
    //   equivalent to standard wrapping when no URL is present.
    let wrap_width = area.width.max(1) as usize;
    let (wrapped, wrapped_rows) = wrap_history_hyperlink_lines(lines, wrap_width, wrap_policy);
    let wrapped_lines = wrapped_rows as u16;
    match mode {
        InsertHistoryMode::FullScreen => {
            // The existing viewport is immediately replaced in the same draw pass. Clear it
            // before terminal scrolling can move composer contents into scrollback.
            terminal.clear_after_position(area.as_position())?;
            let writer = terminal.backend_mut();
            queue!(writer, MoveTo(/*x*/ 0, area.top()))?;
            for (index, line) in wrapped.iter().enumerate() {
                if index > 0 {
                    queue!(writer, Print("\r\n"))?;
                }
                write_history_line(writer, line, wrap_width)?;
            }

            // Writing raw source text through the terminal preserves its soft-wrap metadata.
            // Advance through empty rows for the viewport so history ends immediately above the
            // composer even when a replay batch is taller than the visible history region.
            for _ in 0..area.height {
                queue!(writer, Print("\r\n"), Clear(ClearType::UntilNewLine))?;
            }
            queue!(writer, MoveTo(last_cursor_pos.x, last_cursor_pos.y))?;

            let viewport_top = area
                .top()
                .saturating_add(wrapped_lines)
                .min(screen_size.height.saturating_sub(area.height));
            if area.y != viewport_top {
                area.y = viewport_top;
                should_update_area = true;
            }
        }
        InsertHistoryMode::Standard => {
            let writer = terminal.backend_mut();
            let cursor_top = if area.bottom() < screen_size.height {
                // If the viewport is not at the bottom of the screen, scroll it down to make room.
                // Don't scroll it past the bottom of the screen.
                let scroll_amount = wrapped_lines.min(screen_size.height - area.bottom());

                let top_1based = area.top() + 1;
                queue!(writer, SetScrollRegion(top_1based..screen_size.height))?;
                queue!(writer, MoveTo(/*x*/ 0, area.top()))?;
                for _ in 0..scroll_amount {
                    queue!(writer, Print("\x1bM"))?;
                }
                queue!(writer, ResetScrollRegion)?;

                let cursor_top = area.top().saturating_sub(1);
                area.y += scroll_amount;
                should_update_area = true;
                cursor_top
            } else {
                area.top().saturating_sub(1)
            };

            // Limit the scroll region to the lines from the top of the screen to the
            // top of the viewport. With this in place, when we add lines inside this
            // area, only the lines in this area will be scrolled. We place the cursor
            // at the end of the scroll region, and add lines starting there.
            //
            // ┌─Screen───────────────────────┐
            // │┌╌Scroll region╌╌╌╌╌╌╌╌╌╌╌╌╌╌┐│
            // │┆                            ┆│
            // │┆                            ┆│
            // │┆                            ┆│
            // │█╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌┘│
            // │╭─Viewport───────────────────╮│
            // ││                            ││
            // │╰────────────────────────────╯│
            // └──────────────────────────────┘
            queue!(writer, SetScrollRegion(1..area.top()))?;

            // NB: we are using MoveTo instead of set_cursor_position here to avoid messing with the
            // terminal's last_known_cursor_position, which hopefully will still be accurate after we
            // fetch/restore the cursor position. insert_history_lines should be cursor-position-neutral :)
            queue!(writer, MoveTo(/*x*/ 0, cursor_top))?;

            for line in &wrapped {
                queue!(writer, Print("\r\n"))?;
                write_history_line(writer, line, wrap_width)?;
            }

            queue!(writer, ResetScrollRegion)?;
            queue!(writer, MoveTo(last_cursor_pos.x, last_cursor_pos.y))?;
        }
    }

    if should_update_area {
        terminal.set_viewport_area(area);
    }
    if wrapped_lines > 0 {
        terminal.note_history_rows_inserted(wrapped_lines);
    }

    Ok(())
}

