fn copy_prefix(&self, pending_marker_line: bool) -> String {
        // Code's display padding is not a Markdown container. Keep only the innermost semantic
        // containers so lazy continuation lines cannot each retain an arbitrarily deep prefix.
        let containers =
            &self.indent_stack[..self.indent_stack.len() - usize::from(self.in_code_block)];
        let containers = &containers[containers
            .len()
            .saturating_sub(crate::markdown_copy::MAX_COPY_DEPTH)..];
        let last_list = containers.iter().rposition(|context| context.is_list);
        let mut prefix = String::new();
        for (index, context) in containers.iter().enumerate() {
            if context.is_list {
                let marker = &context.copy_marker;
                let width = marker.find('[').unwrap_or(marker.len());
                if pending_marker_line && Some(index) == last_list {
                    prefix.push_str(marker);
                } else {
                    prefix.extend(std::iter::repeat_n(' ', width));
                }
            } else {
                prefix.extend(context.prefix.iter().map(|span| span.content.as_ref()));
            }
        }
        prefix
    }

fn wrapped_question_url_keeps_its_complete_destination() {
    let url = "https://github.com/openai/codex/pull/12345?diff=split";
    let mut editor = editor();
    editor.navigate(/*forward*/ true);
    editor.state.pending[1].question.title = format!("Review this change ({url})?");

    let width = 40;
    let full_height = editor.desired_height(width);
    for height in [full_height, 4] {
        let buffer = render_editor(&editor, width, height);
        let linked_text = buffer
            .content
            .iter()
            .filter_map(|cell| {
                let symbol = cell.symbol();
                symbol.contains("\x1b]8;;").then(|| {
                    let text = crate::terminal_hyperlinks::strip_osc8(symbol);
                    assert_eq!(
                        symbol,
                        crate::terminal_hyperlinks::osc8_hyperlink(url, &text)
                    );
                    text
                })
            })
            .collect::<String>();
        if height == full_height {
            assert_eq!(linked_text, url);
            insta::assert_snapshot!(
                "question_wrapped_url",
                crate::terminal_hyperlinks::strip_osc8(&buffer_text(&buffer))
            );
        } else {
            assert!(!linked_text.is_empty());
            assert!(url.starts_with(&linked_text));
            assert_ne!(linked_text, url);
        }
    }
}

fn begin_selection(
        &mut self,
        cells: &[Arc<dyn HistoryCell>],
        column: u16,
        row: u16,
        clicks: u8,
    ) {
        self.copy_mode = None;
        let Some((anchor, layout)) = self.hit_test(column, row) else {
            return;
        };
        self.cancel_beginning();
        let unit = SelectionUnit::from_clicks(clicks);
        let range = unit.range(layout.text(), anchor.offset);
        let snapshot = self.capture_snapshot(cells);
        self.held_reading = None;
        let start = Anchor {
            offset: range.start,
            ..anchor
        };
        let end = Anchor {
            offset: range.end,
            ..anchor
        };
        let was_following = self.is_following();
        self.selection = Some(Selection {
            pending_copy: None,
            primary_owner: None,
            snapshot,
            start,
            end,
            origin: (start, end),
            unit,
            preferred_column: None,
            dragging: true,
            moved: false,
            moved_vertically: false,
            pointer_origin_row: row,
            resume_on_empty: was_following,
            pointer: Some(ScreenPosition::new(column, row)),
            pressed_link: None,
        });
        if was_following {
            self.hold_position();
        }
    }

fn apply_commit_tick_plan(
    drain_plan: DrainPlan,
    stream_controller: Option<&mut StreamController>,
    plan_stream_controller: Option<&mut PlanStreamController>,
) -> CommitTickOutput {
    let mut output = CommitTickOutput::default();

    if let Some(controller) = stream_controller {
        output.has_controller = true;
        let (cell, is_idle) = drain_stream_controller(controller, drain_plan);
        if let Some(cell) = cell {
            output.cells.push(cell);
        }
        output.all_idle &= is_idle;
    }
    if let Some(controller) = plan_stream_controller {
        output.has_controller = true;
        let (cell, is_idle) = drain_plan_stream_controller(controller, drain_plan);
        if let Some(cell) = cell {
            output.cells.push(cell);
        }
        output.all_idle &= is_idle;
    }

    output
}

fn restore_vim_replaced_character(&mut self) -> bool {
        let steps = &mut self.vim_commands.replace_steps;
        let Some(step) = steps
            .pop()
            .filter(|step| self.cursor_pos == step.start + step.inserted_len)
        else {
            steps.clear();
            return false;
        };
        // Replace skips existing elements, so an overlapping marker was added after typing.
        // Unmark it before restoring one character; never expand recovery to the whole token.
        self.elements.retain(|element| {
            element.range.end <= step.start || element.range.start >= step.start + step.inserted_len
        });
        self.replace_range_preserving_recovery(
            step.start..step.start + step.inserted_len,
            &step.original,
        );
        self.set_cursor(step.cursor_before);
        true
    }

