fn audio_meter_level(peak: u16) -> usize {
    usize::from(peak.saturating_sub(AUDIO_METER_NOISE_FLOOR))
        .saturating_mul(AUDIO_METER_SEGMENTS)
        .div_ceil(usize::from(
            AUDIO_METER_FULL_SCALE - AUDIO_METER_NOISE_FLOOR,
        ))
        .min(AUDIO_METER_SEGMENTS)
}

