fn agents_overview_view(
        &self,
        mut threads: Vec<Thread>,
        selected_thread_id: Option<ThreadId>,
    ) -> AgentsOverviewView {
        threads.retain(|thread| !thread.ephemeral);
        for thread in &mut threads {
            if thread.parent_thread_id.is_none()
                && let SessionSource::SubAgent(SubAgentSource::ThreadSpawn {
                    parent_thread_id, ..
                }) = &thread.source
            {
                thread.parent_thread_id = Some(parent_thread_id.to_string());
            }
        }
        let mut children: HashMap<String, Vec<&Thread>> = HashMap::new();
        for thread in &threads {
            if let Some(parent_thread_id) = &thread.parent_thread_id {
                children
                    .entry(parent_thread_id.clone())
                    .or_default()
                    .push(thread);
            }
        }

        let voice_owner = self.voice_owner_thread_id().map(|id| id.to_string());
        let voice_session = threads
            .iter()
            .find(|thread| Some(&thread.id) == voice_owner.as_ref())
            .map(|thread| &thread.session_id);
        let mut roots = threads
            .iter()
            .filter(|thread| thread.parent_thread_id.is_none())
            .map(|root| (root, agents_overview_group(root, &children)))
            .collect::<Vec<_>>();
        roots.sort_by(|(left, left_group), (right, right_group)| {
            left_group
                .cmp(right_group)
                .then_with(|| right.updated_at.cmp(&left.updated_at))
                .then_with(|| left.id.cmp(&right.id))
        });
        let mut rows = Vec::new();
        for (root, group) in roots {
            let Ok(thread_id) = ThreadId::from_string(&root.id) else {
                continue;
            };
            if self.agents_overview.hidden_threads.contains(&thread_id) {
                continue;
            }
            rows.push(AgentsOverviewRow {
                details: self.agents_overview_details(root, &children),
                thread: root.clone(),
                thread_id,
                group,
                is_current: self.primary_thread_id == Some(thread_id),
                has_voice: voice_session == Some(&root.session_id),
            });
        }

        self.agents_overview
            .view_state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .vim_enabled = self.chat_widget.composer_is_vim_enabled();
        let mut view = AgentsOverviewView::new(
            rows,
            selected_thread_id,
            !crate::uses_remote_workspace_or_environment(
                &self.app_server_target,
                self.environment_manager.as_ref(),
            ),
            self.local_settings.tui.status_line_use_colors,
            self.app_event_tx.clone(),
            self.keymap.clone(),
            Arc::clone(&self.agents_overview.view_state),
        );
        view.pinned_thread_ranks = self.agents_overview.pinned_thread_ids.as_ref().map(|ids| {
            ids.iter()
                .copied()
                .enumerate()
                .map(|(rank, id)| (id, rank))
                .collect()
        });
        view.pin_action_pending = self.agents_overview.pending_pin_change.is_some();
        view
    }

fn queued_submission_flushes_ascii_burst_instead_of_inserting_newline() {
        use crossterm::event::KeyCode;
        use crossterm::event::KeyEvent;
        use crossterm::event::KeyModifiers;

        let (tx, _rx) = unbounded_channel::<AppEvent>();
        let sender = AppEventSender::new(tx);
        let mut composer = ChatComposer::new(
            /*has_input_focus*/ true,
            sender,
            /*enhanced_keys_supported*/ false,
            "Ask Codex to do anything".to_string(),
            /*disable_paste_burst*/ false,
        );

        let mut now = Instant::now();
        let step = Duration::from_millis(1);
        for ch in ['h', 'i'] {
            let _ = composer.handle_input_basic_with_time(
                KeyEvent::new(KeyCode::Char(ch), KeyModifiers::NONE),
                now,
            );
            now += step;
        }
        assert!(composer.is_in_paste_burst());

        let (result, _) = composer.handle_submission_with_time(/*should_queue*/ true, now);

        assert_eq!(
            result,
            InputResult::Queued {
                text: "hi".to_string(),
                text_elements: Vec::new(),
                action: QueuedInputAction::Plain,
                pending_pastes: Vec::new(),
            }
        );
        assert!(composer.draft.textarea.text().is_empty());
        assert!(!composer.is_in_paste_burst());
    }

fn render(&self, area: Rect, buf: &mut Buffer) {
        if area.height == 0 || area.width == 0 {
            return;
        }

        // Reserve the footer line for the key-hint row.
        let preview_height = if self.preview_line.is_some() { 1 } else { 0 };
        let hint_lines = self.footer_lines(area.width);
        let hint_height = hint_lines.len() as u16;
        let footer_height = hint_height + preview_height;
        let [content_area, footer_area] =
            Layout::vertical([Constraint::Fill(1), Constraint::Length(footer_height)]).areas(area);

        Block::default()
            .style(user_message_style())
            .render(content_area, buf);

        let header_height = self
            .header
            .desired_height(content_area.width.saturating_sub(4));
        let rows = self.build_rows();
        let rows_height = self.rows_height(&rows);
        let [header_area, search_area, list_area] =
            picker_rows::layout(content_area, header_height, /*search*/ 1, rows_height);

        self.header.render(header_area, buf);
        if search_area.height > 0 {
            let query_span = if self.search_query.is_empty() {
                SEARCH_PLACEHOLDER.dim()
            } else {
                self.search_query.clone().into()
            };
            Line::from(query_span).render(search_area, buf);
        }

        if list_area.height > 0 {
            let body = list_area.inset(Insets::vh(u16::from(list_area.height >= 3), /*h*/ 0));
            let rendered = render_rows_single_line_with_col_width_mode(
                body,
                buf,
                &rows.rows,
                &rows.state,
                usize::from(body.height),
                "no matches",
                ColumnWidthConfig::default(),
            );
            picker_style::render_scroll_indicators(list_area, buf, rendered);
        }

        let hint_area = if let Some(preview_line) = &self.preview_line {
            let [preview_area, hint_area] =
                Layout::vertical([Constraint::Length(1), Constraint::Length(hint_height)])
                    .areas(footer_area);
            let preview_area = Rect {
                x: preview_area.x + 2,
                y: preview_area.y,
                width: preview_area.width.saturating_sub(2),
                height: preview_area.height,
            };
            let max_preview_width = preview_area.width.saturating_sub(2) as usize;
            let preview_line =
                truncate_line_with_ellipsis_if_overflow(preview_line.clone(), max_preview_width);
            preview_line.render(preview_area, buf);
            hint_area
        } else {
            footer_area
        };
        let hint_area = Rect {
            x: hint_area.x + 2,
            y: hint_area.y,
            width: hint_area.width.saturating_sub(2),
            height: hint_area.height,
        };
        Paragraph::new(hint_lines).dim().render(hint_area, buf);
    }

fn new(input: &'a str, options: Options) -> Self {
        let mut prepared = Self {
            input,
            markdown: Cow::Borrowed(input),
            directives: Vec::new(),
        };
        if !input.contains("codex-file-citation") && !input.contains(":codex-followup[") {
            return prepared;
        }

        let parser = Parser::new_ext(input, options);
        let mut literal_ranges: Vec<_> = parser
            .reference_definitions()
            .iter()
            .map(|(_, definition)| definition.span.clone())
            .collect();
        literal_ranges.extend(parser.into_offset_iter().filter_map(|(event, range)| {
            matches!(
                event,
                Event::Code(_)
                    | Event::Html(_)
                    | Event::InlineHtml(_)
                    | Event::Start(Tag::CodeBlock(_) | Tag::Link { .. } | Tag::Image { .. })
            )
            .then_some(range)
        }));
        // Reference definitions arrive separately; visit all literal ranges in source order.
        literal_ranges.sort_unstable_by_key(|range| range.start);
        let mut literal_ranges = literal_ranges.into_iter().peekable();

        let mut directive_end = 0;
        // Share separate preferred/fallback allowances across offsets, so fallback retries
        // cannot starve later preferred parses. Both allowances stay proportional to input size.
        let mut scan_budget = [input.len().saturating_mul(/*rhs*/ 4); 2];
        for (start, _) in input.match_indices(':') {
            while literal_ranges.next_if(|range| range.end <= start).is_some() {}
            if start < directive_end
                || input[..start].ends_with(':')
                || literal_ranges
                    .peek()
                    .is_some_and(|range| range.contains(&start))
            {
                continue;
            }
            let source = &input[start..];
            // Citations prefer literal quoting; other directives prefer escaped quotes.
            let escaping = if source
                .trim_start_matches(':')
                .starts_with("codex-file-citation{")
            {
                [QuoteEscaping::Literal, QuoteEscaping::Backslash]
            } else {
                [QuoteEscaping::Backslash, QuoteEscaping::Literal]
            };
            let Some(directive) =
                escaping
                    .into_iter()
                    .zip(&mut scan_budget)
                    .find_map(|(escaping, remaining)| {
                        parse_assistant_directive_with_budget(source, escaping, remaining)
                    })
            else {
                continue;
            };
            let end = start + directive.raw.len();
            directive_end = end;
            if input[..start]
                .bytes()
                .rev()
                .take_while(|byte| *byte == b'\\')
                .count()
                % 2
                != 0
                || match directive.name {
                    "codex-file-citation" => directive
                        .attributes
                        .get("path")
                        .is_none_or(|path| path.is_empty()),
                    "codex-followup" => {
                        !directive.raw.starts_with(":codex-followup[")
                            || directive.label.is_none_or(|label| label.trim().is_empty())
                    }
                    _ => true,
                }
            {
                continue;
            }
            // Mask the interior without moving offsets or changing Markdown delimiter flanking.
            let markdown = prepared.markdown.to_mut();
            markdown.replace_range(start + 1..end - 1, &"x".repeat(end - start - 2));
            prepared.directives.push((start..end, directive));
        }
        prepared
    }

fn voice_acknowledges_only_a_real_interruption_once() {
    let (mut chat, _sender, _events, _ops) = make_chatwidget_manual_with_sender().await;
    chat.local_settings.tui.animations = true;
    activate_voice(&mut chat);

    chat.on_realtime_transcript_delta("user".to_string(), "hello".to_string());
    assert!(
        chat.realtime_conversation
            .interruption_acknowledged_until
            .is_none()
    );
    chat.on_realtime_transcript_done("user".to_string(), "hello".to_string());
    chat.on_realtime_transcript_delta("assistant".to_string(), "speaking".to_string());
    chat.realtime_conversation.speaker_level = 3;
    chat.on_realtime_transcript_delta("user".to_string(), "wait".to_string());
    let acknowledged = chat.realtime_conversation.interruption_acknowledged_until;
    assert!(acknowledged.is_some());
    chat.on_realtime_transcript_delta("user".to_string(), " please".to_string());
    assert_eq!(
        chat.realtime_conversation.interruption_acknowledged_until,
        acknowledged
    );
    chat.on_realtime_transcript_done("user".to_string(), "wait please".to_string());
    chat.on_realtime_transcript_done("assistant".to_string(), "speaking".to_string());
    chat.on_realtime_transcript_delta("assistant".to_string(), "sure".to_string());
    assert!(
        chat.realtime_conversation
            .interruption_acknowledged_until
            .is_none()
    );

    chat.local_settings.tui.animations = false;
    chat.realtime_conversation.speaker_level = 3;
    chat.on_realtime_transcript_delta("user".to_string(), "stop".to_string());
    assert!(
        chat.realtime_conversation
            .interruption_acknowledged_until
            .is_none()
    );
}

