fn terminal_input_is_readable() -> Result<bool> {
    use windows_sys::Win32::Foundation::INVALID_HANDLE_VALUE;
    use windows_sys::Win32::System::Console::GetNumberOfConsoleInputEvents;
    use windows_sys::Win32::System::Console::GetStdHandle;
    use windows_sys::Win32::System::Console::STD_INPUT_HANDLE;

    let handle = unsafe { GetStdHandle(STD_INPUT_HANDLE) };
    if handle == INVALID_HANDLE_VALUE || handle.is_null() {
        return Err(io::Error::other("terminal input handle is unavailable"));
    }

    let mut pending = 0;
    if unsafe { GetNumberOfConsoleInputEvents(handle, &mut pending) } == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(pending != 0)
}

fn fold_trailing_activity_details(
    older: &Arc<dyn HistoryCell>,
    details: &[Arc<dyn HistoryCell>],
    turns: &[codex_app_server_protocol::Turn],
) -> Option<Arc<dyn HistoryCell>> {
    let (mut ids, retained) =
        if let Some(group) = older.as_any().downcast_ref::<ComputerActivityCell>() {
            (group.call_ids().collect::<Vec<_>>(), &group.group.details)
        } else {
            let group = older.as_any().downcast_ref::<ExecCell>()?;
            if !group.is_exploring_cell() || group.should_flush() {
                return None;
            }
            (
                group
                    .iter_calls()
                    .map(|call| call.call_id.as_str())
                    .collect::<Vec<_>>(),
                &group.group.details,
            )
        };
    let count = ids.len();
    for detail in details {
        let detail = detail.as_any().downcast_ref::<ReasoningSummaryCell>()?;
        if !detail.is_transcript_only() {
            return None;
        }
        ids.push(detail.source_item_id()?);
    }
    let items = super::computer_groups::adjacent_activity_items(&ids, turns)?;
    let mut retained = retained.clone();
    for detail in details {
        retained.push(count, Arc::clone(detail));
    }
    if older.as_any().is::<ComputerActivityCell>() {
        let mut group = super::computer_groups::completed_group(items)?;
        group.group.details = retained;
        Some(Arc::new(group))
    } else {
        let mut group = super::exploration_groups::completed_group(items)?;
        group.group.details = retained;
        Some(Arc::new(group))
    }
}

fn repeated_boundary_search_does_not_refetch_persistent_history() {
        let (tx, mut rx) = unbounded_channel::<AppEvent>();
        let tx = AppEventSender::new(tx);

        let mut history = ChatComposerHistory::new();
        history.set_metadata(test_thread_id(), /*log_id*/ 1, /*entry_count*/ 3);

        assert_eq!(
            HistorySearchResult::Pending,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ true,
                &tx
            )
        );
        let _ = rx.try_recv().expect("expected latest lookup");
        assert_eq!(
            HistoryEntryResponse::Search(HistorySearchResult::Found(HistoryEntry::new(
                "needle latest".to_string()
            ))),
            history.on_entry_response(
                /*log_id*/ 1,
                /*offset*/ 2,
                Some("needle latest".into()),
                &tx,
            )
        );

        assert_eq!(
            HistorySearchResult::Pending,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ false,
                &tx
            )
        );
        let _ = rx.try_recv().expect("expected next older lookup");
        assert_eq!(
            HistoryEntryResponse::Search(HistorySearchResult::Pending),
            history.on_entry_response(
                /*log_id*/ 1,
                /*offset*/ 1,
                Some("not a match".into()),
                &tx,
            )
        );
        let AppEvent::LookupMessageHistoryBatch { cursor, .. } =
            rx.try_recv().expect("expected oldest batch")
        else {
            panic!("unexpected event variant");
        };
        assert_eq!(cursor.end_offset(), 0);
        assert_eq!(
            Some(HistorySearchResult::AtBoundary),
            history.on_batch_response(
                /*log_id*/ 1,
                cursor,
                vec![batch_entry(/*offset*/ 0, "also not a match")],
                /*next_older_cursor*/ None,
                &tx,
            )
        );
        assert!(rx.try_recv().is_err());

        assert_eq!(
            HistorySearchResult::AtBoundary,
            history.search(
                "needle",
                HistorySearchDirection::Older,
                /*restart*/ false,
                &tx
            )
        );
        assert!(rx.try_recv().is_err());
    }

fn blockquote_selection_copies_only_selected_content() {
    let mut copies = Vec::new();
    for (source, selected) in [
        ("> quoted text", "quoted text"),
        ("> quoted text", "quoted"),
        ("> quoted text", "text"),
        ("> first line\n> second line", "first line\nsecond line"),
        (
            "> first paragraph\n>\n> second paragraph",
            "first paragraph\n\nsecond paragraph",
        ),
        (
            "> outer\n>> nested café界\n>\n> outer again",
            "outer\n\nnested café界\n\nouter again",
        ),
        ("> **bold** and `code`", "bold and code"),
        ("> **bold**\n>\n> - [x] task", "bold\n\n"),
        ("> **bold**\n>\n> | A |\n> |---|\n> | cell |", "bold\n\n"),
        (
            "> literal \\> marker and a > b",
            "literal > marker and a > b",
        ),
        ("Before\n\n> quoted text\n\nAfter", "quoted text"),
        ("Before\n\n> quoted text\n\nAfter", "quoted text\n"),
        ("Before\n\n> quoted text\n\nAfter", "\nquoted text"),
        (
            "> - first\n>   continuation\n> - second",
            "first\ncontinuation\n\nsecond",
        ),
    ] {
        for width in [18, 80] {
            let layout = markdown_layout(source, width);
            let start = layout.text().find(selected).expect(source);
            let copied = payload(&layout, start..start + selected.len());
            assert_eq!(copied, (selected.into(), CopyFormat::PlainText), "{source}");
            assert_eq!(
                payload(&layout.rewrap(/*width*/ 12), start..start + selected.len()),
                copied
            );
            if width == 80 && copies.len() < 3 {
                copies.push(format!("{source}\nSelected {selected:?} -> {copied:?}"));
            }
        }
    }
    insta::assert_snapshot!(copies.join("\n"), @r#"
    > quoted text
    Selected "quoted text" -> ("quoted text", PlainText)
    > quoted text
    Selected "quoted" -> ("quoted", PlainText)
    > quoted text
    Selected "text" -> ("text", PlainText)
    "#);
}

