        );

        pane.hide_status_indicator();
        pane.handle_key_event(KeyEvent::new(KeyCode::F(12), KeyModifiers::NONE));
        assert!(matches!(
            rx.try_recv(),
            Ok(AppEvent::CodexOp(Op::Interrupt))
        ));
    }

