fn handle_key_event(&mut self, key_event: KeyEvent) {
        if key_event.kind == KeyEventKind::Release {
            return;
        }

        self.snooze_auto_resolution();

        if self.confirm_unanswered_active() {
            self.handle_confirm_unanswered_key_event(key_event);
            return;
        }

        if matches!(key_event.code, KeyCode::Esc) && self.has_options() && self.notes_ui_visible() {
            self.clear_notes_and_focus_options();
            return;
        }

        if self.interrupt_turn_keys.is_pressed(key_event) {
            // TODO: Emit interrupted request_user_input results (including committed answers)
            // once core supports persisting them reliably without follow-up turn issues.
            self.app_event_tx.interrupt();
            self.done = true;
            return;
        }

        if self.focus_is_notes() && self.composer_submit_keys.is_pressed(key_event) {
            self.ensure_selected_for_notes();
            self.pending_submission_draft = Some(self.capture_composer_draft());
            let (result, _) = self.composer.handle_key_event(key_event);
            if !self.handle_composer_input_result(result) {
                self.pending_submission_draft = None;
                if self.has_options() {
                    self.select_current_option(/*committed*/ true);
                }
                self.go_next_or_submit();
            }
            return;
        }

        // Question navigation is always available.
        match key_event {
            KeyEvent {
                code: KeyCode::Char('p'),
                modifiers: KeyModifiers::CONTROL,
                ..
            }
            | KeyEvent {
                code: KeyCode::PageUp,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.move_question(/*next*/ false);
                return;
            }
            KeyEvent {
                code: KeyCode::PageDown,
                modifiers: KeyModifiers::NONE,
                ..
            }
            | KeyEvent {
                code: KeyCode::Char('n'),
                modifiers: KeyModifiers::CONTROL,
                ..
            } => {
                self.move_question(/*next*/ true);
                return;
            }
            KeyEvent {
                code: KeyCode::Char('h'),
                modifiers: KeyModifiers::NONE,
                ..
            }
            | KeyEvent {
                code: KeyCode::Left,
                modifiers: KeyModifiers::NONE,
                ..
            } if self.has_options() && matches!(self.focus, Focus::Options) => {
                self.move_question(/*next*/ false);
                return;
            }
            _ if self.has_options()
                && matches!(self.focus, Focus::Options)
                && self.list_keymap.action_for(key_event) == Some(ListAction::MoveLeft) =>
            {
                self.move_question(/*next*/ false);
                return;
            }
            KeyEvent {
                code: KeyCode::Char('l'),
                modifiers: KeyModifiers::NONE,
                ..
            }
            | KeyEvent {
                code: KeyCode::Right,
                modifiers: KeyModifiers::NONE,
                ..
            } if self.has_options() && matches!(self.focus, Focus::Options) => {
                self.move_question(/*next*/ true);
                return;
            }
            _ if self.has_options()
                && matches!(self.focus, Focus::Options)
                && self.list_keymap.action_for(key_event) == Some(ListAction::MoveRight) =>
            {
                self.move_question(/*next*/ true);
                return;
            }
            _ => {}
        }

        match self.focus {
            Focus::Options => {
                let options_len = self.options_len();
                // Keep selection synchronized as the user moves.
                match (self.list_keymap.action_for(key_event), key_event.code) {
                    (Some(ListAction::MoveUp), _) | (_, KeyCode::Up | KeyCode::Char('k')) => {
                        let moved = if let Some(answer) = self.current_answer_mut() {
                            answer.options_state.move_up_wrap(options_len);
                            answer.answer_committed = false;
                            true
                        } else {
                            false
                        };
                        if moved {
                            self.sync_composer_placeholder();
                        }
                    }
                    (Some(ListAction::MoveDown), _) | (_, KeyCode::Down | KeyCode::Char('j')) => {
                        let moved = if let Some(answer) = self.current_answer_mut() {
                            answer.options_state.move_down_wrap(options_len);
                            answer.answer_committed = false;
                            true
                        } else {
                            false
                        };
                        if moved {
                            self.sync_composer_placeholder();
                        }
                    }
                    (_, KeyCode::Char(' ')) => {
                        self.select_current_option(/*committed*/ true);
                    }
                    (_, KeyCode::Backspace | KeyCode::Delete) => {
                        self.clear_selection();
                    }
                    (_, KeyCode::Tab) | (Some(ListAction::Accept), _) | (_, KeyCode::Enter)
                        if self.selected_option_index().is_some()
                            && (key_event.code == KeyCode::Tab
                                || self.current_question().is_some_and(|question| {
                                    Self::other_option_enabled_for_question(question)
                                        && self.selected_option_index()
                                            == question.options.as_ref().map(Vec::len)
                                })) =>
                    {
                        self.focus = Focus::Notes;
                        self.ensure_selected_for_notes();
                    }
                    (Some(ListAction::Accept), _) | (_, KeyCode::Enter) => {
                        let has_selection = self.selected_option_index().is_some();
                        if has_selection {
                            self.select_current_option(/*committed*/ true);
                        }
                        self.go_next_or_submit();
                    }
                    (_, KeyCode::Char(ch)) => {
                        if let Some(option_idx) = self.option_index_for_digit(ch) {
                            if let Some(answer) = self.current_answer_mut() {
                                answer.options_state.selected_idx = Some(option_idx);
                            }
                            self.select_current_option(/*committed*/ true);
                            self.go_next_or_submit();
                        }
                    }
                    _ => {}
                }
            }
            Focus::Notes => {
                let notes_empty = self.composer.current_text_with_pending().trim().is_empty();
                if self.has_options() && matches!(key_event.code, KeyCode::Tab) {
                    self.clear_notes_and_focus_options();
                    return;
                }
                if self.has_options() && matches!(key_event.code, KeyCode::Backspace) && notes_empty
                {
                    self.save_current_draft();
                    if let Some(answer) = self.current_answer_mut() {
                        answer.notes_visible = false;
                    }
                    self.focus = Focus::Options;
                    self.sync_composer_placeholder();
                    return;
                }
                if self.has_options() && matches!(key_event.code, KeyCode::Up | KeyCode::Down) {
                    let options_len = self.options_len();
                    match key_event.code {
                        KeyCode::Up => {
                            let moved = if let Some(answer) = self.current_answer_mut() {
                                answer.options_state.move_up_wrap(options_len);
                                answer.answer_committed = false;
                                true
                            } else {
                                false
                            };
                            if moved {
                                self.sync_composer_placeholder();
                            }
                        }
                        KeyCode::Down => {
                            let moved = if let Some(answer) = self.current_answer_mut() {
                                answer.options_state.move_down_wrap(options_len);
                                answer.answer_committed = false;
                                true
                            } else {
                                false
                            };
                            if moved {
                                self.sync_composer_placeholder();
                            }
                        }
                        _ => {}
                    }
                    return;
                }
                self.ensure_selected_for_notes();
                if matches!(
                    key_event.code,
                    KeyCode::Char(_) | KeyCode::Backspace | KeyCode::Delete
                ) && let Some(answer) = self.current_answer_mut()
                {
                    answer.answer_committed = false;
                }
                let before = self.capture_composer_draft();
                let (result, _) = self.composer.handle_key_event(key_event);
                let submitted = self.handle_composer_input_result(result);
                if !submitted {
                    let after = self.capture_composer_draft();
                    if before != after
                        && let Some(answer) = self.current_answer_mut()
                    {
                        answer.answer_committed = false;
                    }
                }
            }
        }
    }

fn accepted_find_defers_paste_rendering_but_keeps_enter() -> Result<()> {
    let mut app = crate::app::test_support::make_test_app().await;
    let mut server = Box::pin(crate::start_embedded_app_server_for_picker(&app.config)).await?;
    let mut tui = crate::tui::test_support::make_test_tui()?;
    tui.set_owned_screen(/*owned*/ true)?;
    app.local_settings.tui.animations = false;
    app.transcript_cells = vec![Arc::new(PlainHistoryCell::new(vec![
        "Before paste needle".into(),
    ]))];
    for event in [
        TuiEvent::Key(KeyCode::F(3).into()),
        TuiEvent::Paste("needle".to_string()),
        TuiEvent::Draw,
        TuiEvent::Key(KeyCode::Enter.into()),
    ] {
        app.handle_tui_event(&mut tui, &mut server, event).await?;
    }
    assert!(!app.transcript_view.is_search_editing());
    assert!(app.transcript_view.has_active_interaction());
    tokio::time::pause();
    app.handle_tui_event(
        &mut tui,
        &mut server,
        TuiEvent::Key(KeyCode::Char('D').into()),
    )
    .await?;
    let before = crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal).clone();
    app.transcript_cells = vec![Arc::new(PlainHistoryCell::new(vec![
        "After paste needle".into(),
    ]))];
    for ch in "ebug log ".repeat(80).chars() {
        app.handle_tui_event(
            &mut tui,
            &mut server,
            TuiEvent::Key(KeyCode::Char(ch).into()),
        )
        .await?;
    }
    assert_eq!(
        crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal),
        &before
    );
    // Enter still belongs to accepted Find, even in the middle of a paste burst.
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Key(KeyCode::Enter.into()))
        .await?;
    assert_ne!(
        crate::custom_terminal::test_support::last_rendered_buffer(&tui.terminal),
        &before
    );
    assert!(app.chat_widget.queued_user_message_texts().is_empty());
    tokio::time::advance(Duration::from_secs(/*secs*/ 1)).await;
    app.handle_tui_event(&mut tui, &mut server, TuiEvent::Draw)
        .await?;
    assert_eq!(
        app.chat_widget.composer_text_with_pending(),
        format!("D{}", "ebug log ".repeat(80))
    );
    tokio::time::resume();
    server.shutdown().await?;
    tui.set_owned_screen(/*owned*/ false)?;
    Ok(())
}

fn interleaved_transcripts_keep_interrupted_speech_suppressed() {
    let (mut chat, _sender, _events, _ops) = make_chatwidget_manual_with_sender().await;
    activate_voice(&mut chat);
    chat.on_realtime_transcript_delta("assistant".into(), "The long answer".into());
    chat.on_realtime_transcript_delta("user".into(), "Actually, ".into());
    let generation = chat.realtime_conversation.input_generation;

    chat.on_realtime_transcript_delta("assistant".into(), " keeps going".into());
    assert_eq!(
        chat.realtime_conversation.speaker_suppression_generation,
        Some(generation)
    );
    chat.on_realtime_transcript_done("user".into(), "Actually, make it short".into());
    chat.on_realtime_transcript_delta("assistant".into(), " and going".into());
    chat.on_realtime_transcript_done("assistant".into(), "The long answer keeps going".into());
    assert_eq!(
        chat.realtime_conversation.speaker_suppression_generation,
        Some(generation)
    );

    chat.on_realtime_transcript_delta("assistant".into(), "Short answer".into());
    assert!(
        chat.realtime_conversation
            .speaker_suppression_generation
            .is_none()
    );
}

fn leave_vim_insert_mode(&mut self) {
        self.mouse_selection = None;
        let bol = self.beginning_of_current_line();
        if self.cursor_pos > bol {
            self.cursor_pos = self.prev_atomic_boundary(self.cursor_pos).max(bol);
        }
        self.enter_vim_normal_mode();
    }

fn experimental_features_discovery_preserves_server_order_and_accepts_new_keys() {
    let (app_tx, mut app_rx) = tokio::sync::mpsc::unbounded_channel();
    let (catalog_tx, catalog_rx) = oneshot::channel();
    let mut view = ExperimentalFeaturesView::new(
        Vec::new(),
        ThreadId::new(),
        Some(catalog_rx),
        AppEventSender::new(app_tx),
        crate::keymap::RuntimeKeymap::defaults().list,
    );
    view.toggle_selected();
    let mut stable = server_feature("stable_feature");
    stable.stage = ExperimentalFeatureStage::Stable;
    catalog_tx
        .send(Ok(vec![
            server_feature("network_proxy"),
            server_feature("future_feature"),
            server_feature("worktrees"),
            server_feature("realtime_conversation"),
            stable,
            server_feature("prevent_idle_sleep"),
        ]))
        .unwrap();
    assert!(view.pre_draw_tick(Instant::now()));
    assert_eq!(
        view.features
            .iter()
            .map(|item| (item.key.as_str(), item.enabled))
            .collect::<Vec<_>>(),
        vec![
            ("network_proxy", true),
            ("future_feature", true),
            ("prevent_idle_sleep", true)
        ]
    );
    let area = Rect::new(
        /*x*/ 0,
        /*y*/ 0,
        /*width*/ 100,
        view.desired_height(/*width*/ 100),
    );
    let mut buffer = Buffer::empty(area);
    view.render(area, &mut buffer);
    insta::assert_snapshot!(
        "experimental_features_server_discovery",
        buffer_text(&buffer)
    );
    // New server features are writable without a local Feature enum variant.
    view.state.selected_idx = Some(1);
    view.toggle_selected();
    assert!(!view.features[1].enabled);
    view.state.selected_idx = Some(0);
    view.toggle_selected();
    view.features[2].enabled = false;
    view.handle_key_event(KeyEvent::from(KeyCode::Enter));
    assert!(
        matches!(app_rx.try_recv().unwrap(), AppEvent::UpdateFeatureFlags { updates }
        if updates == vec![(Feature::PreventIdleSleep, false)])
    );
    let AppEvent::SaveExperimentalFeatures {
        updates,
        response_tx,
        ..
    } = app_rx.try_recv().unwrap()
    else {
        panic!("expected feature edits");
    };
    assert_eq!(
        updates,
        vec![
            ("network_proxy".to_string(), false),
            ("future_feature".to_string(), false)
        ]
    );
    snapshot_view("experimental_features_saving", &view);
    response_tx
        .send(Err("Saved but readback failed".to_string()))
        .unwrap();
    view.pre_draw_tick(Instant::now());
    snapshot_view("experimental_features_save_failed", &view);

    // Reverting uncertain saves to their original values must still write them.
    view.features[0].enabled = true;
    view.features[1].enabled = true;
    view.handle_key_event(KeyEvent::from(KeyCode::Enter));
    let AppEvent::SaveExperimentalFeatures {
        updates,
        response_tx,
        ..
    } = app_rx.try_recv().unwrap()
    else {
        panic!("expected corrective save without repeating special controls");
    };
    assert_eq!(
        updates,
        vec![
            ("network_proxy".to_string(), true),
            ("future_feature".to_string(), true)
        ]
    );
    response_tx
        .send(Err("Persistent write rejection".to_string()))
        .unwrap();
    view.pre_draw_tick(Instant::now());
    // Cancel saves new special edits without retrying the failed generic write.
    view.features[2].enabled = true;
    view.handle_key_event(KeyEvent::from(KeyCode::Esc));
    assert!(view.is_complete());
    assert!(
        matches!(app_rx.try_recv().unwrap(), AppEvent::UpdateFeatureFlags { updates }
        if updates == vec![(Feature::PreventIdleSleep, true)])
    );
    assert!(app_rx.try_recv().is_err());
}

fn copy_on_select_copies_word_and_line_on_release_without_dragging() {
    let cells = vec![cell("alpha beta gamma")];
    let mut view = TranscriptView {
        copy_on_select: true,
        ..Default::default()
    };
    render(&mut view, &cells, /*width*/ 24, /*height*/ 1);
    let down = mouse(MouseEventKind::Down(MouseButton::Left), /*column*/ 7);
    let up = MouseEvent {
        kind: MouseEventKind::Up(MouseButton::Left),
        ..down
    };
    for expected in [None, Some("beta"), Some("alpha beta gamma")] {
        if let Some((at, ..)) = &mut view.last_click {
            *at = Instant::now();
        }
        assert!(matches!(
            view.handle_mouse(down, &cells),
            Some(ViewAction::Changed)
        ));
        let copied = match view.handle_mouse(up, &cells) {
            Some(ViewAction::CopyOnSelect(text)) => Some(text),
            Some(ViewAction::Changed) => None,
            _ => panic!("release must finish the repeated click"),
        };
        assert_eq!(
            (copied.as_deref(), view.selected_text(&cells).as_deref()),
            (expected, expected)
        );
        assert!(view.handle_mouse(up, &cells).is_none());
    }
}

fn prune_local_images_for_submission(
        &mut self,
        text: &str,
        text_elements: &[TextElement],
    ) {
        if self.local_images.is_empty() {
            return;
        }

        let image_placeholders: HashSet<&str> = text_elements
            .iter()
            .filter_map(|element| element.placeholder(text))
            .collect();
        self.local_images
            .retain(|image| image_placeholders.contains(image.placeholder.as_str()));
    }

