fn start_search_scan(&mut self, cells: &[Arc<dyn HistoryCell>], direction: Direction) {
        self.search.page_start = None;
        let count = cells.len() + usize::from(self.live.is_some() || self.search.live.is_some());
        let index = if self.search.is_reading() {
            // Without a retained match, resume from the visible entry, not a transcript end.
            self.start(cells).0
        } else {
            match direction {
                Direction::Older => count.saturating_sub(/*rhs*/ 1),
                Direction::Newer => 0,
            }
        };
        let offset = match direction {
            Direction::Older => usize::MAX,
            Direction::Newer => 0,
        };
        self.search.progress = Progress::Scanning(Cursor {
            anchor: Anchor {
                key: self.entry_key(cells, index),
                index,
                offset,
                row_bias: 0,
            },
            direction,
        });
    }

fn search_resumes_in_prepended_history_without_rescanning_the_newer_entry() {
    let newest = cell("newer messages");
    let mut cells = vec![Arc::clone(&newest)];
    let mut view = TranscriptView {
        history: TranscriptHistoryState::Partial,
        ..TranscriptView::default()
    };
    view.begin_search();
    view.paste_search("needle");
    finish_scan(&mut view, &cells);
    assert!(view.search.needs_history(view.history));
    view.history = TranscriptHistoryState::LoadingOlder;
    assert!(!view.advance_search(&cells));
    cells.insert(/*index*/ 0, cell("old NEEDLE"));
    view.history = TranscriptHistoryState::Complete;
    view.history_loaded(&cells, 0..1);
    finish_scan(&mut view, &cells);
    let found = view.search.current.as_ref().expect("match in earlier page");
    assert_eq!(
        (
            found.anchor.key,
            found.anchor.index,
            found.anchor.offset,
            found.end
        ),
        (EntryKey::cell(&cells[0]), 0, 4, 10)
    );
    assert!(!view.search.needs_history(view.history));
}

fn next_frame_delay(&self) -> Option<Duration> {
        self.timer_remaining(Instant::now())
            .map(|remaining| {
                if remaining > Duration::from_secs(20) {
                    remaining - Duration::from_secs(20)
                } else {
                    remaining.min(Duration::from_secs(1))
                }
            })
            .into_iter()
            .chain(self.composer.footer_flash_delay())
            .min()
    }

