fn edit_input(&mut self, edit: impl FnOnce(&mut String)) -> bool {
        let mut state = self.state.lock().unwrap_or_else(PoisonError::into_inner);
        let searching = state.searching;
        if searching {
            edit(&mut state.search);
        }
        drop(state);
        if searching {
            self.selected = self
                .selectable_indices()
                .first()
                .copied()
                .unwrap_or(usize::MAX);
        }
        true
    }

