fn complete_quiet_success(&mut self, now: Instant) -> bool {
        let HookRunState::VisibleRunning { visible_since, .. } = self else {
            return false;
        };
        let minimum_deadline = *visible_since + QUIET_HOOK_MIN_VISIBLE;
        if now >= minimum_deadline {
            return false;
        }
        *self = HookRunState::QuietLinger {
            removal_deadline: minimum_deadline,
        };
        true
    }

fn sync_history_tail(&mut self, cells: &[Arc<dyn HistoryCell>]) {
        let tail = cells.last().map(EntryKey::cell);
        if !self.is_following() && self.last_tail.is_some() && self.last_tail != tail {
            let previous = cells
                .iter()
                .rposition(|cell| Some(EntryKey::cell(cell)) == self.last_tail);
            self.unseen_activity |= previous.is_none_or(|index| {
                (index + 1..cells.len()).any(|index| {
                    self.current_layout(cells, index)
                        .is_some_and(|layout| layout.row_count() > 0)
                })
            });
        }
        self.last_tail = tail;
        if self.is_following() {
            self.unseen_activity = false;
        }
    }

