fn vim_search_command(&self, event: KeyEvent) -> Option<SearchCommand> {
        use SearchCommand::Start;

        if !self.vim_search_enabled
            || !self.is_vim_normal_mode()
            || !matches!(self.vim_pending, VimPending::None | VimPending::Operator(_))
        {
            return None;
        }
        let keys = &self.vim_search_keymap;
        [
            (&keys.forward, Start(SearchDirection::Forward)),
            (&keys.backward, Start(SearchDirection::Backward)),
            (&keys.next, SearchCommand::Next),
            (&keys.previous, SearchCommand::Previous),
        ]
        .into_iter()
        .find_map(|(bindings, command)| bindings.is_pressed(event).then_some(command))
    }

fn scrolling_or_releasing_elsewhere_cancels_link_activation() {
    for interruption in [
        mouse(MouseEventKind::ScrollUp, /*column*/ 4, /*row*/ 1),
        mouse(
            MouseEventKind::ScrollDown,
            /*column*/ 4,
            /*row*/ 1,
        ),
        mouse(
            MouseEventKind::Up(MouseButton::Left),
            /*column*/ 5,
            /*row*/ 1,
        ),
        mouse(
            MouseEventKind::Up(MouseButton::Left),
            /*column*/ 0,
            /*row*/ 0,
        ),
    ] {
        let (mut view, cells) = transcript("[docs](https://example.com/docs)", /*width*/ 60);
        view.handle_mouse(
            mouse(
                MouseEventKind::Down(MouseButton::Left),
                /*column*/ 4,
                /*row*/ 1,
            ),
            &cells,
        );
        assert!(!matches!(
            view.handle_mouse(interruption, &cells),
            Some(ViewAction::OpenLink(_))
        ));
        assert!(!matches!(
            view.handle_mouse(
                mouse(
                    MouseEventKind::Up(MouseButton::Left),
                    /*column*/ 4,
                    /*row*/ 1
                ),
                &cells
            ),
            Some(ViewAction::OpenLink(_))
        ));
    }
}

fn find_jump_and_search_navigation_never_snapshot_the_draft() {
    let mut composer = vim_composer("alpha beta\nalpha gamma");
    for key in ['f', 'F', 'G', '/', '?', 'n', 'N'] {
        composer.begin_vim_edit(KeyEvent::new(KeyCode::Char(key), KeyModifiers::NONE));
        assert!(
            composer.vim_history.pending.is_none(),
            "navigation binding {key:?} snapshotted the draft"
        );
    }
    let (code, modifiers) = composer
        .vim_normal_keymap
        .jump_top
        .first()
        .expect("native jump-top chord")
        .parts();
    composer.begin_vim_edit(KeyEvent::new(code, modifiers));
    assert!(composer.vim_history.pending.is_none());

    for command in ["llwbh0$", "fb", "Fa", "G", "/beta\nnN", "?alpha\n"] {
        let text = "alpha beta\nalpha gamma";
        let mut composer = vim_composer(text);
        for key in command.chars() {
            keys(&mut composer, &key.to_string());
            assert!(
                composer.vim_history.pending.is_none(),
                "navigation command {command:?} snapshotted the draft"
            );
            assert!(composer.vim_history.undo.is_empty());
        }
        assert_eq!(composer.current_text(), text);
    }
    let mut keymap = RuntimeKeymap::defaults();
    keymap.vim_normal.redo.clear();
    composer.set_keymap_bindings(&keymap);
    composer
        .history
        .record_local_submission(HistoryEntry::new("alpha archived".to_owned()));
    ctrl_r(&mut composer);
    keys(&mut composer, "alpha");
    assert_eq!(composer.current_text(), "alpha archived");
    assert!(composer.vim_history.pending.is_none());
    assert!(composer.vim_history.undo.is_empty());
    escape(&mut composer);
    assert_eq!(composer.current_text(), "alpha beta\nalpha gamma");
}

